const DRIVE_PROXY_URL        = process.env.DRIVE_PROXY_URL || ''
const DRIVE_PROXY_SECRET     = process.env.DRIVE_PROXY_SECRET || 'g2g-drive-2026'

// Helper: call Apps Script proxy (handles 302 redirect pattern)
// Google Apps Script web apps return HTTP 302 on POST; actual JSON lives at the Location URL
async function callDriveProxy(payload) {
  if (!DRIVE_PROXY_URL) return null
  try {
    // Step 1: POST to Apps Script (expect 302, don't auto-follow)
    const res = await fetch(DRIVE_PROXY_URL, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
      redirect: 'manual'
    })

    // Step 2: Follow the redirect URL with GET
    const redirectUrl = res.headers.get('location')
    if (!redirectUrl) {
      // No redirect — try reading body directly
      return await res.json().catch(() => null)
    }

    const res2 = await fetch(redirectUrl, { method: 'GET' })
    return await res2.json()
  } catch (e) {
    console.error('[Drive] callDriveProxy error:', e.message)
    return null
  }
}

// Save JSON to Google Drive via Apps Script proxy (create or update by filename within a folder)
async function saveToDrive(folderId, fileName, data) {
  if (!DRIVE_PROXY_URL) return false
  const result = await callDriveProxy({
    action: 'save',
    secret: DRIVE_PROXY_SECRET,
    folderId,
    fileName,
    content: data
  })
  if (result?.ok) {
    console.log(`[Drive] ✅ Saved ${fileName} (${result.action})`)
    return true
  }
  console.warn('[Drive] ⚠️ Save failed:', result?.error || 'unknown')
  return false
}

// Load JSON from Google Drive via Apps Script proxy by filename within a folder
async function loadFromDrive(folderId, fileName) {
  if (!DRIVE_PROXY_URL) return null
  const result = await callDriveProxy({
    action: 'load',
    secret: DRIVE_PROXY_SECRET,
    folderId,
    fileName
  })
  return result?.ok ? result.content : null
}

// =============================================================
// AIRTABLE I/O
// =============================================================
async function airtableGet(table, params = {}) {
  const q = new URLSearchParams(params).toString();
  const url = `https://api.airtable.com/v0/${AIRTABLE_BASE}/${encodeURIComponent(table)}${q ? "?" + q : ""}`;
  const r = await fetch(url, { headers: { Authorization: `Bearer ${AIRTABLE_TOKEN}` } });
  if (!r.ok) throw new Error(`airtable_get_${r.status}: ${await r.text()}`);
  return r.json();
}

async function airtablePost(table, fields) {
  const url = `https://api.airtable.com/v0/${AIRTABLE_BASE}/${encodeURIComponent(table)}`;
  const r = await fetch(url, {
    method: "POST",
    headers: { Authorization: `Bearer ${AIRTABLE_TOKEN}`, "Content-Type": "application/json" },
    body: JSON.stringify({ fields, typecast: true }),
  });
  if (!r.ok) throw new Error(`airtable_post_${r.status}: ${await r.text()}`);
  return r.json();
}

async function airtablePatch(table, recId, fields) {
  const url = `https://api.airtable.com/v0/${AIRTABLE_BASE}/${encodeURIComponent(table)}/${recId}`;
  const r = await fetch(url, {
    method: "PATCH",
    headers: { Authorization: `Bearer ${AIRTABLE_TOKEN}`, "Content-Type": "application/json" },
    body: JSON.stringify({ fields, typecast: true }),
  });
  if (!r.ok) throw new Error(`airtable_patch_${r.status}: ${await r.text()}`);
  return r.json();
}

