// LINE webhook endpoint — one per channel
app.post("/line/webhook/:channelIdExt", async (req, res) => {
  res.status(200).end(); // ACK immediately to LINE
  try {
    const { channelIdExt } = req.params;
    // Verify LINE signature (skip if no secret configured)
    const sig = req.headers["x-line-signature"];
    const secret = getChannelSecret(channelIdExt);
    if (sig && secret && !verifyLineSignature(req.rawBody || JSON.stringify(req.body), sig, secret)) {
      console.warn(`[webhook] invalid signature for ${channelIdExt}`);
      return;
    }
    const events = req.body?.events || [];
    for (const ev of events) {
      if (ev.type !== "message" || ev.message?.type !== "text") continue;
      const lineToken = process.env[`LINE_TOKEN_${channelIdExt}`] || process.env.LINE_TOKEN_DEFAULT;
      if (!lineToken) {
        console.warn("no_line_token_for", channelIdExt);
        continue;
      }
      const userId = ev.source.userId;
      const userText = ev.message.text;

      // --- ตรวจจับคำสั่งเปลี่ยนชื่อบอท ---
      const nameChangeMatch = userText.match(
        /(?:เปลี่ยนชื่อ(?:น้อง)?(?:เป็น|ว่า)|ชื่อใหม่(?:คือ|เป็น)?|ตั้งชื่อ(?:ว่า)?|เรียก(?:ว่า)?)\s*[""]?([^"""]{1,30})[""]?/
      );
      if (nameChangeMatch) {
        const newName = nameChangeMatch[1].trim().replace(/["""]/g, "");
        if (newName.length >= 1) {
          BOT_CUSTOM_NAMES.set(channelIdExt, { name: newName, setBy: userId, setAt: new Date().toISOString() });
          saveBotNames();
          const lineTokenForName = process.env[`LINE_TOKEN_${channelIdExt}`] || process.env.LINE_TOKEN_DEFAULT;
          if (lineTokenForName) {
            await lineReply(ev.replyToken, `✅ รับทราบครับ! ตั้งแต่นี้จะใช้ชื่อว่า "${newName}" นะครับ 😊\n\nจำไว้เรียบร้อยแล้ว ถึงจะรีสตาร์ทระบบก็ยังใช้ชื่อนี้อยู่ครับ`, lineTokenForName);
          }
          continue; // ไม่ส่งต่อไป AI
        }
      }

      // 1) Resolve identity — search across all profiles by name/phone in current msg
      const { profiles, merged, hints, linkedUserIds } = await resolveIdentity(userId, userText)
        .catch(e => { console.error("resolve_identity_failed", e.message); return { profiles: [], merged: null, hints: {}, linkedUserIds: [userId] }; });

      // 2) Fetch conversation history across ALL linked userIds (cross-channel, cross-AI)
      const persistentHistory = await getCrossChannelHistory(linkedUserIds, 30).catch(() => []);
      const aiHistory = persistentHistory
        .filter(m => m.role === "user" || m.role === "assistant")
        .map(m => ({ role: m.role, content: m.content }));

      // 3) โหลด custom system prompt จาก Airtable Channels table ถ้ามี
      const channelProfile = await airtableGet(ONBOARD_TABLE, {
        filterByFormula: `{channel_id_ext}="${channelIdExt}"`,
        maxRecords: 1,
      }).catch(() => ({ records: [] }));
      const channelSystemPrompt = channelProfile.records?.[0]?.fields?.system_prompt
        || CHANNEL_SYSTEM_PROMPTS[channelIdExt]
        || SYSTEM_PROMPT_G2G_THAI;

      // 3b) Inject merged user memory snippet + custom bot name + platform knowledge
      const memorySnippet = buildMemorySnippet(merged);

      // Inject custom bot name if user changed it via LINE
      const customBotName = getBotName(channelIdExt);
      let effectiveSystemPrompt = channelSystemPrompt;
      if (customBotName) {
        // Replace name references in system prompt
        effectiveSystemPrompt = effectiveSystemPrompt
          .replace(/ชื่อ: (น้อง\S+|ผู้ช่วย\S*|\S+)/g, `ชื่อ: ${customBotName}`)
          .replace(/คุณคือ \*\*"(.+?)"\*\*/, `คุณคือ **"${customBotName}"**`);
        effectiveSystemPrompt += `\n\n# ชื่อปัจจุบัน (อัปเดตโดยผู้ใช้)\nชื่อของคุณตอนนี้คือ "${customBotName}" — ใช้ชื่อนี้เสมอเมื่อแนะนำตัวหรือเซ็นชื่อ อย่าใช้ชื่อเดิม`;
      }

      // Inject G2G platform knowledge for MHESI bots
      if (channelIdExt && channelIdExt.startsWith("MHESI")) {
        effectiveSystemPrompt += G2G_PLATFORM_KNOWLEDGE;
      }

      const fullSystem = effectiveSystemPrompt + memorySnippet
        + (linkedUserIds.length > 1 ? `\n\n# Cross-channel: ระบบเชื่อมโยง LINE userId ${linkedUserIds.length} ตัวเข้าด้วยกัน (ผู้ใช้คนเดียวกันคุยจากหลายช่องทาง — ใช้ประวัติรวม)` : "");

      // Pre-seed channel cache สำหรับ LINE webhooks
      // (token ถูก validate แล้วข้างบน — ไม่ต้อง query Airtable ซ้ำใน getChannel)
      const ck = `channel:${channelIdExt}`;
      if (!cacheGet(ck)) {
        const cf = channelProfile.records?.[0]?.fields || {};
        cacheSet(ck, {
          channel_id_ext: channelIdExt,
          name: cf.channel_name || channelIdExt,
          type: cf.channel_type?.name || cf.channel_type || "line_oa",
          tier: cf.tier?.name || cf.tier || "free",
          channel_adjust: cf.channel_adjust ?? 1.0,
          daily_quota_tokens: cf.daily_quota_tokens ?? 200000,
          webhook_secret: null,
        });
      }

      const r = await route({
        channel_id: channelIdExt,
        channel_key: req.headers["x-channel-key"] || "",
        user_id: userId,
        conversation_id: userId,
        prompt: userText,
        system: fullSystem,
        history: aiHistory,
        model_class: "smart",
        max_tokens: 1024,
      });

      let replyText;
      if (r.ok) {
        replyText = r.text;
        // 4) Persist user msg + AI response to Conversation_Log
        saveConversationMessage({
          userId, channelIdExt, role: "user",
          content: userText, agent: "พี่เก่ง",
        });
        saveConversationMessage({
          userId, channelIdExt, role: "assistant",
          content: replyText, agent: "พี่เก่ง",
          model: r.model_used, tokens: (r.tokens?.input || 0) + (r.tokens?.output || 0),
        });

        // 5) Update User_Memory with hints extracted earlier (auto-create on first msg)
        upsertUserMemory(userId, channelIdExt, hints).catch(e =>
          console.error("upsert_memory_failed", e.message));
      } else {
        replyText = `⚠️ ระบบติดขัดชั่วคราว (${r.error}) — ลองอีกครั้งใน 1 นาที`;
      }
      await lineReply(ev.replyToken, replyText, lineToken);
    }
  } catch (err) {
    console.error("line_webhook_error", err);
  }
});

