const BRIDGE_TABLE = "AI_Bridge";

app.post("/api/bridge/post", async (req, res) => {
  try {
    const { from, to = "all", type = "INFO", message, data = {} } = req.body;
    if (!from || !message) return res.status(400).json({ ok: false, error: "from + message required" });
    const rec = await airtablePost(BRIDGE_TABLE, { From: from, To: to, Type: type, Message: message, Data: JSON.stringify(data), CreatedAt: new Date().toISOString(), Read: false });
    console.log(`[BRIDGE] ${from}→${to} ${type}`);
    res.json({ ok: true, id: rec.id });
  } catch (err) { res.status(500).json({ ok: false, error: err.message }); }
});

app.get("/api/bridge/read", async (req, res) => {
  try {
    const { to } = req.query;
    const formula = to ? `AND({Read}=FALSE(),OR({To}="${to}",{To}="all"))` : `{Read}=FALSE()`;
    const data = await airtableGet(BRIDGE_TABLE, { filterByFormula: formula, sort: [{ field: "CreatedAt", direction: "asc" }], maxRecords: 50 });
    const messages = (data.records || []).map(r => ({ id: r.id, from: r.fields.From, to: r.fields.To, type: r.fields.Type, message: r.fields.Message, createdAt: r.fields.CreatedAt }));
    res.json({ ok: true, count: messages.length, messages });
  } catch (err) { res.status(500).json({ ok: false, error: err.message }); }
});

