// AUTO-ONBOARDING SYSTEM
// รับสมัครลูกค้าใหม่ผ่านฟอร์ม → สร้าง ChannelID → generate system prompt
// → บันทึก Airtable → รอทีมงานติดตั้ง LINE token
// =============================================================

// System prompt templates ตาม type
const PROMPT_TEMPLATES = {
  personal: `คุณคือ AI Boss ผู้ช่วยส่วนตัวของ {ownerName} — ผู้ช่วยอัจฉริยะที่พูดจาเป็นกันเองแบบเพื่อนสนิท
รู้จักเจ้านายเป็นอย่างดี คอยช่วยงานทุกอย่างตั้งแต่จัดตารางนัดหมาย ตอบคำถาม ไปจนถึงให้คำปรึกษาส่วนตัว
เรียกเจ้านายว่า "คุณ{ownerName}" หรือตามที่เจ้านายชอบ
ติดต่อได้ทาง LINE: {contactLine} โทรศัพท์: {contactPhone} อีเมล: {contactEmail}
ตอบภาษาไทยเป็นหลัก กระชับ ตรงประเด็น เป็นกันเอง ห้ามทำตัวเหมือน call center`,

  corporate: `คุณคือ AI Boss ผู้ช่วยอัจฉริยะของ {companyName}
ทำหน้าที่เป็นตัวแทนดิจิทัลขององค์กร ช่วยพนักงาน ลูกค้า และคู่ค้าในทุกเรื่อง
พูดจาเป็นมืออาชีพ สุภาพ แต่ไม่เป็นทางการมากเกินไป
ติดต่อ {companyName}: LINE {contactLine} โทร {contactPhone} อีเมล {contactEmail}
ตอบภาษาไทยหรืออังกฤษตามที่ผู้ใช้ถาม ให้ข้อมูลถูกต้อง ถ้าไม่รู้ให้บอกตรงๆ แล้วโอนต่อให้ทีมงาน`,

  government: `คุณคือ AI Boss ผู้ให้บริการประชาชนของ {agencyName}
ช่วยอำนวยความสะดวกแก่ประชาชนในการรับบริการ ตอบคำถามข้อมูลหน่วยงาน ลดขั้นตอนการติดต่อราชการ
พูดจาสุภาพ เข้าใจง่าย เป็นมิตร ไม่ใช้ศัพท์ราชการเกินจำเป็น
ติดต่อ {agencyName}: LINE {contactLine} โทร {contactPhone} อีเมล {contactEmail}
ห้ามให้ข้อมูลที่ไม่แน่ใจ ถ้าไม่มีข้อมูลให้แจ้งช่องทางติดต่อเจ้าหน้าที่โดยตรง`,
};

// แทนที่ {key} ด้วยค่าจาก data object
function fillTemplate(template, data) {
  return template.replace(/\{(\w+)\}/g, (_, key) => data[key] || "");
}

// Tier / monthly fee defaults ตาม type
const TIER_DEFAULTS = {
  personal:    { tier: "basic",      monthlyFee: 990  },
  corporate:   { tier: "pro",        monthlyFee: 2990 },
  government:  { tier: "ministry",   monthlyFee: 4990 },
};

// POST /api/onboard — รับข้อมูลจากฟอร์ม onboarding
app.post("/api/onboard", async (req, res) => {
  try {
    const { type, data = {} } = req.body || {};

    // 1) Validate type
    if (!["personal", "corporate", "government"].includes(type)) {
      return res.status(400).json({ ok: false, error: "type ต้องเป็น personal | corporate | government" });
    }

    // 2) Required fields per type
    const required = {
      personal:   ["ownerName"],
      corporate:  ["companyName"],
      government: ["agencyName"],
    };
    const missing = required[type].filter(f => !data[f]);
    if (missing.length) {
      return res.status(400).json({ ok: false, error: `ข้อมูลไม่ครบ: ${missing.join(", ")}` });
    }

    // 3) สร้าง channelId unique
    const channelId = "C" + Date.now().toString(36).toUpperCase();

    // 4) สร้าง system_prompt จาก template
    const templateData = {
      ownerName:    data.ownerName    || "",
      companyName:  data.companyName  || "",
      agencyName:   data.agencyName   || "",
      contactLine:  data.contactLine  || data.lineId    || "-",
      contactPhone: data.contactPhone || data.phone     || "-",
      contactEmail: data.contactEmail || data.email     || "-",
    };
    const systemPrompt = fillTemplate(PROMPT_TEMPLATES[type], templateData);

    // 5) หา display name
    const ownerDisplay = data.ownerName || data.companyName || data.agencyName || "";
    const { tier, monthlyFee } = TIER_DEFAULTS[type];

    // 6) บันทึกลง Airtable "Channels"
    const rec = await airtablePost(ONBOARD_TABLE, {
      channel_name:    ownerDisplay || channelId,
      channel_id_ext:  channelId,
      channel_type:    type === "personal" ? "line_oa" : type === "corporate" ? "b2b_api" : "gov_app",
      tier:            tier,
      active:          false,           // จะ active หลัง LINE token ได้รับ
      system_prompt:   systemPrompt,
    });

    console.log(`[ONBOARD] created channel ${channelId} type=${type} owner="${ownerDisplay}" rec=${rec.id}`);

    return res.json({
      ok: true,
      channelId,
      message: `ลงทะเบียน ${ownerDisplay} สำเร็จ ChannelID: ${channelId}`,
      nextStep: "รอทีมงานติดต่อกลับภายใน 1 วันทำการ เพื่อ activate LINE OA และเชื่อมต่อระบบ",
    });

  } catch (err) {
    console.error("[ONBOARD] error:", err.message);
    res.status(500).json({ ok: false, error: err.message });
  }
});

// GET /api/channels — list channels สำหรับ admin
app.get("/api/channels", async (req, res) => {
  try {
    const { type, status } = req.query;
    const conditions = [];
    if (type)   conditions.push(`{Type}="${type}"`);
    if (status) conditions.push(`{Status}="${status}"`);
    const filterByFormula = conditions.length === 1
      ? conditions[0]
      : conditions.length > 1
        ? `AND(${conditions.join(",")})`
        : undefined;

    const params = { maxRecords: 100 };
    if (filterByFormula) params.filterByFormula = filterByFormula;

    const data = await airtableGet(ONBOARD_TABLE, params);
    const channels = (data.records || []).map(r => ({
      id:           r.id,
      channelId:    r.fields.channel_id_ext,
      channelName:  r.fields.channel_name || "",
      type:         r.fields.channel_type?.name || r.fields.channel_type || "",
      tier:         r.fields.tier?.name || r.fields.tier || "",
      active:       r.fields.active || false,
      hasPrompt:    !!(r.fields.system_prompt),
    }));

    res.json({ ok: true, count: channels.length, channels });
  } catch (err) {
    console.error("[CHANNELS] list error:", err.message);
    res.status(500).json({ ok: false, error: err.message });
  }
});

// PATCH /api/channels/:channelId/activate — activate channel เมื่อได้รับ LINE token
app.patch("/api/channels/:channelId/activate", async (req, res) => {
  try {
    const { channelId } = req.params;
    const { lineChannelToken, lineChannelSecret, lineBasicId } = req.body || {};

    if (!lineChannelToken || !lineChannelSecret) {
      return res.status(400).json({ ok: false, error: "lineChannelToken และ lineChannelSecret จำเป็นต้องมี" });
    }

    // หา record ใน Airtable
    const found = await airtableGet(ONBOARD_TABLE, {
      filterByFormula: `{channel_id_ext}="${channelId}"`,
      maxRecords: 1,
    });
    if (!found.records || !found.records.length) {
      return res.status(404).json({ ok: false, error: `channel_id_ext "${channelId}" ไม่พบในระบบ` });
    }

    const recId = found.records[0].id;
    await airtablePatch(ONBOARD_TABLE, recId, {
      active: true,
      // NOTE: LINE token ไม่เก็บใน Airtable — ต้อง set ผ่าน fly secret set LINE_TOKEN_<channelId>=<token>
    });

    console.log(`[ONBOARD] activated channel ${channelId}`);
    res.json({ ok: true, channelId, message: `Channel ${channelId} activated เรียบร้อย` });
  } catch (err) {
    console.error("[ONBOARD] activate error:", err.message);
    res.status(500).json({ ok: false, error: err.message });
  }
});

