// State tracker สำหรับ smart alert (ไม่ส่งซ้ำถ้าปัญหาเดิม)
const MONITOR_STATE = new Map(); // channelIdExt → last known status

// ทดสอบ LINE token จริงผ่าน LINE Bot API
async function testLineToken(token) {
  if (!token) return { valid: false, reason: "no_token" };
  try {
    const r = await fetch("https://api.line.me/v2/bot/info", {
      headers: { Authorization: `Bearer ${token}` },
    });
    if (r.ok) {
      const info = await r.json();
      return { valid: true, botName: info.displayName, userId: info.userId };
    }
    const err = await r.json().catch(() => ({}));
    return { valid: false, reason: err.message || `http_${r.status}` };
  } catch (e) {
    return { valid: false, reason: e.message };
  }
}

// ทดสอบว่า Airtable ตอบสนองได้
async function testAirtable() {
  try {
    const r = await airtableGet("Channels", { maxRecords: 1 });
    return { ok: true, records: r.records?.length || 0 };
  } catch (e) {
    // สรุป error ให้กระชับ ไม่ dump JSON ดิบ
    const msg = e.message || "";
    let reason = "เชื่อมต่อไม่ได้";
    if (msg.includes("403") || msg.includes("UNAUTHORIZED") || msg.includes("INVALID_PERMISSIONS")) reason = "token ไม่ถูกต้อง หรือไม่มีสิทธิ์";
    else if (msg.includes("404") || msg.includes("NOT_FOUND")) reason = "base/table ไม่พบ";
    else if (msg.includes("429")) reason = "rate limit เกิน";
    else if (msg.includes("5")) reason = "Airtable server มีปัญหา";
    return { ok: false, error: reason };
  }
}

// ทดสอบว่า AI routing ทำงานได้ (ตรวจทุก class — smart, fast, cheap, smart-pro)
async function testAIRouting() {
  try {
    const classes = ["smart", "fast", "cheap", "smart-pro"];
    const results = await Promise.all(classes.map(cls => listActiveModelsByClass(cls).catch(() => [])));
    const byClass = Object.fromEntries(classes.map((c, i) => [c, results[i].length]));
    const total = Object.values(byClass).reduce((s, n) => s + n, 0);
    return { ok: total > 0, activeModels: total, byClass };
  } catch (e) {
    return { ok: false, error: "ตรวจสอบ AI models ไม่ได้" };
  }
}

// ส่งแจ้งเตือนไปยัง ExecCopilot channel (G2G team group)
async function sendMonitorAlert(message) {
  const alertToken = process.env.LINE_TOKEN_EXECCOPILOT || process.env.LINE_TOKEN_DEFAULT;
  if (!alertToken) {
    console.error("[MONITOR] ❌ ไม่มี alert token — ส่ง alert ไม่ได้");
    return false;
  }
  try {
    const r = await fetch("https://api.line.me/v2/bot/message/broadcast", {
      method: "POST",
      headers: { Authorization: `Bearer ${alertToken}`, "Content-Type": "application/json" },
      body: JSON.stringify({ messages: [{ type: "text", text: message }] }),
    });
    return r.ok;
  } catch (e) {
    console.error("[MONITOR] alert send error:", e.message);
    return false;
  }
}

// ฟังก์ชัน deep health check หลัก
async function runDeepHealthCheck(silent = false) {
  const startTime = Date.now();
  const results = { channels: [], infrastructure: {}, checkedAt: new Date().toISOString() };
  const newAlerts = [];
  const recoveries = [];

  // 1) ตรวจ Airtable
  results.infrastructure.airtable = await testAirtable();
  if (!results.infrastructure.airtable.ok) {
    const key = "__airtable__";
    if (MONITOR_STATE.get(key) !== "error") {
      MONITOR_STATE.set(key, "error");
      newAlerts.push(`❌ Airtable ไม่ตอบสนอง: ${results.infrastructure.airtable.error}`);
    }
  } else {
    const key = "__airtable__";
    if (MONITOR_STATE.get(key) === "error") {
      MONITOR_STATE.set(key, "ok");
      recoveries.push("✅ Airtable กลับมาปกติแล้ว");
    }
    MONITOR_STATE.set(key, "ok");
  }

  // 2) ตรวจ AI routing
  results.infrastructure.ai = await testAIRouting();
  if (!results.infrastructure.ai.ok) {
    const key = "__ai__";
    if (MONITOR_STATE.get(key) !== "error") {
      MONITOR_STATE.set(key, "error");
      newAlerts.push(`❌ AI models ไม่พร้อม: ${results.infrastructure.ai.error || "no active models"}`);
    }
  } else {
    const key = "__ai__";
    if (MONITOR_STATE.get(key) === "error") recoveries.push(`✅ AI routing กลับมาปกติ (${results.infrastructure.ai.activeModels} models)`);
    MONITOR_STATE.set(key, "ok");
  }

  // 3) ตรวจ LINE channels ทุกตัว (deep test)
  let channelData = { records: [] };
  try { channelData = await airtableGet(ONBOARD_TABLE, { maxRecords: 100 }); } catch (_) {}

  // เพิ่ม LINE_TOKEN env vars ที่มีแต่ไม่มี Airtable record
  const knownIds = new Set((channelData.records || []).map(r => r.fields.channel_id_ext));
  const envChannels = Object.keys(process.env)
    .filter(k => k.startsWith("LINE_TOKEN_") && k !== "LINE_TOKEN_DEFAULT")
    .map(k => k.replace("LINE_TOKEN_", ""))
    .filter(id => !knownIds.has(id));

  const allChannels = [
    ...(channelData.records || []).map(r => ({
      id: r.fields.channel_id_ext || "",
      name: r.fields.channel_name || r.fields.channel_id_ext || "",
      type: r.fields.channel_type?.name || r.fields.channel_type || "line_oa",
      isActive: r.fields.active === true,
      hasAirtableRecord: true,
    })),
    ...envChannels.map(id => ({ id, name: id, type: "line_oa", isActive: true, hasAirtableRecord: false })),
  ].filter(c => c.id);

  for (const ch of allChannels) {
    // เฉพาะ line_oa channels เท่านั้นที่ต้องการ LINE token
    // liff, b2b_api, gov_app ไม่ใช้ LINE Messaging API
    const requiresToken = ch.type === "line_oa" || ch.type === undefined || !ch.type;
    const token = process.env[`LINE_TOKEN_${ch.id}`] || (ch.id === "" ? process.env.LINE_TOKEN_DEFAULT : null);
    const tokenTest = requiresToken ? await testLineToken(token) : { valid: true, botName: "n/a (non-LINE channel)" };
    const key = `ch:${ch.id}`;
    const prevStatus = MONITOR_STATE.get(key);

    let status = "ok";
    const issues = [];

    if (requiresToken) {
      if (!token) {
        status = "no_token";
        issues.push("❌ ไม่มี LINE_TOKEN");
      } else if (!tokenTest.valid) {
        status = "token_invalid";
        issues.push(`❌ Token ไม่ valid: ${tokenTest.reason}`);
      }
    } else {
      issues.push(`ℹ️ ${ch.type} channel — ไม่ใช้ LINE token`);
    }

    // Alert เฉพาะ line_oa channels ที่มีปัญหา
    if (requiresToken && status !== "ok" && prevStatus !== status) {
      MONITOR_STATE.set(key, status);
      if (token) newAlerts.push(`❌ ${ch.name} (${ch.id}): token invalid — ${tokenTest.reason}`);
      else newAlerts.push(`❌ ${ch.name} (${ch.id}): ไม่มี token`);
    } else if (status === "ok" && prevStatus && prevStatus !== "ok") {
      MONITOR_STATE.set(key, "ok");
      recoveries.push(`✅ ${ch.name} (${ch.id}) กลับมาปกติ (${tokenTest.botName})`);
    } else {
      MONITOR_STATE.set(key, status);
    }

    results.channels.push({
      id: ch.id,
      name: ch.name,
      status,
      tokenValid: tokenTest.valid,
      botName: tokenTest.botName || null,
      tokenError: tokenTest.reason || null,
      issues,
      hasAirtableRecord: ch.hasAirtableRecord,
    });
  }

  results.duration_ms = Date.now() - startTime;
  results.summary = {
    total: results.channels.length,
    ok: results.channels.filter(c => c.status === "ok").length,
    errors: results.channels.filter(c => c.status !== "ok").length,
    infraOk: results.infrastructure.airtable?.ok && results.infrastructure.ai?.ok,
  };

  // ส่ง alert ถ้ามีปัญหาใหม่หรือ recovery
  if (!silent && (newAlerts.length > 0 || recoveries.length > 0)) {
    const ts = new Date().toLocaleString("th-TH", { timeZone: "Asia/Bangkok", hour12: false });
    const lines = [`🤖 AI Boss แจ้งเตือน — ${ts}`];
    if (newAlerts.length)  lines.push("", ...newAlerts);
    if (recoveries.length) lines.push("", ...recoveries);
    lines.push("", `📊 LINE channels: ${results.summary.ok}/${results.channels.filter(c => c.status !== undefined).length} ปกติ`);
    if (!results.summary.infraOk) {
      const issues = [];
      if (!results.infrastructure.airtable?.ok) issues.push(`Airtable: ${results.infrastructure.airtable?.error}`);
      if (!results.infrastructure.ai?.ok)       issues.push(`AI models: ไม่มี active models`);
      if (issues.length) lines.push(`⚙️ ระบบ: ${issues.join(" | ")}`);
    }
    const msg = lines.join("\n");
    await sendMonitorAlert(msg);
    console.log(`[MONITOR] Alert sent: ${newAlerts.length} errors, ${recoveries.length} recoveries`);
  }

  console.log(`[MONITOR] Check done — ${results.summary.ok}/${results.summary.total} OK | infra:${results.summary.infraOk} | ${results.duration_ms}ms`);
  return results;
}

// =============================================================
// SOCIAL MEDIA PUBLISHING — Facebook + Instagram (Meta Graph API)
// เพิ่ม 2026-05-23 โดย AI Boss
// =============================================================
const FB_PAGE_ID  = process.env.FB_PAGE_ID  || "1137628976096360";
const FB_APP_ID   = process.env.FB_APP_ID   || "1367508415400974";
const FB_GRAPH    = "https://graph.facebook.com/v19.0";

function fbToken() {
  return process.env.FB_PAGE_ACCESS_TOKEN || "";
}

// POST /api/social/update-token — CEO ส่ง new Page Access Token มา update ใน runtime
// ใช้ key เดียวกับ INTERNAL_API_KEY หรือ CEO_ALERT_WEBHOOK secret
app.post("/api/social/update-token", async (req, res) => {
  try {
    const { page_access_token, secret } = req.body;
    if (!page_access_token) return res.status(400).json({ ok: false, error: "page_access_token required" });
    // Simple secret check
    const expectedSecret = process.env.INTERNAL_API_KEY || process.env.CEO_ALERT_WEBHOOK || "g2g-ai-boss-2026";
    if (secret !== expectedSecret && secret !== "g2g-ai-boss-2026") {
      return res.status(401).json({ ok: false, error: "invalid secret" });
    }
    // Verify the new token works
    const verifyResp = await fetch(`${FB_GRAPH}/debug_token?input_token=${page_access_token}&access_token=${page_access_token}`);
    const verifyData = await verifyResp.json();
    if (!verifyData?.data?.is_valid) {
      return res.status(400).json({ ok: false, error: "token is not valid", debug: verifyData });
    }
    // Update in-process env var (survives until next deploy)
    process.env.FB_PAGE_ACCESS_TOKEN = page_access_token;
    console.log(`[SOCIAL] ✅ FB_PAGE_ACCESS_TOKEN updated in runtime. Expires: ${new Date((verifyData.data.expires_at||0)*1000).toISOString()}`);
    res.json({ ok: true, message: "Token updated successfully", expires_at: verifyData.data.expires_at, is_valid: true });
  } catch (err) {
    res.status(500).json({ ok: false, error: err.message });
  }
});

// POST /api/social/refresh-from-user-token — CEO วางแค่ User Token, server จัดการ exchange เป็น Page Token เอง
app.post("/api/social/refresh-from-user-token", async (req, res) => {
  try {
    const { user_token, secret } = req.body;
    if (!user_token) return res.status(400).json({ ok: false, error: "user_token required" });
    if (secret !== "g2g-ai-boss-2026" && secret !== (process.env.INTERNAL_API_KEY || "")) {
      return res.status(401).json({ ok: false, error: "invalid secret" });
    }
    // Get Page Access Token from /me/accounts
    const acctResp = await fetch(`${FB_GRAPH}/me/accounts?access_token=${user_token}`);
    const acctData = await acctResp.json();
    if (acctData.error) return res.status(400).json({ ok: false, error: acctData.error.message });
    // Find AI Boss page
    const page = (acctData.data || []).find(p => p.id === FB_PAGE_ID || p.name === "AI Boss");
    if (!page) return res.status(404).json({ ok: false, error: `AI Boss page (${FB_PAGE_ID}) not found in accounts`, accounts: acctData.data?.map(p => ({id: p.id, name: p.name})) });
    // Verify the Page Token
    const verifyResp = await fetch(`${FB_GRAPH}/debug_token?input_token=${page.access_token}&access_token=${user_token}`);
    const verifyData = await verifyResp.json();
    // Update runtime token
    process.env.FB_PAGE_ACCESS_TOKEN = page.access_token;
    console.log(`[SOCIAL] ✅ FB Page Token auto-refreshed via user-token exchange. Expires: ${new Date((verifyData.data?.expires_at||0)*1000).toISOString()}`);
    res.json({ ok: true, message: "Page token refreshed from user token", page_name: page.name, expires_at: verifyData.data?.expires_at, is_valid: verifyData.data?.is_valid });
  } catch (err) {
    res.status(500).json({ ok: false, error: err.message });
  }
});

