// POST /api/social/fb-post — โพสต์ข้อความ (+ รูป optional) ไปยัง AI Boss Facebook Page
app.post("/api/social/fb-post", async (req, res) => {
  try {
    const { message, image_url, scheduled_publish_time, published = true } = req.body;
    if (!message) return res.status(400).json({ ok: false, error: "message required" });
    const token = fbToken();
    if (!token) return res.status(500).json({ ok: false, error: "FB_PAGE_ACCESS_TOKEN not set" });

    let postId;
    if (image_url) {
      // โพสต์พร้อมรูป
      const body = { caption: message, url: image_url, published, access_token: token };
      if (scheduled_publish_time) { body.scheduled_publish_time = scheduled_publish_time; body.published = false; }
      const r = await fetch(`${FB_GRAPH}/${FB_PAGE_ID}/photos`, {
        method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body)
      });
      const d = await r.json();
      if (d.error) return res.status(400).json({ ok: false, error: d.error.message });
      postId = d.id || d.post_id;
    } else {
      // โพสต์ข้อความล้วน
      const body = { message, published, access_token: token };
      if (scheduled_publish_time) { body.scheduled_publish_time = scheduled_publish_time; body.published = false; }
      const r = await fetch(`${FB_GRAPH}/${FB_PAGE_ID}/feed`, {
        method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body)
      });
      const d = await r.json();
      if (d.error) return res.status(400).json({ ok: false, error: d.error.message });
      postId = d.id;
    }

    console.log(`[SOCIAL] FB post created: ${postId}`);
    res.json({ ok: true, post_id: postId, platform: "facebook" });
  } catch (err) {
    console.error("[SOCIAL] fb-post error:", err.message);
    res.status(500).json({ ok: false, error: err.message });
  }
});

// POST /api/social/ig-post — โพสต์รูป+caption ไปยัง Instagram @aiboss.g2g
// ต้องเชื่อม IG Business Account กับ AI Boss FB Page ก่อน
app.post("/api/social/ig-post", async (req, res) => {
  try {
    const { caption, image_url } = req.body;
    if (!caption || !image_url) return res.status(400).json({ ok: false, error: "caption and image_url required" });
    const token = fbToken();
    if (!token) return res.status(500).json({ ok: false, error: "FB_PAGE_ACCESS_TOKEN not set" });

    // Get IG Business Account ID from Page
    const pageResp = await fetch(`${FB_GRAPH}/${FB_PAGE_ID}?fields=instagram_business_account&access_token=${token}`);
    const pageData = await pageResp.json();
    const igId = pageData?.instagram_business_account?.id;
    if (!igId) return res.status(400).json({ ok: false, error: "IG Business Account not linked to FB Page. Please connect @aiboss.g2g to AI Boss Facebook Page." });

    // Step 1: Create media container
    const containerResp = await fetch(`${FB_GRAPH}/${igId}/media`, {
      method: "POST", headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ image_url, caption, access_token: token })
    });
    const containerData = await containerResp.json();
    if (containerData.error) return res.status(400).json({ ok: false, error: containerData.error.message });
    const creationId = containerData.id;

    // Step 2: Publish the container
    const publishResp = await fetch(`${FB_GRAPH}/${igId}/media_publish`, {
      method: "POST", headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ creation_id: creationId, access_token: token })
    });
    const publishData = await publishResp.json();
    if (publishData.error) return res.status(400).json({ ok: false, error: publishData.error.message });

    console.log(`[SOCIAL] IG post created: ${publishData.id}`);
    res.json({ ok: true, media_id: publishData.id, platform: "instagram" });
  } catch (err) {
    console.error("[SOCIAL] ig-post error:", err.message);
    res.status(500).json({ ok: false, error: err.message });
  }
});

// POST /api/social/publish-both — โพสต์พร้อมกันทั้ง FB + IG
app.post("/api/social/publish-both", async (req, res) => {
  try {
    const { message, caption, image_url } = req.body;
    const results = { facebook: null, instagram: null, errors: [] };

    // Facebook post
    try {
      const fbBody = { message: message || caption };
      if (image_url) fbBody.image_url = image_url;
      const fbResp = await fetch(`https://g2g-ai-pool.fly.dev/api/social/fb-post`, {
        method: "POST", headers: { "Content-Type": "application/json", "x-api-key": process.env.INTERNAL_API_KEY || "" },
        body: JSON.stringify(fbBody)
      });
      results.facebook = await fbResp.json();
    } catch (e) { results.errors.push(`FB: ${e.message}`); }

    // Instagram post
    if (image_url) {
      try {
        const igResp = await fetch(`https://g2g-ai-pool.fly.dev/api/social/ig-post`, {
          method: "POST", headers: { "Content-Type": "application/json", "x-api-key": process.env.INTERNAL_API_KEY || "" },
          body: JSON.stringify({ caption: caption || message, image_url })
        });
        results.instagram = await igResp.json();
      } catch (e) { results.errors.push(`IG: ${e.message}`); }
    }

    res.json({ ok: results.errors.length === 0, ...results });
  } catch (err) {
    res.status(500).json({ ok: false, error: err.message });
  }
});

// POST /api/social/generate-and-post — AI สร้างโพสต์อัตโนมัติ + publish
app.post("/api/social/generate-and-post", async (req, res) => {
  try {
    const { topic, tone = "professional", platforms = ["facebook"] } = req.body;
    const token = fbToken();
    if (!token) return res.status(500).json({ ok: false, error: "FB_PAGE_ACCESS_TOKEN not set" });

    // Generate content with Claude
    const prompt = `สร้างโพสต์ Social Media สำหรับ AI Boss (บริษัท G2G ที่ให้บริการ LINE AI สำหรับ SME และหน่วยงานรัฐไทย)
หัวข้อ: ${topic || "AI เปลี่ยนธุรกิจไทย"}
โทน: ${tone}
ความยาว: 150-250 ตัวอักษร
ให้มี: emoji, hashtag ที่เกี่ยวข้อง (#AIBoss #LineAI #G2G #DigitalThailand)
ภาษา: ไทย เป็นหลัก ผสมอังกฤษนิดหน่อย
ตอบแค่ข้อความโพสต์เท่านั้น ไม่ต้องมีคำอธิบาย`;

    const aiResp = await fetch("https://api.anthropic.com/v1/messages", {
      method: "POST",
      headers: { "x-api-key": process.env.ANTHROPIC_API_KEY, "anthropic-version": "2023-06-01", "Content-Type": "application/json" },
      body: JSON.stringify({ model: "claude-haiku-4-5", max_tokens: 500, messages: [{ role: "user", content: prompt }] })
    });
    const aiData = await aiResp.json();
    const generatedMessage = aiData?.content?.[0]?.text || "AI Boss — เปลี่ยนธุรกิจไทยด้วย LINE AI 🚀 #AIBoss";

    // Post to platforms
    const results = { message: generatedMessage, posts: {} };
    if (platforms.includes("facebook")) {
      const r = await fetch(`${FB_GRAPH}/${FB_PAGE_ID}/feed`, {
        method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ message: generatedMessage, access_token: token })
      });
      results.posts.facebook = await r.json();
    }

    console.log(`[SOCIAL] Auto-generated post published to ${platforms.join(", ")}`);
    res.json({ ok: true, ...results });
  } catch (err) {
    console.error("[SOCIAL] generate-and-post error:", err.message);
    res.status(500).json({ ok: false, error: err.message });
  }
});

// GET /api/social/status — ตรวจสอบ token และ connection status
app.get("/api/social/status", async (_req, res) => {
  try {
    const token = fbToken();
    if (!token) return res.json({ ok: false, error: "FB_PAGE_ACCESS_TOKEN not configured" });

    // Check FB Page
    const pageResp = await fetch(`${FB_GRAPH}/${FB_PAGE_ID}?fields=id,name,fan_count,instagram_business_account&access_token=${token}`);
    const pageData = await pageResp.json();

    // Check token debug
    const debugResp = await fetch(`${FB_GRAPH}/debug_token?input_token=${token}&access_token=${token}`);
    const debugData = await debugResp.json();

    res.json({
      ok: !pageData.error,
      facebook: {
        page_id: pageData.id,
        page_name: pageData.name,
        fans: pageData.fan_count,
        error: pageData.error?.message
      },
      instagram: {
        linked: !!pageData.instagram_business_account?.id,
        ig_id: pageData.instagram_business_account?.id
      },
      token: {
        is_valid: debugData?.data?.is_valid,
        expires_at: debugData?.data?.expires_at,
        expires_date: debugData?.data?.expires_at ? new Date(debugData.data.expires_at * 1000).toISOString() : "never",
        scopes: debugData?.data?.scopes
      }
    });
  } catch (err) {
    res.status(500).json({ ok: false, error: err.message });
  }
});

// GET /api/social/ig-diagnostic — ตรวจสอบ Instagram accounts ที่ user token เห็น
app.get("/api/social/ig-diagnostic", async (_req, res) => {
  try {
    const userToken = process.env.FB_LONG_LIVED_USER_TOKEN;
    const pageToken = process.env.FB_PAGE_ACCESS_TOKEN;
    const results = {};

    // 1. Check me/instagram_accounts with user token
    if (userToken) {
      const r1 = await fetch(`${FB_GRAPH}/me/instagram_accounts?access_token=${userToken}&fields=id,username,account_type,profile_picture_url`);
      results.me_instagram_accounts = await r1.json();

      // 2. Check me/accounts (pages the user manages)
      const r2 = await fetch(`${FB_GRAPH}/me/accounts?access_token=${userToken}&fields=id,name,instagram_business_account`);
      results.me_accounts_pages = await r2.json();
    } else {
      results.me_instagram_accounts = { error: "FB_LONG_LIVED_USER_TOKEN not set" };
    }

    // 3. Check page for connected_instagram_account (alternative field)
    if (pageToken) {
      const r3 = await fetch(`${FB_GRAPH}/${FB_PAGE_ID}?fields=id,name,instagram_business_account,connected_instagram_account&access_token=${pageToken}`);
      results.page_fields = await r3.json();
    }

    // 4. Try to get IG account 39088995938 info with page token
    if (pageToken) {
      const r4 = await fetch(`${FB_GRAPH}/39088995938?fields=id,username,account_type,profile_picture_url&access_token=${pageToken}`);
      results.ig_user_39088995938 = await r4.json();
    }

    res.json({ ok: true, results });
  } catch (err) {
    res.status(500).json({ ok: false, error: err.message });
  }
});

