const SOCIAL_POST_HOUR_ICT = 9; // 09:00 ไทย = 02:00 UTC
const WEEKLY_TOPICS = [
  "LINE AI ช่วย SME ประหยัดเวลา — case study จริง",
  "AI Chatbot สำหรับราชการไทย — ทำไมต้องใช้",
  "เพิ่มยอดขายด้วย LINE OA AI — 5 วิธีที่ได้ผล",
  "DigitalTransformation ในองค์กรไทย — เริ่มยังไง",
  "AI Boss ช่วย SME ไทยแข่งขันได้ — เรื่องจริง",
  "คุณค่าของ Data ในธุรกิจไทย — AI วิเคราะห์อะไรได้บ้าง",
  "สัปดาห์นี้ที่ G2G — อัปเดตผลิตภัณฑ์และบริการ"
];

async function checkAndAlertTokenExpiry() {
  try {
    const token = fbToken();
    if (!token) return;
    const resp = await fetch(`${FB_GRAPH}/debug_token?input_token=${token}&access_token=${token}`);
    const data = await resp.json();
    const expiresAt = data?.data?.expires_at;
    const isValid   = data?.data?.is_valid;
    if (!isValid) {
      const msg = `⚠️ AI Boss FB Token หมดอายุแล้ว!\n\nการโพสต์ Facebook จะล้มเหลว\n🔑 Refresh: https://g2g-ai-pool.fly.dev/api/social/token-refresh-url\nจากนั้น POST token ใหม่ไปที่ /api/social/update-token`;
      const webhook = process.env.CEO_ALERT_WEBHOOK;
      if (webhook) await fetch(webhook, { method: "POST", headers: {"Content-Type":"application/json"}, body: JSON.stringify({text: msg}) }).catch(()=>{});
      console.log("[SOCIAL] ⚠️ FB Token expired — alert sent");
    } else if (expiresAt && expiresAt > 0) {
      const hoursLeft = (expiresAt - Date.now()/1000) / 3600;
      if (hoursLeft < 24 && hoursLeft > 0) {
        const msg = `⏰ AI Boss FB Token จะหมดอายุในอีก ${Math.round(hoursLeft)} ชั่วโมง!\n🔑 Refresh ได้ที่: https://g2g-ai-pool.fly.dev/api/social/token-refresh-url`;
        const webhook = process.env.CEO_ALERT_WEBHOOK;
        if (webhook) await fetch(webhook, { method: "POST", headers: {"Content-Type":"application/json"}, body: JSON.stringify({text: msg}) }).catch(()=>{});
        console.log(`[SOCIAL] ⏰ FB Token expires in ${Math.round(hoursLeft)}h`);
      }
    }
  } catch(e) { console.error("[SOCIAL] Token check error:", e.message); }
}

function startSocialAutoPost() {
  console.log("[SOCIAL] 📅 Starting weekly auto-post scheduler (7x/week at 09:00 ICT)");
  // Check token expiry every hour
  setInterval(checkAndAlertTokenExpiry, 60 * 60 * 1000);
  setTimeout(checkAndAlertTokenExpiry, 5000); // initial check after 5s

  setInterval(async () => {
    const now = new Date();
    const hourUTC = now.getUTCHours();
    const minUTC  = now.getUTCMinutes();
    if (hourUTC !== 2 || minUTC > 5) return; // 02:00-02:05 UTC = 09:00-09:05 ICT
    const dayIdx = now.getUTCDay(); // 0=Sun, 1=Mon...
    const topic = WEEKLY_TOPICS[dayIdx] || WEEKLY_TOPICS[0];
    try {
      const token = fbToken();
      if (!token) { console.log("[SOCIAL] Skipping — no FB token"); return; }
      const prompt = `สร้างโพสต์ Social Media สำหรับ AI Boss (G2G — LINE AI สำหรับ SME และราชการไทย)
หัวข้อวันนี้: ${topic}
ความยาว: 150-250 ตัวอักษร พร้อม emoji และ hashtag (#AIBoss #LineAI #G2G #DigitalThailand)
ภาษาไทย + อังกฤษนิดหน่อย ตอบแค่ข้อความโพสต์`;
      const aiResp = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST",
        headers: { "x-api-key": process.env.ANTHROPIC_API_KEY, "anthropic-version": "2023-06-01", "Content-Type": "application/json" },
        body: JSON.stringify({ model: "claude-haiku-4-5", max_tokens: 400, messages: [{ role: "user", content: prompt }] })
      });
      const aiData = await aiResp.json();
      const message = aiData?.content?.[0]?.text;
      if (!message) return;
      const r = await fetch(`${FB_GRAPH}/${FB_PAGE_ID}/feed`, {
        method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ message, access_token: token })
      });
      const postData = await r.json();
      if (postData.id) console.log(`[SOCIAL] ✅ Daily auto-post published: ${postData.id} | topic: ${topic}`);
      else console.log(`[SOCIAL] ❌ Auto-post failed:`, JSON.stringify(postData));
    } catch (e) { console.error("[SOCIAL] Auto-post error:", e.message); }
  }, 5 * 60 * 1000); // check every 5 minutes
}

