// =============================================================
// TIKTOK INTEGRATION
// TikTok Content Posting API v2
// Docs: https://developers.tiktok.com/doc/content-posting-api-get-started
// =============================================================
const TIKTOK_CLIENT_KEY    = process.env.TIKTOK_CLIENT_KEY    || "";
const TIKTOK_CLIENT_SECRET = process.env.TIKTOK_CLIENT_SECRET || "";
const TIKTOK_REDIRECT_URI  = process.env.TIKTOK_REDIRECT_URI  || "https://g2g-ai-pool.fly.dev/api/tiktok/callback";
const TIKTOK_BASE          = "https://open.tiktokapis.com/v2";
const TIKTOK_AUTH_URL      = "https://www.tiktok.com/v2/auth/authorize/";

// Runtime token store (persists in memory; use fly secrets for long-lived tokens)
let tiktokTokens = {
  access_token:  process.env.TIKTOK_ACCESS_TOKEN  || "",
  refresh_token: process.env.TIKTOK_REFRESH_TOKEN || "",
  open_id:       process.env.TIKTOK_OPEN_ID       || "",
  // If loaded from env, assume token valid for ~24h from boot
  expires_at:    process.env.TIKTOK_ACCESS_TOKEN ? Date.now() + 86400 * 1000 : 0,
};

// PKCE state store: state → { code_verifier, created_at }
const tiktokPkceStore = new Map();

// PKCE helpers
function base64urlEncode(buf) {
  return buf.toString("base64").replace(/\+/g, "-").replace(/\//g, "_").replace(/=/g, "");
}
async function generatePkce() {
  const verifier = base64urlEncode(crypto.randomBytes(32));
  const challenge = base64urlEncode(
    crypto.createHash("sha256").update(verifier).digest()
  );
  return { verifier, challenge };
}

// --- GET /api/tiktok/auth  — redirect user to TikTok OAuth (with PKCE) ---
app.get("/api/tiktok/auth", async (req, res) => {
  if (!TIKTOK_CLIENT_KEY) return res.status(500).json({ ok: false, error: "TIKTOK_CLIENT_KEY not set — fly secrets set TIKTOK_CLIENT_KEY=..." });
  const state = crypto.randomBytes(16).toString("hex");
  const { verifier, challenge } = await generatePkce();
  // Store verifier keyed by state (TTL 10 min)
  tiktokPkceStore.set(state, { code_verifier: verifier, created_at: Date.now() });
  setTimeout(() => tiktokPkceStore.delete(state), 10 * 60 * 1000);

  const scopes = [
    "user.info.basic",
    "video.upload",
    "video.publish",
  ].join(",");
  const url = `${TIKTOK_AUTH_URL}?client_key=${TIKTOK_CLIENT_KEY}&scope=${encodeURIComponent(scopes)}&response_type=code&redirect_uri=${encodeURIComponent(TIKTOK_REDIRECT_URI)}&state=${state}&code_challenge=${challenge}&code_challenge_method=S256`;
  console.log(`[TIKTOK] Auth redirect — state=${state} challenge=${challenge}`);
  res.redirect(url);
});


// --- GET /api/tiktok/callback  — exchange code for token ---
app.get("/api/tiktok/callback", async (req, res) => {
  const { code, state, error, error_description } = req.query;
  if (error) return res.status(400).send(`TikTok OAuth Error: ${error} — ${error_description}`);
  if (!code)  return res.status(400).send("Missing code param");
  if (!TIKTOK_CLIENT_KEY || !TIKTOK_CLIENT_SECRET)
    return res.status(500).send("TIKTOK_CLIENT_KEY or TIKTOK_CLIENT_SECRET not configured");

  // Retrieve PKCE verifier
  const pkceEntry = state ? tiktokPkceStore.get(state) : null;
  const code_verifier = pkceEntry ? pkceEntry.code_verifier : null;
  if (pkceEntry) tiktokPkceStore.delete(state);
  console.log(`[TIKTOK] Callback — state=${state} pkce_found=${!!code_verifier} code_prefix=${code.slice(0,12)}`);

  try {
    const tokenBody = {
      client_key:    TIKTOK_CLIENT_KEY,
      client_secret: TIKTOK_CLIENT_SECRET,
      code,
      grant_type:    "authorization_code",
      redirect_uri:  TIKTOK_REDIRECT_URI,
    };
    if (code_verifier) tokenBody.code_verifier = code_verifier;

    const params = new URLSearchParams(tokenBody);
    console.log(`[TIKTOK] Token exchange body: ${params.toString().replace(TIKTOK_CLIENT_SECRET, "***")}`);
    const tokenResp = await fetch(`${TIKTOK_BASE}/oauth/token/`, {
      method: "POST",
      headers: { "Content-Type": "application/x-www-form-urlencoded" },
      body: params.toString(),
    });
    const tokenData = await tokenResp.json();
    console.log(`[TIKTOK] Token response: ${JSON.stringify(tokenData)}`);
    if (tokenData.error) return res.status(400).json({ ok: false, error: tokenData.error, desc: tokenData.error_description, full: tokenData });

    tiktokTokens = {
      access_token:  tokenData.access_token,
      refresh_token: tokenData.refresh_token,
      open_id:       tokenData.open_id,
      expires_at:    Date.now() + (tokenData.expires_in || 86400) * 1000,
    };

    console.log(`[TIKTOK] ✅ OAuth success! open_id=${tiktokTokens.open_id}`);
    res.json({
      ok: true,
      message: "TikTok linked! ✅",
      open_id: tiktokTokens.open_id,
      expires_in: tokenData.expires_in,
      scopes: tokenData.scope,
    });
  } catch (err) {
    res.status(500).json({ ok: false, error: err.message });
  }
});

// --- POST /api/tiktok/refresh — refresh access token ---
app.post("/api/tiktok/refresh", async (req, res) => {
  const refresh_token = req.body?.refresh_token || tiktokTokens.refresh_token;
  if (!refresh_token) return res.status(400).json({ ok: false, error: "No refresh_token" });

  try {
    const params = new URLSearchParams({
      client_key:    TIKTOK_CLIENT_KEY,
      client_secret: TIKTOK_CLIENT_SECRET,
      grant_type:    "refresh_token",
      refresh_token,
    });
    const r = await fetch(`${TIKTOK_BASE}/oauth/token/`, {
      method: "POST",
      headers: { "Content-Type": "application/x-www-form-urlencoded" },
      body: params.toString(),
    });
    const data = await r.json();
    if (data.error) return res.status(400).json({ ok: false, error: data.error });
    tiktokTokens.access_token  = data.access_token;
    tiktokTokens.refresh_token = data.refresh_token || refresh_token;
    tiktokTokens.expires_at    = Date.now() + (data.expires_in || 86400) * 1000;
    console.log("[TIKTOK] ✅ Token refreshed");
    res.json({ ok: true, expires_in: data.expires_in });
  } catch (err) {
    res.status(500).json({ ok: false, error: err.message });
  }
});

// --- POST /api/tiktok/post — upload video to TikTok ---
// Body: { video_url: "https://...", title: "...", privacy: "PUBLIC_TO_EVERYONE" }
app.post("/api/tiktok/post", async (req, res) => {
  if (!tiktokTokens.access_token) return res.status(401).json({ ok: false, error: "TikTok not linked. Visit /api/tiktok/auth first" });
  const { video_url, title = "", privacy = "PUBLIC_TO_EVERYONE" } = req.body || {};
  if (!video_url) return res.status(400).json({ ok: false, error: "video_url required" });

  try {
    // Step 1: Init upload
    const initResp = await fetch(`${TIKTOK_BASE}/post/publish/video/init/`, {
      method: "POST",
      headers: {
        "Authorization": `Bearer ${tiktokTokens.access_token}`,
        "Content-Type": "application/json; charset=UTF-8",
      },
      body: JSON.stringify({
        post_info: {
          title: title.slice(0, 150),
          privacy_level: privacy,
          disable_duet: false,
          disable_comment: false,
          disable_stitch: false,
        },
        source_info: {
          source: "PULL_FROM_URL",
          video_url,
        },
      }),
    });
    const initData = await initResp.json();
    if (initData.error?.code && initData.error.code !== "ok") {
      return res.status(400).json({ ok: false, error: initData.error.message, code: initData.error.code });
    }

    const publish_id = initData.data?.publish_id;
    console.log(`[TIKTOK] ✅ Video upload initiated: publish_id=${publish_id}`);
    res.json({ ok: true, publish_id, message: "Video upload initiated — TikTok will process and publish" });
  } catch (err) {
    res.status(500).json({ ok: false, error: err.message });
  }
});


// --- GET /api/tiktok/status — check TikTok connection ---
app.get("/api/tiktok/status", async (_req, res) => {
  if (!tiktokTokens.access_token) {
    return res.json({
      ok: true,
      linked: false,
      auth_url: TIKTOK_CLIENT_KEY ? `https://g2g-ai-pool.fly.dev/api/tiktok/auth` : null,
      message: TIKTOK_CLIENT_KEY ? "Visit auth_url to link TikTok" : "TIKTOK_CLIENT_KEY not configured",
    });
  }

  try {
    const userResp = await fetch(`${TIKTOK_BASE}/user/info/?fields=open_id,union_id,avatar_url,display_name,profile_deep_link,bio_description,follower_count,following_count,likes_count,video_count`, {
      headers: { "Authorization": `Bearer ${tiktokTokens.access_token}` },
    });
    const userData = await userResp.json();
    const user = userData?.data?.user;
    res.json({
      ok: true,
      linked: true,
      open_id: tiktokTokens.open_id,
      expires_at: new Date(tiktokTokens.expires_at).toISOString(),
      user: user ? {
        display_name:   user.display_name,
        follower_count: user.follower_count,
        video_count:    user.video_count,
        profile_link:   user.profile_deep_link,
      } : null,
    });
  } catch (err) {
    res.status(500).json({ ok: false, error: err.message });
  }
});

