// GET /api/line/health — basic check (fast)
app.get("/api/line/health", async (_req, res) => {
  try {
    const data = await airtableGet(ONLOAD_TABLE_SAFE(), { maxRecords: 100 }).catch(() => ({ records: [] }));
    const channels = (data.records || []).map(r => {
      const id   = r.fields.channel_id_ext || "";
      const name = r.fields.channel_name   || id;
      const chType = r.fields.channel_type?.name || r.fields.channel_type || "line_oa";
      // เฉพาะ line_oa ต้องการ LINE token; liff/b2b_api/gov_app ไม่ต้องการ
      const requiresToken = chType === "line_oa";
      const token = process.env[`LINE_TOKEN_${id}`];
      const hasToken = !!token;
      const isActive = r.fields.active === true;
      const issues = [];
      let status = "ok";
      if (requiresToken && !hasToken) { status = "error"; issues.push("❌ ไม่มี LINE_TOKEN env var"); }
      if (!isActive) { if (status !== "error") status = "warn"; issues.push("⚠️ active=false"); }
      if (requiresToken && !r.fields.system_prompt) issues.push("ℹ️ ใช้ default prompt");
      if (!requiresToken) issues.push(`ℹ️ ${chType} channel — ไม่ใช้ LINE token`);
      return { id, name, type: chType, status, hasToken, requiresToken, isActive, issues,
               webhookUrl: requiresToken ? `https://g2g-ai-pool.fly.dev/line/webhook/${id}` : null,
               flySecret: requiresToken ? `LINE_TOKEN_${id}` : null };
    });
    const lineOaChannels = channels.filter(c => c.requiresToken);
    const errors  = lineOaChannels.filter(c => c.status === "error").length;
    const healthy = lineOaChannels.filter(c => c.status === "ok").length;
    res.json({ ok: errors === 0,
               summary: { total: channels.length, lineOa: lineOaChannels.length, healthy, errors },
               channels, checkedAt: new Date().toISOString() });
  } catch (err) {
    res.status(500).json({ ok: false, error: err.message });
  }
});

