// ----------------------------------------------------------
// GET /api/phrae/weather — พยากรณ์อากาศ + วิเคราะห์ผลกระทบต่อพืช (Phrae)
// ----------------------------------------------------------
app.get("/api/phrae/weather", phraeCors, async (req, res) => {
  try {
    const cacheKey = "phrae_weather_v2";
    const cached = cacheGet(cacheKey);
    if (cached) return res.json(cached);

    // Open-Meteo API — free, no API key, จังหวัดแพร่ lat 18.14 lon 100.16
    const weatherUrl = "https://api.open-meteo.com/v1/forecast?latitude=18.14&longitude=100.16" +
      "&daily=temperature_2m_max,temperature_2m_min,precipitation_sum,weathercode," +
      "windspeed_10m_max,relative_humidity_2m_max,relative_humidity_2m_min" +
      "&hourly=temperature_2m,precipitation,windspeed_10m,relativehumidity_2m" +
      "&current_weather=true&timezone=Asia%2FBangkok&forecast_days=7";

    const wResp = await fetch(weatherUrl);
    if (!wResp.ok) throw new Error("Open-Meteo API error: " + wResp.status);
    const wData = await wResp.json();

    // Build 7-day forecast summary
    const daily = wData.daily;
    const forecast = [];
    for (let i = 0; i < (daily.time?.length || 0); i++) {
      forecast.push({
        date:       daily.time[i],
        maxTemp:    daily.temperature_2m_max[i],
        minTemp:    daily.temperature_2m_min[i],
        rain:       daily.precipitation_sum[i],
        windMax:    daily.windspeed_10m_max[i],
        humidMax:   daily.relative_humidity_2m_max?.[i],
        humidMin:   daily.relative_humidity_2m_min?.[i],
        weatherCode: daily.weathercode[i],
      });
    }

    // AI crop-impact analysis via Claude
    const today = new Date().toLocaleDateString("th-TH", { year: "numeric", month: "long", day: "numeric" });
    const forecastText = forecast.map(d =>
      `${d.date}: อุณหภูมิ ${d.minTemp}–${d.maxTemp}°C ฝน ${d.rain}mm ลม ${d.windMax}km/h ความชื้น ${d.humidMin}–${d.humidMax}%`
    ).join("\n");

    const aiPrompt = `วันที่ ${today} พยากรณ์อากาศจังหวัดแพร่ 7 วัน:\n${forecastText}\n\n` +
      `วิเคราะห์ผลกระทบต่อพืชหลักจังหวัดแพร่ ได้แก่ ลำไย ส้มโอ ส้มเขียวหวาน ทุเรียน โดยระบุ:\n` +
      `1. ความเสี่ยงโรค/แมลง (ถ้ามี)\n2. คำแนะนำการดูแลรักษา\n3. ข้อควรระวังสำคัญ\nตอบกระชับ ภาษาเกษตรกรเข้าใจง่าย`;

    let cropAnalysis = "ไม่สามารถวิเคราะห์ได้ในขณะนี้";
    try {
      const aiResp = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST",
        headers: {
          "x-api-key": process.env.ANTHROPIC_API_KEY,
          "anthropic-version": "2023-06-01",
          "content-type": "application/json",
        },
        body: JSON.stringify({
          model: "claude-opus-4-7",
          max_tokens: 600,
          messages: [{ role: "user", content: aiPrompt }],
        }),
      });
      if (aiResp.ok) {
        const aiData = await aiResp.json();
        cropAnalysis = aiData.content?.[0]?.text || cropAnalysis;
      }
    } catch (aiErr) {
      console.error("[PHRAE] AI crop analysis error:", aiErr.message);
    }

    const result = {
      ok: true,
      current: wData.current_weather,
      forecast,
      cropAnalysis,
      fetchedAt: new Date().toISOString(),
    };

    cacheSet(cacheKey, result, 30 * 60 * 1000); // cache 30 นาที
    res.json(result);
  } catch (err) {
    console.error("[PHRAE] GET /weather error:", err.message);
    res.status(500).json({ ok: false, error: err.message });
  }
});

// ----------------------------------------------------------
// GET /api/phrae/prices — ราคาสินค้าเกษตรปัจจุบัน
// ----------------------------------------------------------
app.get("/api/phrae/prices", phraeCors, async (req, res) => {
  try {
    // ดึงจาก Airtable ถ้ามี MarketPrices table
    let airtablePrices = null;
    try {
      const data = await phraeGet("MarketPrices", {
        maxRecords: 50,
        sort: [{ field: "date", direction: "desc" }],
        filterByFormula: `DATETIME_DIFF(NOW(), {date}, "days") <= 3`,
      });
      if (data.records?.length > 0) {
        airtablePrices = data.records.map(r => ({
          id:      r.id,
          crop:    r.fields.crop || "",
          grade:   r.fields.grade || "",
          unit:    r.fields.unit || "กก.",
          price:   r.fields.price || 0,
          source:  r.fields.source || "",
          date:    r.fields.date || "",
          note:    r.fields.note || "",
        }));
      }
    } catch (_e) {
      // MarketPrices table ยังไม่มี — ใช้ in-memory
    }

    res.json({
      ok: true,
      updatedAt: PHRAE_PRICES.updatedAt,
      source: airtablePrices ? "airtable" : "memory",
      prices: airtablePrices || PHRAE_PRICES.items,
    });
  } catch (err) {
    console.error("[PHRAE] GET /prices error:", err.message);
    res.status(500).json({ ok: false, error: err.message });
  }
});

// ----------------------------------------------------------
// POST /api/phrae/prices — อัปเดตราคา (admin only)
// ----------------------------------------------------------
app.post("/api/phrae/prices", phraeCors, phraeAuth, async (req, res) => {
  try {
    const { prices } = req.body; // array ของ { crop, grade, unit, price, source, note }
    if (!Array.isArray(prices)) return res.status(400).json({ ok: false, error: "prices array required" });

    // บันทึกลง Airtable MarketPrices
    const today = new Date().toISOString().split("T")[0];
    const records = [];
    for (const p of prices) {
      try {
        const rec = await phraePost("MarketPrices", {
          crop:   p.crop,
          grade:  p.grade || "",
          unit:   p.unit || "กก.",
          price:  Number(p.price),
          source: p.source || "ตลาดกลาง",
          note:   p.note || "",
          date:   today,
          updatedBy: "admin",
        });
        records.push(rec.id);
      } catch (_e) {
        // ถ้า Airtable fail ก็ fallback in-memory
      }
    }

    // อัปเดต in-memory ด้วย
    PHRAE_PRICES.updatedAt = new Date().toISOString();
    PHRAE_PRICES.items = prices.map(p => ({
      crop: p.crop, grade: p.grade || "", unit: p.unit || "กก.",
      price: Number(p.price), note: p.note || "",
    }));

    res.json({ ok: true, savedRecords: records.length, updatedAt: PHRAE_PRICES.updatedAt });
  } catch (err) {
    console.error("[PHRAE] POST /prices error:", err.message);
    res.status(500).json({ ok: false, error: err.message });
  }
});

