// ----------------------------------------------------------
// POST /api/phrae/alerts — เพิ่มแจ้งเตือนโรค/แมลงใหม่ (admin)
// ----------------------------------------------------------
app.post("/api/phrae/alerts", phraeCors, phraeAuth, async (req, res) => {
  try {
    const { title, crop, pest_type, severity, area, description, remedy } = req.body;
    if (!title) return res.status(400).json({ ok: false, error: "title required" });

    const fields = {
      title, crop: crop || "", pest_type: pest_type || "",
      severity: severity || "medium", area: area || "",
      description: description || "", remedy: remedy || "",
      created_at: new Date().toISOString(), active: true,
    };

    let id = `mem_${Date.now()}`;
    try {
      const rec = await phraePost("PestAlerts", fields);
      id = rec.id;
    } catch (_e) {
      PHRAE_ALERTS.unshift({ id, ...fields });
    }

    res.json({ ok: true, id, message: "Alert created" });
  } catch (err) {
    console.error("[PHRAE] POST /alerts error:", err.message);
    res.status(500).json({ ok: false, error: err.message });
  }
});

// ----------------------------------------------------------
// POST /api/phrae/reports/generate — สร้างรายงาน AI จากข้อมูลจริง
// ----------------------------------------------------------
app.post("/api/phrae/reports/generate", phraeCors, phraeAuth, async (req, res) => {
  try {
    const { report_type, period, agency } = req.body;
    // รวบรวมข้อมูลจริงทั้งหมด
    const [farmersData, weatherResp, alertsResp] = await Promise.allSettled([
      phraeGet("FarmerRegistration", { maxRecords: 500 }),
      fetch("https://api.open-meteo.com/v1/forecast?latitude=18.14&longitude=100.16&current_weather=true&timezone=Asia%2FBangkok"),
      phraeGet("PestAlerts", { maxRecords: 10, filterByFormula: "{active}=TRUE()" }),
    ]);

    const farmers = farmersData.status === "fulfilled" ? farmersData.value.records || [] : [];
    const weather = weatherResp.status === "fulfilled" && weatherResp.value.ok
      ? await weatherResp.value.json() : null;
    const alerts  = alertsResp.status === "fulfilled" ? alertsResp.value.records || [] : [];

    // สถิติเกษตรกร
    const totalFarmers = farmers.length;
    const activeFarmers = farmers.filter(f => f.fields.status === "active" || !f.fields.status).length;
    const cropBreakdown = {};
    farmers.forEach(f => {
      const c = f.fields.main_crop || "ไม่ระบุ";
      cropBreakdown[c] = (cropBreakdown[c] || 0) + 1;
    });
    const cropSummary = Object.entries(cropBreakdown).map(([k, v]) => `${k}: ${v} ราย`).join(", ");

    // รายงาน weekly จาก AgencyReports
    let reportsSummary = "ยังไม่มีข้อมูลรายงานหน่วยงาน";
    try {
      const week = getWeekNumber(new Date());
      const rData = await phraeGet("AgencyReports", {
        maxRecords: 20,
        filterByFormula: `{week}=${week}`,
      });
      if (rData.records?.length > 0) {
        const totalVisits = rData.records.reduce((s, r) => s + (r.fields.farmers_visited || 0), 0);
        reportsSummary = `สัปดาห์ที่ ${week}: ${rData.records.length} หน่วยงานส่งรายงาน, เยี่ยมเกษตรกรรวม ${totalVisits} ราย`;
      }
    } catch (_e) {}

    // สร้าง prompt สำหรับ Claude
    const reportDate = new Date().toLocaleDateString("th-TH", { year: "numeric", month: "long", day: "numeric" });
    const currentWeather = weather?.current_weather ? `อุณหภูมิ ${weather.current_weather.temperature}°C ลม ${weather.current_weather.windspeed} km/h` : "ไม่มีข้อมูล";
    const alertCount = alerts.length;

    const prompt = `สร้าง${report_type === "executive" ? "รายงานสรุปผู้บริหาร" : "รายงานประจำ" + (period || "สัปดาห์")} ภาคเกษตรจังหวัดแพร่
วันที่: ${reportDate}
${agency ? `หน่วยงาน: ${agency}` : ""}

ข้อมูลจริง:
- เกษตรกรในระบบ: ${totalFarmers} ราย (ใช้งานอยู่ ${activeFarmers} ราย)
- พืชหลัก: ${cropSummary || "ไม่มีข้อมูล"}
- สภาพอากาศวันนี้: ${currentWeather}
- การแจ้งเตือนโรค/แมลงที่ active: ${alertCount} รายการ
- สรุปรายงานหน่วยงาน: ${reportsSummary}
- ราคาตลาด: ${PHRAE_PRICES.updatedAt ? `อัปเดตล่าสุด ${new Date(PHRAE_PRICES.updatedAt).toLocaleDateString("th-TH")}` : "ยังไม่มีข้อมูลราคา"}

สร้างรายงานครอบคลุม: สรุปภาพรวม, ความคืบหน้า, ปัญหา, ข้อเสนอแนะ, แผนการดำเนินงาน
ภาษาทางการ เหมาะสำหรับ${report_type === "executive" ? "ผู้ว่าราชการจังหวัด/รัฐมนตรี" : "หัวหน้าหน่วยงาน"}`;

    const aiResp = await fetch("https://api.anthropic.com/v1/messages", {
      method: "POST",
      headers: {
        "x-api-key": process.env.ANTHROPIC_API_KEY,
        "anthropic-version": "2023-06-01",
        "content-type": "application/json",
      },
      body: JSON.stringify({
        model: "claude-opus-4-7",
        max_tokens: 1500,
        messages: [{ role: "user", content: prompt }],
      }),
    });

    if (!aiResp.ok) throw new Error(`Claude API error: ${aiResp.status}`);
    const aiData = await aiResp.json();
    const reportText = aiData.content?.[0]?.text || "ไม่สามารถสร้างรายงานได้";

    // บันทึก log
    try {
      await phraePost("GeneratedReports", {
        report_type: report_type || "weekly",
        period: period || "weekly",
        agency: agency || "all",
        content: reportText,
        generated_at: new Date().toISOString(),
        data_snapshot: JSON.stringify({ totalFarmers, activeFarmers, alertCount }),
      });
    } catch (_e) {}

    res.json({
      ok: true,
      report_type: report_type || "weekly",
      generated_at: new Date().toISOString(),
      report: reportText,
      data_used: { totalFarmers, activeFarmers, alertCount, weatherAvailable: !!weather },
    });
  } catch (err) {
    console.error("[PHRAE] POST /reports/generate error:", err.message);
    res.status(500).json({ ok: false, error: err.message });
  }
});

