app.get("/api/phrae/keyfacts", phraeCors, async (req, res) => {
  try {
    const cacheKey = "phrae_keyfacts_v1";
    const cached = cacheGet(cacheKey);
    if (cached) return res.json(cached);

    const data = await phraeGet("KeyFacts", { maxRecords: 100 });
    const facts = (data.records || []).map(r => ({
      id:       r.id,
      category: r.fields.category || r.fields.Category || "",
      key:      r.fields.key || r.fields.Key || "",
      value:    r.fields.value || r.fields.Value || "",
      unit:     r.fields.unit || "",
      year:     r.fields.year || "",
      source:   r.fields.source || "",
    }));

    const result = { ok: true, total: facts.length, facts };
    cacheSet(cacheKey, result, 60 * 60 * 1000); // cache 1 ชั่วโมง
    res.json(result);
  } catch (err) {
    console.error("[PHRAE] GET /keyfacts error:", err.message);
    res.status(500).json({ ok: false, error: err.message });
  }
});

// ----------------------------------------------------------
// GET /api/phrae/dashboard — สรุปภาพรวม dashboard (combined)
// ----------------------------------------------------------
app.get("/api/phrae/dashboard", phraeCors, async (req, res) => {
  try {
    const cacheKey = "phrae_dashboard_v1";
    const cached = cacheGet(cacheKey);
    if (cached) return res.json(cached);

    const [farmersR, alertsR, reportsR] = await Promise.allSettled([
      phraeGet("FarmerRegistration", { maxRecords: 500, fields: ["Name", "status", "main_crop", "village"] }),
      phraeGet("PestAlerts", { maxRecords: 5, filterByFormula: "{active}=TRUE()", sort: [{ field: "created_at", direction: "desc" }] }),
      phraeGet("AgencyReports", { maxRecords: 20, filterByFormula: `{week}=${getWeekNumber(new Date())}` }),
    ]);

    const farmers = farmersR.status === "fulfilled" ? farmersR.value.records || [] : [];
    const alerts  = alertsR.status  === "fulfilled" ? alertsR.value.records  || [] : [];
    const reports = reportsR.status === "fulfilled" ? reportsR.value.records  || [] : [];

    const cropBreakdown = {};
    farmers.forEach(f => {
      const c = f.fields.main_crop || "อื่นๆ";
      cropBreakdown[c] = (cropBreakdown[c] || 0) + 1;
    });

    const result = {
      ok: true,
      summary: {
        totalFarmers:      farmers.length,
        activeFarmers:     farmers.filter(f => f.fields.status !== "inactive").length,
        activeAlerts:      alerts.length,
        reportsThisWeek:   reports.length,
        pricesUpdated:     PHRAE_PRICES.updatedAt,
      },
      cropBreakdown,
      recentAlerts: alerts.map(r => ({
        id:       r.id,
        title:    r.fields.title,
        crop:     r.fields.crop,
        severity: r.fields.severity,
        area:     r.fields.area,
      })),
      weeklyReports: reports.map(r => ({
        agency_name:     r.fields.agency_name,
        farmers_visited: r.fields.farmers_visited || 0,
        status:          r.fields.status,
      })),
      updatedAt: new Date().toISOString(),
    };

    cacheSet(cacheKey, result, 10 * 60 * 1000); // cache 10 นาที
    res.json(result);
  } catch (err) {
    console.error("[PHRAE] GET /dashboard error:", err.message);
    res.status(500).json({ ok: false, error: err.message });
  }
});

// Helper: คำนวณ ISO week number
function getWeekNumber(d) {
  const date = new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()));
  date.setUTCDate(date.getUTCDate() + 4 - (date.getUTCDay() || 7));
  const yearStart = new Date(Date.UTC(date.getUTCFullYear(), 0, 1));
  return Math.ceil((((date - yearStart) / 86400000) + 1) / 7);
}

// =============================================================
// MANAGEMENT PLATFORM API — บริหารระบบกระทรวงเกษตรจังหวัดแพร่
// Tables: Personnel_GSA, Budget_FY2568, Projects_2568,
//         Contracts_GSA, Integration_Plans
// =============================================================

// -- GET /api/phrae/management/summary -------------------------
app.get("/api/phrae/management/summary", phraeCors, async (req, res) => {
  try {
    const cacheKey = "phrae_mgmt_summary_v1";
    const cached = cacheGet(cacheKey);
    if (cached) return res.json(cached);

    // Try Airtable; fall back to static cache on any error (e.g. 403 token scope)
    let personnel, budgets, projects, contracts, intPlans;
    try {
      const [perR, budR, prjR, ctrR, intR] = await Promise.allSettled([
        phraeGet("Personnel_GSA", { maxRecords: 500 }),
        phraeGet("Budget_FY2568", { maxRecords: 100 }),
        phraeGet("Projects_2568", { maxRecords: 200 }),
        phraeGet("Contracts_GSA", { maxRecords: 200 }),
        phraeGet("Integration_Plans", { maxRecords: 100 }),
      ]);
      // Use raw Airtable records (has .fields)
      const _per = perR.status === "fulfilled" ? perR.value.records || [] : [];
      const _bud = budR.status === "fulfilled" ? budR.value.records || [] : [];
      const _prj = prjR.status === "fulfilled" ? prjR.value.records || [] : [];
      const _ctr = ctrR.status === "fulfilled" ? ctrR.value.records || [] : [];
      const _int = intR.status === "fulfilled" ? intR.value.records || [] : [];
      // If Airtable returned zero results for all (likely 403), fall back
      if (_per.length === 0 && _bud.length === 0 && _prj.length === 0) throw new Error("empty");
      // Map to summary format from raw Airtable records
      const sc = mgmtStatic(); // also load static for fallback calculations
      personnel = _per; budgets = _bud; projects = _prj; contracts = _ctr; intPlans = _int;
    } catch (_) {
      console.warn("[MGMT] /summary using static cache");
      const sc = mgmtStatic();
      personnel = sc.personnel || [];
      budgets   = sc.budget    || [];
      projects  = sc.projects  || [];
      contracts = sc.contracts || [];
      intPlans  = sc.integration || [];
      // Static cache items are already mapped (no .fields wrapper)
      const totalBudget    = budgets.reduce((s, r) => s + (r.budget_total || 0), 0);
      const totalDisbursed = budgets.reduce((s, r) => s + (r.disbursed_total || 0), 0);
      const avgProgress    = projects.length ? Math.round(projects.reduce((s, r) => s + (r.progress_pct || 0), 0) / projects.length) : 0;
      const contractTotal  = contracts.reduce((s, r) => s + (r.total_amount || 0), 0);
      const result = {
        ok: true, _source: "static_cache",
        summary: {
          personnel:   { total: personnel.length, active: personnel.filter(r => r.status === "ปฏิบัติงาน").length },
          budget:      { agencies: budgets.length, total: totalBudget, disbursed: totalDisbursed, pct: totalBudget ? Math.round(totalDisbursed / totalBudget * 100) : 0 },
          projects:    { total: projects.length, avg_progress: avgProgress, on_track: projects.filter(r => (r.progress_pct || 0) >= 60).length },
          contracts:   { total: contracts.length, total_amount: contractTotal, active: contracts.filter(r => r.status === "มีผลบังคับ").length },
          integration: { total: intPlans.length, in_progress: intPlans.filter(r => r.status === "กำลังดำเนินการ").length },
        },
        updatedAt: new Date().toISOString(),
      };
      cacheSet(cacheKey, result, 5 * 60 * 1000);
      return res.json(result);
    }

    const totalBudget    = budgets.reduce((s, r) => s + (r.fields.budget_total || 0), 0);
    const totalDisbursed = budgets.reduce((s, r) => s + (r.fields.disbursed_total || 0), 0);
    const avgProgress    = projects.length
      ? Math.round(projects.reduce((s, r) => s + (r.fields.progress_pct || 0), 0) / projects.length)
      : 0;
    const contractTotal  = contracts.reduce((s, r) => s + (r.fields.total_amount || 0), 0);

    const result = {
      ok: true,
      summary: {
        personnel:       { total: personnel.length, active: personnel.filter(r => r.fields.status === "ปฏิบัติงาน").length },
        budget:          { agencies: budgets.length, total: totalBudget, disbursed: totalDisbursed, pct: totalBudget ? Math.round(totalDisbursed / totalBudget * 100) : 0 },
        projects:        { total: projects.length, avg_progress: avgProgress, on_track: projects.filter(r => (r.fields.progress_pct || 0) >= 60).length },
        contracts:       { total: contracts.length, total_amount: contractTotal, active: contracts.filter(r => r.fields.status === "มีผลบังคับ").length },
        integration:     { total: intPlans.length, in_progress: intPlans.filter(r => r.fields.status === "กำลังดำเนินการ").length },
      },
      updatedAt: new Date().toISOString(),
    };

    cacheSet(cacheKey, result, 5 * 60 * 1000);
    res.json(result);
  } catch (err) {
    console.error("[MGMT] GET /summary error:", err.message);
    res.status(500).json({ ok: false, error: err.message });
  }
});

// -- GET /api/phrae/management/personnel -----------------------
app.get("/api/phrae/management/personnel", phraeCors, async (req, res) => {
  try {
    const { agency_id, type } = req.query;
    let formula = "";
    if (agency_id && type) formula = `AND({agency_id}="${agency_id}",{employment_type}="${type}")`;
    else if (agency_id) formula = `{agency_id}="${agency_id}"`;
    else if (type)      formula = `{employment_type}="${type}"`;

    const opts = { maxRecords: 500, sort: [{ field: "agency_id", direction: "asc" }] };
    if (formula) opts.filterByFormula = formula;

    let people;
    try {
      const data = await phraeGet("Personnel_GSA", opts);
      const recs = data.records || [];
      if (recs.length === 0) throw new Error("empty");
      people = recs.map(r => ({
        id:              r.id,
        full_name:       r.fields.full_name || "",
        agency_id:       r.fields.agency_id || "",
        agency_name:     r.fields.agency_name || "",
        dept_name:       r.fields.dept_name || "",
        employee_type:   r.fields.employee_type || r.fields.employment_type || "",
        position_title:  r.fields.position_title || r.fields.position || "",
        position_level:  r.fields.position_level || r.fields.level_grade || "",
        district:        r.fields.district || "",
        phone:           r.fields.phone || "",
        status:          r.fields.status || "",
      }));
    } catch (_) {
      console.warn("[MGMT] /personnel using static cache");
      people = mgmtStatic("personnel");
    }

    res.json({ ok: true, total: people.length, people });
  } catch (err) {
    console.error("[MGMT] GET /personnel error:", err.message);
    res.status(500).json({ ok: false, error: err.message });
  }
});

