app.get("/api/phrae/management/budget", phraeCors, async (req, res) => {
  try {
    const cacheKey = "phrae_mgmt_budget_v1";
    const cached = cacheGet(cacheKey);
    if (cached) return res.json(cached);

    let agencies;
    try {
      const data = await phraeGet("Budget_FY2568", { maxRecords: 50, sort: [{ field: "agency_id", direction: "asc" }] });
      const recs = data.records || [];
      if (recs.length === 0) throw new Error("empty");
      agencies = recs.map(r => ({
        id:               r.id,
        agency_id:        r.fields.agency_id || "",
        agency_name:      r.fields.agency_name || "",
        dept_name:        r.fields.dept_name || "",
        // Support both old field names (budget_personnel) and new (personnel_budget)
        personnel_budget: r.fields.personnel_budget || r.fields.budget_personnel || 0,
        operating_budget: r.fields.operating_budget || r.fields.budget_operation || 0,
        capital_budget:   r.fields.capital_budget   || r.fields.budget_investment || 0,
        subsidy_budget:   r.fields.subsidy_budget   || r.fields.budget_subsidy || 0,
        other_budget:     r.fields.other_budget     || r.fields.budget_other || 0,
        budget_total:     r.fields.budget_total || 0,
        disbursed_total:  r.fields.disbursed_total || 0,
        disbursed_pct:    r.fields.disbursed_pct || 0,
        fiscal_year:      r.fields.fiscal_year || "2568",
      }));
    } catch (_) {
      console.warn("[MGMT] /budget using static cache");
      agencies = mgmtStatic("budget");
    }

    const result = { ok: true, fiscal_year: "2568", total: agencies.length, agencies };
    cacheSet(cacheKey, result, 15 * 60 * 1000);
    res.json(result);
  } catch (err) {
    console.error("[MGMT] GET /budget error:", err.message);
    res.status(500).json({ ok: false, error: err.message });
  }
});

