app.post("/api/phrae/management/contracts", phraeCors, async (req, res) => {
  try {
    const b = req.body;
    if (!b.contractor_name) return res.status(400).json({ ok: false, error: "contractor_name จำเป็น" });
    const total = b.total_amount || (b.monthly_rate || 0) * (b.duration_months || 0);
    const method = total > 500000 ? "ประกวดราคา" : total > 100000 ? "สืบราคา" : "เฉพาะเจาะจง";
    const record = await phraePost("Contracts_GSA", {
      contractor_name: b.contractor_name, agency_id: b.agency_id, agency_name: b.agency_name || "",
      dept_name: b.dept_name || "", contract_type: b.contract_type || "รายเดือน",
      work_description: b.work_description || "", monthly_rate: b.monthly_rate || 0,
      duration_months: b.duration_months || 12, total_amount: total,
      procurement_method: b.procurement_method || method,
      egp_number: b.egp_number || "", fiscal_year: "2568", status: "มีผลบังคับ",
    });
    cacheGet("phrae_mgmt_summary_v1") && cacheSet("phrae_mgmt_summary_v1", null, 0);
    res.json({ ok: true, id: record.id, procurement_method: method });
  } catch (err) {
    console.error("[MGMT] POST /contracts error:", err.message);
    res.status(500).json({ ok: false, error: err.message });
  }
});

