app.put("/api/phrae/management/projects/:id/progress", phraeCors, async (req, res) => {
  try {
    const { id } = req.params;
    const { progress_pct, status } = req.body;
    const updateFields = {};
    if (progress_pct !== undefined) updateFields.progress_pct = parseInt(progress_pct);
    if (status) updateFields.status = status;
    await phraePatch("Projects_2568", id, updateFields);
    cacheGet("phrae_mgmt_summary_v1") && cacheSet("phrae_mgmt_summary_v1", null, 0);
    res.json({ ok: true, id });
  } catch (err) {
    console.error("[MGMT] PUT /projects/:id/progress error:", err.message);
    res.status(500).json({ ok: false, error: err.message });
  }
});

