// =============================================================
// AGENCY-SPECIFIC PLATFORM API — Phase A
// Per-agency endpoints: /api/phrae/agency/:agencyId/*
// Data source: public/agency-data/{agencyId}.json
// =============================================================

const VALID_AGENCY = /^KST-54-\d{3}$/;

// In-memory cache for agency static files
const _AGENCY_CACHE = {};
function agencyStatic(agencyId) {
  if (_AGENCY_CACHE[agencyId]) return _AGENCY_CACHE[agencyId];
  try {
    const file = join(__dirname, "public", "agency-data", `${agencyId}.json`);
    const data = JSON.parse(readFileSync(file, "utf8"));
    _AGENCY_CACHE[agencyId] = data;
    console.log(`[AGENCY] Loaded ${agencyId}: personnel=${(data.personnel||[]).length} budget=${(data.budget||[]).length} projects=${(data.projects||[]).length}`);
    return data;
  } catch (e) {
    console.warn(`[AGENCY] Could not load ${agencyId}.json:`, e.message);
    return null;
  }
}

// -- GET /api/phrae/agency/:agencyId/summary -------------------
app.get("/api/phrae/agency/:agencyId/summary", phraeCors, async (req, res) => {
  const { agencyId } = req.params;
  if (!VALID_AGENCY.test(agencyId)) return res.status(400).json({ ok: false, error: "invalid_agency_id" });
  const d = agencyStatic(agencyId);
  if (!d) return res.status(404).json({ ok: false, error: "agency_not_found" });
  res.json({
    ok: true,
    agency_id: agencyId,
    agency_name: d.agency_name,
    dept_name: d.dept_name,
    ministry: d.ministry,
    summary: {
      personnel_total: (d.personnel || []).length,
      budget_total: (d.budget || []).reduce((s, b) => s + (b.budget_total || 0), 0),
      projects_total: (d.projects || []).length,
      contracts_total: (d.contracts || []).length,
    },
    personnel:   d.personnel   || [],
    budget:      d.budget      || [],
    projects:    d.projects    || [],
    contracts:   d.contracts   || [],
    integration: d.integration || [],
  });
});

