// =============================================================
// สกจ. COORDINATOR ROUTES — Phase B
// Read-only aggregate from all agency JSON files
// สกจ. = ประสานงาน/รับรายงาน เท่านั้น ไม่มีอำนาจสั่งการรายกรม
// =============================================================

// GET /api/phrae/satkj/overview — aggregate summary from all agencies
app.get("/api/phrae/satkj/overview", phraeCors, async (req, res) => {
  const agencies = ["KST-54-001","KST-54-002","KST-54-003","KST-54-004","KST-54-005","KST-54-006","KST-54-007","KST-54-008"];
  const totals = { personnel: 0, budget: 0, projects: 0, contracts: 0, agencies_count: agencies.length };
  const agencyList = [];

  for (const id of agencies) {
    try {
      const d = agencyStatic(id);
      if (!d) continue;
      totals.personnel += (d.personnel  || []).length;
      totals.budget    += (d.budget     || []).reduce((s, b) => s + (b.budget_total || 0), 0);
      totals.projects  += (d.projects   || []).length;
      totals.contracts += (d.contracts  || []).length;
      agencyList.push({ agency_id: id, agency_name: d.agency_name, dept_name: d.dept_name });
    } catch (_) {}
  }

  res.json({
    ok: true,
    note: "ข้อมูลอ้างอิงจากรายงานที่ได้รับ — สกจ. ไม่มีอำนาจสั่งการหรือแก้ไขข้อมูลรายกรม",
    totals,
    agencies: agencyList,
  });
});

