// =============================================================
// ─── Data Request Workflow Routes ─────────────────────────────

const DATA_REQ_FILE = join(__dirname, "public", "data-requests", "requests.json");

function loadRequests() {
  try { return JSON.parse(readFileSync(DATA_REQ_FILE, "utf8")); }
  catch { return { requests: [] }; }
}

function saveRequests(data) {
  writeFileSync(DATA_REQ_FILE, JSON.stringify(data, null, 2), "utf8");
}

function genReqId(requests) {
  const seq = (requests.length + 1).toString().padStart(3, "0");
  return `REQ-2568-${seq}`;
}

// POST /api/phrae/data-request/submit
app.post("/api/phrae/data-request/submit", phraeCors, async (req, res) => {
  const { requester_agency_id, target_agency_id, data_type, data_description, reason } = req.body;
  if (!requester_agency_id || !target_agency_id || !data_type) {
    return res.status(400).json({ ok: false, error: "missing_fields" });
  }
  if (requester_agency_id === target_agency_id) {
    return res.status(400).json({ ok: false, error: "cannot_request_from_self" });
  }
  const rAgency = agencyStatic(requester_agency_id);
  const tAgency = agencyStatic(target_agency_id);
  if (!rAgency || !tAgency) return res.status(404).json({ ok: false, error: "agency_not_found" });
  const store = loadRequests();
  const now = new Date().toISOString();
  const req_record = {
    request_id: genReqId(store.requests),
    created_at: now,
    requester_agency_id,
    requester_agency_name: rAgency.agency_name,
    target_agency_id,
    target_agency_name: tAgency.agency_name,
    data_type,
    data_description: data_description || "",
    reason: reason || "",
    status: "pending_approval",
    workflow_steps: [{ step: 1, action: "submitted", actor: rAgency.agency_name, timestamp: now, note: "ส่งคำขอเข้าระบบ" }],
    response_data: null,
    completed_at: null
  };
  store.requests.push(req_record);
  saveRequests(store);
  res.json({ ok: true, request_id: req_record.request_id, message: "ส่งคำขอเรียบร้อย กรุณารอการพิจารณาจากหัวหน้าหน่วยงาน" });
});

// GET /api/phrae/data-request/list?agency_id=KST-54-001&role=target
app.get("/api/phrae/data-request/list", phraeCors, async (req, res) => {
  const { agency_id, role, status } = req.query;
  const store = loadRequests();
  let list = store.requests;
  if (agency_id) {
    if (role === "target") list = list.filter(r => r.target_agency_id === agency_id);
    else if (role === "requester") list = list.filter(r => r.requester_agency_id === agency_id);
    else list = list.filter(r => r.target_agency_id === agency_id || r.requester_agency_id === agency_id);
  }
  if (status) list = list.filter(r => r.status === status);
  res.json({ ok: true, total: list.length, requests: list.sort((a, b) => b.created_at.localeCompare(a.created_at)) });
});

// POST /api/phrae/data-request/:id/approve
app.post("/api/phrae/data-request/:id/approve", phraeCors, async (req, res) => {
  const store = loadRequests();
  const rec = store.requests.find(r => r.request_id === req.params.id);
  if (!rec) return res.status(404).json({ ok: false, error: "not_found" });
  if (rec.status !== "pending_approval") return res.status(400).json({ ok: false, error: "invalid_status" });
  const now = new Date().toISOString();
  rec.status = "approved_preparing";
  rec.workflow_steps.push({ step: 2, action: "approved", actor: "หัวหน้า " + rec.target_agency_name, timestamp: now, note: req.body.note || "อนุมัติคำขอ มอบหมายให้จัดเตรียมข้อมูล" });
  saveRequests(store);
  res.json({ ok: true, request_id: rec.request_id, status: rec.status });
});

// POST /api/phrae/data-request/:id/reject
app.post("/api/phrae/data-request/:id/reject", phraeCors, async (req, res) => {
  const store = loadRequests();
  const rec = store.requests.find(r => r.request_id === req.params.id);
  if (!rec) return res.status(404).json({ ok: false, error: "not_found" });
  const now = new Date().toISOString();
  rec.status = "rejected";
  rec.workflow_steps.push({ step: 2, action: "rejected", actor: "หัวหน้า " + rec.target_agency_name, timestamp: now, note: req.body.reason || "ปฏิเสธคำขอ" });
  rec.completed_at = now;
  saveRequests(store);
  res.json({ ok: true, request_id: rec.request_id, status: rec.status });
});

// POST /api/phrae/data-request/:id/submit-data
app.post("/api/phrae/data-request/:id/submit-data", phraeCors, async (req, res) => {
  const store = loadRequests();
  const rec = store.requests.find(r => r.request_id === req.params.id);
  if (!rec) return res.status(404).json({ ok: false, error: "not_found" });
  if (rec.status !== "approved_preparing") return res.status(400).json({ ok: false, error: "invalid_status" });
  const now = new Date().toISOString();
  rec.status = "under_review";
  rec.response_data = req.body.data || "";
  rec.workflow_steps.push({ step: 3, action: "data_prepared", actor: "เจ้าหน้าที่ " + rec.target_agency_name, timestamp: now, note: "เตรียมข้อมูลเสร็จ รอหัวหน้าตรวจสอบ" });
  saveRequests(store);
  res.json({ ok: true, request_id: rec.request_id, status: rec.status });
});

// POST /api/phrae/data-request/:id/send
app.post("/api/phrae/data-request/:id/send", phraeCors, async (req, res) => {
  const store = loadRequests();
  const rec = store.requests.find(r => r.request_id === req.params.id);
  if (!rec) return res.status(404).json({ ok: false, error: "not_found" });
  if (rec.status !== "under_review") return res.status(400).json({ ok: false, error: "invalid_status" });
  const now = new Date().toISOString();
  rec.status = "completed";
  rec.completed_at = now;
  rec.workflow_steps.push({ step: 4, action: "sent", actor: "หัวหน้า " + rec.target_agency_name, timestamp: now, note: "เห็นชอบและส่งข้อมูลให้ผู้ขอ" });
  rec.workflow_steps.push({ step: 5, action: "received", actor: rec.requester_agency_name, timestamp: now, note: "ได้รับข้อมูลแล้ว" });
  saveRequests(store);
  res.json({ ok: true, request_id: rec.request_id, status: rec.status });
});

