// =============================================================
// ─── Policy Command Center Routes ─────────────────────────────
// L1 Platform: Policy Board, Submit, Consensus, CEO Approval, Distribution

const POLICY_FILE = join(__dirname, "public", "policy-data", "policies.json");

function loadPolicies() {
  try { return JSON.parse(readFileSync(POLICY_FILE, "utf8")); }
  catch { return { policies: [] }; }
}

function savePolicies(data) {
  writeFileSync(POLICY_FILE, JSON.stringify(data, null, 2), "utf8");
}

function genPolicyId(policies) {
  const year = new Date().getFullYear();
  const seq = (policies.length + 1).toString().padStart(3, "0");
  return `POL-${year}-${seq}`;
}

// GET /api/policy/list
app.get("/api/policy/list", (req, res) => {
  const store = loadPolicies();
  const sorted = (store.policies || []).sort((a, b) => b.created_at.localeCompare(a.created_at));
  res.json({ ok: true, total: sorted.length, policies: sorted });
});

// POST /api/policy/submit
app.post("/api/policy/submit", (req, res) => {
  const { proposer, ministry, title, detail, priority, formatted_detail } = req.body;
  if (!proposer || !ministry || !title || !detail) {
    return res.status(400).json({ ok: false, error: "missing_required_fields" });
  }
  const store = loadPolicies();
  const now = new Date().toISOString();
  const policy = {
    id: genPolicyId(store.policies),
    title,
    proposer,
    ministry,
    priority: priority || "กลาง",
    detail,
    formatted_detail: formatted_detail || null,
    status: "review",
    created_at: now,
    votes: [],
    distributions: [],
    history: [{ action: "submitted", by: proposer, at: now }, { action: "moved_to_review", by: "system", at: now }],
  };
  store.policies.push(policy);
  savePolicies(store);
  // Log the action
  appendSystemLog({ action: "policy_submitted", user: proposer, detail: `Policy: ${title} | Ministry: ${ministry}` });
  res.json({ ok: true, policy_id: policy.id, message: "บันทึกนโยบายและส่งเข้า Review เรียบร้อย" });
});

// POST /api/policy/format — Claude AI policy formatting
app.post("/api/policy/format", async (req, res) => {
  const { proposer, title, detail, ministry, priority } = req.body;
  if (!title || !detail) return res.status(400).json({ ok: false, error: "title_and_detail_required" });

  const apiKey = process.env.ANTHROPIC_API_KEY || process.env.ANTHROPIC_KEY_1;
  if (!apiKey) {
    // Fallback to simple format if no API key
    const pLabel = priority === "สูง" ? "สูง — เร่งด่วน" : priority === "ต่ำ" ? "ต่ำ — ระยะยาว" : "กลาง — ปกติ";
    const formatted = [
      `นโยบาย: ${title}`,
      `ผู้เสนอ: ${proposer || "—"}`,
      `กระทรวงเป้าหมาย: ${ministry || "—"}`,
      `ลำดับความสำคัญ: ${pLabel}`,
      ``,
      `รายละเอียด:`,
      detail,
      ``,
      `วันที่จัดทำ: ${new Date().toLocaleDateString("th-TH", { year: "numeric", month: "long", day: "numeric" })}`,
    ].join("\n");
    return res.json({ ok: true, formatted, source: "fallback" });
  }

  try {
    const prompt = `คุณเป็นผู้เชี่ยวชาญร่างนโยบายภาครัฐของไทย จงแปลงข้อเสนอต่อไปนี้เป็นรูปแบบนโยบายราชการที่ถูกต้องตามระเบียบ มีหัวข้อ วัตถุประสงค์ เป้าหมาย ผู้รับผิดชอบ และระยะเวลา
กระทรวง: ${ministry || "—"}
หัวข้อ: ${title}
รายละเอียด: ${detail}
ลำดับความสำคัญ: ${priority || "กลาง"}
ผู้เสนอ: ${proposer || "—"}

จงเขียนเอกสารนโยบายราชการฉบับสมบูรณ์เป็นภาษาไทย มีความยาวเหมาะสม ครอบคลุมทุกหัวข้อที่จำเป็นสำหรับเอกสารราชการไทย`;

    const aiResp = await fetch("https://api.anthropic.com/v1/messages", {
      method: "POST",
      headers: {
        "x-api-key": apiKey,
        "anthropic-version": "2023-06-01",
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        model: "claude-opus-4-7",
        max_tokens: 1500,
        messages: [{ role: "user", content: prompt }],
      }),
    });
    const aiData = await aiResp.json();
    if (aiData.error) throw new Error(aiData.error.message);
    const formatted = aiData.content?.[0]?.text || "";
    appendSystemLog({ action: "ai_policy_format", user: proposer || "system", detail: `Formatted: ${title}` });
    res.json({ ok: true, formatted, source: "claude" });
  } catch (err) {
    console.error("[policy/format] Claude API error:", err.message);
    // Graceful fallback
    const pLabel = priority === "สูง" ? "สูง — เร่งด่วน" : priority === "ต่ำ" ? "ต่ำ — ระยะยาว" : "กลาง — ปกติ";
    const formatted = [
      `นโยบาย: ${title}`,
      `ผู้เสนอ: ${proposer || "—"}`,
      `กระทรวงเป้าหมาย: ${ministry || "—"}`,
      `ลำดับความสำคัญ: ${pLabel}`,
      ``,
      `รายละเอียด:`,
      detail,
      ``,
      `วันที่จัดทำ: ${new Date().toLocaleDateString("th-TH", { year: "numeric", month: "long", day: "numeric" })}`,
    ].join("\n");
    res.json({ ok: true, formatted, source: "fallback", warning: "Claude API ไม่พร้อม ใช้รูปแบบพื้นฐาน" });
  }
});

// POST /api/policy/:id/vote
app.post("/api/policy/:id/vote", (req, res) => {
  const { voter, vote, reason } = req.body;
  if (!voter || !["approve", "observe", "reject"].includes(vote)) {
    return res.status(400).json({ ok: false, error: "invalid_vote_payload" });
  }
  const store = loadPolicies();
  const policy = store.policies.find(p => p.id === req.params.id);
  if (!policy) return res.status(404).json({ ok: false, error: "policy_not_found" });
  if (policy.status !== "review") return res.status(400).json({ ok: false, error: "policy_not_in_review" });
  const existing = policy.votes.findIndex(v => v.voter === voter);
  const entry = { voter, vote, reason: reason || "", voted_at: new Date().toISOString() };
  if (existing >= 0) policy.votes[existing] = entry;
  else policy.votes.push(entry);
  policy.history.push({ action: `voted_${vote}`, by: voter, at: entry.voted_at });
  savePolicies(store);
  res.json({ ok: true, policy_id: policy.id, total_votes: policy.votes.length });
});

// POST /api/policy/:id/ceo-approve
app.post("/api/policy/:id/ceo-approve", (req, res) => {
  const store = loadPolicies();
  const policy = store.policies.find(p => p.id === req.params.id);
  if (!policy) return res.status(404).json({ ok: false, error: "policy_not_found" });
  if (!["review", "draft"].includes(policy.status)) {
    return res.status(400).json({ ok: false, error: "cannot_approve_in_current_status" });
  }
  const now = new Date().toISOString();
  policy.status = "approved";
  policy.approved_at = now;
  policy.approved_by = "CEO";
  policy.history.push({ action: "ceo_approved", by: "CEO", at: now });
  savePolicies(store);
  res.json({ ok: true, policy_id: policy.id, status: policy.status });
});

// POST /api/policy/:id/ceo-return
app.post("/api/policy/:id/ceo-return", (req, res) => {
  const store = loadPolicies();
  const policy = store.policies.find(p => p.id === req.params.id);
  if (!policy) return res.status(404).json({ ok: false, error: "policy_not_found" });
  const now = new Date().toISOString();
  policy.status = "draft";
  policy.history.push({ action: "ceo_returned", by: "CEO", at: now, note: req.body.note || "" });
  savePolicies(store);
  res.json({ ok: true, policy_id: policy.id, status: policy.status });
});

// POST /api/policy/:id/distribute
app.post("/api/policy/:id/distribute", (req, res) => {
  const { ministry } = req.body;
  if (!ministry) return res.status(400).json({ ok: false, error: "ministry_required" });
  const store = loadPolicies();
  const policy = store.policies.find(p => p.id === req.params.id);
  if (!policy) return res.status(404).json({ ok: false, error: "policy_not_found" });
  if (policy.status !== "approved") return res.status(400).json({ ok: false, error: "policy_not_approved" });
  const now = new Date().toISOString();
  const already = policy.distributions.find(d => d.ministry === ministry);
  if (!already) {
    policy.distributions.push({ ministry, distributed_at: now, status: "received" });
    policy.history.push({ action: "distributed", by: "CEO", at: now, ministry });
  }
  savePolicies(store);
  res.json({ ok: true, policy_id: policy.id, ministry, distributions: policy.distributions });
});

