const SYSTEM_LOG_FILE = join(__dirname, "public", "policy-data", "system-log.json");

function loadSystemLog() {
  try { return JSON.parse(readFileSync(SYSTEM_LOG_FILE, "utf8")); }
  catch { return { logs: [] }; }
}

function saveSystemLog(data) {
  writeFileSync(SYSTEM_LOG_FILE, JSON.stringify(data, null, 2), "utf8");
}

function appendSystemLog(entry) {
  try {
    const store = loadSystemLog();
    store.logs.push({ timestamp: new Date().toISOString(), ...entry });
    // Keep last 500 entries
    if (store.logs.length > 500) store.logs = store.logs.slice(-500);
    saveSystemLog(store);
  } catch (e) {
    console.warn("[syslog] append error:", e.message);
  }
}

// Initialize log file if it doesn't exist
try {
  readFileSync(SYSTEM_LOG_FILE, "utf8");
} catch {
  saveSystemLog({ logs: [{ action: "system_start", user: "system", timestamp: new Date().toISOString(), detail: "Platform initialized" }] });
  console.log("[G2G] system-log.json created ✅");
}

// POST /api/ai/chat — General AI chat for all pages
app.post("/api/ai/chat", async (req, res) => {
  const { message, context } = req.body;
  if (!message) return res.status(400).json({ ok: false, error: "message_required" });

  const apiKey = process.env.ANTHROPIC_API_KEY || process.env.ANTHROPIC_KEY_1;
  if (!apiKey) {
    return res.json({ ok: true, reply: "ขออภัย ระบบ AI ไม่พร้อมในขณะนี้ กรุณาลองใหม่ภายหลัง" });
  }

  try {
    const aiResp = await fetch("https://api.anthropic.com/v1/messages", {
      method: "POST",
      headers: {
        "x-api-key": apiKey,
        "anthropic-version": "2023-06-01",
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        model: "claude-haiku-4-5",
        max_tokens: 800,
        system: "คุณเป็นผู้ช่วย AI ของระบบบริหารภาครัฐ G2G ตอบคำถามเป็นภาษาไทย กระชับ ชัดเจน เป็นประโยชน์ ไม่พูดฟุ่มเฟือย",
        messages: [{ role: "user", content: `[หน้า: ${context || "ไม่ระบุ"}]\n\n${message}` }],
      }),
    });
    const d = await aiResp.json();
    if (d.error) throw new Error(d.error.message);
    const reply = d.content?.[0]?.text || "ขออภัย ไม่สามารถประมวลผลได้";
    appendSystemLog({ action: "ai_chat", user: "visitor", detail: `Page: ${context || "—"} | Q: ${message.slice(0, 60)}` });
    res.json({ ok: true, reply });
  } catch (err) {
    console.error("[ai/chat] error:", err.message);
    res.json({ ok: false, reply: "ขออภัย ระบบ AI เกิดข้อผิดพลาด กรุณาลองใหม่", error: err.message });
  }
});

