const POSITIONS_FILE = join(__dirname, "public", "position-data", "positions.json");

function loadPositions() {
  try { return JSON.parse(readFileSync(POSITIONS_FILE, "utf8")); }
  catch { return { positions: [] }; }
}

function savePositions(data) {
  writeFileSync(POSITIONS_FILE, JSON.stringify(data, null, 2), "utf8");
}

// GET /api/positions/list — all positions
app.get("/api/positions/list", (req, res) => {
  const store = loadPositions();
  res.json({ ok: true, total: store.positions.length, positions: store.positions });
});

// GET /api/positions/:id — single position detail
app.get("/api/positions/:id", (req, res) => {
  const store = loadPositions();
  const pos = store.positions.find(p => p.position_id === req.params.id);
  if (!pos) return res.status(404).json({ ok: false, error: "position_not_found" });
  res.json({ ok: true, position: pos });
});

// POST /api/positions/:id/update-incumbent — change incumbent (position stays)
app.post("/api/positions/:id/update-incumbent", (req, res) => {
  const { name, start_date, citizen_id_last4, contact_line } = req.body;
  if (!name || !start_date) return res.status(400).json({ ok: false, error: "name_and_start_date_required" });
  const store = loadPositions();
  const pos = store.positions.find(p => p.position_id === req.params.id);
  if (!pos) return res.status(404).json({ ok: false, error: "position_not_found" });
  // Archive old incumbent to work_history
  if (pos.incumbent && pos.incumbent.name) {
    if (!pos.work_history) pos.work_history = [];
    const today = new Date().toISOString().slice(0, 10);
    pos.work_history.unshift({
      name: pos.incumbent.name,
      start_date: pos.incumbent.start_date,
      end_date: today,
      key_achievements: ""
    });
  }
  pos.incumbent = { name, start_date, citizen_id_last4: citizen_id_last4 || "", contact_line: contact_line || "" };
  pos.status = "active";
  savePositions(store);
  res.json({ ok: true, position_id: pos.position_id, incumbent: pos.incumbent, message: "บันทึกการเปลี่ยนผู้ดำรงตำแหน่งเรียบร้อย" });
});

// GET /api/positions/:id/history — ประวัติผู้ดำรงตำแหน่ง
app.get("/api/positions/:id/history", (req, res) => {
  const store = loadPositions();
  const pos = store.positions.find(p => p.position_id === req.params.id);
  if (!pos) return res.status(404).json({ ok: false, error: "position_not_found" });
  res.json({
    ok: true,
    position_id: pos.position_id,
    title_th: pos.title_th,
    work_history_summary: pos.work_history_summary || "",
    current_incumbent: pos.incumbent || null,
    past_incumbents: pos.work_history || []
  });
});

// POST /api/positions/:id/add-task — เพิ่ม pending task
app.post("/api/positions/:id/add-task", (req, res) => {
  const { task_name, due_date, priority } = req.body;
  if (!task_name) return res.status(400).json({ ok: false, error: "task_name_required" });
  const store = loadPositions();
  const pos = store.positions.find(p => p.position_id === req.params.id);
  if (!pos) return res.status(404).json({ ok: false, error: "position_not_found" });
  if (!pos.pending_tasks) pos.pending_tasks = [];
  const task = {
    task_id: `TASK-${Date.now()}`,
    task_name,
    due_date: due_date || null,
    priority: priority || "กลาง",
    status: "pending",
    created_at: new Date().toISOString()
  };
  pos.pending_tasks.push(task);
  savePositions(store);
  res.json({ ok: true, task_id: task.task_id, message: "เพิ่มงานเรียบร้อย" });
});

// POST /api/positions/:id/complete-task — mark task complete
app.post("/api/positions/:id/complete-task", (req, res) => {
  const { task_id } = req.body;
  if (!task_id) return res.status(400).json({ ok: false, error: "task_id_required" });
  const store = loadPositions();
  const pos = store.positions.find(p => p.position_id === req.params.id);
  if (!pos) return res.status(404).json({ ok: false, error: "position_not_found" });
  const task = (pos.pending_tasks || []).find(t => t.task_id === task_id);
  if (!task) return res.status(404).json({ ok: false, error: "task_not_found" });
  task.status = "completed";
  task.completed_at = new Date().toISOString();
  savePositions(store);
  res.json({ ok: true, task_id, message: "ทำเครื่องหมายงานเสร็จสิ้นเรียบร้อย" });
});

