// =============================================================
// ─── Agent Task Board API ─────────────────────────────────────
// Table: AgentTasks (tblRdw1NyNIVxouF5) in AIRTABLE_BASE
// =============================================================

const AGENT_TASKS_TABLE = "AgentTasks";
// AgentTasks lives in the main AIRTABLE_BASE (app6keeRcHmiTMLKy)
// Note: appRQwVddDxQdU6P3 is the LINE/AI_Pool base — AgentTasks is in main base
const AGENT_TASKS_BASE = AIRTABLE_BASE;

// POST /api/tasks/setup — one-time table creation (idempotent)
app.post("/api/tasks/setup", async (req, res) => {
  try {
    const schema = {
      name: AGENT_TASKS_TABLE,
      fields: [
        { name: "TaskID", type: "singleLineText" },
        { name: "Title", type: "singleLineText" },
        { name: "Type", type: "singleSelect", options: { choices: [
          { name: "research" }, { name: "build" }, { name: "review" },
          { name: "monitor" }, { name: "personal-ai" }, { name: "deploy" }
        ]}},
        { name: "AssignedTo", type: "singleLineText" },
        { name: "Status", type: "singleSelect", options: { choices: [
          { name: "pending" }, { name: "in_progress" }, { name: "blocked" },
          { name: "completed" }, { name: "failed" }
        ]}},
        { name: "Priority", type: "singleSelect", options: { choices: [
          { name: "critical" }, { name: "high" }, { name: "normal" }, { name: "low" }
        ]}},
        { name: "CreatedBy", type: "singleLineText" },
        { name: "CreatedAt", type: "date", options: { dateFormat: { name: "iso" } } },
        { name: "Result", type: "multilineText" },
        { name: "ErrorLog", type: "multilineText" },
        { name: "ParentTaskID", type: "singleLineText" }
      ]
    };
    const schemaUrl = `https://api.airtable.com/v0/meta/bases/${AGENT_TASKS_BASE}/tables`;
    const r = await fetch(schemaUrl, {
      method: "POST",
      headers: { Authorization: `Bearer ${AIRTABLE_TOKEN}`, "Content-Type": "application/json" },
      body: JSON.stringify(schema)
    });
    const d = await r.json();
    if (!r.ok) {
      // If table already exists, that's OK
      if (d.error && d.error.message && d.error.message.includes("already exists")) {
        return res.json({ ok: true, message: "Table already exists", base: AGENT_TASKS_BASE });
      }
      return res.status(r.status).json({ ok: false, error: d.error, base: AGENT_TASKS_BASE });
    }
    // Seed 3 records
    const seedUrl = `https://api.airtable.com/v0/${AGENT_TASKS_BASE}/${encodeURIComponent(AGENT_TASKS_TABLE)}`;
    const seeds = [
      { TaskID: "TASK-001", Title: "Build Position Registry", Type: "build", AssignedTo: "build-agent", Status: "completed", Priority: "high", CreatedBy: "aiboss", CreatedAt: "2026-05-20", Result: "position-registry.html deployed" },
      { TaskID: "TASK-002", Title: "Research Multi-AI Patterns", Type: "research", AssignedTo: "research-agent", Status: "completed", Priority: "normal", CreatedBy: "aiboss", CreatedAt: "2026-05-21", Result: "4 patterns analyzed" },
      { TaskID: "TASK-003", Title: "Build Personal AI Engine", Type: "build", AssignedTo: "build-agent", Status: "in_progress", Priority: "high", CreatedBy: "aiboss", CreatedAt: "2026-05-24" }
    ];
    const sr = await fetch(seedUrl, {
      method: "POST",
      headers: { Authorization: `Bearer ${AIRTABLE_TOKEN}`, "Content-Type": "application/json" },
      body: JSON.stringify({ records: seeds.map(fields => ({ fields })) })
    });
    const sd = await sr.json();
    res.json({ ok: true, table_id: d.id, seeded: (sd.records || []).length, base: AGENT_TASKS_BASE });
  } catch (e) {
    res.status(500).json({ ok: false, error: e.message });
  }
});

// Helper: generate next TaskID
async function nextTaskID() {
  const url = `https://api.airtable.com/v0/${AGENT_TASKS_BASE}/${encodeURIComponent(AGENT_TASKS_TABLE)}?fields%5B%5D=TaskID&sort%5B0%5D%5Bfield%5D=TaskID&sort%5B0%5D%5Bdirection%5D=desc&maxRecords=1`;
  const r = await fetch(url, { headers: { Authorization: `Bearer ${AIRTABLE_TOKEN}` } });
  const d = await r.json();
  if (!d.records || d.records.length === 0) return "TASK-001";
  const last = d.records[0].fields.TaskID || "TASK-000";
  const num = parseInt(last.replace("TASK-", ""), 10) || 0;
  return `TASK-${String(num + 1).padStart(3, "0")}`;
}

// GET /api/tasks/list?status=pending&assigned_to=build-agent
app.get("/api/tasks/list", async (req, res) => {
  try {
    const { status, assigned_to } = req.query;
    const filters = [];
    if (status) filters.push(`{Status}="${status}"`);
    if (assigned_to) filters.push(`{AssignedTo}="${assigned_to}"`);
    const formula = filters.length === 1 ? filters[0] : filters.length > 1 ? `AND(${filters.join(",")})` : "";
    const q = formula ? `filterByFormula=${encodeURIComponent(formula)}` : "";
    const url = `https://api.airtable.com/v0/${AGENT_TASKS_BASE}/${encodeURIComponent(AGENT_TASKS_TABLE)}${q ? "?" + q : ""}`;
    const r = await fetch(url, { headers: { Authorization: `Bearer ${AIRTABLE_TOKEN}` } });
    const d = await r.json();
    if (!r.ok) return res.status(r.status).json({ ok: false, error: d.error });
    res.json({ ok: true, tasks: (d.records || []).map(rec => ({ id: rec.id, ...rec.fields })) });
  } catch (e) {
    res.status(500).json({ ok: false, error: e.message });
  }
});

// POST /api/tasks/create
app.post("/api/tasks/create", async (req, res) => {
  try {
    const { title, type, assigned_to, priority, created_by, parent_task_id } = req.body;
    if (!title) return res.status(400).json({ ok: false, error: "title_required" });
    const taskId = await nextTaskID();
    const fields = {
      TaskID: taskId,
      Title: title,
      Status: "pending",
      CreatedAt: new Date().toISOString().split("T")[0]
    };
    if (type) fields.Type = type;
    if (assigned_to) fields.AssignedTo = assigned_to;
    if (priority) fields.Priority = priority;
    if (created_by) fields.CreatedBy = created_by;
    if (parent_task_id) fields.ParentTaskID = parent_task_id;
    const url = `https://api.airtable.com/v0/${AGENT_TASKS_BASE}/${encodeURIComponent(AGENT_TASKS_TABLE)}`;
    const r = await fetch(url, {
      method: "POST",
      headers: { Authorization: `Bearer ${AIRTABLE_TOKEN}`, "Content-Type": "application/json" },
      body: JSON.stringify({ records: [{ fields }] })
    });
    const d = await r.json();
    if (!r.ok) return res.status(r.status).json({ ok: false, error: d.error });
    const rec = d.records[0];
    res.json({ ok: true, task_id: taskId, record_id: rec.id, fields: rec.fields });
  } catch (e) {
    res.status(500).json({ ok: false, error: e.message });
  }
});

// POST /api/tasks/:taskId/update
app.post("/api/tasks/:taskId/update", async (req, res) => {
  try {
    const { taskId } = req.params;
    const { status, result, error_log } = req.body;
    // Find record by TaskID field
    const searchUrl = `https://api.airtable.com/v0/${AGENT_TASKS_BASE}/${encodeURIComponent(AGENT_TASKS_TABLE)}?filterByFormula=${encodeURIComponent(`{TaskID}="${taskId}"`)}`;
    const sr = await fetch(searchUrl, { headers: { Authorization: `Bearer ${AIRTABLE_TOKEN}` } });
    const sd = await sr.json();
    if (!sd.records || sd.records.length === 0) return res.status(404).json({ ok: false, error: "task_not_found" });
    const recId = sd.records[0].id;
    const fields = {};
    if (status) fields.Status = status;
    if (result !== undefined) fields.Result = result;
    if (error_log !== undefined) fields.ErrorLog = error_log;
    const url = `https://api.airtable.com/v0/${AGENT_TASKS_BASE}/${encodeURIComponent(AGENT_TASKS_TABLE)}/${recId}`;
    const r = await fetch(url, {
      method: "PATCH",
      headers: { Authorization: `Bearer ${AIRTABLE_TOKEN}`, "Content-Type": "application/json" },
      body: JSON.stringify({ fields })
    });
    const d = await r.json();
    if (!r.ok) return res.status(r.status).json({ ok: false, error: d.error });
    res.json({ ok: true, task_id: taskId, record_id: recId, fields: d.fields });
  } catch (e) {
    res.status(500).json({ ok: false, error: e.message });
  }
});

// GET /api/tasks/board — tasks grouped by status (Kanban)
app.get("/api/tasks/board", async (req, res) => {
  try {
    const url = `https://api.airtable.com/v0/${AGENT_TASKS_BASE}/${encodeURIComponent(AGENT_TASKS_TABLE)}?sort%5B0%5D%5Bfield%5D=CreatedAt&sort%5B0%5D%5Bdirection%5D=desc`;
    const r = await fetch(url, { headers: { Authorization: `Bearer ${AIRTABLE_TOKEN}` } });
    const d = await r.json();
    if (!r.ok) return res.status(r.status).json({ ok: false, error: d.error });
    const board = { pending: [], in_progress: [], blocked: [], completed: [], failed: [] };
    for (const rec of (d.records || [])) {
      const task = { id: rec.id, ...rec.fields };
      const col = (task.Status || "pending").replace("-", "_");
      if (board[col]) board[col].push(task);
      else board.pending.push(task);
    }
    res.json({ ok: true, board });
  } catch (e) {
    res.status(500).json({ ok: false, error: e.message });
  }
});

// POST /api/tasks — alias for /api/tasks/create (AiBoss Command Center)
app.post("/api/tasks", async (req, res) => {
  try {
    const { title, type, assigned_to, assignedTo, priority, created_by, description, parent_task_id, parentTaskId } = req.body;
    if (!title) return res.status(400).json({ ok: false, error: "title_required" });
    const taskId = `TASK-${Date.now()}`;
    const fields = {
      TaskID: taskId,
      Title: title,
      Status: "pending",
      CreatedBy: created_by || "aiboss",
      CreatedAt: new Date().toISOString().split("T")[0]
    };
    if (type) fields.Type = type;
    const agent = assigned_to || assignedTo;
    if (agent) fields.AssignedTo = agent;
    if (priority) fields.Priority = priority;
    if (description) fields.Result = "";  // keep Result empty; store desc in notes
    const pid = parent_task_id || parentTaskId;
    if (pid) fields.ParentTaskID = pid;
    const url = `https://api.airtable.com/v0/${AGENT_TASKS_BASE}/${encodeURIComponent(AGENT_TASKS_TABLE)}`;
    const r = await fetch(url, {
      method: "POST",
      headers: { Authorization: `Bearer ${AIRTABLE_TOKEN}`, "Content-Type": "application/json" },
      body: JSON.stringify({ records: [{ fields }] })
    });
    const d = await r.json();
    if (!r.ok) return res.status(r.status).json({ ok: false, error: d.error });
    const rec = d.records[0];
    res.json({ ok: true, taskId, task_id: taskId, record_id: rec.id, fields: rec.fields });
  } catch (e) {
    res.status(500).json({ ok: false, error: e.message });
  }
});

// GET /api/tasks — alias for /api/tasks/list (AiBoss Command Center)
app.get("/api/tasks", async (req, res) => {
  try {
    const { status, assigned_to } = req.query;
    const filters = [];
    if (status) filters.push(`{Status}="${status}"`);
    if (assigned_to) filters.push(`{AssignedTo}="${assigned_to}"`);
    const formula = filters.length === 1 ? filters[0] : filters.length > 1 ? `AND(${filters.join(",")})` : "";
    const q = formula ? `filterByFormula=${encodeURIComponent(formula)}&` : "";
    const url = `https://api.airtable.com/v0/${AGENT_TASKS_BASE}/${encodeURIComponent(AGENT_TASKS_TABLE)}?${q}sort%5B0%5D%5Bfield%5D=CreatedAt&sort%5B0%5D%5Bdirection%5D=desc`;
    const r = await fetch(url, { headers: { Authorization: `Bearer ${AIRTABLE_TOKEN}` } });
    const d = await r.json();
    if (!r.ok) return res.status(r.status).json({ ok: false, error: d.error });
    res.json({ ok: true, tasks: (d.records || []).map(rec => ({ id: rec.id, ...rec.fields })) });
  } catch (e) {
    res.status(500).json({ ok: false, error: e.message });
  }
});

