// GET /api/agents/health — ping key endpoints and return status
app.get("/api/agents/health", async (req, res) => {
  const endpoints = [
    { key: "policy-list",     path: "/api/policy/list" },
    { key: "positions-list",  path: "/api/positions/list" },
    { key: "doae-overview",   path: "/api/doae/national/overview" },
    { key: "tasks-board",     path: "/api/tasks/board" },
    { key: "token-status",    path: "/api/system/token-status" },
  ];
  const baseUrl = `http://localhost:${PORT}`;
  const results = await Promise.all(endpoints.map(async (ep) => {
    const start = Date.now();
    try {
      const r = await fetch(baseUrl + ep.path, { signal: AbortSignal.timeout(5000) });
      const latency = Date.now() - start;
      return {
        endpoint: ep.key,
        path: ep.path,
        status: r.ok ? (latency > 2000 ? "degraded" : "ok") : "down",
        http_status: r.status,
        latency_ms: latency,
        last_checked: new Date().toISOString(),
      };
    } catch (e) {
      return {
        endpoint: ep.key,
        path: ep.path,
        status: "down",
        http_status: null,
        latency_ms: Date.now() - start,
        error: e.message,
        last_checked: new Date().toISOString(),
      };
    }
  }));
  const allOk = results.every(r => r.status === "ok");
  const anyDown = results.some(r => r.status === "down");
  res.json({
    ok: true,
    overall: allOk ? "ok" : anyDown ? "degraded" : "degraded",
    endpoints: results,
    checked_at: new Date().toISOString(),
  });
});

// GET /api/agents/:id — single agent detail + recent tasks
app.get("/api/agents/:id", async (req, res) => {
  const { id } = req.params;
  const config = loadAgentsConfig();
  const agent = config.agents.find(a => a.agent_id === id);
  if (!agent) return res.status(404).json({ ok: false, error: "agent_not_found" });
  // Try to fetch recent tasks for this agent from Airtable
  let recent_tasks = [];
  try {
    const filter = encodeURIComponent(`{AssignedTo}="${id}"`);
    const url = `https://api.airtable.com/v0/${AGENT_TASKS_BASE}/${encodeURIComponent(AGENT_TASKS_TABLE)}?filterByFormula=${filter}&sort%5B0%5D%5Bfield%5D=CreatedAt&sort%5B0%5D%5Bdirection%5D=desc&maxRecords=5`;
    const r = await fetch(url, { headers: { Authorization: `Bearer ${AIRTABLE_TOKEN}` } });
    if (r.ok) {
      const d = await r.json();
      recent_tasks = (d.records || []).map(rec => ({ id: rec.id, ...rec.fields }));
    }
  } catch (_) {}
  res.json({ ok: true, agent, recent_tasks });
});

// POST /api/agents/:id/assign-task — assign task to agent (writes to Airtable AgentTasks)
app.post("/api/agents/:id/assign-task", async (req, res) => {
  const { id } = req.params;
  const config = loadAgentsConfig();
  const agent = config.agents.find(a => a.agent_id === id);
  if (!agent) return res.status(404).json({ ok: false, error: "agent_not_found" });

  const { title, description, priority, requested_by } = req.body;
  if (!title) return res.status(400).json({ ok: false, error: "title is required" });

  // Auto-generate TaskID
  let taskId = "TASK-001";
  try {
    const url = `https://api.airtable.com/v0/${AGENT_TASKS_BASE}/${encodeURIComponent(AGENT_TASKS_TABLE)}?fields%5B%5D=TaskID&sort%5B0%5D%5Bfield%5D=TaskID&sort%5B0%5D%5Bdirection%5D=desc&maxRecords=1`;
    const r = await fetch(url, { headers: { Authorization: `Bearer ${AIRTABLE_TOKEN}` } });
    if (r.ok) {
      const d = await r.json();
      if (d.records && d.records.length > 0) {
        const last = d.records[0].fields.TaskID || "TASK-000";
        const num = parseInt(last.replace("TASK-", "")) + 1;
        taskId = "TASK-" + String(num).padStart(3, "0");
      }
    }
  } catch (_) {}

  const fields = {
    TaskID: taskId,
    Title: title,
    Description: description || "",
    AssignedTo: id,
    AgentName: agent.name,
    Status: "pending",
    Priority: priority || "normal",
    RequestedBy: requested_by || "system",
    CreatedAt: new Date().toISOString(),
  };

  try {
    const postUrl = `https://api.airtable.com/v0/${AGENT_TASKS_BASE}/${encodeURIComponent(AGENT_TASKS_TABLE)}`;
    const r = await fetch(postUrl, {
      method: "POST",
      headers: { Authorization: `Bearer ${AIRTABLE_TOKEN}`, "Content-Type": "application/json" },
      body: JSON.stringify({ fields }),
    });
    const d = await r.json();
    if (!r.ok) return res.status(r.status).json({ ok: false, error: d.error });
    res.json({ ok: true, task_id: taskId, record_id: d.id, agent_id: id, fields: d.fields });
  } catch (e) {
    res.status(500).json({ ok: false, error: e.message });
  }
});

