const POSITION_MEMORY_DIR = join(__dirname, "public", "position-data", "position-memory");

function loadPositionMemory(positionId) {
  try {
    const filePath = join(POSITION_MEMORY_DIR, `${positionId}.json`);
    return JSON.parse(readFileSync(filePath, "utf8"));
  } catch { return { position_id: positionId, memories: [], preferences: { response_style: "กระชับ", morning_briefing: true, language: "th" } }; }
}

function savePositionMemory(positionId, data) {
  const filePath = join(POSITION_MEMORY_DIR, `${positionId}.json`);
  writeFileSync(filePath, JSON.stringify(data, null, 2), "utf8");
  // Also persist to Google Drive for long-term storage (non-blocking)
  const driveFileName = `position_${positionId}.json`
  saveToDrive(DRIVE_POSITION_MEMORY, driveFileName, data).catch(() => {})
}

// GET /api/personal-ai/:positionId/context
app.get("/api/personal-ai/:positionId/context", (req, res) => {
  const { positionId } = req.params;
  const store = loadPositions();
  const position = store.positions.find(p => p.position_id === positionId);
  if (!position) {
    return res.status(404).json({ ok: false, error: "position_not_found", position_id: positionId });
  }
  const memory = loadPositionMemory(positionId);
  const pendingTasks = (memory.memories || []).filter(m => m.type === "task" && m.status !== "done");
  const context = {
    position,
    memory,
    summary: {
      pending_task_count: pendingTasks.length,
      nearest_deadline: pendingTasks
        .filter(t => t.deadline)
        .sort((a, b) => a.deadline.localeCompare(b.deadline))[0] || null,
      kpi_count: (position.kpis || []).length,
      subordinate_count: (position.subordinate_positions || []).length,
    }
  };
  res.json({ ok: true, context });
});

// POST /api/personal-ai/:positionId/chat
app.post("/api/personal-ai/:positionId/chat", async (req, res) => {
  const { positionId } = req.params;
  const { message, conversation_history } = req.body;
  if (!message) return res.status(400).json({ ok: false, error: "message_required" });

  const store = loadPositions();
  const position = store.positions.find(p => p.position_id === positionId);
  if (!position) return res.status(404).json({ ok: false, error: "position_not_found" });

  const memory = loadPositionMemory(positionId);
  const context = { position, memory };

  const apiKey = process.env.ANTHROPIC_API_KEY || process.env.ANTHROPIC_KEY_1;
  if (!apiKey) {
    return res.json({ ok: true, reply: "ขออภัย ระบบ AI ไม่พร้อมในขณะนี้ กรุณาลองใหม่ภายหลัง" });
  }

  const systemPrompt = `คุณเป็น AI ประจำตำแหน่ง${position.title_th} ของกรมส่งเสริมการเกษตร กระทรวงเกษตรและสหกรณ์
คุณรู้จักงานของตำแหน่งนี้ดี รู้ KPI รู้งานค้าง รู้นโยบายล่าสุด รู้ผู้ดำรงตำแหน่ง
ตอบเป็นภาษาไทย กระชับ เป็นมิตร เหมือนผู้ช่วยส่วนตัวที่เก่งงานราชการ
ถามเชิงรุกเพื่อช่วยงาน อย่ารอให้ถาม ถ้าเห็นงานที่ควรทำให้แนะนำทันที
ใช้ **ตัวหนา** สำหรับข้อความสำคัญ ใช้ emoji ช่วยให้อ่านง่าย

ข้อมูล Context ของตำแหน่งนี้:
${JSON.stringify(context, null, 2)}

วันที่ปัจจุบัน: ${new Date().toLocaleDateString("th-TH", { weekday: "long", year: "numeric", month: "long", day: "numeric" })}`;

  const messages = [
    ...(conversation_history || []).filter(m => m.role && m.content),
    { role: "user", content: message }
  ];

  try {
    const aiResp = await fetch("https://api.anthropic.com/v1/messages", {
      method: "POST",
      headers: {
        "x-api-key": apiKey,
        "anthropic-version": "2023-06-01",
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        model: "claude-opus-4-7",
        max_tokens: 1200,
        system: systemPrompt,
        messages,
      }),
    });
    const aiData = await aiResp.json();
    if (aiData.error) throw new Error(aiData.error.message);
    const reply = aiData.content?.[0]?.text || "ขออภัย ไม่สามารถประมวลผลได้";
    appendSystemLog({ action: "personal_ai_chat", user: position.incumbent?.name || positionId, detail: `Position: ${positionId} | Q: ${message.slice(0, 60)}` });
    res.json({ ok: true, reply, position_id: positionId });
  } catch (err) {
    console.error("[personal-ai/chat] error:", err.message);
    res.json({ ok: false, reply: "ขออภัย ระบบ AI เกิดข้อผิดพลาด: " + err.message });
  }
});

// POST /api/personal-ai/:positionId/save-memory
app.post("/api/personal-ai/:positionId/save-memory", (req, res) => {
  const { positionId } = req.params;
  const { type, content, deadline } = req.body;
  if (!type || !content) return res.status(400).json({ ok: false, error: "type_and_content_required" });
  if (!["task", "note"].includes(type)) return res.status(400).json({ ok: false, error: "type_must_be_task_or_note" });

  const memory = loadPositionMemory(positionId);
  const newEntry = {
    date: new Date().toISOString().split("T")[0],
    type,
    content,
    ...(deadline ? { deadline } : {}),
    ...(type === "task" ? { status: "pending" } : {}),
    saved_by: "system",
  };
  memory.memories = memory.memories || [];
  memory.memories.push(newEntry);

  // Also save to positions.json pending_tasks for tasks
  if (type === "task") {
    const store = loadPositions();
    const pos = store.positions.find(p => p.position_id === positionId);
    if (pos) {
      pos.pending_tasks = pos.pending_tasks || [];
      pos.pending_tasks.push({ content, deadline: deadline || null, created_at: new Date().toISOString(), status: "pending" });
      savePositions(store);
    }
  }

  try {
    mkdirSync(POSITION_MEMORY_DIR, { recursive: true });
    savePositionMemory(positionId, memory);
    res.json({ ok: true, saved: newEntry, total_memories: memory.memories.length });
  } catch (err) {
    res.status(500).json({ ok: false, error: err.message });
  }
});

// GET /api/personal-ai/:positionId/morning-briefing
