// POST /api/briefing/generate/:positionId
app.post("/api/briefing/generate/:positionId", async (req, res) => {
  const { positionId } = req.params;
  const store = loadPositions();
  const position = store.positions.find(p => p.position_id === positionId);
  if (!position) return res.status(404).json({ ok: false, error: "position_not_found" });

  const today = new Date().toISOString().split("T")[0];
  const todayTh = new Date().toLocaleDateString("th-TH", { weekday: "long", year: "numeric", month: "long", day: "numeric" });
  const pendingTasks = (position.pending_tasks || []).filter(t => t.status !== "done");

  const apiKey = process.env.ANTHROPIC_API_KEY || process.env.ANTHROPIC_KEY_1;
  let briefing_text;

  if (!apiKey) {
    briefing_text = `📅 Briefing ประจำวัน — ${todayTh}\n\nตำแหน่ง: ${position.title_th}\nผู้ดำรง: ${position.incumbent?.name || "ว่าง"}\nงานค้าง: ${pendingTasks.length} รายการ\nKPI ที่ต้องติดตาม: ${(position.kpis||[]).map(k=>k.name).join(", ")}\n\n💡 คำถามเชิงรุก: วันนี้มีประเด็นเร่งด่วนที่ต้องการข้อมูลเพิ่มเติมไหมครับ?`;
  } else {
    try {
      const systemPrompt = `คุณเป็น AI ประจำตำแหน่ง${position.title_th} จงสร้าง morning briefing ภาษาไทยกระชับ เป็นมิตร ให้ข้อมูลที่จำเป็นสำหรับวันนี้ ระบุงานค้าง deadline ข่าวสารสำคัญ และถามคำถามเชิงรุก 1 ข้อ ความยาวไม่เกิน 5 ประเด็น ใช้ emoji ประกอบ`;
      const userPrompt = `วันที่: ${todayTh}
ผู้ดำรงตำแหน่ง: ${position.incumbent?.name || "ว่าง"}
งานค้าง: ${JSON.stringify(pendingTasks)}
KPI: ${JSON.stringify(position.kpis)}
ความรับผิดชอบ: ${(position.responsibilities||[]).join(", ")}
หน่วยงาน: ${position.department_name}`;

      const aiResp = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST",
        headers: {
          "x-api-key": apiKey,
          "anthropic-version": "2023-06-01",
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          model: "claude-opus-4-7",
          max_tokens: 700,
          system: systemPrompt,
          messages: [{ role: "user", content: userPrompt }],
        }),
      });
      const aiData = await aiResp.json();
      if (aiData.error) throw new Error(aiData.error.message);
      briefing_text = aiData.content?.[0]?.text || "";
    } catch (err) {
      console.error("[briefing/generate] AI error:", err.message);
      briefing_text = `📅 Briefing ประจำวัน — ${todayTh}\n\nตำแหน่ง: ${position.title_th}\nผู้ดำรง: ${position.incumbent?.name || "ว่าง"}\nKPI: ${(position.kpis||[]).map(k=>k.name).join(", ")}\n\n⚠️ ระบบ AI ขัดข้องชั่วคราว กรุณาตรวจสอบระบบ`;
    }
  }

  const entry = {
    date: today,
    generated_at: new Date().toISOString(),
    briefing_text,
    sent_via_line: false,
    line_message_id: null,
  };

  const history = loadBriefingHistory(positionId);
  // ลบ briefing เก่าของวันนี้ออกก่อน (ถ้ามี) แล้วเพิ่มใหม่
  history.briefings = history.briefings.filter(b => b.date !== today);
  history.briefings.unshift(entry);
  // เก็บแค่ 30 วันล่าสุด
  history.briefings = history.briefings.slice(0, 30);
  saveBriefingHistory(positionId, history);

  res.json({ ok: true, briefing_text, generated_at: entry.generated_at, position_id: positionId });
});

// POST /api/briefing/send-line/:positionId
app.post("/api/briefing/send-line/:positionId", async (req, res) => {
  const { positionId } = req.params;
  const lineToken = process.env.LINE_CHANNEL_ACCESS_TOKEN;

  const store = loadPositions();
  const position = store.positions.find(p => p.position_id === positionId);
  if (!position) return res.status(404).json({ ok: false, error: "position_not_found" });

  const history = loadBriefingHistory(positionId);
  const latest = history.briefings[0];
  if (!latest) return res.status(404).json({ ok: false, error: "no_briefing_found", hint: "generate briefing first" });

  if (!lineToken) {
    console.warn(`[briefing/send-line] LINE_CHANNEL_ACCESS_TOKEN not set — skipping LINE push for ${positionId}`);
    return res.json({ ok: false, error: "no_line_token", hint: "Set Fly secret: fly secrets set LINE_CHANNEL_ACCESS_TOKEN=your_token" });
  }

  const incumbentName = position.incumbent?.name || "เจ้าหน้าที่";
  const lineUserId = position.incumbent?.line_user_id;
  const lineGroupId = position.incumbent?.line_group_id;
  const targetId = lineUserId || lineGroupId;

  if (!targetId) {
    return res.json({ ok: false, error: "no_line_target", hint: "เพิ่ม line_user_id หรือ line_group_id ใน incumbent ของตำแหน่งนี้" });
  }

  const flexMessage = {
    type: "flex",
    altText: `📋 Briefing ประจำวัน — ${position.title_th}`,
    contents: {
      type: "bubble",
      header: {
        type: "box",
        layout: "vertical",
        contents: [
          { type: "text", text: "🌾 กรมส่งเสริมการเกษตร", size: "sm", color: "#ffffff" },
          { type: "text", text: "Daily Briefing", size: "xs", color: "#c8e6c9" },
        ],
        backgroundColor: "#1a5c1a",
        paddingAll: "16px",
      },
      body: {
        type: "box",
        layout: "vertical",
        contents: [
          { type: "text", text: `สวัสดีตอนเช้า ${incumbentName}`, weight: "bold", size: "md", margin: "none" },
          { type: "separator", margin: "md" },
          { type: "text", text: latest.briefing_text, wrap: true, size: "sm", margin: "md", color: "#333333" },
        ],
        paddingAll: "16px",
      },
      footer: {
        type: "box",
        layout: "horizontal",
        contents: [
          {
            type: "button",
            action: {
              type: "uri",
              label: "เปิด AI ของฉัน",
              uri: `https://g2g-ai-pool.fly.dev/personal-ai.html?position=${positionId}`,
            },
            style: "primary",
            color: "#1a5c1a",
            height: "sm",
          },
        ],
        paddingAll: "12px",
      },
    },
  };

  try {
    const pushResp = await fetch("https://api.line.me/v2/bot/message/push", {
      method: "POST",
      headers: {
        "Authorization": `Bearer ${lineToken}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ to: targetId, messages: [flexMessage] }),
    });
    const pushData = await pushResp.json();
    if (pushData.message && pushData.message !== "ok" && pushResp.status >= 400) {
      throw new Error(JSON.stringify(pushData));
    }
    // บันทึกสถานะส่งแล้ว
    latest.sent_via_line = true;
    latest.line_sent_at = new Date().toISOString();
    latest.line_message_id = pushData.sentMessages?.[0]?.id || null;
    saveBriefingHistory(positionId, history);
    res.json({ ok: true, message: "ส่ง LINE สำเร็จ", position_id: positionId });
  } catch (err) {
    console.error("[briefing/send-line] error:", err.message);
    res.json({ ok: false, error: err.message });
  }
});

// POST /api/briefing/daily-run
app.post("/api/briefing/daily-run", async (req, res) => {
  const store = loadPositions();
  const active = (store.positions || []).filter(p => p.status === "active");
  const results = [];

  for (const pos of active) {
    const pid = pos.position_id;
    try {
      // Generate
      const genResp = await fetch(`http://localhost:${PORT}/api/briefing/generate/${pid}`, { method: "POST" });
      const genData = await genResp.json();
      // Send LINE
      const sendResp = await fetch(`http://localhost:${PORT}/api/briefing/send-line/${pid}`, { method: "POST" });
      const sendData = await sendResp.json();
      results.push({ position_id: pid, generated: genData.ok, line_sent: sendData.ok, line_note: sendData.error || null });
    } catch (err) {
      results.push({ position_id: pid, generated: false, line_sent: false, error: err.message });
    }
  }

  const success = results.filter(r => r.generated).length;
  const lineSent = results.filter(r => r.line_sent).length;
  console.log(`[briefing/daily-run] Generated: ${success}/${active.length} | LINE sent: ${lineSent}/${active.length}`);
  appendSystemLog({ action: "daily_briefing_run", detail: `Generated: ${success}/${active.length}, LINE: ${lineSent}/${active.length}`, results });
  res.json({ ok: true, total: active.length, generated: success, line_sent: lineSent, results });
});

// GET /api/briefing/history/:positionId
app.get("/api/briefing/history/:positionId", (req, res) => {
  const { positionId } = req.params;
  const limit = parseInt(req.query.limit) || 7;
  const history = loadBriefingHistory(positionId);
  history.briefings = history.briefings.slice(0, limit);
  res.json({ ok: true, position_id: positionId, count: history.briefings.length, briefings: history.briefings });
});

// GET /api/briefing/all-latest — ดึง briefing ล่าสุดของทุกตำแหน่ง
app.get("/api/briefing/all-latest", (req, res) => {
  const store = loadPositions();
  const results = (store.positions || []).map(p => {
    const history = loadBriefingHistory(p.position_id);
    const latest = history.briefings[0] || null;
    return {
      position_id: p.position_id,
      title_th: p.title_th,
      incumbent_name: p.incumbent?.name || "ว่าง",
      status: p.status,
      latest_briefing: latest,
    };
  });
  res.json({ ok: true, positions: results });
});

console.log("[G2G] Daily Briefing System registered ✅");

// --- Scheduler: Daily Briefing 08:00 ICT (01:00 UTC) ---
function scheduleDailyBriefing() {
  const now = new Date();
  const next8am = new Date();
  next8am.setUTCHours(1, 0, 0, 0); // 08:00 ICT = 01:00 UTC
  if (next8am <= now) next8am.setDate(next8am.getDate() + 1);
  const msUntil = next8am - now;
  const hUntil = Math.round(msUntil / 3600000 * 10) / 10;
  console.log(`[briefing-scheduler] Next daily run in ${hUntil}h (${next8am.toISOString()})`);
  setTimeout(async () => {
    console.log("[briefing-scheduler] Running daily briefing...");
    try {
      await fetch(`http://localhost:${PORT}/api/briefing/daily-run`, { method: "POST" });
    } catch (err) {
      console.error("[briefing-scheduler] error:", err.message);
    }
    scheduleDailyBriefing(); // reschedule for next day
  }, msUntil);
}

