// Google Drive Integration Routes
// ใช้ Google Drive REST API ผ่าน OAuth token ที่ผูกกับ CEO account (Woravat Auapinyakul)
// Set GOOGLE_DRIVE_ACCESS_TOKEN ใน Fly.io secrets เมื่อต้องการเปิดใช้งานจริง
// หรือใช้ GOOGLE_SERVICE_ACCOUNT_JSON สำหรับ service account

const GOOGLE_DRIVE_TOKEN = process.env.GOOGLE_DRIVE_ACCESS_TOKEN || null;
const DRIVE_FOLDER_MAP = {
  position_memory: process.env.DRIVE_FOLDER_POSITION_MEMORY || null,
  briefing_history: process.env.DRIVE_FOLDER_BRIEFINGS || null,
  handover_documents: process.env.DRIVE_FOLDER_HANDOVERS || null,
  reports: process.env.DRIVE_FOLDER_REPORTS || null,
  policies: process.env.DRIVE_FOLDER_POLICIES || null,
};

// Helper: ตรวจว่า Drive credentials พร้อมใช้หรือไม่
function driveReady() {
  return !!GOOGLE_DRIVE_TOKEN;
}

// GET /api/drive/test — verify Drive proxy write works (saveToDrive + 302-redirect pattern)
app.get("/api/drive/test", async (req, res) => {
  const result = await saveToDrive(DRIVE_LINE_MEMORY, 'health_check.json', {
    ok: true, ts: new Date().toISOString(), platform: 'g2g-ai-pool'
  })
  res.json({ ok: result, drive_proxy: !!DRIVE_PROXY_URL, folder: DRIVE_LINE_MEMORY })
})

// GET /api/drive/status — ตรวจสถานะ Google Drive connection
app.get("/api/drive/status", (req, res) => {
  res.json({
    ok: true,
    connected: driveReady(),
    message: driveReady()
      ? "Google Drive พร้อมใช้งาน"
      : "ยังไม่ได้ตั้งค่า GOOGLE_DRIVE_ACCESS_TOKEN — ไปที่ fly secrets set GOOGLE_DRIVE_ACCESS_TOKEN=<token>",
    folders: DRIVE_FOLDER_MAP,
    index_file_id: "1Jb3JHm8ltEjDdHINDL4T92ZhrCYLMpI9",
    index_url: "https://drive.google.com/file/d/1Jb3JHm8ltEjDdHINDL4T92ZhrCYLMpI9/view",
  });
});

// GET /api/drive/list?folder=position_memory — list ไฟล์ในโฟลเดอร์
app.get("/api/drive/list", async (req, res) => {
  const folder = req.query.folder || "position_memory";
  if (!driveReady()) {
    return res.json({
      ok: false,
      message: "Google Drive not configured — set GOOGLE_DRIVE_ACCESS_TOKEN",
      folder,
      files: [],
    });
  }
  try {
    const folderId = DRIVE_FOLDER_MAP[folder];
    const q = folderId
      ? `'${folderId}' in parents and trashed=false`
      : `name contains 'G2G' and trashed=false`;
    const driveRes = await fetch(
      `https://www.googleapis.com/drive/v3/files?q=${encodeURIComponent(q)}&fields=files(id,name,mimeType,modifiedTime,size)&orderBy=modifiedTime desc`,
      { headers: { Authorization: `Bearer ${GOOGLE_DRIVE_TOKEN}` } }
    );
    const data = await driveRes.json();
    if (data.error) throw new Error(data.error.message);
    res.json({ ok: true, folder, files: data.files || [] });
  } catch (err) {
    res.status(500).json({ ok: false, error: err.message });
  }
});

// POST /api/drive/upload — อัปโหลดไฟล์ขึ้น Drive
// body: { filename: string, content: string (JSON/text), folder: string, mimeType?: string }
app.post("/api/drive/upload", async (req, res) => {
  if (!driveReady()) {
    return res.json({ ok: false, message: "Google Drive not configured — set GOOGLE_DRIVE_ACCESS_TOKEN" });
  }
  const { filename, content, folder, mimeType } = req.body;
  if (!filename || !content) return res.status(400).json({ ok: false, error: "filename and content required" });
  try {
    const folderId = DRIVE_FOLDER_MAP[folder] || null;
    const metadata = { name: filename, ...(folderId ? { parents: [folderId] } : {}) };
    const boundary = "g2g_drive_boundary";
    const contentType = mimeType || "application/json";
    const body = [
      `--${boundary}`,
      "Content-Type: application/json; charset=UTF-8",
      "",
      JSON.stringify(metadata),
      `--${boundary}`,
      `Content-Type: ${contentType}`,
      "",
      typeof content === "string" ? content : JSON.stringify(content),
      `--${boundary}--`,
    ].join("\r\n");
    const uploadRes = await fetch(
      "https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&fields=id,name,webViewLink",
      {
        method: "POST",
        headers: {
          Authorization: `Bearer ${GOOGLE_DRIVE_TOKEN}`,
          "Content-Type": `multipart/related; boundary=${boundary}`,
        },
        body,
      }
    );
    const data = await uploadRes.json();
    if (data.error) throw new Error(data.error.message);
    appendSystemLog({ action: "drive_upload", user: "system", detail: `Uploaded ${filename} → Drive ID: ${data.id}` });
    res.json({ ok: true, file: data });
  } catch (err) {
    res.status(500).json({ ok: false, error: err.message });
  }
});

// GET /api/drive/file/:fileId — ดาวน์โหลด/อ่าน file content
app.get("/api/drive/file/:fileId", async (req, res) => {
  if (!driveReady()) {
    return res.json({ ok: false, message: "Google Drive not configured — set GOOGLE_DRIVE_ACCESS_TOKEN" });
  }
  try {
    const fileRes = await fetch(
      `https://www.googleapis.com/drive/v3/files/${req.params.fileId}?alt=media`,
      { headers: { Authorization: `Bearer ${GOOGLE_DRIVE_TOKEN}` } }
    );
    const text = await fileRes.text();
    let content;
    try { content = JSON.parse(text); } catch { content = text; }
    res.json({ ok: true, fileId: req.params.fileId, content });
  } catch (err) {
    res.status(500).json({ ok: false, error: err.message });
  }
});

// POST /api/drive/sync-position/:positionId — sync position memory file ขึ้น Drive
app.post("/api/drive/sync-position/:positionId", async (req, res) => {
  const positionId = req.params.positionId;
  const memPath = path.join(__dirname, "public", "position-data", "position-memory", `${positionId}.json`);
  if (!fs.existsSync(memPath)) {
    return res.status(404).json({ ok: false, error: "Position memory file not found locally" });
  }
  const content = fs.readFileSync(memPath, "utf8");
  if (!driveReady()) {
    return res.json({ ok: false, message: "Google Drive not configured", local_content: JSON.parse(content) });
  }
  try {
    // ค้นหาว่ามีไฟล์นี้ใน Drive แล้วหรือยัง
    const searchRes = await fetch(
      `https://www.googleapis.com/drive/v3/files?q=${encodeURIComponent(`name='${positionId}_memory.json' and trashed=false`)}&fields=files(id,name)`,
      { headers: { Authorization: `Bearer ${GOOGLE_DRIVE_TOKEN}` } }
    );
    const searchData = await searchRes.json();
    const existing = searchData.files?.[0];
    let result;
    if (existing) {
      // อัปเดตไฟล์เดิม
      const patchRes = await fetch(
        `https://www.googleapis.com/upload/drive/v3/files/${existing.id}?uploadType=media&fields=id,name`,
        {
          method: "PATCH",
          headers: {
            Authorization: `Bearer ${GOOGLE_DRIVE_TOKEN}`,
            "Content-Type": "application/json",
          },
          body: content,
        }
      );
      result = await patchRes.json();
    } else {
      // สร้างไฟล์ใหม่
      const boundary = "g2g_sync_boundary";
      const metadata = { name: `${positionId}_memory.json` };
      const body = [
        `--${boundary}`,
        "Content-Type: application/json; charset=UTF-8",
        "",
        JSON.stringify(metadata),
        `--${boundary}`,
        "Content-Type: application/json",
        "",
        content,
        `--${boundary}--`,
      ].join("\r\n");
      const createRes = await fetch(
        "https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&fields=id,name",
        {
          method: "POST",
          headers: {
            Authorization: `Bearer ${GOOGLE_DRIVE_TOKEN}`,
            "Content-Type": `multipart/related; boundary=${boundary}`,
          },
          body,
        }
      );
      result = await createRes.json();
    }
    if (result.error) throw new Error(result.error.message);
    appendSystemLog({ action: "drive_sync", user: "system", detail: `Synced ${positionId} → Drive ID: ${result.id}` });
    res.json({ ok: true, positionId, driveFileId: result.id, action: existing ? "updated" : "created" });
  } catch (err) {
    res.status(500).json({ ok: false, error: err.message });
  }
});

// =============================================================
// LINE Webhook + Position Identification System
// POST /webhook/line
// =============================================================

const LINE_USERS_FILE = join(__dirname, "public", "position-data", "line-users.json");

function loadLineUsers() {
  try { return JSON.parse(readFileSync(LINE_USERS_FILE, "utf8")); }
  catch { return { users: [], pending_verification: [], last_updated: new Date().toISOString().slice(0, 10) }; }
}

function saveLineUsers(data) {
  data.last_updated = new Date().toISOString().slice(0, 10);
  writeFileSync(LINE_USERS_FILE, JSON.stringify(data, null, 2), "utf8");
}

async function sendLineReply(replyToken, text) {
  const token = process.env.LINE_CHANNEL_ACCESS_TOKEN;
  if (!token) { console.warn("[LINE] LINE_CHANNEL_ACCESS_TOKEN not set — skip reply"); return; }
  try {
    await fetch("https://api.line.me/v2/bot/message/reply", {
      method: "POST",
      headers: { "Content-Type": "application/json", "Authorization": `Bearer ${token}` },
      body: JSON.stringify({ replyToken, messages: [{ type: "text", text }] }),
    });
  } catch (err) { console.error("[LINE reply] error:", err.message); }
}

async function sendLinePush(lineUserId, text) {
  const token = process.env.LINE_CHANNEL_ACCESS_TOKEN;
  if (!token) return { ok: false, error: "no_line_token" };
  try {
    const res = await fetch("https://api.line.me/v2/bot/message/push", {
      method: "POST",
      headers: { "Content-Type": "application/json", "Authorization": `Bearer ${token}` },
      body: JSON.stringify({ to: lineUserId, messages: [{ type: "text", text }] }),
    });
    const data = await res.json();
    if (!res.ok) return { ok: false, error: JSON.stringify(data) };
    return { ok: true, status: res.status };
  } catch (err) {
    console.error("[LINE push] error:", err.message);
    return { ok: false, error: err.message };
  }
}

async function handleVerifiedUser(event, knownUser) {
  const message = event.message?.text || "";
  try {
    const chatResp = await fetch(`http://localhost:${PORT}/api/personal-ai/${knownUser.position_id}/chat`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ message, conversation_history: [] }),
    });
    const chatData = await chatResp.json();
    await sendLineReply(event.replyToken, chatData.reply || "ขออภัยครับ ระบบขัดข้องชั่วคราว");
  } catch (err) {
    console.error("[handleVerifiedUser] error:", err.message);
    await sendLineReply(event.replyToken, "ขออภัยครับ ระบบขัดข้องชั่วคราว กรุณาลองใหม่อีกครั้ง");
  }
}

async function handleVerification(event, pending, lineUsers) {
  const message = event.message?.text?.trim() || "";
  const userId = event.source.userId;

  const confirmed = ["✅", "ใช่", "ถูก", "ยืนยัน", "yes", "ok", "ครับ", "ค่ะ"].some(kw =>
    message.toLowerCase().includes(kw.toLowerCase())
  );

  if (confirmed) {
    const store = loadPositions();
    const pos = store.positions.find(p => p.position_id === pending.guessed_position_id);
    lineUsers.users.push({
      line_user_id: userId,
      line_display_name: "",
      position_id: pending.guessed_position_id,
      position_title: pos?.title_th || "",
      verified_at: new Date().toISOString(),
      receive_briefing: true,
      briefing_time: "08:00",
    });
    lineUsers.pending_verification = lineUsers.pending_verification.filter(p => p.line_user_id !== userId);
    saveLineUsers(lineUsers);
    appendSystemLog({ action: "line_user_verified", user: userId, detail: `position: ${pending.guessed_position_id}` });
    await sendLineReply(event.replyToken,
      `ยืนยันแล้วครับ ท่าน${pos?.title_th || ""} 🎉\n\nตั้งแต่นี้ผมจะส่ง briefing ประจำวันให้ท่านทุกเช้า 08:00 น.\nและพร้อมช่วยงานของท่านได้ตลอดเวลาครับ\n\nพิมพ์อะไรถามผมได้เลยครับ`);
  } else {
    // ตอบชื่อ-ตำแหน่งใหม่ — ลองค้นหาตำแหน่งจาก text
    const store = loadPositions();
    const matched = store.positions.find(p =>
      message.includes(p.title_th) ||
      (p.incumbent?.name && message.includes(p.incumbent.name))
    );
    if (matched) {
      lineUsers.pending_verification = lineUsers.pending_verification.filter(p => p.line_user_id !== userId);
      lineUsers.pending_verification.push({
        line_user_id: userId,
        guessed_position_id: matched.position_id,
        asked_at: new Date().toISOString(),
      });
      saveLineUsers(lineUsers);
      await sendLineReply(event.replyToken,
        `ขอบคุณครับ ท่าน${matched.title_th} ${matched.incumbent?.name || ""} ใช่ไหมครับ?\nกรุณากด ✅ หรือพิมพ์ "ใช่" เพื่อยืนยัน`);
    } else {
      await sendLineReply(event.replyToken,
        `ขอบคุณครับ ขออภัยที่ค้นหาตำแหน่งไม่พบอัตโนมัติ\nกรุณาแจ้งชื่อ-ตำแหน่งให้ชัดเจนอีกครั้ง หรือติดต่อผู้ดูแลระบบเพื่อ link ด้วยตนเองครับ`);
    }
  }
}

async function handleNewUser(event, userId, lineUsers) {
  const store = loadPositions();
  const verifiedPositionIds = new Set(lineUsers.users.map(u => u.position_id));
  const unlinked = store.positions.filter(p =>
    p.status === "active" && !verifiedPositionIds.has(p.position_id)
  );

  let replyText;
  if (unlinked.length === 1) {
    const pos = unlinked[0];
    replyText = `สวัสดีครับ 🙏\nท่าน${pos.title_th} ${pos.incumbent?.name || ""} ใช่ไหมครับ?\n\nกรุณาพิมพ์ "ใช่" เพื่อยืนยัน หรือแจ้งชื่อ-ตำแหน่งจริงได้เลยครับ`;
    const already = lineUsers.pending_verification.find(p => p.line_user_id === userId);
    if (!already) {
      lineUsers.pending_verification.push({
        line_user_id: userId,
        guessed_position_id: pos.position_id,
        asked_at: new Date().toISOString(),
      });
    }
  } else {
    replyText = `สวัสดีครับ 🙏 ผมคือ AI ผู้ช่วยของกรมส่งเสริมการเกษตรจังหวัดแพร่\n\nกรุณาแจ้งชื่อ-ตำแหน่งของท่านด้วยครับ เพื่อให้ผมให้บริการได้ถูกต้อง\n\nเช่น: "เกษตรจังหวัด สุพล" หรือ "รองเกษตรจังหวัด จิรัชยา"`;
  }

  saveLineUsers(lineUsers);
  appendSystemLog({ action: "line_new_user", user: userId, detail: `unlinked_positions: ${unlinked.length}` });
  await sendLineReply(event.replyToken, replyText);
}

async function handleLineMessage(event) {
  if (!event.replyToken) return; // echo test or no reply needed
  const userId = event.source?.userId;
  if (!userId) return;

  const lineUsers = loadLineUsers();
  const knownUser = lineUsers.users.find(u => u.line_user_id === userId);

  if (knownUser) {
    return handleVerifiedUser(event, knownUser);
  }

  const pending = lineUsers.pending_verification.find(p => p.line_user_id === userId);
  if (pending) {
    return handleVerification(event, pending, lineUsers);
  }

  return handleNewUser(event, userId, lineUsers);
}

