// GET /api/line-users/list — verified users
app.get("/api/line-users/list", (req, res) => {
  const lineUsers = loadLineUsers();
  const store = loadPositions();
  const enriched = lineUsers.users.map(u => {
    const pos = store.positions.find(p => p.position_id === u.position_id);
    return { ...u, incumbent_name: pos?.incumbent?.name || "", title_th: pos?.title_th || u.position_title };
  });
  res.json({ ok: true, total: enriched.length, users: enriched, last_updated: lineUsers.last_updated });
});

// GET /api/line-users/pending — pending verification
app.get("/api/line-users/pending", (req, res) => {
  const lineUsers = loadLineUsers();
  const store = loadPositions();
  const enriched = lineUsers.pending_verification.map(p => {
    const pos = store.positions.find(pos => pos.position_id === p.guessed_position_id);
    return { ...p, guessed_title: pos?.title_th || "", guessed_incumbent: pos?.incumbent?.name || "" };
  });
  res.json({ ok: true, total: enriched.length, pending: enriched });
});

// POST /api/line-users/link — manual link
app.post("/api/line-users/link", (req, res) => {
  const { line_user_id, position_id, line_display_name } = req.body;
  if (!line_user_id || !position_id) return res.status(400).json({ ok: false, error: "line_user_id and position_id required" });

  const store = loadPositions();
  const pos = store.positions.find(p => p.position_id === position_id);
  if (!pos) return res.status(404).json({ ok: false, error: "position_not_found" });

  const lineUsers = loadLineUsers();
  // Remove duplicates
  lineUsers.users = lineUsers.users.filter(u => u.line_user_id !== line_user_id && u.position_id !== position_id);
  lineUsers.pending_verification = lineUsers.pending_verification.filter(p => p.line_user_id !== line_user_id);
  lineUsers.users.push({
    line_user_id,
    line_display_name: line_display_name || "",
    position_id,
    position_title: pos.title_th,
    verified_at: new Date().toISOString(),
    receive_briefing: true,
    briefing_time: "08:00",
  });
  saveLineUsers(lineUsers);
  appendSystemLog({ action: "line_user_manual_link", user: "admin", detail: `${line_user_id} → ${position_id}` });
  res.json({ ok: true, line_user_id, position_id, position_title: pos.title_th });
});

// DELETE /api/line-users/:lineUserId — remove user
app.delete("/api/line-users/:lineUserId", (req, res) => {
  const lineUsers = loadLineUsers();
  const before = lineUsers.users.length;
  lineUsers.users = lineUsers.users.filter(u => u.line_user_id !== req.params.lineUserId);
  lineUsers.pending_verification = lineUsers.pending_verification.filter(p => p.line_user_id !== req.params.lineUserId);
  saveLineUsers(lineUsers);
  res.json({ ok: true, removed: before - lineUsers.users.length });
});

// POST /api/line-users/broadcast — ส่ง briefing ทุกคนที่ verified แล้ว
app.post("/api/line-users/broadcast", async (req, res) => {
  const lineUsers = loadLineUsers();
  const verified = lineUsers.users.filter(u => u.receive_briefing);
  const results = [];

  for (const user of verified) {
    try {
      // Generate briefing สำหรับตำแหน่งนั้น
      const genResp = await fetch(`http://localhost:${PORT}/api/briefing/generate/${user.position_id}`, { method: "POST" });
      const genData = await genResp.json();
      const text = genData.briefing_text;
      if (!text) { results.push({ position_id: user.position_id, ok: false, error: "no_briefing_text" }); continue; }
      const pushResult = await sendLinePush(user.line_user_id, text);
      results.push({ position_id: user.position_id, line_user_id: user.line_user_id, ok: pushResult.ok, error: pushResult.error || null });
    } catch (err) {
      results.push({ position_id: user.position_id, ok: false, error: err.message });
    }
  }

  const sent = results.filter(r => r.ok).length;
  appendSystemLog({ action: "line_broadcast", user: "admin", detail: `Sent: ${sent}/${verified.length}` });
  res.json({ ok: true, sent, total: verified.length, results });
});

console.log("[G2G] LINE Users Management API registered ✅");

// =============================================================
// Override /api/briefing/send-line/:positionId to use line-users.json
// (Replaces old logic that used incumbent.line_user_id directly)
// =============================================================

// POST /api/briefing/send-line-v2/:positionId — uses line-users.json
app.post("/api/briefing/send-line-v2/:positionId", async (req, res) => {
  const { positionId } = req.params;
  const lineUsers = loadLineUsers();
  const target = lineUsers.users.find(u => u.position_id === positionId && u.receive_briefing);

  if (!target) {
    return res.json({ ok: false, message: "no_verified_line_user", hint: "เจ้าหน้าที่ต้องทัก LINE OA ก่อนเพื่อยืนยันตัวตน หรือใช้ /api/line-users/link เพื่อ link ด้วยตนเอง" });
  }

  const history = loadBriefingHistory(positionId);
  const latest = history.briefings?.[0];
  if (!latest) return res.json({ ok: false, message: "no_briefing_generated", hint: "generate briefing ก่อน" });

  const result = await sendLinePush(target.line_user_id, latest.briefing_text);
  if (result.ok) {
    latest.sent_via_line = true;
    latest.line_sent_at = new Date().toISOString();
    saveBriefingHistory(positionId, history);
  }
  res.json({ ok: result.ok, line_user_id: target.line_user_id, position_id: positionId, error: result.error || null });
});

