// ─── Per-LINE-User Memory (Airtable "LINEUsers" table) ───────────────────────

// In-memory fallback for LINE user memory (used when Airtable returns 403 / is unavailable)
// Key: `${lineUserId}:${channelId}`  Value: memoryData object
const LINE_MEMORY_FALLBACK = new Map();

async function loadUserMemoryLine(lineUserId, channelId) {
  try {
    const formula = `AND({lineUserId}="${lineUserId}",{channelId}="${channelId}")`;
    const url = `https://api.airtable.com/v0/${LINE_AIRTABLE_BASE}/${encodeURIComponent("LINEUsers")}?filterByFormula=${encodeURIComponent(formula)}&maxRecords=1`;
    const r = await fetch(url, { headers: { Authorization: `Bearer ${AIRTABLE_TOKEN}` } });
    if (r.status === 403) {
      console.warn("[LINE-MEMORY] Airtable 403 for LINEUsers — using in-memory fallback");
      return LINE_MEMORY_FALLBACK.get(`${lineUserId}:${channelId}`) || null;
    }
    if (!r.ok) return LINE_MEMORY_FALLBACK.get(`${lineUserId}:${channelId}`) || null;
    const data = await r.json();
    if (!data.records?.length) return LINE_MEMORY_FALLBACK.get(`${lineUserId}:${channelId}`) || null;
    const rec = data.records[0];
    const f = rec.fields;
    let memoryJSON = {};
    try { memoryJSON = typeof f.memoryJSON === "string" ? JSON.parse(f.memoryJSON) : (f.memoryJSON || {}); } catch (_) {}
    return { _recId: rec.id, lineUserId: f.lineUserId, channelId: f.channelId, displayName: f.displayName || "", positionId: f.positionId || "", memoryJSON, lastSeen: f.lastSeen, messageCount: f.messageCount || 0 };
  } catch (e) {
    console.error("[LINE-MEMORY] loadUserMemoryLine error:", e.message);
    return LINE_MEMORY_FALLBACK.get(`${lineUserId}:${channelId}`) || null;
  }
}

async function saveUserMemoryLine(lineUserId, channelId, memoryData) {
  // Always update in-memory fallback so memory works within session
  LINE_MEMORY_FALLBACK.set(`${lineUserId}:${channelId}`, {
    ...memoryData,
    lineUserId,
    channelId,
    lastSeen: new Date().toISOString(),
    messageCount: (memoryData.messageCount || 0) + 1,
  });
  try {
    const existing = await loadUserMemoryLine(lineUserId, channelId);
    const now = new Date().toISOString();
    const memoryJSON = JSON.stringify(memoryData.memoryJSON || {});
    if (existing?._recId) {
      const url = `https://api.airtable.com/v0/${LINE_AIRTABLE_BASE}/${encodeURIComponent("LINEUsers")}/${existing._recId}`;
      const r = await fetch(url, {
        method: "PATCH",
        headers: { Authorization: `Bearer ${AIRTABLE_TOKEN}`, "Content-Type": "application/json" },
        body: JSON.stringify({ fields: { displayName: memoryData.displayName || existing.displayName || "", positionId: memoryData.positionId || existing.positionId || "", memoryJSON, lastSeen: now, messageCount: (existing.messageCount || 0) + 1 }, typecast: true }),
      });
      if (r.status === 403) { console.warn("[LINE-MEMORY] Airtable 403 on PATCH — in-memory fallback active"); return; }
    } else {
      const url = `https://api.airtable.com/v0/${LINE_AIRTABLE_BASE}/${encodeURIComponent("LINEUsers")}`;
      const r = await fetch(url, {
        method: "POST",
        headers: { Authorization: `Bearer ${AIRTABLE_TOKEN}`, "Content-Type": "application/json" },
        body: JSON.stringify({ fields: { lineUserId, channelId, displayName: memoryData.displayName || "", positionId: memoryData.positionId || "", memoryJSON, lastSeen: now, messageCount: 1 }, typecast: true }),
      });
      if (r.status === 403) { console.warn("[LINE-MEMORY] Airtable 403 on POST — in-memory fallback active"); return; }
    }
  } catch (e) {
    console.error("[LINE-MEMORY] saveUserMemoryLine error:", e.message);
  }
  // Also persist full memory to Google Drive for long-term storage (non-blocking)
  const driveFileName = `line_${lineUserId.replace(/[^a-zA-Z0-9]/g,'_')}_${channelId}.json`
  saveToDrive(DRIVE_LINE_MEMORY, driveFileName, {
    lineUserId, channelId, ...memoryData, lastSaved: new Date().toISOString()
  }).catch(() => {})
}

async function appendLineConversationLog(lineUserId, channelId, message, role) {
  try {
    const existing = await loadUserMemoryLine(lineUserId, channelId);
    const mem = existing?.memoryJSON || {};
    const history = Array.isArray(mem.history) ? mem.history : [];
    history.push({ role, content: message, ts: new Date().toISOString() });
    // Keep last 10 turns (20 messages)
    if (history.length > 20) history.splice(0, history.length - 20);
    mem.history = history;
    await saveUserMemoryLine(lineUserId, channelId, { ...(existing || {}), memoryJSON: mem });
  } catch (e) {
    console.error("[LINE-MEMORY] appendLineConversationLog error:", e.message);
  }
}

function buildLineMemoryContext(memoryData) {
  if (!memoryData) return "";
  const parts = [];
  if (memoryData.displayName) parts.push(`ชื่อ: ${memoryData.displayName}`);
  if (memoryData.positionId)  parts.push(`ตำแหน่ง: ${memoryData.positionId}`);
  const mem = memoryData.memoryJSON || {};
  if (mem.role)         parts.push(`บทบาท: ${mem.role}`);
  if (mem.organization) parts.push(`องค์กร: ${mem.organization}`);
  if (mem.province)     parts.push(`จังหวัด: ${mem.province}`);
  if (mem.phone)        parts.push(`โทร: ${mem.phone}`);
  if (mem.notes)        parts.push(`บันทึก: ${mem.notes}`);
  if (memoryData.messageCount > 1) parts.push(`คุยมาแล้ว ${memoryData.messageCount} ข้อความ`);
  // Last few conversation turns as context
  const history = Array.isArray(mem.history) ? mem.history : [];
  const recentTurns = history.slice(-6);
  if (recentTurns.length) {
    const turnText = recentTurns.map(t => `${t.role === "user" ? "User" : "AI"}: ${(t.content || "").slice(0, 200)}`).join("\n");
    parts.push(`\nบทสนทนาล่าสุด:\n${turnText}`);
  }
  if (!parts.length) return "";
  return `\n\n# ข้อมูลที่จำได้เกี่ยวกับผู้ใช้คนนี้\n${parts.join(" | ")}`;
}

// ─── Upgraded /webhook/line with multi-tenant routing ────────────────────────
// Wraps the existing POST /webhook/line handler with multi-channel support.
// The LINE payload's "destination" field = the OA's LINE channel ID.
// If found in registry → use that channel's token + system prompt.
// Otherwise falls back to existing logic unchanged.

async function handleLineMultiTenant(req, res) {
  // ACK immediately
  res.status(200).json({ ok: true });
  try {
    const destination = req.body?.destination;  // LINE channel ID
    const channelConfig = (destination && LINE_CHANNEL_REGISTRY.get(destination))
      || LINE_DEFAULT_CHANNEL_CONFIG;
    const lineToken = channelConfig.channelAccessToken || process.env.LINE_CHANNEL_ACCESS_TOKEN;
    if (!lineToken) { console.warn("[MT-WEBHOOK] No LINE token for channel:", destination); return; }

    const events = req.body?.events || [];
    for (const event of events) {
      if (event.type !== "message" || event.message?.type !== "text") continue;
      const userId   = event.source?.userId;
      const userText = event.message?.text || "";
      if (!userId) continue;

      // Group/room message filtering — only reply when explicitly triggered
      if (event.source?.type === 'group' || event.source?.type === 'room') {
        const triggerWords = ['น้องเอไอ', '@เอไอ', 'ช่วยหน่อย', 'ถามว่า', '?', 'คำถาม'];
        const hasTrigger = triggerWords.some(w => userText.includes(w));
        if (!hasTrigger) continue; // skip non-triggered group messages
      }

      // 1) Load user memory
      const memData = await loadUserMemoryLine(userId, destination || "__default__").catch(() => null);

      // 2) Build full system prompt with memory context
      const memContext = buildLineMemoryContext(memData);
      const fullSystem = channelConfig.systemPrompt + memContext;

      // 3) Build conversation history from memory
      const memHistory = (memData?.memoryJSON?.history || [])
        .slice(-12)
        .map(t => ({ role: t.role === "user" ? "user" : "assistant", content: t.content || "" }));

      // 4) Call Claude directly with channel-scoped system prompt + history
      const ANTHROPIC_KEY = process.env.ANTHROPIC_API_KEY || process.env.ANTHROPIC_KEY_1;
      let replyText = "ขออภัยครับ ระบบชั่วคราวขัดข้อง";
      let tokensUsed = 0;
      if (ANTHROPIC_KEY) {
        try {
          const messages = [...memHistory, { role: "user", content: userText }];
          // Channel-specific model routing
          const phraeAgencyChannelId = process.env.LINE_CHANNELID_PHRAEAGENCY || "PHRAEAGENCY";
          // Team G2G bots — all use Opus 4.6
          const teamG2GSlugs = ["GAME_G2G","WANNA_G2G","BAIPARE_G2G","SOM_G2G","CHADA_G2G","PIMONRAT_G2G","PANNEE_G2G","PUWASA_G2G"];
          const teamG2GChannelIds = teamG2GSlugs.map(s => process.env[`LINE_CHANNELID_${s}`]).filter(Boolean);
          const OPUS_CHANNELS = new Set(["EXECCOPILOT", "2010057448", "MHESI02", phraeAgencyChannelId, ...teamG2GChannelIds]); // PLATvip1, MHESI02=เลขารมว, PHRAEAGENCY, TeamG2G x8
          const lineModel = OPUS_CHANNELS.has(destination) ? "claude-opus-4-6" : "claude-sonnet-4-6";
          const aiResp = await fetch("https://api.anthropic.com/v1/messages", {
            method: "POST",
            headers: { "x-api-key": ANTHROPIC_KEY, "anthropic-version": "2023-06-01", "content-type": "application/json" },
            body: JSON.stringify({ model: lineModel, max_tokens: 800, temperature: 0.7, system: fullSystem, messages }),
          });
          const aiData = await aiResp.json();
          if (aiData.error) throw new Error(aiData.error.message);
          replyText = (aiData.content || []).map(c => c.text).join("\n").trim() || replyText;
          tokensUsed = (aiData.usage?.input_tokens || 0) + (aiData.usage?.output_tokens || 0);
        } catch (aiErr) {
          console.error("[MT-WEBHOOK] AI error:", aiErr.message);
        }
      }

      // 5) Reply via the correct channel token
      await fetch("https://api.line.me/v2/bot/message/reply", {
        method: "POST",
        headers: { Authorization: `Bearer ${lineToken}`, "Content-Type": "application/json" },
        body: JSON.stringify({ replyToken: event.replyToken, messages: [{ type: "text", text: replyText }] }),
      }).catch(e => console.error("[MT-WEBHOOK] LINE reply error:", e.message));

      // 6) Persist memory (fire-and-forget)
      const channelKey = destination || "__default__";
      appendLineConversationLog(userId, channelKey, userText, "user").catch(() => {});
      appendLineConversationLog(userId, channelKey, replyText, "assistant").catch(() => {});
      const updatedMem = { ...(memData || {}), displayName: memData?.displayName || "", memoryJSON: memData?.memoryJSON || {} };
      saveUserMemoryLine(userId, channelKey, updatedMem).catch(() => {});

      console.log(`[MT-WEBHOOK] channel=${channelKey} user=${userId} tokens=${tokensUsed}`);
    }
  } catch (err) {
    console.error("[MT-WEBHOOK] error:", err.message);
  }
}

app.post("/webhook/line/mt", handleLineMultiTenant);
console.log("[G2G] LINE Multi-Tenant Webhook registered: POST /webhook/line/mt ✅");

// ─── Management APIs ──────────────────────────────────────────────────────────

// GET /api/line-channels — list all registered channels
app.get("/api/line-channels", (_req, res) => {
  const channels = [];
  // From registry (Airtable-backed)
  for (const [id, cfg] of LINE_CHANNEL_REGISTRY.entries()) {
    channels.push({
      channelId: id,
      agencyName: cfg.agencyName,
      hasToken: !!(cfg.channelAccessToken),
      hasSystemPrompt: !!(cfg.systemPrompt),
      source: "airtable",
    });
  }
  // Add env-based channels not in registry
  const envIds = Object.keys(process.env)
    .filter(k => k.startsWith("LINE_TOKEN_") && k !== "LINE_TOKEN_DEFAULT")
    .map(k => k.replace("LINE_TOKEN_", ""));
  for (const id of envIds) {
    if (!LINE_CHANNEL_REGISTRY.has(id)) {
      channels.push({ channelId: id, agencyName: id, hasToken: true, hasSystemPrompt: false, source: "env" });
    }
  }
  res.json({ ok: true, count: channels.length, channels });
});

// POST /api/line-channels — register new channel in Airtable LINEChannels
app.post("/api/line-channels", async (req, res) => {
  try {
    const { channelId, channelAccessToken, agencyName, systemPrompt, agencyBrand, airtableBase } = req.body || {};
    if (!channelId || !agencyName) {
      return res.status(400).json({ ok: false, error: "channelId and agencyName are required" });
    }
    const url = `https://api.airtable.com/v0/${LINE_AIRTABLE_BASE}/${encodeURIComponent("LINEChannels")}`;
    const r = await fetch(url, {
      method: "POST",
      headers: { Authorization: `Bearer ${AIRTABLE_TOKEN}`, "Content-Type": "application/json" },
      body: JSON.stringify({
        fields: {
          channelId,
          channelAccessToken: channelAccessToken || "",
          agencyName,
          agencyBrand: typeof agencyBrand === "object" ? JSON.stringify(agencyBrand) : (agencyBrand || "{}"),
          systemPrompt: systemPrompt || SYSTEM_PROMPT_G2G_THAI,
          airtableBase: airtableBase || AIRTABLE_BASE,
        },
        typecast: true,
      }),
    });
    const data = await r.json();
    if (data.error) throw new Error(data.error.message);
    // Add to in-memory registry immediately
    LINE_CHANNEL_REGISTRY.set(channelId, {
      channelId,
      channelAccessToken: channelAccessToken || "",
      agencyName,
      agencyBrand: agencyBrand || {},
      airtableBase: airtableBase || AIRTABLE_BASE,
      systemPrompt: systemPrompt || SYSTEM_PROMPT_G2G_THAI,
      _recId: data.id,
    });
    console.log(`[LINE-CHANNELS] Registered channel ${channelId} for ${agencyName}`);
    res.json({ ok: true, channelId, agencyName, recordId: data.id, webhookUrl: `https://g2g-ai-pool.fly.dev/webhook/line/mt` });
  } catch (err) {
    console.error("[LINE-CHANNELS] POST error:", err.message);
    res.status(500).json({ ok: false, error: err.message });
  }
});

// POST /api/line-channels/reload — reload registry from Airtable
app.post("/api/line-channels/reload", async (_req, res) => {
  try {
    LINE_CHANNEL_REGISTRY.clear();
    await loadLineChannelRegistry();
    res.json({ ok: true, count: LINE_CHANNEL_REGISTRY.size, channels: [...LINE_CHANNEL_REGISTRY.keys()] });
  } catch (err) {
    res.status(500).json({ ok: false, error: err.message });
  }
});

// GET /api/line-users/:channelId — list users for a specific channel
app.get("/api/line-users/:channelId", async (req, res) => {
  try {
    const { channelId } = req.params;
    const formula = `{channelId}="${channelId}"`;
    const url = `https://api.airtable.com/v0/${LINE_AIRTABLE_BASE}/${encodeURIComponent("LINEUsers")}?filterByFormula=${encodeURIComponent(formula)}&maxRecords=100`;
    const r = await fetch(url, { headers: { Authorization: `Bearer ${AIRTABLE_TOKEN}` } });
    const data = await r.json();
    const users = (data.records || []).map(rec => ({
      recId: rec.id,
      lineUserId: rec.fields.lineUserId,
      displayName: rec.fields.displayName || "",
      positionId: rec.fields.positionId || "",
      lastSeen: rec.fields.lastSeen || "",
      messageCount: rec.fields.messageCount || 0,
    }));
    res.json({ ok: true, channelId, count: users.length, users });
  } catch (err) {
    res.status(500).json({ ok: false, error: err.message });
  }
});

// GET /api/line-users/:channelId/:userId/memory — get user memory
app.get("/api/line-users/:channelId/:userId/memory", async (req, res) => {
  try {
    const { channelId, userId } = req.params;
    const mem = await loadUserMemoryLine(userId, channelId);
    if (!mem) return res.status(404).json({ ok: false, error: "user_not_found" });
    res.json({ ok: true, channelId, lineUserId: userId, memory: mem });
  } catch (err) {
    res.status(500).json({ ok: false, error: err.message });
  }
});

// POST /api/agency/onboard — full agency onboarding
app.post("/api/agency/onboard", async (req, res) => {
  try {
    const { agencyName, agencyNameEn, channelId, channelAccessToken, primaryColor, positions } = req.body || {};
    if (!agencyName || !channelId) {
      return res.status(400).json({ ok: false, error: "agencyName and channelId are required" });
    }

    const checklist = [];
    const agencyBrand = { primaryColor: primaryColor || "#00B900", agencyNameEn: agencyNameEn || "" };

    // 1) Build default system prompt for this agency
    const systemPrompt = `คุณคือผู้ช่วยอัจฉริยะของ ${agencyName} — ให้บริการประชาชนและเจ้าหน้าที่ผ่าน LINE\nพูดจาสุภาพ เข้าใจง่าย กระชับ ตอบภาษาไทยเป็นหลัก\nถ้าไม่ทราบข้อมูลให้แจ้งช่องทางติดต่อหน่วยงานโดยตรง`;

    // 2) Register in Airtable LINEChannels
    const url = `https://api.airtable.com/v0/${LINE_AIRTABLE_BASE}/${encodeURIComponent("LINEChannels")}`;
    const r = await fetch(url, {
      method: "POST",
      headers: { Authorization: `Bearer ${AIRTABLE_TOKEN}`, "Content-Type": "application/json" },
      body: JSON.stringify({
        fields: { channelId, channelAccessToken: channelAccessToken || "", agencyName, agencyBrand: JSON.stringify(agencyBrand), systemPrompt, airtableBase: AIRTABLE_BASE },
        typecast: true,
      }),
    });
    const recData = await r.json();
    if (recData.error) throw new Error(recData.error.message);
    checklist.push({ step: "LINEChannels record", status: "done", id: recData.id });

    // 3) Register in Channels table (for existing AI routing compatibility)
    const channelRec = await airtablePost(ONBOARD_TABLE, {
      channel_name: agencyName,
      channel_id_ext: channelId,
      channel_type: "gov_app",
      tier: "ministry",
      active: !!(channelAccessToken),
      system_prompt: systemPrompt,
    }).catch(e => { checklist.push({ step: "Channels record", status: "skipped", reason: e.message }); return null; });
    if (channelRec) checklist.push({ step: "Channels record", status: "done", id: channelRec.id });

    // 4) Update in-memory registry
    LINE_CHANNEL_REGISTRY.set(channelId, {
      channelId, channelAccessToken: channelAccessToken || "", agencyName, agencyBrand,
      airtableBase: AIRTABLE_BASE, systemPrompt, _recId: recData.id,
    });
    checklist.push({ step: "Registry updated", status: "done" });

    // 5) Positions summary
    if (Array.isArray(positions) && positions.length) {
      checklist.push({ step: "Positions configured", status: "done", count: positions.length, positions });
    }

    checklist.push({ step: "Webhook URL", status: "ready", url: `https://g2g-ai-pool.fly.dev/webhook/line/mt` });
    checklist.push({ step: "Set LINE webhook in LINE Developer Console", status: "manual", url: `https://g2g-ai-pool.fly.dev/webhook/line/mt` });
    if (!channelAccessToken) {
      checklist.push({ step: "LINE Channel Access Token", status: "pending", action: "POST /api/line-channels with channelAccessToken to complete" });
    }

    console.log(`[AGENCY-ONBOARD] ${agencyName} (${channelId}) onboarded ✅`);
    res.json({ ok: true, agencyName, channelId, checklist, webhookUrl: `https://g2g-ai-pool.fly.dev/webhook/line/mt` });
  } catch (err) {
    console.error("[AGENCY-ONBOARD] error:", err.message);
    res.status(500).json({ ok: false, error: err.message });
  }
});

console.log("[G2G] Multi-tenant LINE + AI Memory endpoints registered ✅");

