// Static cache for each new province
const _PROV_STATIC = { chiangrai: null, udonthani: null };
function provStatic(province, key) {
  if (!_PROV_STATIC[province]) {
    try {
      const file = join(__dirname, "public", `management-data-${province}.json`);
      _PROV_STATIC[province] = JSON.parse(readFileSync(file, "utf8"));
      console.log(`[MGMT-${province.toUpperCase()}] Static cache loaded ✅ personnel:`, _PROV_STATIC[province].personnel?.length);
    } catch (e) {
      console.warn(`[MGMT-${province.toUpperCase()}] Static cache load failed:`, e.message);
      _PROV_STATIC[province] = { personnel: [], budget: [], projects: [], contracts: [], integration: [] };
    }
  }
  return key ? (_PROV_STATIC[province][key] || []) : _PROV_STATIC[province];
}

// Generic CORS helper for province APIs
function provCors(req, res, next) {
  const key = req.header("x-api-key");
  const province = req.params?.province || req.url.match(/\/api\/([a-z]+)\//)?.[1];
  const validKeys = ['phrae2026','chiangrai2026','udonthani2026'];
  if (!validKeys.includes(key)) {
    return res.status(401).json({ ok: false, error: "invalid x-api-key" });
  }
  res.header("Access-Control-Allow-Origin", "*");
  res.header("Access-Control-Allow-Headers", "x-api-key,Content-Type");
  res.header("Access-Control-Allow-Methods", "GET,POST,PUT,DELETE,OPTIONS");
  if (req.method === "OPTIONS") return res.sendStatus(200);
  next();
}

// Register routes for each new province (chiangrai, udonthani)
['chiangrai','udonthani'].forEach(prov => {
  // GET /api/{prov}/management/summary
  app.get(`/api/${prov}/management/summary`, provCors, async (req, res) => {
    try {
      const data = provStatic(prov);
      res.json({
        ok: true,
        province: prov,
        source: 'static',
        summary: {
          personnel: data.personnel?.length || 0,
          budget: data.budget?.length || 0,
          projects: data.projects?.length || 0,
          contracts: data.contracts?.length || 0,
          integration: data.integration?.length || 0,
          budget_total: (data.budget || []).reduce((s, b) => s + (b.budget_total || 0), 0),
          disbursed_total: (data.budget || []).reduce((s, b) => s + (b.disbursed_total || 0), 0),
        }
      });
    } catch (e) { res.status(500).json({ ok: false, error: e.message }); }
  });

  // GET /api/{prov}/management/personnel
  app.get(`/api/${prov}/management/personnel`, provCors, (req, res) => {
    const arr = provStatic(prov, 'personnel');
    res.json({ ok: true, province: prov, total: arr.length, people: arr });
  });
  // POST /api/{prov}/management/personnel
  app.post(`/api/${prov}/management/personnel`, provCors, (req, res) => {
    const arr = provStatic(prov, 'personnel');
    const newRec = { id: 'rec' + Date.now().toString(36) + Math.random().toString(36).slice(2,8), ...req.body };
    arr.push(newRec);
    res.json({ ok: true, province: prov, record: newRec, note: 'static cache — not persisted across restart unless Airtable scope added' });
  });

  // GET /api/{prov}/management/budget
  app.get(`/api/${prov}/management/budget`, provCors, (req, res) => {
    const arr = provStatic(prov, 'budget');
    res.json({ ok: true, province: prov, total: arr.length, agencies: arr });
  });

  // GET /api/{prov}/management/projects
  app.get(`/api/${prov}/management/projects`, provCors, (req, res) => {
    const arr = provStatic(prov, 'projects');
    res.json({ ok: true, province: prov, total: arr.length, projects: arr });
  });
  // POST /api/{prov}/management/projects
  app.post(`/api/${prov}/management/projects`, provCors, (req, res) => {
    const arr = provStatic(prov, 'projects');
    const rec = { id: 'rec' + Date.now().toString(36) + Math.random().toString(36).slice(2,8), ...req.body };
    arr.push(rec);
    res.json({ ok: true, province: prov, record: rec });
  });
  // PUT /api/{prov}/management/projects/:id/progress
  app.put(`/api/${prov}/management/projects/:id/progress`, provCors, (req, res) => {
    const arr = provStatic(prov, 'projects');
    const target = arr.find(p => p.id === req.params.id);
    if (!target) return res.status(404).json({ ok: false, error: 'project not found' });
    if (typeof req.body.progress_pct === 'number') target.progress_pct = req.body.progress_pct;
    if (req.body.status) target.status = req.body.status;
    res.json({ ok: true, province: prov, record: target });
  });

  // GET /api/{prov}/management/contracts
  app.get(`/api/${prov}/management/contracts`, provCors, (req, res) => {
    const arr = provStatic(prov, 'contracts');
    res.json({ ok: true, province: prov, total: arr.length, contracts: arr });
  });
  // POST /api/{prov}/management/contracts
  app.post(`/api/${prov}/management/contracts`, provCors, (req, res) => {
    const arr = provStatic(prov, 'contracts');
    const rec = { id: 'rec' + Date.now().toString(36) + Math.random().toString(36).slice(2,8), ...req.body };
    arr.push(rec);
    res.json({ ok: true, province: prov, record: rec });
  });

  // GET /api/{prov}/management/integration
  app.get(`/api/${prov}/management/integration`, provCors, (req, res) => {
    const arr = provStatic(prov, 'integration');
    res.json({ ok: true, province: prov, total: arr.length, plans: arr });
  });
  // POST /api/{prov}/management/integration
  app.post(`/api/${prov}/management/integration`, provCors, (req, res) => {
    const arr = provStatic(prov, 'integration');
    const rec = { id: 'rec' + Date.now().toString(36) + Math.random().toString(36).slice(2,8), ...req.body };
    arr.push(rec);
    res.json({ ok: true, province: prov, record: rec });
  });

  console.log(`[G2G] ${prov.toUpperCase()} management API registered ✅`);
});


// =============================================================
// FINANCE / BUDGET MODULE — Multi-province (phrae, chiangrai, udonthani)
// Iron Rule #1: ระบบใช้งานได้จริง (real CRUD), #5 static fallback, #8 จ้างเหมา = ค่าใช้สอย
// Generated: 2026-05-25
// =============================================================

// Per-province finance data cache (loaded lazily, mutated in-memory)
const _FIN_CACHE = { phrae: null, chiangrai: null, udonthani: null };
function finData(province) {
  if (!_FIN_CACHE[province]) {
    try {
      // Phrae uses public/finance-data.json; other provinces fall back to same file as seed (clone)
      const fname = province === 'phrae' ? 'finance-data.json' : `finance-data-${province}.json`;
      let raw;
      try {
        raw = readFileSync(join(__dirname, 'public', fname), 'utf8');
      } catch {
        // fallback to phrae seed if province-specific file missing
        raw = readFileSync(join(__dirname, 'public', 'finance-data.json'), 'utf8');
      }
      _FIN_CACHE[province] = JSON.parse(raw);
      console.log(`[FINANCE-${province.toUpperCase()}] Static cache loaded ✅ transactions:`, _FIN_CACHE[province].transactions?.length || 0);
    } catch (e) {
      console.warn(`[FINANCE-${province.toUpperCase()}] cache load failed:`, e.message);
      _FIN_CACHE[province] = { transactions: [], vouchers: [], budget: [] };
    }
  }
  return _FIN_CACHE[province];
}

// CORS + multi-key auth for finance module (accepts {prov}2026 keys)
function financeCors(req, res, next) {
  const key = req.header('x-api-key') || req.query.apiKey;
  const validKeys = ['phrae2026', 'chiangrai2026', 'udonthani2026'];
  res.header('Access-Control-Allow-Origin', '*');
  res.header('Access-Control-Allow-Headers', 'x-api-key,Content-Type,Authorization');
  res.header('Access-Control-Allow-Methods', 'GET,POST,PUT,DELETE,OPTIONS');
  if (req.method === 'OPTIONS') return res.sendStatus(200);
  if (!validKeys.includes(key)) {
    return res.status(401).json({ ok: false, error: 'invalid x-api-key — expected phrae2026 / chiangrai2026 / udonthani2026' });
  }
  next();
}

function newRecId(prefix) {
  return `${prefix}_${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;
}

// Register routes for each province
['phrae', 'chiangrai', 'udonthani'].forEach(prov => {

  // ───── TRANSACTIONS ─────
  app.get(`/api/${prov}/finance/transactions`, financeCors, (req, res) => {
    const { agency_id, fiscal_year, type, category } = req.query;
    let arr = finData(prov).transactions || [];
    arr = arr.filter(t => t.status !== 'deleted');
    if (agency_id)   arr = arr.filter(t => t.agency_id === agency_id);
    if (fiscal_year) arr = arr.filter(t => String(t.fiscal_year) === String(fiscal_year));
    if (type)        arr = arr.filter(t => t.type === type);
    if (category)    arr = arr.filter(t => (t.category || '').includes(category));
    res.json({ ok: true, province: prov, total: arr.length, transactions: arr });
  });

  app.post(`/api/${prov}/finance/transactions`, financeCors, (req, res) => {
    const b = req.body || {};
    if (!b.date || !b.type || !b.amount || !b.agency_name) {
      return res.status(400).json({ ok: false, error: 'required fields: date, type, amount, agency_name' });
    }
    if (!['income', 'expense'].includes(b.type)) {
      return res.status(400).json({ ok: false, error: 'type must be income or expense' });
    }
    const rec = {
      id: newRecId('trx'),
      date: b.date,
      type: b.type,
      category: b.category || (b.type === 'income' ? 'อื่นๆ' : 'งบดำเนินงาน'),
      agency_id: b.agency_id || '',
      agency_name: b.agency_name,
      amount: Number(b.amount) || 0,
      doc_no: b.doc_no || '',
      description: b.description || '',
      fiscal_year: b.fiscal_year || '2568',
      status: 'active'
    };
    finData(prov).transactions.push(rec);
    res.json({ ok: true, province: prov, record: rec });
  });

  app.put(`/api/${prov}/finance/transactions/:id`, financeCors, (req, res) => {
    const arr = finData(prov).transactions;
    const t = arr.find(x => x.id === req.params.id);
    if (!t) return res.status(404).json({ ok: false, error: 'transaction not found' });
    const updatable = ['date', 'type', 'category', 'agency_id', 'agency_name', 'amount', 'doc_no', 'description', 'fiscal_year'];
    updatable.forEach(k => { if (req.body[k] !== undefined) t[k] = (k === 'amount') ? Number(req.body[k]) : req.body[k]; });
    res.json({ ok: true, province: prov, record: t });
  });

  app.delete(`/api/${prov}/finance/transactions/:id`, financeCors, (req, res) => {
    const arr = finData(prov).transactions;
    const t = arr.find(x => x.id === req.params.id);
    if (!t) return res.status(404).json({ ok: false, error: 'transaction not found' });
    t.status = 'deleted';
    res.json({ ok: true, province: prov, id: t.id, note: 'soft deleted' });
  });

  // ───── VOUCHERS ─────
  app.get(`/api/${prov}/finance/vouchers`, financeCors, (req, res) => {
    const { agency_id, budget_category, status, fiscal_year } = req.query;
    let arr = (finData(prov).vouchers || []).filter(v => v.status !== 'deleted');
    if (agency_id)        arr = arr.filter(v => v.agency_id === agency_id);
    if (budget_category)  arr = arr.filter(v => v.budget_category === budget_category);
    if (status)           arr = arr.filter(v => v.status === status);
    if (fiscal_year)      arr = arr.filter(v => String(v.fiscal_year) === String(fiscal_year));
    res.json({ ok: true, province: prov, total: arr.length, vouchers: arr });
  });

  app.post(`/api/${prov}/finance/vouchers`, financeCors, (req, res) => {
    const b = req.body || {};
    if (!b.voucher_date || !b.voucher_type || !b.amount || !b.agency_name) {
      return res.status(400).json({ ok: false, error: 'required: voucher_date, voucher_type, amount, agency_name' });
    }
    const rec = {
      id: newRecId('vch'),
      voucher_no: b.voucher_no || `ฎ.${Date.now().toString().slice(-6)}`,
      voucher_date: b.voucher_date,
      voucher_type: b.voucher_type,
      budget_category: b.budget_category || 'operating_budget',
      agency_id: b.agency_id || '',
      agency_name: b.agency_name,
      amount: Number(b.amount) || 0,
      requester: b.requester || '',
      approver: b.approver || '',
      purpose: b.purpose || '',
      fiscal_year: b.fiscal_year || '2568',
      status: b.status || 'รออนุมัติ'
    };
    finData(prov).vouchers.push(rec);
    res.json({ ok: true, province: prov, record: rec });
  });

  app.put(`/api/${prov}/finance/vouchers/:id`, financeCors, (req, res) => {
    const v = (finData(prov).vouchers || []).find(x => x.id === req.params.id);
    if (!v) return res.status(404).json({ ok: false, error: 'voucher not found' });
    const upd = ['voucher_no', 'voucher_date', 'voucher_type', 'budget_category', 'agency_id', 'agency_name', 'amount', 'requester', 'approver', 'purpose', 'fiscal_year', 'status'];
    upd.forEach(k => { if (req.body[k] !== undefined) v[k] = (k === 'amount') ? Number(req.body[k]) : req.body[k]; });
    res.json({ ok: true, province: prov, record: v });
  });

  app.delete(`/api/${prov}/finance/vouchers/:id`, financeCors, (req, res) => {
    const v = (finData(prov).vouchers || []).find(x => x.id === req.params.id);
    if (!v) return res.status(404).json({ ok: false, error: 'voucher not found' });
    v.status = 'deleted';
    res.json({ ok: true, province: prov, id: v.id, note: 'soft deleted' });
  });

  // ───── BUDGET (read + write-through, no delete) ─────
  app.get(`/api/${prov}/finance/budget`, financeCors, (req, res) => {
    const { agency_id, fiscal_year } = req.query;
    let arr = finData(prov).budget || [];
    if (agency_id)   arr = arr.filter(b => b.agency_id === agency_id);
    if (fiscal_year) arr = arr.filter(b => String(b.fiscal_year) === String(fiscal_year));
    // recompute disbursed_total from active expense transactions per agency (live view)
    const expenses = (finData(prov).transactions || []).filter(t => t.type === 'expense' && t.status !== 'deleted');
    const out = arr.map(b => {
      const live = expenses.filter(e => e.agency_id === b.agency_id).reduce((s, e) => s + Number(e.amount || 0), 0);
      const total = Number(b.budget_total) || 0;
      const livePct = total > 0 ? Math.round((live / total) * 100) : 0;
      return { ...b, live_disbursed: live, live_disbursed_pct: livePct };
    });
    res.json({ ok: true, province: prov, total: out.length, budget: out });
  });

  app.post(`/api/${prov}/finance/budget`, financeCors, (req, res) => {
    const b = req.body || {};
    if (!b.agency_name) return res.status(400).json({ ok: false, error: 'required: agency_name' });
    const personnel  = Number(b.personnel_budget)  || 0;
    const operating  = Number(b.operating_budget)  || 0;
    const capital    = Number(b.capital_budget)    || 0;
    const subsidy    = Number(b.subsidy_budget)    || 0;
    const other      = Number(b.other_budget)      || 0;
    const total      = personnel + operating + capital + subsidy + other;
    const rec = {
      id: newRecId('bdg'),
      agency_id: b.agency_id || '',
      agency_name: b.agency_name,
      personnel_budget: personnel,
      operating_budget: operating,
      capital_budget: capital,
      subsidy_budget: subsidy,
      other_budget: other,
      budget_total: total,
      disbursed_total: Number(b.disbursed_total) || 0,
      disbursed_pct: total > 0 ? Math.round((Number(b.disbursed_total || 0) / total) * 100) : 0,
      fiscal_year: b.fiscal_year || '2568'
    };
    finData(prov).budget.push(rec);
    res.json({ ok: true, province: prov, record: rec });
  });

  app.put(`/api/${prov}/finance/budget/:id`, financeCors, (req, res) => {
    const rec = (finData(prov).budget || []).find(x => x.id === req.params.id);
    if (!rec) return res.status(404).json({ ok: false, error: 'budget entry not found' });
    const upd = ['agency_id', 'agency_name', 'personnel_budget', 'operating_budget', 'capital_budget', 'subsidy_budget', 'other_budget', 'disbursed_total', 'fiscal_year'];
    upd.forEach(k => { if (req.body[k] !== undefined) rec[k] = (k.endsWith('_budget') || k === 'disbursed_total') ? (Number(req.body[k]) || 0) : req.body[k]; });
    rec.budget_total = (rec.personnel_budget || 0) + (rec.operating_budget || 0) + (rec.capital_budget || 0) + (rec.subsidy_budget || 0) + (rec.other_budget || 0);
    rec.disbursed_pct = rec.budget_total > 0 ? Math.round((rec.disbursed_total / rec.budget_total) * 100) : 0;
    res.json({ ok: true, province: prov, record: rec });
  });

  // ───── REPORTS — Monthly / Quarterly aggregation ─────
  app.get(`/api/${prov}/finance/reports/monthly`, financeCors, (req, res) => {
    const { fiscal_year, agency_id } = req.query;
    let arr = (finData(prov).transactions || []).filter(t => t.status !== 'deleted');
    if (fiscal_year) arr = arr.filter(t => String(t.fiscal_year) === String(fiscal_year));
    if (agency_id)   arr = arr.filter(t => t.agency_id === agency_id);
    // Group by YYYY-MM
    const byMonth = {};
    arr.forEach(t => {
      const m = (t.date || '').slice(0, 7);
      if (!m) return;
      if (!byMonth[m]) byMonth[m] = { month: m, income: 0, expense: 0, count: 0 };
      if (t.type === 'income')  byMonth[m].income  += Number(t.amount || 0);
      if (t.type === 'expense') byMonth[m].expense += Number(t.amount || 0);
      byMonth[m].count++;
    });
    const monthly = Object.values(byMonth).sort((a, b) => a.month.localeCompare(b.month))
      .map(r => ({ ...r, net: r.income - r.expense }));

    // Quarterly (Thai FY: Q1=Oct-Dec, Q2=Jan-Mar, Q3=Apr-Jun, Q4=Jul-Sep)
    const qMap = { Q1: { income: 0, expense: 0, count: 0 }, Q2: { income: 0, expense: 0, count: 0 }, Q3: { income: 0, expense: 0, count: 0 }, Q4: { income: 0, expense: 0, count: 0 } };
    arr.forEach(t => {
      const mo = parseInt((t.date || '').slice(5, 7), 10);
      if (!mo) return;
      let q;
      if (mo >= 10) q = 'Q1';
      else if (mo <= 3)  q = 'Q2';
      else if (mo <= 6)  q = 'Q3';
      else q = 'Q4';
      if (t.type === 'income')  qMap[q].income  += Number(t.amount || 0);
      if (t.type === 'expense') qMap[q].expense += Number(t.amount || 0);
      qMap[q].count++;
    });
    const quarterly = Object.entries(qMap).map(([q, v]) => ({ quarter: q, ...v, net: v.income - v.expense }));

    const totals = arr.reduce((s, t) => {
      if (t.type === 'income')  s.income  += Number(t.amount || 0);
      if (t.type === 'expense') s.expense += Number(t.amount || 0);
      return s;
    }, { income: 0, expense: 0 });
    totals.net = totals.income - totals.expense;
    totals.count = arr.length;

    res.json({ ok: true, province: prov, fiscal_year: fiscal_year || 'all', agency_id: agency_id || 'all', totals, monthly, quarterly });
  });

  console.log(`[G2G] ${prov.toUpperCase()} finance API registered ✅`);
});


// =============================================================
// PROJECT MANAGER MODULE — activities, milestones, exec summary
// Iron Rule #1: real CRUD — static JSON-backed, write-through.
// Generated: 2026-05-25
// Routes registered for: phrae, chiangrai, udonthani
// =============================================================
let _PROJ_ACTIVITY_CACHE = null;
function projActivityCache() {
  if (_PROJ_ACTIVITY_CACHE) return _PROJ_ACTIVITY_CACHE;
  try {
    const file = join(__dirname, "public", "project-activity-data.json");
    _PROJ_ACTIVITY_CACHE = JSON.parse(readFileSync(file, "utf8"));
    console.log("[PROJ-MGR] Activity cache loaded ✅ provinces:", Object.keys(_PROJ_ACTIVITY_CACHE.activities || {}).join(","));
  } catch (e) {
    console.warn("[PROJ-MGR] Activity cache load failed:", e.message);
    _PROJ_ACTIVITY_CACHE = {
      activities: { phrae: [], chiangrai: [], udonthani: [] },
      milestones: { phrae: [], chiangrai: [], udonthani: [] }
    };
  }
  return _PROJ_ACTIVITY_CACHE;
}

function getProjectFromProv(prov, projectId) {
  if (prov === 'phrae') {
    return (mgmtStatic('projects') || []).find(p => p.id === projectId);
  }
  return (provStatic(prov, 'projects') || []).find(p => p.id === projectId);
}
function listProjectsForProv(prov) {
  if (prov === 'phrae') return mgmtStatic('projects') || [];
  return provStatic(prov, 'projects') || [];
}

// Thai gov executive summary generator
function makeExecutiveSummary(project, activities, milestones) {
  const p = project || {};
  const acts = activities || [];
  const miles = milestones || [];
  const doneActs = acts.filter(a => a.status === 'ครบ').length;
  const inprogActs = acts.filter(a => a.status === 'อยู่ระหว่างดำเนินการ').length;
  const pendingActs = acts.filter(a => a.status === 'ยังไม่ดำเนินการ').length;
  const doneMs = miles.filter(m => m.completed).length;
  const fy = p.fiscal_year || '2568';
  const budget = (p.budget_total || p.budget || 0).toLocaleString('th-TH');
  const progress = p.progress_pct || 0;
  const statusText = p.status || 'กำลังดำเนินการ';
  const nextMs = miles.find(m => !m.completed);
  const recentAct = [...acts].sort((a,b) => (b.date||'').localeCompare(a.date||''))[0];

  const headline = `บทสรุปผู้บริหาร — ${p.project_name || 'โครงการ'}`;
  const intro = `โครงการ "${p.project_name || ''}" รหัส ${p.project_code || '-'} ดำเนินการโดย ${p.agency_name || '-'} ภายใต้กรอบงบประมาณ ${budget} บาท ปีงบประมาณ พ.ศ. ${fy} ระยะเวลาดำเนินการ ${p.start_date || '-'} ถึง ${p.end_date || '-'} โดยมีตัวชี้วัดเป้าหมาย: ${p.kpi_target || p.target || '-'}`;
  const progressTxt = `ขณะนี้โครงการมีความก้าวหน้าโดยรวมร้อยละ ${progress} จัดอยู่ในสถานะ "${statusText}" โดยดำเนินกิจกรรมแล้วเสร็จ ${doneActs} รายการ อยู่ระหว่างดำเนินการ ${inprogActs} รายการ และยังไม่ดำเนินการอีก ${pendingActs} รายการ ส่งมอบ Milestones สำเร็จ ${doneMs} จาก ${miles.length} จุด`;
  const nextTxt = nextMs
    ? `Milestone ลำดับถัดไป: ${nextMs.title} กำหนดส่งมอบภายใน ${nextMs.target_date}`
    : `Milestones ทั้งหมดดำเนินการเสร็จสิ้นแล้ว เตรียมจัดทำรายงานปิดโครงการ`;
  const recentTxt = recentAct
    ? `กิจกรรมล่าสุด (${recentAct.date}): ${recentAct.title}`
    : `ยังไม่มีบันทึกกิจกรรม`;
  const risk = progress < 30
    ? 'ข้อเสนอแนะ: ความก้าวหน้าต่ำกว่าแผน ควรเร่งรัดการเบิกจ่ายและทบทวนกลยุทธ์การดำเนินงาน'
    : progress < 70
    ? 'ข้อเสนอแนะ: ดำเนินการเป็นไปตามแผน ควรติดตามผลกระทบและเตรียมการประเมินกลางโครงการ'
    : 'ข้อเสนอแนะ: ผลดำเนินงานดี ควรเตรียมการตรวจรับ KPI และจัดทำรายงานสรุปบทเรียน';
  const summary = [headline, intro, progressTxt, nextTxt, recentTxt, risk].join("\n\n");
  return {
    headline,
    sections: { intro, progress: progressTxt, next_milestone: nextTxt, recent_activity: recentTxt, recommendation: risk },
    summary_text: summary,
    metrics: {
      progress_pct: progress,
      activities_done: doneActs,
      activities_inprogress: inprogActs,
      activities_pending: pendingActs,
      milestones_done: doneMs,
      milestones_total: miles.length,
      budget_total: p.budget_total || p.budget || 0,
      fiscal_year: fy,
      status: statusText
    }
  };
}

['phrae','chiangrai','udonthani'].forEach(prov => {
  // GET /api/{prov}/projects/list — list with filters (status, agency_id, fiscal_year)
  app.get(`/api/${prov}/projects/list`, provCors, (req, res) => {
    try {
      const { status, agency_id, fiscal_year, q } = req.query;
      let arr = listProjectsForProv(prov);
      if (status)      arr = arr.filter(p => (p.status||'').includes(status));
      if (agency_id)   arr = arr.filter(p => p.agency_id === agency_id);
      if (fiscal_year) arr = arr.filter(p => String(p.fiscal_year) === String(fiscal_year));
      if (q)           arr = arr.filter(p => (p.project_name||'').includes(q) || (p.project_code||'').includes(q));
      res.json({ ok: true, province: prov, total: arr.length, projects: arr });
    } catch (e) { res.status(500).json({ ok: false, error: e.message }); }
  });

  // GET /api/{prov}/projects/:id/activities
  app.get(`/api/${prov}/projects/:id/activities`, provCors, (req, res) => {
    const all = projActivityCache().activities[prov] || [];
    const acts = all.filter(a => a.project_id === req.params.id)
                    .sort((a,b) => (a.date||'').localeCompare(b.date||''));
    res.json({ ok: true, province: prov, project_id: req.params.id, total: acts.length, activities: acts });
  });

  // POST /api/{prov}/projects/:id/activities (or /log)
  const addActivity = (req, res) => {
    const arr = projActivityCache().activities[prov] = projActivityCache().activities[prov] || [];
    const b = req.body || {};
    const rec = {
      id: 'act_' + Date.now().toString(36) + Math.random().toString(36).slice(2,6),
      project_id: req.params.id,
      date: b.date || new Date().toISOString().slice(0,10),
      title: b.title || '',
      description: b.description || b.title || '',
      status: b.status || 'ครบ',
      responsible: b.responsible || '',
      attachments: b.attachments || []
    };
    arr.push(rec);
    res.json({ ok: true, province: prov, record: rec });
  };
  app.post(`/api/${prov}/projects/:id/activities`, provCors, addActivity);
  app.post(`/api/${prov}/projects/:id/log`, provCors, addActivity);

  // PUT /api/{prov}/projects/:id/activities/:actId
  app.put(`/api/${prov}/projects/:id/activities/:actId`, provCors, (req, res) => {
    const arr = projActivityCache().activities[prov] || [];
    const target = arr.find(a => a.id === req.params.actId && a.project_id === req.params.id);
    if (!target) return res.status(404).json({ ok: false, error: 'activity not found' });
    ['date','title','description','status','responsible','attachments'].forEach(k => {
      if (req.body[k] !== undefined) target[k] = req.body[k];
    });
    res.json({ ok: true, province: prov, record: target });
  });

  // DELETE /api/{prov}/projects/:id/activities/:actId
  app.delete(`/api/${prov}/projects/:id/activities/:actId`, provCors, (req, res) => {
    const cache = projActivityCache();
    const arr = cache.activities[prov] || [];
    const idx = arr.findIndex(a => a.id === req.params.actId && a.project_id === req.params.id);
    if (idx < 0) return res.status(404).json({ ok: false, error: 'activity not found' });
    const removed = arr.splice(idx, 1)[0];
    res.json({ ok: true, province: prov, removed });
  });

  // GET /api/{prov}/projects/:id/milestones
  app.get(`/api/${prov}/projects/:id/milestones`, provCors, (req, res) => {
    const all = projActivityCache().milestones[prov] || [];
    const ms = all.filter(m => m.project_id === req.params.id)
                  .sort((a,b) => (a.target_date||'').localeCompare(b.target_date||''));
    res.json({ ok: true, province: prov, project_id: req.params.id, total: ms.length, milestones: ms });
  });

  // POST /api/{prov}/projects/:id/milestones — add new milestone
  app.post(`/api/${prov}/projects/:id/milestones`, provCors, (req, res) => {
    const cache = projActivityCache();
    const arr = cache.milestones[prov] = cache.milestones[prov] || [];
    const b = req.body || {};
    const existing = arr.filter(m => m.project_id === req.params.id);
    const nextN = existing.length + 1;
    const rec = {
      id: 'ms_' + Date.now().toString(36) + Math.random().toString(36).slice(2,6),
      project_id: req.params.id,
      milestone_code: b.milestone_code || `M${nextN}`,
      title: b.title || '',
      target_date: b.target_date || '',
      actual_date: b.actual_date || null,
      target_pct: typeof b.target_pct === 'number' ? b.target_pct : 0,
      completed: !!b.completed,
      note: b.note || ''
    };
    arr.push(rec);
    res.json({ ok: true, province: prov, record: rec });
  });

  // PUT /api/{prov}/projects/:id/milestones/:msId — update milestone (date, completion)
  app.put(`/api/${prov}/projects/:id/milestones/:msId`, provCors, (req, res) => {
    const arr = projActivityCache().milestones[prov] || [];
    const target = arr.find(m => m.id === req.params.msId && m.project_id === req.params.id);
    if (!target) return res.status(404).json({ ok: false, error: 'milestone not found' });
    ['title','target_date','actual_date','target_pct','completed','note','milestone_code'].forEach(k => {
      if (req.body[k] !== undefined) target[k] = req.body[k];
    });
    // Auto-fill actual_date when marked complete and no actual_date provided
    if (target.completed && !target.actual_date) {
      target.actual_date = new Date().toISOString().slice(0,10);
    }
    res.json({ ok: true, province: prov, record: target });
  });

  // DELETE /api/{prov}/projects/:id/milestones/:msId
  app.delete(`/api/${prov}/projects/:id/milestones/:msId`, provCors, (req, res) => {
    const arr = projActivityCache().milestones[prov] || [];
    const idx = arr.findIndex(m => m.id === req.params.msId && m.project_id === req.params.id);
    if (idx < 0) return res.status(404).json({ ok: false, error: 'milestone not found' });
    const removed = arr.splice(idx, 1)[0];
    res.json({ ok: true, removed });
  });

  // PUT /api/{prov}/projects/:id/progress — update progress % and status
  app.put(`/api/${prov}/projects/:id/progress`, provCors, (req, res) => {
    const p = getProjectFromProv(prov, req.params.id);
    if (!p) return res.status(404).json({ ok: false, error: 'project not found' });
    if (typeof req.body.progress_pct === 'number') {
      p.progress_pct = Math.max(0, Math.min(100, req.body.progress_pct));
    }
    if (req.body.status) p.status = req.body.status;
    res.json({ ok: true, province: prov, record: p });
  });

  // PUT /api/{prov}/projects/:id/dates — update start_date/end_date (used by Gantt drag)
  app.put(`/api/${prov}/projects/:id/dates`, provCors, (req, res) => {
    const p = getProjectFromProv(prov, req.params.id);
    if (!p) return res.status(404).json({ ok: false, error: 'project not found' });
    if (req.body.start_date) p.start_date = req.body.start_date;
    if (req.body.end_date)   p.end_date   = req.body.end_date;
    res.json({ ok: true, record: p });
  });

  // GET /api/{prov}/projects/:id/executive-summary — auto-generated Thai gov summary
  app.get(`/api/${prov}/projects/:id/executive-summary`, provCors, (req, res) => {
    const project = getProjectFromProv(prov, req.params.id);
    if (!project) return res.status(404).json({ ok: false, error: 'project not found' });
    const acts = (projActivityCache().activities[prov] || []).filter(a => a.project_id === req.params.id);
    const ms = (projActivityCache().milestones[prov] || []).filter(m => m.project_id === req.params.id);
    const exec = makeExecutiveSummary(project, acts, ms);
    res.json({ ok: true, province: prov, project_id: req.params.id, ...exec });
  });

  // GET /api/{prov}/projects/dashboard — donut data (done/inprog/pending counts)
  app.get(`/api/${prov}/projects/dashboard`, provCors, (req, res) => {
    const projects = listProjectsForProv(prov);
    const buckets = { 'เสร็จสิ้น': 0, 'ใกล้เสร็จ': 0, 'ดำเนินการ': 0, 'เริ่มต้น': 0, 'ปิดโครงการ': 0, 'อื่นๆ': 0 };
    projects.forEach(p => {
      const pct = p.progress_pct || 0;
      const s = (p.status || '').trim();
      if (s.includes('ปิด'))         buckets['ปิดโครงการ']++;
      else if (s.includes('เสร็จ'))   buckets['เสร็จสิ้น']++;
      else if (pct >= 80)             buckets['ใกล้เสร็จ']++;
      else if (pct >= 10)             buckets['ดำเนินการ']++;
      else if (pct >= 0)              buckets['เริ่มต้น']++;
      else buckets['อื่นๆ']++;
    });
    const total = projects.length || 1;
    const avgProgress = projects.reduce((s,p) => s + (p.progress_pct||0), 0) / total;
    res.json({
      ok: true, province: prov,
      total_projects: projects.length,
      avg_progress: Math.round(avgProgress * 10) / 10,
      buckets,
      total_budget: projects.reduce((s,p) => s + (p.budget_total || p.budget || 0), 0)
    });
  });

  // GET /api/{prov}/projects/:id — single project (registered LAST so specific routes win)
  app.get(`/api/${prov}/projects/:id`, provCors, (req, res) => {
    const p = getProjectFromProv(prov, req.params.id);
    if (!p) return res.status(404).json({ ok: false, error: 'project not found' });
    res.json({ ok: true, project: p });
  });

  console.log(`[PROJ-MGR] ${prov.toUpperCase()} project manager API registered ✅`);
});
// =============================================================
// END PROJECT MANAGER MODULE
// =============================================================


// =============================================================
// HR / PAYROLL MODULE — phrae / chiangrai / udonthani
// Static-fallback CRUD for payslips, salary scale, leaves, OT
// Iron Rule #1: ใช้งานได้จริง — every UI button hits a real endpoint
// Generated: 2026-05-25
// =============================================================

let _HR_CACHE = null;
const HR_FILE = join(__dirname, "public", "hr-payroll-data.json");
function hrData() {
  if (_HR_CACHE) return _HR_CACHE;
  try {
    _HR_CACHE = JSON.parse(readFileSync(HR_FILE, "utf8"));
    console.log("[HR-PAYROLL] Static cache loaded ✅",
      "phrae:", _HR_CACHE.phrae?.payslips?.length,
      "chiangrai:", _HR_CACHE.chiangrai?.payslips?.length,
      "udonthani:", _HR_CACHE.udonthani?.payslips?.length);
  } catch (e) {
    console.warn("[HR-PAYROLL] Static cache load failed:", e.message);
    _HR_CACHE = {
      salary_scale: { academic: [], general: [], executive: [], deduction_rules: {} },
      phrae: { payslips: [], leaves: [], ot_records: [] },
      chiangrai: { payslips: [], leaves: [], ot_records: [] },
      udonthani: { payslips: [], leaves: [], ot_records: [] }
    };
  }
  return _HR_CACHE;
}
function hrPersistAsync() {
  try {
    writeFileSync(HR_FILE, JSON.stringify(_HR_CACHE, null, 2), "utf8");
  } catch (e) {
    console.warn("[HR-PAYROLL] persist failed (read-only FS ok):", e.message);
  }
}
function newHrId(prefix) {
  return prefix + "-" + Date.now().toString(36).toUpperCase() + Math.random().toString(36).slice(2,5).toUpperCase();
}
// monthly Thai personal income tax — annualized progressive brackets w/ default allowances
function calcPayslipFields(input) {
  const base = Number(input.base_salary || 0);
  const ot = Number(input.ot_amount || 0);
  const allow = Number(input.allowance || 0);
  const empType = input.employee_type || "ข้าราชการ";
  const gross = base + ot + allow;
  const ds = hrData().salary_scale.deduction_rules || {};
  const ssfRate = ds.social_security_rate || 0.05;
  const ssfCapBase = ds.social_security_cap_base || 15000;
  const ssfCapAmt = ds.social_security_cap_amount || 750;
  const gpfRate = ds.gpf_rate || 0.03;
  const ssf = Math.min(Math.round(Math.min(base, ssfCapBase) * ssfRate), ssfCapAmt);
  const gpf = (empType === "ข้าราชการ") ? Math.round(base * gpfRate) : 0;
  const annualGross = gross * 12;
  const expenseDed = Math.min(annualGross * 0.40, 100000);
  const personalAllow = 60000;
  const annualSSF = ssf * 12;
  const annualGPF = gpf * 12;
  const taxable = Math.max(0, annualGross - expenseDed - personalAllow - annualSSF - annualGPF);
  const brackets = ds.tax_brackets_2568 || [
    {from:0,to:150000,rate:0}, {from:150001,to:300000,rate:0.05},
    {from:300001,to:500000,rate:0.10}, {from:500001,to:750000,rate:0.15},
    {from:750001,to:1000000,rate:0.20}, {from:1000001,to:2000000,rate:0.25},
    {from:2000001,to:5000000,rate:0.30}, {from:5000001,to:null,rate:0.35}
  ];
  let annualTax = 0;
  for (const b of brackets) {
    if (taxable <= b.from - 1) break;
    const upper = b.to == null ? taxable : Math.min(taxable, b.to);
    const slab = Math.max(0, upper - (b.from - 1));
    annualTax += slab * b.rate;
  }
  const tax = Math.round(annualTax / 12);
  const net = gross - ssf - gpf - tax;
  return { gross, ssf, gpf, tax, net };
}

function hrCors(req, res, next) {
  res.setHeader("Access-Control-Allow-Origin", "*");
  res.setHeader("Access-Control-Allow-Methods", "GET,POST,PUT,DELETE,OPTIONS");
  res.setHeader("Access-Control-Allow-Headers", "Content-Type,Authorization,x-api-key");
  if (req.method === "OPTIONS") return res.sendStatus(204);
  next();
}

['phrae','chiangrai','udonthani'].forEach(prov => {
  const bucket = () => {
    const d = hrData();
    if (!d[prov]) d[prov] = { payslips: [], leaves: [], ot_records: [] };
    if (!d[prov].payslips) d[prov].payslips = [];
    if (!d[prov].leaves) d[prov].leaves = [];
    if (!d[prov].ot_records) d[prov].ot_records = [];
    return d[prov];
  };

  app.get(`/api/${prov}/hr/salary-scale`, hrCors, (req, res) => {
    const d = hrData();
    res.json({ ok: true, province: prov, scale: d.salary_scale });
  });

  app.get(`/api/${prov}/hr/payslips`, hrCors, (req, res) => {
    const b = bucket();
    let arr = b.payslips.slice();
    const { month, personnel_id, agency_name } = req.query;
    if (month) arr = arr.filter(p => p.month === month);
    if (personnel_id) arr = arr.filter(p => p.personnel_id === personnel_id);
    if (agency_name) arr = arr.filter(p => (p.agency_name||"").includes(agency_name));
    res.json({ ok: true, province: prov, total: arr.length, payslips: arr });
  });

  app.post(`/api/${prov}/hr/payslips`, hrCors, (req, res) => {
    const body = req.body || {};
    if (!body.full_name || !body.month) {
      return res.status(400).json({ ok:false, error:"full_name + month จำเป็น" });
    }
    const calc = calcPayslipFields(body);
    const rec = {
      id: newHrId("PSL"),
      personnel_id: body.personnel_id || "",
      full_name: body.full_name,
      agency_name: body.agency_name || "",
      position_level: body.position_level || "",
      level_code: body.level_code || "",
      base_salary: Number(body.base_salary || 0),
      ot_amount:   Number(body.ot_amount || 0),
      allowance:   Number(body.allowance || 0),
      ssf: calc.ssf, gpf: calc.gpf, tax: calc.tax, net: calc.net,
      month: body.month,
      status: body.status || "ฉบับร่าง"
    };
    bucket().payslips.push(rec);
    hrPersistAsync();
    res.json({ ok:true, province:prov, record:rec });
  });

  app.put(`/api/${prov}/hr/payslips/:id`, hrCors, (req, res) => {
    const b = bucket();
    const idx = b.payslips.findIndex(p => p.id === req.params.id);
    if (idx < 0) return res.status(404).json({ ok:false, error:"payslip not found" });
    const merged = { ...b.payslips[idx], ...req.body };
    if (req.body && (req.body.base_salary != null || req.body.ot_amount != null || req.body.allowance != null)) {
      const calc = calcPayslipFields(merged);
      Object.assign(merged, calc);
    }
    b.payslips[idx] = merged;
    hrPersistAsync();
    res.json({ ok:true, province:prov, record:merged });
  });

  app.post(`/api/${prov}/hr/payslips/generate`, hrCors, (req, res) => {
    const body = req.body || {};
    if (!body.full_name || !body.base_salary || !body.month) {
      return res.status(400).json({ ok:false, error:"full_name, base_salary, month จำเป็น" });
    }
    const calc = calcPayslipFields(body);
    const rec = {
      id: newHrId("PSL"),
      personnel_id: body.personnel_id || "",
      full_name: body.full_name,
      agency_name: body.agency_name || "",
      position_level: body.position_level || "",
      level_code: body.level_code || "",
      base_salary: Number(body.base_salary),
      ot_amount:   Number(body.ot_amount || 0),
      allowance:   Number(body.allowance || 0),
      ssf: calc.ssf, gpf: calc.gpf, tax: calc.tax, net: calc.net,
      month: body.month,
      status: body.status || "จ่ายแล้ว"
    };
    bucket().payslips.push(rec);
    hrPersistAsync();
    res.json({ ok:true, province:prov, record:rec, breakdown:{ gross: calc.gross, ssf: calc.ssf, gpf: calc.gpf, tax: calc.tax, net: calc.net } });
  });

  app.get(`/api/${prov}/hr/leaves`, hrCors, (req, res) => {
    const arr = bucket().leaves.slice();
    res.json({ ok:true, province:prov, total:arr.length, leaves:arr });
  });
  app.post(`/api/${prov}/hr/leaves`, hrCors, (req, res) => {
    const body = req.body || {};
    if (!body.full_name || !body.leave_type) {
      return res.status(400).json({ ok:false, error:"full_name + leave_type จำเป็น" });
    }
    const rec = {
      id: newHrId("LV"),
      personnel_id: body.personnel_id || "",
      full_name: body.full_name,
      leave_type: body.leave_type,
      days: Number(body.days || 1),
      from: body.from || "",
      to:   body.to || "",
      reason: body.reason || "",
      status: body.status || "รออนุมัติ"
    };
    bucket().leaves.push(rec);
    hrPersistAsync();
    res.json({ ok:true, province:prov, record:rec });
  });
  app.put(`/api/${prov}/hr/leaves/:id`, hrCors, (req, res) => {
    const b = bucket();
    const idx = b.leaves.findIndex(p => p.id === req.params.id);
    if (idx < 0) return res.status(404).json({ ok:false, error:"leave not found" });
    b.leaves[idx] = { ...b.leaves[idx], ...req.body };
    hrPersistAsync();
    res.json({ ok:true, province:prov, record:b.leaves[idx] });
  });

  app.get(`/api/${prov}/hr/ot`, hrCors, (req, res) => {
    const arr = bucket().ot_records.slice();
    res.json({ ok:true, province:prov, total:arr.length, ot:arr });
  });
  app.post(`/api/${prov}/hr/ot`, hrCors, (req, res) => {
    const body = req.body || {};
    if (!body.full_name || !body.date) {
      return res.status(400).json({ ok:false, error:"full_name + date จำเป็น" });
    }
    const hours = Number(body.hours || 0);
    const rate = Number(body.rate || 150);
    const rec = {
      id: newHrId("OT"),
      personnel_id: body.personnel_id || "",
      full_name: body.full_name,
      date: body.date,
      hours: hours,
      rate: rate,
      amount: Number(body.amount || (hours * rate)),
      reason: body.reason || "",
      status: body.status || "รออนุมัติ"
    };
    bucket().ot_records.push(rec);
    hrPersistAsync();
    res.json({ ok:true, province:prov, record:rec });
  });

  console.log(`[G2G] ${prov.toUpperCase()} HR/Payroll API registered ✅`);
});
