// =============================================================
// INVENTORY / STOCK MODULE — Multi-province (phrae, chiangrai, udonthani)
// Iron Rule #1: ระบบใช้งานได้จริง (real CRUD)
// Iron Rule #5: Static fallback (public/inventory-data.json)
// Iron Rule #4: API pattern /api/{province}/inventory/*
// Law: ระเบียบกระทรวงการคลังว่าด้วยการจัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ พ.ศ. 2560
// Status workflow: ปกติ → ชำรุด → จำหน่าย → ทำลาย (forward-only)
// Generated: 2026-05-25
// =============================================================

// Per-province inventory cache (in-memory; clones from a shared seed file)
const _INV_CACHE = { phrae: null, chiangrai: null, udonthani: null };
function invData(province) {
  if (!_INV_CACHE[province]) {
    try {
      const file = join(__dirname, "public", "inventory-data.json");
      const raw = JSON.parse(readFileSync(file, "utf8"));
      // Deep clone per-province so writes do not leak across provinces
      _INV_CACHE[province] = JSON.parse(JSON.stringify(raw));
      console.log(`[INVENTORY-${province.toUpperCase()}] Static cache loaded ✅ items:`, _INV_CACHE[province].items?.length || 0, "assets:", _INV_CACHE[province].assets?.length || 0);
    } catch (e) {
      console.warn(`[INVENTORY-${province.toUpperCase()}] cache load failed:`, e.message);
      _INV_CACHE[province] = { items: [], assets: [], receiving: [], withdrawal: [], audit: [], _meta: {} };
    }
  }
  return _INV_CACHE[province];
}

function _invFilter(arr, q) {
  let out = arr;
  if (q.agency)   out = out.filter(r => !r.agency || r.agency === q.agency);
  if (q.category) out = out.filter(r => r.category === q.category);
  if (q.status)   out = out.filter(r => r.status === q.status);
  return out;
}

function _newInvId(prefix) {
  return prefix + '-' + Date.now().toString(36).toUpperCase() + Math.random().toString(36).slice(2,5).toUpperCase();
}

// Compute current balance from receiving (+) and withdrawal (-) — by item_id
function _computeBalance(prov) {
  const d = invData(prov);
  const items = d.items || [];
  const balance = {};
  items.forEach(it => { balance[it.id] = { item: it, opening: it.stock_balance || 0, received: 0, withdrawn: 0, current: it.stock_balance || 0 }; });
  (d.receiving || []).forEach(rec => (rec.items || []).forEach(li => {
    if (!balance[li.item_id]) return;
    balance[li.item_id].received += (li.qty || 0);
  }));
  (d.withdrawal || []).forEach(wd => {
    if (wd.status === 'ยกเลิก') return;
    (wd.items || []).forEach(li => {
      if (!balance[li.item_id]) return;
      balance[li.item_id].withdrawn += (li.qty || 0);
    });
  });
  Object.values(balance).forEach(b => {
    b.computed_movement = b.received - b.withdrawn;
    b.current = b.item.stock_balance || 0;
    b.reorder_alert = b.current <= (b.item.reorder_point || 0);
    b.value = b.current * (b.item.unit_price || 0);
  });
  return Object.values(balance);
}

// Helper: when a receiving doc is POSTed, increment item stock
function _applyReceiving(prov, doc) {
  const d = invData(prov);
  (doc.items || []).forEach(li => {
    const it = (d.items || []).find(x => x.id === li.item_id);
    if (it) {
      it.stock_balance = (it.stock_balance || 0) + (li.qty || 0);
      it.last_updated = doc.date || new Date().toISOString().slice(0,10);
    }
  });
}

// Helper: when a withdrawal doc is POSTed, decrement item stock
function _applyWithdrawal(prov, doc) {
  const d = invData(prov);
  (doc.items || []).forEach(li => {
    const it = (d.items || []).find(x => x.id === li.item_id);
    if (it) {
      it.stock_balance = Math.max(0, (it.stock_balance || 0) - (li.qty || 0));
      it.last_updated = doc.date || new Date().toISOString().slice(0,10);
    }
  });
}

// Province-code mapping for asset_no prefix
// KST = กระทรวงเกษตรและสหกรณ์; 2-digit code = building/agency code
const INV_PROV_CODE = { phrae: '54', chiangrai: '57', udonthani: '41' };

function _nextAssetNo(prov) {
  const d = invData(prov);
  const code = INV_PROV_CODE[prov] || '00';
  const yr = new Date().getFullYear() - 1957; // BE year
  const yrSuffix = String(yr).slice(-2);
  const existing = (d.assets || []).filter(a => a.asset_no && a.asset_no.startsWith(`KST-${code}-`));
  const maxSeq = existing.reduce((m, a) => {
    const mm = a.asset_no.match(/-(\d+)\//);
    if (mm) return Math.max(m, parseInt(mm[1], 10));
    return m;
  }, 0);
  const seq = String(maxSeq + 1).padStart(3, '0');
  return `KST-${code}-${seq}/${yrSuffix}`;
}

// Register routes for all 3 provinces
['phrae','chiangrai','udonthani'].forEach(prov => {

  // ===== ITEMS (พัสดุสิ้นเปลือง) =====
  app.get(`/api/${prov}/inventory/items`, provCors, (req, res) => {
    const arr = _invFilter(invData(prov).items || [], req.query);
    res.json({ ok: true, province: prov, total: arr.length, items: arr });
  });
  app.post(`/api/${prov}/inventory/items`, provCors, (req, res) => {
    const d = invData(prov);
    const rec = {
      id: _newInvId('INV'),
      status: 'ปกติ',
      stock_balance: 0,
      reorder_point: 0,
      last_updated: new Date().toISOString().slice(0,10),
      ...req.body
    };
    d.items.push(rec);
    res.json({ ok: true, province: prov, record: rec });
  });
  app.put(`/api/${prov}/inventory/items/:id`, provCors, (req, res) => {
    const d = invData(prov);
    const target = (d.items || []).find(x => x.id === req.params.id);
    if (!target) return res.status(404).json({ ok: false, error: 'item not found' });
    Object.assign(target, req.body, { last_updated: new Date().toISOString().slice(0,10) });
    res.json({ ok: true, province: prov, record: target });
  });
  app.delete(`/api/${prov}/inventory/items/:id`, provCors, (req, res) => {
    const d = invData(prov);
    const idx = (d.items || []).findIndex(x => x.id === req.params.id);
    if (idx === -1) return res.status(404).json({ ok: false, error: 'item not found' });
    const removed = d.items.splice(idx, 1)[0];
    res.json({ ok: true, province: prov, removed });
  });

  // ===== ASSETS (ครุภัณฑ์) =====
  app.get(`/api/${prov}/inventory/assets`, provCors, (req, res) => {
    const arr = _invFilter(invData(prov).assets || [], req.query);
    res.json({ ok: true, province: prov, total: arr.length, assets: arr });
  });
  app.post(`/api/${prov}/inventory/assets`, provCors, (req, res) => {
    const d = invData(prov);
    const rec = {
      id: _newInvId('AST'),
      asset_no: req.body.asset_no || _nextAssetNo(prov),
      status: 'ปกติ',
      acquire_date: new Date().toISOString().slice(0,10),
      ...req.body
    };
    d.assets.push(rec);
    res.json({ ok: true, province: prov, record: rec });
  });
  app.put(`/api/${prov}/inventory/assets/:id`, provCors, (req, res) => {
    const d = invData(prov);
    const target = (d.assets || []).find(x => x.id === req.params.id || x.asset_no === req.params.id);
    if (!target) return res.status(404).json({ ok: false, error: 'asset not found' });
    // Enforce status workflow: ปกติ → ชำรุด → จำหน่าย → ทำลาย (forward-only)
    const workflow = ['ปกติ','ชำรุด','จำหน่าย','ทำลาย'];
    if (req.body.status && workflow.includes(req.body.status)) {
      const curIdx = workflow.indexOf(target.status || 'ปกติ');
      const newIdx = workflow.indexOf(req.body.status);
      if (newIdx < curIdx) {
        return res.status(400).json({ ok: false, error: `ไม่สามารถย้อนสถานะจาก "${target.status}" กลับเป็น "${req.body.status}" ได้ (workflow forward-only)` });
      }
    }
    Object.assign(target, req.body);
    res.json({ ok: true, province: prov, record: target });
  });

  // ===== RECEIVING (ใบรับพัสดุ) =====
  app.get(`/api/${prov}/inventory/receiving`, provCors, (req, res) => {
    const arr = _invFilter(invData(prov).receiving || [], req.query);
    res.json({ ok: true, province: prov, total: arr.length, receiving: arr });
  });
  app.post(`/api/${prov}/inventory/receiving`, provCors, (req, res) => {
    const d = invData(prov);
    const seq = (d.receiving || []).length + 1;
    const rec = {
      id: _newInvId('REC'),
      doc_no: req.body.doc_no || `รพ.${String(seq).padStart(3,'0')}/${new Date().getFullYear() - 1957}`,
      date: req.body.date || new Date().toISOString().slice(0,10),
      status: 'รับเรียบร้อย',
      items: req.body.items || [],
      total_amount: (req.body.items || []).reduce((s,li) => s + ((li.qty||0) * (li.unit_price||0)), 0),
      ...req.body
    };
    d.receiving.push(rec);
    _applyReceiving(prov, rec);
    res.json({ ok: true, province: prov, record: rec });
  });

  // ===== WITHDRAWAL (ใบเบิกพัสดุ) =====
  app.get(`/api/${prov}/inventory/withdrawal`, provCors, (req, res) => {
    const arr = _invFilter(invData(prov).withdrawal || [], req.query);
    res.json({ ok: true, province: prov, total: arr.length, withdrawal: arr });
  });
  app.post(`/api/${prov}/inventory/withdrawal`, provCors, (req, res) => {
    const d = invData(prov);
    // Pre-check stock — refuse if any item would go negative
    const insufficient = (req.body.items || []).filter(li => {
      const it = (d.items || []).find(x => x.id === li.item_id);
      return !it || (it.stock_balance || 0) < (li.qty || 0);
    });
    if (insufficient.length) {
      return res.status(400).json({ ok: false, error: 'พัสดุไม่พอเบิก', items: insufficient });
    }
    const seq = (d.withdrawal || []).length + 1;
    const rec = {
      id: _newInvId('WD'),
      doc_no: req.body.doc_no || `บก.${String(seq).padStart(3,'0')}/${new Date().getFullYear() - 1957}`,
      date: req.body.date || new Date().toISOString().slice(0,10),
      status: 'เบิกแล้ว',
      items: req.body.items || [],
      total_amount: (req.body.items || []).reduce((s,li) => s + ((li.qty||0) * (li.unit_price||0)), 0),
      ...req.body
    };
    d.withdrawal.push(rec);
    _applyWithdrawal(prov, rec);
    res.json({ ok: true, province: prov, record: rec });
  });

  // ===== AUDIT (การตรวจนับประจำปี) =====
  app.get(`/api/${prov}/inventory/audit`, provCors, (req, res) => {
    const arr = invData(prov).audit || [];
    res.json({ ok: true, province: prov, total: arr.length, audit: arr });
  });
  app.post(`/api/${prov}/inventory/audit`, provCors, (req, res) => {
    const d = invData(prov);
    const rec = {
      id: _newInvId('AUD'),
      fiscal_year: req.body.fiscal_year || (new Date().getFullYear() - 1957),
      audit_date: req.body.audit_date || new Date().toISOString().slice(0,10),
      total_items_audited: (d.items || []).length + (d.assets || []).length,
      matched: 0, shortage: 0, surplus: 0, damaged: 0,
      status: 'รออนุมัติ',
      ...req.body
    };
    d.audit.push(rec);
    res.json({ ok: true, province: prov, record: rec });
  });

  // ===== BALANCE REPORT (รายงานคงเหลือ — computed) =====
  app.get(`/api/${prov}/inventory/balance`, provCors, (req, res) => {
    const balance = _computeBalance(prov);
    const total_items = balance.length;
    const total_value = balance.reduce((s,b) => s + b.value, 0);
    const reorder_count = balance.filter(b => b.reorder_alert).length;
    const d = invData(prov);
    const asset_summary = {
      total: (d.assets || []).length,
      "ปกติ": (d.assets || []).filter(a => a.status === 'ปกติ').length,
      "ชำรุด": (d.assets || []).filter(a => a.status === 'ชำรุด').length,
      "จำหน่าย": (d.assets || []).filter(a => a.status === 'จำหน่าย').length,
      "ทำลาย": (d.assets || []).filter(a => a.status === 'ทำลาย').length,
      total_book_value: (d.assets || []).reduce((s,a) => s + (a.book_value || 0), 0)
    };
    res.json({
      ok: true, province: prov,
      summary: {
        total_items, total_value, reorder_count,
        receiving_count: (d.receiving || []).length,
        withdrawal_count: (d.withdrawal || []).length,
        asset_summary
      },
      balance
    });
  });

  console.log(`[INVENTORY] ${prov.toUpperCase()} inventory API registered ✅`);
});
// =============================================================
// END INVENTORY MODULE
// =============================================================


// =============================================================
// CROP CALENDAR / FARMER ADVISORY MODULE
// 12 พืชหลัก × 52 สัปดาห์ × 3 งาน = 1,872 task entries
// JSON files in public/crop-data/*.json (loaded dynamically)
// Iron Rule #1: real CRUD, #5 static fallback
// Generated: 2026-05-25
// =============================================================

const CROP_DATA_DIR = join(__dirname, 'public', 'crop-data');
const BROADCAST_LOG = join(__dirname, 'public', 'farmer-broadcast.log');
const _CROP_CACHE = {};
const _CROP_LIST_CACHE = { list: null, lastLoad: 0 };

function cropAuth(req, res, next) {
  const key = req.header('x-api-key');
  const validKeys = ['phrae2026','chiangrai2026','udonthani2026'];
  if (!validKeys.includes(key)) {
    return res.status(401).json({ ok:false, error:'invalid x-api-key (use phrae2026/chiangrai2026/udonthani2026)' });
  }
  res.header('Access-Control-Allow-Origin','*');
  res.header('Access-Control-Allow-Headers','x-api-key,Content-Type');
  res.header('Access-Control-Allow-Methods','GET,POST,PUT,DELETE,OPTIONS');
  if (req.method === 'OPTIONS') return res.sendStatus(200);
  next();
}

function loadAllCrops() {
  // 5 minute cache
  if (_CROP_LIST_CACHE.list && (Date.now() - _CROP_LIST_CACHE.lastLoad) < 300000) {
    return _CROP_LIST_CACHE.list;
  }
  try {
    const files = readdirSync(CROP_DATA_DIR).filter(f => f.endsWith('.json'));
    const list = files.map(f => {
      const code = f.replace('.json','');
      if (!_CROP_CACHE[code]) {
        try {
          _CROP_CACHE[code] = JSON.parse(readFileSync(join(CROP_DATA_DIR, f), 'utf8'));
        } catch (e) {
          console.error(`[CROP] load fail ${f}:`, e.message);
          return null;
        }
      }
      const c = _CROP_CACHE[code];
      return {
        crop_code: c.crop_code,
        crop_name_th: c.crop_name_th,
        crop_name_en: c.crop_name_en,
        scientific_name: c.scientific_name,
        growing_zones: c.growing_zones,
        annual_cycle_summary: c.annual_cycle_summary,
        total_weeks: c.weeks?.length || 0,
      };
    }).filter(Boolean);
    _CROP_LIST_CACHE.list = list;
    _CROP_LIST_CACHE.lastLoad = Date.now();
    console.log(`[CROP] cache loaded: ${list.length} crops`);
    return list;
  } catch (e) {
    console.error('[CROP] loadAllCrops error:', e.message);
    return [];
  }
}

function loadCrop(code) {
  if (_CROP_CACHE[code]) return _CROP_CACHE[code];
  try {
    const file = join(CROP_DATA_DIR, `${code}.json`);
    _CROP_CACHE[code] = JSON.parse(readFileSync(file, 'utf8'));
    return _CROP_CACHE[code];
  } catch (e) {
    return null;
  }
}

// GET /api/crops/list - all crops
app.get('/api/crops/list', cropAuth, (_req, res) => {
  try {
    const crops = loadAllCrops();
    res.json({ ok:true, total: crops.length, crops });
  } catch (e) {
    res.status(500).json({ ok:false, error:e.message });
  }
});

// GET /api/crops/:code - full schedule
app.get('/api/crops/:code', cropAuth, (req, res) => {
  const crop = loadCrop(req.params.code);
  if (!crop) return res.status(404).json({ ok:false, error:`crop not found: ${req.params.code}` });
  res.json({ ok:true, crop });
});

// GET /api/crops/:code/week/:n - specific week
app.get('/api/crops/:code/week/:n', cropAuth, (req, res) => {
  const crop = loadCrop(req.params.code);
  if (!crop) return res.status(404).json({ ok:false, error:'crop not found' });
  const n = parseInt(req.params.n);
  const wk = (crop.weeks||[]).find(w => w.week === n);
  if (!wk) return res.status(404).json({ ok:false, error:`week ${n} not found` });
  res.json({ ok:true, crop_code: crop.crop_code, crop_name_th: crop.crop_name_th, week: wk });
});

// PUT /api/crops/:code/week/:n - update week tasks (admin)
app.put('/api/crops/:code/week/:n', cropAuth, (req, res) => {
  const crop = loadCrop(req.params.code);
  if (!crop) return res.status(404).json({ ok:false, error:'crop not found' });
  const n = parseInt(req.params.n);
  const wk = (crop.weeks||[]).find(w => w.week === n);
  if (!wk) return res.status(404).json({ ok:false, error:`week ${n} not found` });
  const { phase, tasks, warnings, weather_dependent } = req.body || {};
  if (phase !== undefined) wk.phase = phase;
  if (Array.isArray(tasks)) wk.tasks = tasks;
  if (Array.isArray(warnings)) wk.warnings = warnings;
  if (typeof weather_dependent === 'boolean') wk.weather_dependent = weather_dependent;
  // persist back to file
  try {
    writeFileSync(join(CROP_DATA_DIR, `${req.params.code}.json`), JSON.stringify(crop, null, 2), 'utf8');
    _CROP_LIST_CACHE.list = null; // invalidate list cache
    res.json({ ok:true, crop_code: crop.crop_code, week: wk, persisted: true });
  } catch (e) {
    res.json({ ok:true, crop_code: crop.crop_code, week: wk, persisted: false, warn: 'in-memory only: '+e.message });
  }
});

// GET /api/farmer/advisory/current?week=N - all crops current week
app.get('/api/farmer/advisory/current', cropAuth, (req, res) => {
  try {
    let week = parseInt(req.query.week);
    if (!week || week < 1 || week > 52) {
      // compute ISO week
      const d = new Date();
      const t = new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()));
      const dayNum = t.getUTCDay() || 7;
      t.setUTCDate(t.getUTCDate() + 4 - dayNum);
      const yearStart = new Date(Date.UTC(t.getUTCFullYear(), 0, 1));
      week = Math.ceil((((t - yearStart) / 86400000) + 1) / 7);
    }
    const cropIcons = { lamyai:'🥭', 'rice-sticky':'🌾', 'rice-jasmine':'🌾', coffee:'☕', tea:'🍵', lychee:'🍒', pineapple:'🍍', orange:'🍊', rubber:'🌳', sugarcane:'🎋', cassava:'🥔', mango:'🥭' };
    const crops = loadAllCrops().map(c => {
      const full = loadCrop(c.crop_code);
      const wk = (full?.weeks||[]).find(w => w.week === week);
      return {
        crop_code: c.crop_code,
        crop_name_th: c.crop_name_th,
        crop_name_en: c.crop_name_en,
        growing_zones: c.growing_zones,
        icon: cropIcons[c.crop_code] || '🌱',
        week_data: wk || null,
      };
    });
    res.json({ ok:true, week, total: crops.length, crops });
  } catch (e) {
    res.status(500).json({ ok:false, error:e.message });
  }
});

// POST /api/farmer/broadcast - send LINE broadcast (or log to file as fallback)
app.post('/api/farmer/broadcast', cropAuth, async (req, res) => {
  try {
    const { province, oa, week, crops, crop_code, message } = req.body || {};
    if (!message) return res.status(400).json({ ok:false, error:'message is required' });
    const logEntry = {
      timestamp: new Date().toISOString(),
      province: province || 'unknown',
      oa: oa || 'default',
      week: week || null,
      crops: crops || (crop_code ? [crop_code] : []),
      message_length: message.length,
      message_preview: message.substring(0, 200),
    };
    // append to log file
    try {
      appendFileSync(BROADCAST_LOG, JSON.stringify(logEntry) + '\n', 'utf8');
    } catch (e) {
      console.warn('[FARMER-BC] log write failed:', e.message);
    }
    // attempt real LINE broadcast if PHRAE channel token is configured
    const token = process.env.PHRAE_LINE_CHANNEL_TOKEN || process.env.LINE_CHANNEL_ACCESS_TOKEN;
    let broadcastResult = { sent: false, target: 'log-only' };
    if (token && oa && oa !== 'custom') {
      try {
        const lineResp = await fetch('https://api.line.me/v2/bot/message/broadcast', {
          method: 'POST',
          headers: { 'Content-Type':'application/json', 'Authorization': `Bearer ${token}` },
          body: JSON.stringify({ messages: [{ type:'text', text: message }] }),
        });
        if (lineResp.ok) {
          broadcastResult = { sent: true, target: `LINE-${oa}` };
        } else {
          const errText = await lineResp.text();
          broadcastResult = { sent: false, target: 'log-only', warn: `LINE ${lineResp.status}: ${errText.substring(0,200)}` };
        }
      } catch (e) {
        broadcastResult = { sent: false, target: 'log-only', warn: 'LINE call failed: '+e.message };
      }
    }
    console.log(`[FARMER-BC] week=${week} province=${province} oa=${oa} sent=${broadcastResult.sent}`);
    res.json({ ok:true, ...broadcastResult, logged: true, log_entry: logEntry, recipients: broadcastResult.sent ? 'broadcast-all' : 0 });
  } catch (e) {
    res.status(500).json({ ok:false, error:e.message });
  }
});

