// POST /api/moac/ai-analysis — AI วิเคราะห์นโยบาย/ข้อมูล
//   v2: If body has `directiveId`, delegate to the new directive advisory
//   system (return cached or generate fresh). Otherwise behave like the
//   original one-shot policy analysis (backward compatible).
app.post("/api/moac/ai-analysis", moacCors, async (req, res) => {
  try {
    const { question, context, directiveId } = req.body || {};

    // ── NEW: directive-driven mode — reuse the cascade system advisory ──
    if (directiveId) {
      // moacDirectives is declared further below in this file but JS hoisting
      // makes it accessible at runtime by the time this handler executes.
      const d = (typeof moacDirectives !== 'undefined' ? moacDirectives : [])
        .find(x => x.id === directiveId || x.code === directiveId);
      if (!d) return res.status(404).json({ ok: false, error: 'directive not found' });
      if (d.aiAdvisory) {
        return res.json({ ok: true, mode: 'directive-cached', directiveId: d.id, code: d.code, advisory: d.aiAdvisory });
      }
      if (typeof generateDirectiveAdvisory === 'function') {
        const advisory = await generateDirectiveAdvisory(d);
        d.aiAdvisory = advisory;
        d.aiAdvisoryAt = new Date().toISOString();
        d.aiAdvisoryStatus = advisory.error ? 'error' : 'ready';
        try { persistMoacData(); } catch (_) {}
        return res.json({ ok: true, mode: 'directive-fresh', directiveId: d.id, code: d.code, advisory });
      }
      return res.status(503).json({ ok: false, error: 'directive advisory system not loaded' });
    }

    if (!question) return res.status(400).json({ ok: false, error: "required: question" });

    const d = moacData();
    const systemCtx = `คุณคือผู้เชี่ยวชาญด้านนโยบายเกษตรไทย วิเคราะห์ข้อมูลกระทรวงเกษตรและสหกรณ์ (MOAC) อย่างแม่นยำ อ้างอิงกฎหมายและข้อเท็จจริงเสมอ`;
    const userMsg = `${question}\n\nบริบท:\n- กระทรวง: ${d.ministry_name_th}\n- งบ 2568: ${(d.fiscal_year_2568_budget_baht / 1e9).toFixed(1)} พันล้านบาท\n- เกษตรกร: ${d.thai_farmer_count_total?.toLocaleString()} คน\n- กรม: ${d.departments?.length} กรม\n${context ? "\nข้อมูลเพิ่มเติม: " + context : ""}`;

    const aiResp = await fetch("https://api.anthropic.com/v1/messages", {
      method: "POST",
      headers: {
        "x-api-key": process.env.ANTHROPIC_API_KEY,
        "anthropic-version": "2023-06-01",
        "content-type": "application/json",
      },
      body: JSON.stringify({
        model: "claude-opus-4-7",
        max_tokens: 800,
        system: systemCtx,
        messages: [{ role: "user", content: userMsg }],
      }),
    });

    if (!aiResp.ok) throw new Error("AI API error: " + aiResp.status);
    const aiData = await aiResp.json();
    res.json({ ok: true, question, answer: aiData.content?.[0]?.text || "", model: "claude-opus-4-7" });
  } catch (e) {
    res.status(500).json({ ok: false, error: e.message });
  }
});

