let _MOC_DATA = null;
function mocData() {
  if (!_MOC_DATA) {
    try {
      _MOC_DATA = JSON.parse(readFileSync(join(__dirname, "public", "ministry-data", "moc.json"), "utf8"));
      console.log("[MOC] data loaded departments:", _MOC_DATA.departments?.length || 0);
    } catch(e) {
      console.warn("[MOC] data load failed:", e.message);
      _MOC_DATA = { ministry: {}, departments: [], policies: [], commodity_prices: [], key_kpis: {}, province_rollout: [] };
    }
  }
  return _MOC_DATA;
}
function mocCors(res) {
  res.header("Access-Control-Allow-Origin","*");
  res.header("Access-Control-Allow-Headers","Content-Type,x-api-key");
}

app.get('/api/moc/overview', (req,res) => {
  if(req.headers['x-api-key'] !== 'moc2026') return res.status(401).json({error:'unauthorized'});
  mocCors(res);
  const d = mocData();
  res.json({ministry: d.ministry, departments_count: (d.departments||[]).length, policies_count: (d.policies||[]).length, key_kpis: d.key_kpis||{}, updated_at: new Date().toISOString()});
});

app.get('/api/moc/province-rollout', (req,res) => {
  if(req.headers['x-api-key'] !== 'moc2026') return res.status(401).json({error:'unauthorized'});
  mocCors(res);
  const d = mocData();
  res.json({provinces: d.province_rollout||[], updated_at: new Date().toISOString()});
});

app.get('/api/moc/kpis', (req,res) => {
  if(req.headers['x-api-key'] !== 'moc2026') return res.status(401).json({error:'unauthorized'});
  mocCors(res);
  const d = mocData();
  const K = d.key_kpis||{};
  const kpis = [
    {name:'มูลค่าส่งออก', value: '$'+(K.export_value_billion_usd||0)+'B', target:'$300B', achievement_pct: Math.round((K.export_value_billion_usd||0)/300*100)},
    {name:'สัดส่วนส่งออกเกษตร', value: K.agri_export_pct+'%', target:'25%', achievement_pct: Math.round((K.agri_export_pct||0)/25*100)},
    {name:'ความเสถียรราคา', value: K.price_stability_index+'/100', target:'90/100', achievement_pct: Math.round((K.price_stability_index||0)/90*100)},
    {name:'เกษตรกรในตลาด', value: ((K.farmers_in_market||0)/1000)+'K ราย', target:'500K', achievement_pct: Math.round((K.farmers_in_market||0)/500000*100)},
    {name:'สินค้า GI', value: (K.gi_products||0)+' ชนิด', target:'50ชนิด', achievement_pct: Math.round((K.gi_products||0)/50*100)},
    {name:'E-Commerce เกษตร', value: (K.ecommerce_agri_volume_billion||0)+'Bบาท', target:'20Bบาท', achievement_pct: Math.round((K.ecommerce_agri_volume_billion||0)/20*100)}
  ];
  res.json({kpis, updated_at: new Date().toISOString()});
});

app.get('/api/moc/commodity-prices', (req,res) => {
  if(req.headers['x-api-key'] !== 'moc2026') return res.status(401).json({error:'unauthorized'});
  mocCors(res);
  const d = mocData();
  res.json({prices: d.commodity_prices||[], updated_at: new Date().toISOString()});
});

app.get('/api/moc/departments', (req,res) => {
  if(req.headers['x-api-key'] !== 'moc2026') return res.status(401).json({error:'unauthorized'});
  mocCors(res);
  const d = mocData();
  res.json({departments: d.departments||[], updated_at: new Date().toISOString()});
});

app.options('/api/moc/*', (req,res) => { mocCors(res); res.sendStatus(200); });
// ==================== END MOC ====================


