function mhesiMgmtCors(req,res,next){
  res.header('Access-Control-Allow-Origin','*');
  res.header('Access-Control-Allow-Headers','x-api-key,Content-Type');
  res.header('Access-Control-Allow-Methods','GET,POST,OPTIONS');
  if(req.method==='OPTIONS') return res.sendStatus(200);
  if(req.method==='POST'){
    const k=req.header('x-api-key');
    if(k!=='mhesi2026') return res.status(401).json({ok:false,error:'x-api-key required'});
  }
  next();
}

app.get('/api/mhesi/management/summary', mhesiMgmtCors, (req,res) => {
  const d = mhesiMgmtStatic();
  res.json({ok:true, summary: d.summary, fetchedAt: new Date().toISOString()});
});
app.post('/api/mhesi/management/summary', mhesiMgmtCors, (req,res) => {
  res.json({ok:true, message:'summary updated (static mode)', data: req.body});
});

