// In-memory stores for HEMIS data (supplements static seed in HTML)
const _mhesiStudents = [];
const _mhesiHealth = [];

// GET /api/mhesi/management/students — list all students
app.get('/api/mhesi/management/students', mhesiMgmtCors, (req, res) => {
  const seed = [
    {id:'STD6701001',name:'นางสาวพิมพ์ชนก วงศ์อารีย์',uni:'จุฬาลงกรณ์มหาวิทยาลัย',faculty:'คณะวิศวกรรมศาสตร์',program:'วิศวกรรมคอมพิวเตอร์',year:3,gpa:3.45,credits:90,status:'กำลังศึกษา',risk:'low'},
    {id:'STD6701002',name:'นายธนภัทร สุขสวัสดิ์',uni:'มหาวิทยาลัยธรรมศาสตร์',faculty:'คณะพาณิชยศาสตร์และการบัญชี',program:'บัญชีบัณฑิต',year:2,gpa:2.85,credits:60,status:'กำลังศึกษา',risk:'low'},
    {id:'STD6701003',name:'นางสาวสุภาวดี แก้วมณี',uni:'มหาวิทยาลัยเกษตรศาสตร์',faculty:'คณะเกษตร',program:'เกษตรศาสตร์',year:4,gpa:3.72,credits:120,status:'รอสำเร็จ',risk:'low'},
    {id:'STD6701004',name:'นายกิตติพงษ์ มีทรัพย์',uni:'มหาวิทยาลัยเชียงใหม่',faculty:'คณะวิทยาศาสตร์',program:'ฟิสิกส์',year:1,gpa:1.35,credits:18,status:'กำลังศึกษา',risk:'high'},
    {id:'STD6701005',name:'นางสาวอรพรรณ ดีสม',uni:'มหาวิทยาลัยขอนแก่น',faculty:'คณะแพทยศาสตร์',program:'แพทยศาสตร์',year:5,gpa:3.21,credits:150,status:'กำลังศึกษา',risk:'low'},
  ];
  const all = [...seed, ..._mhesiStudents];
  const { risk, uni, status } = req.query;
  let filtered = all;
  if (risk) filtered = filtered.filter(s => s.risk === risk);
  if (uni) filtered = filtered.filter(s => s.uni.includes(uni));
  if (status) filtered = filtered.filter(s => s.status === status);
  res.json({ ok: true, total: filtered.length, students: filtered, fetchedAt: new Date().toISOString() });
});

// POST /api/mhesi/management/students — upsert student
app.post('/api/mhesi/management/students', mhesiMgmtCors, (req, res) => {
  const b = req.body || {};
  const newId = b.id || 'STD' + String(Date.now()).slice(-7);
  const idx = _mhesiStudents.findIndex(s => s.id === newId);
  const record = { id: newId, ...b, updatedAt: new Date().toISOString() };
  if (idx >= 0) { _mhesiStudents[idx] = record; }
  else { _mhesiStudents.push(record); }
  res.json({ ok: true, id: newId, message: 'student saved', data: record });
});

// GET /api/mhesi/management/health — student health records
app.get('/api/mhesi/management/health', mhesiMgmtCors, (req, res) => {
  const seed = [
    {id:'H001',studentId:'STD6701001',bmi:21.5,bloodType:'A',conditions:'ไม่มี',phq9:3,gad7:2,lastCheckup:'2567-12-01',vaccines:['COVID-19','ไข้หวัดใหญ่'],mentalRisk:'low'},
    {id:'H002',studentId:'STD6701002',bmi:23.1,bloodType:'B',conditions:'ไม่มี',phq9:8,gad7:10,lastCheckup:'2567-11-15',vaccines:['COVID-19'],mentalRisk:'medium'},
    {id:'H003',studentId:'STD6701003',bmi:20.2,bloodType:'O',conditions:'ไม่มี',phq9:2,gad7:1,lastCheckup:'2568-01-10',vaccines:['COVID-19','ไข้หวัดใหญ่','ตับอักเสบบี'],mentalRisk:'low'},
    {id:'H004',studentId:'STD6701004',bmi:26.8,bloodType:'AB',conditions:'ความดันโลหิตสูง',phq9:15,gad7:14,lastCheckup:'2567-10-20',vaccines:['COVID-19'],mentalRisk:'high'},
    {id:'H005',studentId:'STD6701005',bmi:19.8,bloodType:'A',conditions:'ไม่มี',phq9:4,gad7:3,lastCheckup:'2568-02-05',vaccines:['COVID-19','ไข้หวัดใหญ่','MMR'],mentalRisk:'low'},
  ];
  const all = [...seed, ..._mhesiHealth];
  const { studentId, mentalRisk } = req.query;
  let filtered = all;
  if (studentId) filtered = filtered.filter(h => h.studentId === studentId);
  if (mentalRisk) filtered = filtered.filter(h => h.mentalRisk === mentalRisk);
  res.json({ ok: true, total: filtered.length, records: filtered, fetchedAt: new Date().toISOString() });
});

// POST /api/mhesi/management/health — add/update health record
app.post('/api/mhesi/management/health', mhesiMgmtCors, (req, res) => {
  const b = req.body || {};
  const newId = b.id || 'H' + String(Date.now()).slice(-6);
  const idx = _mhesiHealth.findIndex(h => h.id === newId || h.studentId === b.studentId);
  const record = { id: newId, ...b, updatedAt: new Date().toISOString() };
  if (idx >= 0) { _mhesiHealth[idx] = record; }
  else { _mhesiHealth.push(record); }
  res.json({ ok: true, id: newId, message: 'health record saved', data: record });
});

// GET /api/mhesi/management/tracking — at-risk students (GPA < 2.0)
app.get('/api/mhesi/management/tracking', mhesiMgmtCors, (req, res) => {
  const allStudents = [
    {id:'STD6701001',name:'นางสาวพิมพ์ชนก วงศ์อารีย์',uni:'จุฬาลงกรณ์มหาวิทยาลัย',gpa:3.45,risk:'low',status:'กำลังศึกษา'},
    {id:'STD6701004',name:'นายกิตติพงษ์ มีทรัพย์',uni:'มหาวิทยาลัยเชียงใหม่',gpa:1.35,risk:'high',status:'กำลังศึกษา'},
    ..._mhesiStudents,
  ];
  const atRisk = allStudents.filter(s => s.gpa < 2.0 || s.risk === 'high' || s.risk === 'medium');
  const summary = {
    totalAtRisk: atRisk.length,
    highRisk: atRisk.filter(s => s.risk === 'high' || s.gpa < 1.5).length,
    mediumRisk: atRisk.filter(s => s.risk === 'medium' || (s.gpa >= 1.5 && s.gpa < 2.0)).length,
  };
  res.json({ ok: true, summary, students: atRisk, fetchedAt: new Date().toISOString() });
});

