function moacMgmtCors(res) {
  res.header('Access-Control-Allow-Origin','*');
  res.header('Access-Control-Allow-Headers','Content-Type,x-api-key');
}
function moacMgmtAuthMw(req,res,next) {
  if (req.headers['x-api-key'] !== 'moac2026') return res.status(401).json({error:'unauthorized'});
  moacMgmtCors(res); next();
}

app.get('/api/moac/management/summary', moacMgmtAuthMw, (req,res) => {
  const d = moacMgmtStatic();
  const per  = d.personnel.concat(_moacMgmtAdded.personnel);
  const bud  = d.budget.concat(_moacMgmtAdded.budget);
  const prj  = d.projects.concat(_moacMgmtAdded.projects);
  const ctr  = d.contracts.concat(_moacMgmtAdded.contracts);
  const intg = d.integration.concat(_moacMgmtAdded.integration);
  const totalBudget    = bud.reduce((s,r)=>s+Number(r.budget_total||0),0);
  const totalDisbursed = bud.reduce((s,r)=>s+Number(r.disbursed_total||0),0);
  const avgProgress    = prj.length ? Math.round(prj.reduce((s,r)=>s+Number(r.progress_pct||0),0)/prj.length) : 0;
  const contractTotal  = ctr.reduce((s,r)=>s+Number(r.total||0),0);
  res.json({
    ok:true, _source:'static_cache',
    summary:{
      personnel:{total:120000, active:117500, civil:18200, govEmp:8900, contract:5400},
      budget:{depts:bud.length, total:totalBudget, disbursed:totalDisbursed, pct:totalBudget?Math.round(totalDisbursed/totalBudget*100):0},
      projects:{total:prj.length, avg_progress:avgProgress, on_track:prj.filter(r=>Number(r.progress_pct||0)>=60).length, done:prj.filter(r=>r.status==='เสร็จสิ้น').length},
      contracts:{total:ctr.length, total_amount:contractTotal, active:ctr.filter(r=>r.status==='มีผลบังคับ').length},
      integration:{total:intg.length, in_progress:intg.filter(r=>r.status==='กำลังดำเนินการ').length},
      key_kpis:{farmers_in_system:8500000, irrigation_area_rai:31000000, rice_yield_ton:28000000, smart_farmers:120000, organic_area_rai:950000},
    },
    updatedAt: new Date().toISOString(),
  });
});

app.get('/api/moac/management/personnel', moacMgmtAuthMw, (req,res) => {
  const d = moacMgmtStatic();
  const people = d.personnel.concat(_moacMgmtAdded.personnel);
  res.json({ok:true, people, total:people.length});
});
app.post('/api/moac/management/personnel', moacMgmtAuthMw, (req,res) => {
  const b = req.body||{};
  if (!b.name) return res.status(400).json({ok:false, error:'name required'});
  const rec = {id:'P'+Date.now(), name:b.name, dept:b.dept||'', position:b.position||'', grade:b.grade||'C7', status:b.status||'ปฏิบัติงาน', since:b.since||new Date().toISOString().slice(0,10), employee_type:b.employee_type||'ข้าราชการ'};
  _moacMgmtAdded.personnel.push(rec);
  res.json({ok:true, id:rec.id, message:'บันทึกบุคลากรสำเร็จ'});
});

app.get('/api/moac/management/budget', moacMgmtAuthMw, (req,res) => {
  const d = moacMgmtStatic();
  const agencies = d.budget.concat(_moacMgmtAdded.budget);
  res.json({ok:true, agencies, total:agencies.length});
});
app.post('/api/moac/management/budget', moacMgmtAuthMw, (req,res) => {
  const b = req.body||{};
  if (!b.dept) return res.status(400).json({ok:false, error:'dept required'});
  _moacMgmtAdded.budget.push({id:'B'+Date.now(), dept:b.dept, budget_total:Number(b.budget_total||0), disbursed_total:Number(b.disbursed_total||0), pct:Number(b.pct||0), year:b.year||'2568'});
  res.json({ok:true, message:'อัปเดตงบประมาณสำเร็จ'});
});

app.get('/api/moac/management/projects', moacMgmtAuthMw, (req,res) => {
  const d = moacMgmtStatic();
  const projects = d.projects.concat(_moacMgmtAdded.projects);
  res.json({ok:true, projects, total:projects.length});
});
app.post('/api/moac/management/projects', moacMgmtAuthMw, (req,res) => {
  const b = req.body||{};
  if (!b.project_name) return res.status(400).json({ok:false, error:'project_name required'});
  const code = 'MOAC-2568-'+String(Date.now()).slice(-4);
  const rec = {id:'PR'+Date.now(), code, name:b.project_name, dept:b.dept||'', budget:Number(b.budget_total||0), kpi:b.kpi_target||'', progress_pct:Number(b.progress_pct||0), status:b.status||'อยู่ระหว่างดำเนินการ'};
  _moacMgmtAdded.projects.push(rec);
  res.json({ok:true, id:rec.id, project_code:code, message:'บันทึกโครงการสำเร็จ'});
});

app.get('/api/moac/management/contracts', moacMgmtAuthMw, (req,res) => {
  const d = moacMgmtStatic();
  const contracts = d.contracts.concat(_moacMgmtAdded.contracts);
  res.json({ok:true, contracts, total:contracts.length});
});
app.post('/api/moac/management/contracts', moacMgmtAuthMw, (req,res) => {
  const b = req.body||{};
  if (!b.contractor_name) return res.status(400).json({ok:false, error:'contractor_name required'});
  const total = Number(b.total_amount||0);
  const method = total>500000?'ประกวดราคา':total>100000?'สืบราคา':'เฉพาะเจาะจง';
  const rec = {id:'C'+Date.now(), contractor:b.contractor_name, agency:b.agency_name||'', work:b.work_description||'', total, method:b.procurement_method||method, egp:b.egp_number||'รอบันทึก', status:b.status||'มีผลบังคับ', year:b.fiscal_year||'2568'};
  _moacMgmtAdded.contracts.push(rec);
  res.json({ok:true, id:rec.id, procurement_method:rec.method, message:'บันทึกสัญญาสำเร็จ'});
});

app.get('/api/moac/management/integration', moacMgmtAuthMw, (req,res) => {
  const d = moacMgmtStatic();
  const plans = d.integration.concat(_moacMgmtAdded.integration);
  res.json({ok:true, plans, total:plans.length});
});
app.post('/api/moac/management/integration', moacMgmtAuthMw, (req,res) => {
  const b = req.body||{};
  if (!b.plan_name) return res.status(400).json({ok:false, error:'plan_name required'});
  const plan_id = 'INT-2568-'+String(Date.now()).slice(-4);
  const rec = {id:'I'+Date.now(), plan_id, plan_name:b.plan_name, host_agency:b.host_agency||'', partner_agencies:b.partner_agencies||'', budget:Number(b.budget||0), kpi:b.kpi||'', progress_pct:Number(b.progress_pct||0), status:b.status||'กำลังดำเนินการ', year:b.fiscal_year||'2568'};
  _moacMgmtAdded.integration.push(rec);
  res.json({ok:true, id:rec.id, plan_id, message:'บันทึกแผนบูรณาการสำเร็จ'});
});

app.options('/api/moac/management/*', (req,res) => { moacMgmtCors(res); res.sendStatus(200); });
console.log('[G2G] MOAC Management API registered ✅ (12 routes: GET+POST x summary/personnel/budget/projects/contracts/integration)');
// ==================== END MOAC MANAGEMENT API ====================


