function mocMgmtCors(res) {
  res.header('Access-Control-Allow-Origin','*');
  res.header('Access-Control-Allow-Headers','Content-Type,x-api-key');
}
function mocMgmtAuthMw(req,res,next) {
  if (req.headers['x-api-key'] !== 'moc2026') return res.status(401).json({error:'unauthorized'});
  mocMgmtCors(res); next();
}

app.get('/api/moc/management/summary', mocMgmtAuthMw, (req,res) => {
  const d = mocMgmtStatic();
  const per  = d.personnel.concat(_mocMgmtAdded.personnel);
  const bud  = d.budget.concat(_mocMgmtAdded.budget);
  const prj  = d.projects.concat(_mocMgmtAdded.projects);
  const ctr  = d.contracts.concat(_mocMgmtAdded.contracts);
  const intg = d.integration.concat(_mocMgmtAdded.integration);
  const totalBudget    = bud.reduce((s,r)=>s+Number(r.personnel_budget||0)+Number(r.operating_budget||0)+Number(r.capital_budget||0)+Number(r.subsidy_budget||0)+Number(r.other_budget||0),0);
  const totalDisbursed = bud.length ? Math.round(bud.reduce((s,r)=>s+Number(r.disbursed_pct||0),0)/bud.length) : 0;
  const avgProgress    = prj.length ? Math.round(prj.reduce((s,r)=>s+Number(r.progress_pct||0),0)/prj.length) : 0;
  const contractTotal  = ctr.reduce((s,r)=>s+Number(r.total||0),0);
  res.json({
    ok:true, _source:'static_cache',
    summary:{
      personnel:{total:9500, active:9200, civil:7800, govEmp:1200, contract:500},
      budget:{depts:bud.length, total_million:8200, disbursed_pct:totalDisbursed},
      projects:{total:prj.length, avg_progress:avgProgress, on_track:prj.filter(r=>Number(r.progress_pct||0)>=60).length, done:prj.filter(r=>r.status==='เสร็จสิ้น').length},
      contracts:{total:ctr.length, total_amount:contractTotal, active:ctr.filter(r=>r.status==='มีผลบังคับ').length},
      integration:{total:intg.length, in_progress:intg.filter(r=>r.status==='กำลังดำเนินการ').length},
      key_kpis:{export_value_trillion:9.2, export_growth_pct:3.8, fta_count:14, fta_countries:18, ip_registrations:35000, business_registered:1800000, price_monitored:97, trade_centers:20, gi_products:130},
    },
    updatedAt: new Date().toISOString(),
  });
});

app.get('/api/moc/management/personnel', mocMgmtAuthMw, (req,res) => {
  const d = mocMgmtStatic();
  const people = d.personnel.concat(_mocMgmtAdded.personnel);
  res.json({ok:true, people, total:people.length});
});
app.post('/api/moc/management/personnel', mocMgmtAuthMw, (req,res) => {
  const b = req.body||{};
  if (!b.name) return res.status(400).json({ok:false, error:'name required'});
  const rec = {id:'MP'+Date.now(), name:b.name, dept:b.dept||'', position:b.position||'', grade:b.grade||'C7', status:b.status||'ปฏิบัติงาน', since:b.since||new Date().toISOString().slice(0,10), employee_type:b.employee_type||'ข้าราชการ'};
  _mocMgmtAdded.personnel.push(rec);
  res.json({ok:true, id:rec.id, message:'บันทึกบุคลากรสำเร็จ'});
});

app.get('/api/moc/management/budget', mocMgmtAuthMw, (req,res) => {
  const d = mocMgmtStatic();
  const agencies = d.budget.concat(_mocMgmtAdded.budget);
  res.json({ok:true, agencies, total:agencies.length});
});
app.post('/api/moc/management/budget', mocMgmtAuthMw, (req,res) => {
  const b = req.body||{};
  if (!b.dept) return res.status(400).json({ok:false, error:'dept required'});
  _mocMgmtAdded.budget.push({id:'MB'+Date.now(), dept:b.dept, personnel_budget:Number(b.personnel_budget||0), operating_budget:Number(b.operating_budget||0), capital_budget:Number(b.capital_budget||0), subsidy_budget:Number(b.subsidy_budget||0), other_budget:0, disbursed_pct:Number(b.disbursed_pct||0), year:b.year||'2568'});
  res.json({ok:true, message:'อัปเดตงบประมาณสำเร็จ'});
});

app.get('/api/moc/management/projects', mocMgmtAuthMw, (req,res) => {
  const d = mocMgmtStatic();
  const projects = d.projects.concat(_mocMgmtAdded.projects);
  res.json({ok:true, projects, total:projects.length});
});
app.post('/api/moc/management/projects', mocMgmtAuthMw, (req,res) => {
  const b = req.body||{};
  if (!b.project_name) return res.status(400).json({ok:false, error:'project_name required'});
  const code = 'MOC-2568-'+String(Date.now()).slice(-4);
  const rec = {id:'MRP'+Date.now(), code, name:b.project_name, dept:b.dept||'', budget:Number(b.budget_total||0), kpi:b.kpi_target||'', progress_pct:Number(b.progress_pct||0), status:b.status||'อยู่ระหว่างดำเนินการ'};
  _mocMgmtAdded.projects.push(rec);
  res.json({ok:true, id:rec.id, project_code:code, message:'บันทึกโครงการสำเร็จ'});
});

app.get('/api/moc/management/contracts', mocMgmtAuthMw, (req,res) => {
  const d = mocMgmtStatic();
  const contracts = d.contracts.concat(_mocMgmtAdded.contracts);
  res.json({ok:true, contracts, total:contracts.length});
});
app.post('/api/moc/management/contracts', mocMgmtAuthMw, (req,res) => {
  const b = req.body||{};
  if (!b.contractor_name) return res.status(400).json({ok:false, error:'contractor_name required'});
  const total = Number(b.total_amount||0);
  const method = total>500000?'ประกวดราคา':total>100000?'สืบราคา':'เฉพาะเจาะจง';
  const rec = {id:'MC'+Date.now(), contractor:b.contractor_name, agency:b.agency_name||'', work:b.work_description||'', total, method:b.procurement_method||method, egp:b.egp_number||'รอบันทึก', status:b.status||'มีผลบังคับ', year:b.fiscal_year||'2568'};
  _mocMgmtAdded.contracts.push(rec);
  res.json({ok:true, id:rec.id, procurement_method:rec.method, message:'บันทึกสัญญาสำเร็จ'});
});

app.get('/api/moc/management/integration', mocMgmtAuthMw, (req,res) => {
  const d = mocMgmtStatic();
  const plans = d.integration.concat(_mocMgmtAdded.integration);
  res.json({ok:true, plans, total:plans.length});
});
app.post('/api/moc/management/integration', mocMgmtAuthMw, (req,res) => {
  const b = req.body||{};
  if (!b.plan_name) return res.status(400).json({ok:false, error:'plan_name required'});
  const plan_id = 'INT-MOC-2568-'+String(Date.now()).slice(-4);
  const rec = {id:'MI'+Date.now(), plan_id, plan_name:b.plan_name, host_agency:b.host_agency||'', partner_agencies:b.partner_agencies||'', budget:Number(b.budget||0), kpi:b.kpi||'', progress_pct:Number(b.progress_pct||0), status:b.status||'กำลังดำเนินการ', year:b.fiscal_year||'2568'};
  _mocMgmtAdded.integration.push(rec);
  res.json({ok:true, id:rec.id, plan_id, message:'บันทึกแผนบูรณาการสำเร็จ'});
});

app.options('/api/moc/management/*', (req,res) => { mocMgmtCors(res); res.sendStatus(200); });
console.log('[G2G] MOC Management API registered ✅ (12 routes: GET+POST x summary/personnel/budget/projects/contracts/integration)');
