app.post('/api/moi/management/contracts', moiMgmtAuthMw, (req,res) => {
  const b = req.body||{};
  if (!b.title) return res.status(400).json({ok:false, error:'title required'});
  const amount = Number(b.amount||0);
  const method = amount>500000?'ประกวดราคา':amount>100000?'สืบราคา':'เฉพาะเจาะจง';
  const rec = {id:'C'+Date.now(), title:b.title, type:b.type||'จ้างพัฒนาระบบ', amount, status:b.status||'มีผลบังคับ', start_date:b.start_date||new Date().toISOString().slice(0,10), method:b.method||method};
  _moiMgmtAdded.contracts.push(rec);
  res.json({ok:true, id:rec.id, procurement_method:rec.method, message:'บันทึกสัญญาสำเร็จ'});
});

