function mophMgmtCors(res) {
  res.header('Access-Control-Allow-Origin','*');
  res.header('Access-Control-Allow-Headers','Content-Type,x-api-key');
}
function mophMgmtAuthMw(req,res,next) {
  if (req.headers['x-api-key'] !== 'moph2026') return res.status(401).json({error:'unauthorized'});
  mophMgmtCors(res); next();
}

