function mdesMgmtCors(res) {
  res.header('Access-Control-Allow-Origin','*');
  res.header('Access-Control-Allow-Headers','Content-Type,x-api-key');
}
function mdesMgmtAuthMw(req,res,next) {
  if (req.headers['x-api-key'] !== 'mdes2026') return res.status(401).json({error:'unauthorized'});
  mdesMgmtCors(res); next();
}

app.get('/api/mdes/management/summary', mdesMgmtAuthMw, (req,res) => {
  const d = mdesMgmtStatic();
  const per  = d.personnel.concat(_mdesMgmtAdded.personnel);
  const bud  = d.budget.concat(_mdesMgmtAdded.budget);
  const prj  = d.projects.concat(_mdesMgmtAdded.projects);
  const ctr  = d.contracts.concat(_mdesMgmtAdded.contracts);
  const intg = d.integration.concat(_mdesMgmtAdded.integration);
  const totalBudget = bud.reduce((s,r)=>s+Number(r.personnel_budget||0)+Number(r.operating_budget||0)+Number(r.capital_budget||0)+Number(r.subsidy_budget||0)+Number(r.other_budget||0),0);
  const avgProgress = prj.length ? Math.round(prj.reduce((s,r)=>s+Number(r.progress_pct||0),0)/prj.length) : 0;
  const contractTotal = ctr.reduce((s,r)=>s+Number(r.total_amount||0),0);
  res.json({
    ok:true, _source:'static_cache',
    summary:{
      personnel:{total:8500+per.length-d.personnel.length, active:8200, civil:5800, govEmp:1500, contract:1200},
      budget:{agencies:bud.length, total:totalBudget||26800000000, disbursed:Math.round((totalBudget||26800000000)*0.70), pct:70},
      projects:{total:prj.length, avg_progress:avgProgress, on_track:prj.filter(r=>Number(r.progress_pct||0)>=60).length, done:prj.filter(r=>r.status==='เสร็จสิ้น').length},
      contracts:{total:ctr.length, total_amount:contractTotal, active:ctr.filter(r=>r.status==='มีผลบังคับ').length},
      integration:{total:intg.length, in_progress:intg.filter(r=>r.status==='กำลังดำเนินการ').length},
      key_kpis:{broadband_coverage_pct:96.5, egovt_services:1200, cybersecurity_cases:3200, spectrum_mhz:8900, digital_literacy:17500000, startups:3800, incubators:150},
    },
    updatedAt: new Date().toISOString(),
  });
});

