// POST /api/management/chat — Management AI Assistant
app.post("/api/management/chat", async (req, res) => {
  const { ministry = "moac", role = "staff", message, history = [] } = req.body || {};
  if (!message) return res.status(400).json({ ok: false, error: "message required" });

  // Auth check
  const apiKey = req.headers["x-api-key"] || "";
  const expectedKey = MGMT_API_KEYS[ministry];
  if (!expectedKey || apiKey !== expectedKey) {
    return res.status(401).json({ ok: false, error: "unauthorized", reply: "⚠ ไม่มีสิทธิ์เข้าถึง กรุณาตรวจสอบ API key" });
  }

  const ANTHROPIC_KEY = process.env.ANTHROPIC_API_KEY || process.env.ANTHROPIC_KEY_1 || process.env.LEPHAYA_AI_KEY;
  if (!ANTHROPIC_KEY) {
    return res.status(500).json({ ok: false, error: "AI key not configured", reply: "⚠ ระบบยังไม่พร้อม กรุณาติดต่อผู้ดูแล" });
  }

  const systemPrompt = (MGMT_SYSTEM_PROMPTS[ministry] || MGMT_SYSTEM_PROMPTS.moac) +
    `\n\nระดับผู้ใช้: ${role}`;

  const recentHistory = (Array.isArray(history) ? history : []).slice(-10);
  const messages = [];
  for (const h of recentHistory) {
    if (h.role === "user" || h.role === "assistant") {
      messages.push({ role: h.role, content: h.content || h.text || "" });
    } else if (h.role === "ai") {
      messages.push({ role: "assistant", content: h.content || h.text || "" });
    }
  }
  messages.push({ role: "user", content: message });

  try {
    const r = await fetch("https://api.anthropic.com/v1/messages", {
      method: "POST",
      headers: {
        "x-api-key": ANTHROPIC_KEY,
        "anthropic-version": "2023-06-01",
        "content-type": "application/json",
      },
      body: JSON.stringify({
        model: "claude-sonnet-4-6",
        max_tokens: 1024,
        system: systemPrompt,
        messages,
      }),
    });
    const data = await r.json();
    if (data.error) throw new Error(`anthropic: ${data.error.message}`);
    const reply = (data.content || []).map(c => c.text).join("\n").trim();
    console.log(`[management-chat] ministry=${ministry} role=${role} tokens_in=${data.usage?.input_tokens} tokens_out=${data.usage?.output_tokens}`);
    return res.json({ ok: true, reply });
  } catch (e) {
    console.error("[management-chat] error:", e.message);
    return res.status(500).json({ ok: false, error: e.message, reply: "⚠ ขณะนี้ระบบ AI ไม่พร้อมใช้งาน กรุณาลองใหม่อีกครั้ง" });
  }
});
console.log("[G2G] Management Chat API registered ✅ (/api/management/chat — claude-sonnet-4-6)");
