// ==================== MANAGEMENT LINE COMMAND SYSTEM ====================
// Boss can type: /สั่งงาน, /รายงาน, /อนุมัติ, /ประชุม, /ตรวจสอบ

const MGMT_COMMANDS = {
  '/สั่งงาน': 'issue_task',
  '/รายงาน': 'request_report',
  '/อนุมัติ': 'approve_item',
  '/ประชุม': 'schedule_meeting',
  '/ตรวจสอบ': 'check_status',
  '/งบ': 'budget_query',
  '/บุคลากร': 'personnel_query',
  '/โครงการ': 'project_query',
  '/help': 'show_help',
};

const MGMT_COMMAND_LABELS = {
  issue_task: 'สั่งงาน',
  request_report: 'ขอรายงาน',
  approve_item: 'อนุมัติ',
  schedule_meeting: 'นัดประชุม',
  check_status: 'ตรวจสอบสถานะ',
  budget_query: 'สอบถามงบประมาณ',
  personnel_query: 'สอบถามบุคลากร',
  project_query: 'สอบถามโครงการ',
  show_help: 'แสดงความช่วยเหลือ',
};

// POST /api/management/line-command
// Called from the management web app to send a command to LINE OA
// or from LINE webhook when a message starts with /
app.post('/api/management/line-command', async (req, res) => {
  try {
    const { command, params, ministry, targetLineToken, sender, targetDept } = req.body;
    if (!command) return res.status(400).json({ ok: false, error: 'command required' });

    const cmdType = MGMT_COMMANDS[command] || 'general';
    const cmdLabel = MGMT_COMMAND_LABELS[cmdType] || command;
    const ministryName = ministry || 'กระทรวงเกษตรและสหกรณ์';

    // Help command — return static help text, no AI needed
    if (cmdType === 'show_help') {
      const helpText = [
        '📋 คำสั่งระบบบริหาร LINE',
        '/สั่งงาน [รายละเอียด] — ออกคำสั่งให้กรม',
        '/รายงาน [หัวข้อ] — ขอรายงานสถานะ',
        '/อนุมัติ [รายการ] — อนุมัติโครงการ/งบ',
        '/ประชุม [วาระ] — นัดประชุม',
        '/ตรวจสอบ [รายการ] — ตรวจสอบความคืบหน้า',
        '/งบ [หัวข้อ] — สอบถามงบประมาณ',
        '/บุคลากร [ข้อมูล] — สอบถามบุคลากร',
        '/โครงการ [ชื่อ] — สอบถามโครงการ',
      ].join('\n');
      return res.json({ ok: true, cmdType, response: helpText, pushed: false });
    }

    const systemPrompt = `คุณคือผู้ช่วย AI ระบบบริหารราชการ ${ministryName}
ตอบสั้นกระชับ เหมาะกับ LINE message (ไม่เกิน 300 ตัวอักษร)
ใช้ bullet points และ emoji ให้เหมาะสม
ถ้าเป็นคำสั่ง${cmdLabel} ให้ยืนยันว่ารับทราบและจะดำเนินการ พร้อมระบุขั้นตอนถัดไป
ถ้าเป็นการถามข้อมูล ให้ตอบข้อเท็จจริงที่เหมาะสมกับบริบทราชการไทย`;

    const userMessage = params
      ? `${command} ${Array.isArray(params) ? params.join(' ') : params}`
      : command;

    const r = await route({
      channel_id: 'mgmt-line-cmd',
      channel_key: '',
      user_id: sender || 'mgmt-boss',
      conversation_id: 'mgmt-line-cmd',
      prompt: userMessage,
      system: systemPrompt,
      history: [],
      model_class: 'fast',
      max_tokens: 400,
    });

    let responseText;
    if (r.ok) {
      responseText = r.text;
    } else {
      responseText = `⚠️ ไม่สามารถประมวลผลคำสั่งได้ชั่วคราว (${r.error})`;
    }

    // Optionally push to LINE OA if targetLineToken provided
    let pushed = false;
    if (targetLineToken) {
      try {
        const pushResp = await fetch('https://api.line.me/v2/bot/message/broadcast', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${targetLineToken}`,
          },
          body: JSON.stringify({
            messages: [{ type: 'text', text: `[${cmdLabel}] ${responseText}` }],
          }),
        });
        pushed = pushResp.ok;
      } catch (e) {
        console.error('[MGMT-LINE] push error:', e.message);
      }
    }

    res.json({ ok: true, cmdType, response: responseText, pushed, tokens: r.tokens });
  } catch (err) {
    console.error('[MGMT-LINE] error:', err);
    res.status(500).json({ ok: false, error: err.message });
  }
});

