// ==================== AIตลอดชีวิต LINE HEALTH HANDLER ====================

function parseHealthMessage(text) {
  const t = text.trim();
  const patterns = [
    { re: /น้ำหนัก\s*(\d+(?:\.\d+)?)\s*(?:กก|kg)/i, key:'weight', unit:'kg' },
    { re: /ความดัน\s*(\d+\/\d+)/i, key:'bp', unit:'mmHg' },
    { re: /น้ำตาล\s*(\d+(?:\.\d+)?)/i, key:'sugar', unit:'mg/dL' },
    { re: /ชีพจร\s*(\d+)/i, key:'pulse', unit:'bpm' },
    { re: /อุณหภูมิ\s*(\d+(?:\.\d+)?)/i, key:'temp', unit:'°C' },
    { re: /ออกซิเจน\s*(\d+(?:\.\d+)?)/i, key:'spo2', unit:'%' },
    { re: /ไขมัน\s*(\d+(?:\.\d+)?)/i, key:'cholesterol', unit:'mg/dL' },
    { re: /ก้าว\s*(\d+)/i, key:'steps', unit:'steps' },
    { re: /นอน\s*(\d+(?:\.\d+)?)\s*(?:ชม|ชั่วโมง|hr)/i, key:'sleep', unit:'hours' },
    { re: /น้ำ\s*(\d+)\s*(?:แก้ว|ml)/i, key:'water', unit:'glasses' },
    { re: /อารมณ์\s*(\d)/i, key:'mood', unit:'/5' },
  ];
  const results = {};
  patterns.forEach(p => {
    const m = t.match(p.re);
    if(m) results[p.key] = { value: m[1], unit: p.unit };
  });
  return Object.keys(results).length > 0 ? results : null;
}

async function aiHealthAdvice(citizenId, healthData, ANTHROPIC_KEY) {
  try {
    const profile = _lifelongProfiles[citizenId] || {};
    const dataStr = Object.entries(healthData).map(([k,v]) => `${k}: ${v.value} ${v.unit}`).join(', ');
    const systemPrompt = `คุณคือ "AIตลอดชีวิต" ผู้ช่วยสุขภาพส่วนตัว\nบุคคล: อายุ ${profile.age||'?'} ปี เพศ${profile.gender||'?'} โรคประจำตัว: ${(profile.conditions||[]).join(', ')||'ไม่มี'}\nข้อมูลที่เพิ่งบันทึก: ${dataStr}\nให้คำแนะนำสั้น กระชับ ภาษาไทยเข้าใจง่าย ไม่เกิน 150 ตัวอักษร\nถ้าค่าผิดปกติให้เตือนด้วย ถ้าปกติให้ชมเชยและแนะนำ`;
    const r = await fetch('https://api.anthropic.com/v1/messages', {
      method:'POST',
      headers:{'x-api-key':ANTHROPIC_KEY,'anthropic-version':'2023-06-01','Content-Type':'application/json'},
      body: JSON.stringify({ model:'claude-haiku-4-5', max_tokens:300, system: systemPrompt, messages:[{role:'user',content:`บันทึกข้อมูลสุขภาพ: ${dataStr} วิเคราะห์และแนะนำ`}] })
    });
    const d = await r.json();
    return d.content?.[0]?.text || 'บันทึกข้อมูลเรียบร้อยแล้ว ✅';
  } catch(e) {
    return 'บันทึกข้อมูลเรียบร้อย ✅';
  }
}

app.post('/api/lifelong/line-health', async (req, res) => {
  lifelongCors(res);
  try {
    const { citizenId, messageType, text, imageBase64 } = req.body;
    const ANTHROPIC_KEY = process.env.LEPHAYA_AI_KEY || process.env.ANTHROPIC_API_KEY || process.env.ANTHROPIC_KEY_1;
    if(!citizenId) return res.status(400).json({error:'citizenId required'});
    if(!_healthRecords[citizenId]) _healthRecords[citizenId] = [];
    let reply = '';
    let healthData = null;
    if(messageType === 'text' && text) {
      healthData = parseHealthMessage(text);
      if(healthData) {
        const record = { id:`H${Date.now()}`, citizenId, category:'vital', data: healthData, source:'line_text', timestamp: new Date().toISOString() };
        _healthRecords[citizenId].push(record);
        reply = '✅ บันทึกแล้ว!\n' + Object.entries(healthData).map(([k,v])=>`${k}: ${v.value} ${v.unit}`).join('\n') + '\n\n';
        reply += await aiHealthAdvice(citizenId, healthData, ANTHROPIC_KEY);
      } else {
        const r = await fetch('https://api.anthropic.com/v1/messages', {
          method:'POST',
          headers:{'x-api-key':ANTHROPIC_KEY,'anthropic-version':'2023-06-01','Content-Type':'application/json'},
          body: JSON.stringify({ model:'claude-haiku-4-5', max_tokens:400,
            system:'คุณคือ AIตลอดชีวิต ผู้ช่วยสุขภาพส่วนตัว ตอบภาษาไทย กระชับ ไม่เกิน 200 ตัวอักษร',
            messages:[{role:'user',content:text}] })
        });
        const d = await r.json();
        reply = d.content?.[0]?.text || 'สวัสดีครับ ส่งข้อมูลสุขภาพมาได้เลย เช่น "น้ำหนัก 70 กก" หรือ "ความดัน 120/80"';
      }
    }
    if(messageType === 'image' && imageBase64) {
      try {
        const visionPrompt = 'วิเคราะห์รูปภาพสุขภาพนี้ ดึงข้อมูลตัวเลขสำคัญ ตอบ JSON: {"type":"lab_result|bp_meter|glucose_meter|prescription|other","data":{},"summary":"","advice":""}';
        const r = await fetch('https://api.anthropic.com/v1/messages', {
          method:'POST',
          headers:{'x-api-key':ANTHROPIC_KEY,'anthropic-version':'2023-06-01','Content-Type':'application/json'},
          body: JSON.stringify({ model:'claude-haiku-4-5', max_tokens:600,
            messages:[{role:'user',content:[{type:'image',source:{type:'base64',media_type:'image/jpeg',data:imageBase64}},{type:'text',text:visionPrompt}]}] })
        });
        const d = await r.json();
        const rawText = d.content?.[0]?.text || '{}';
        let parsed = {};
        try { const jm = rawText.match(/\{[\s\S]*\}/); if(jm) parsed = JSON.parse(jm[0]); } catch(_) { parsed = {summary: rawText}; }
        if(parsed.data && Object.keys(parsed.data).length > 0) {
          _healthRecords[citizenId].push({ id:`H${Date.now()}`, citizenId, category: parsed.type||'lab', data: parsed.data, source:'line_image', rawSummary: parsed.summary, timestamp: new Date().toISOString() });
          reply = '📊 อ่านรูปได้แล้ว! บันทึกข้อมูล:\n' + Object.entries(parsed.data).slice(0,5).map(([k,v])=>`• ${k}: ${v}`).join('\n');
          if(parsed.advice) reply += `\n\n💡 ${parsed.advice}`;
        } else {
          reply = parsed.summary || '⚠️ ไม่สามารถอ่านข้อมูลจากรูปได้ชัดเจน กรุณาส่งรูปที่ชัดกว่านี้';
        }
      } catch(e) {
        reply = '⚠️ เกิดข้อผิดพลาดในการอ่านรูป กรุณาลองใหม่';
      }
    }
    res.json({ ok:true, reply, healthData });
  } catch(e) {
    res.status(500).json({ ok:false, error:e.message });
  }
});

