app.post('/api/learn/ai-assess', async (req,res)=>{
  learnCors(res);
  try {
    const {citizenId,domain,level,previousAnswers,questionCount}=req.body;
    const KEY=process.env.LEPHAYA_AI_KEY||process.env.ANTHROPIC_API_KEY||process.env.ANTHROPIC_KEY_1;
    const profile=_learnerProfiles[citizenId]||{};
    
    const prevStr=previousAnswers?.length
      ? `คำถามก่อนหน้า: ${previousAnswers.map(a=>`ถาม: ${a.q} → ตอบ: ${a.a} (${a.correct?'ถูก':'ผิด'})`).join('; ')}`
      : '';

    const r=await fetch('https://api.anthropic.com/v1/messages',{
      method:'POST',
      headers:{'x-api-key':KEY,'anthropic-version':'2023-06-01','Content-Type':'application/json'},
      body:JSON.stringify({
        model:'claude-haiku-4-5',max_tokens:1000,
        system:`คุณคือ AI ครูผู้สร้างข้อสอบแบบ Adaptive Testing
สร้างคำถามที่ปรับระดับตามคำตอบก่อนหน้า ถ้าตอบถูก → เพิ่มระดับยาก, ตอบผิด → ลดระดับ
ตอบเป็น JSON array เท่านั้น ไม่มีข้อความอื่น`,
        messages:[{role:'user',content:`สร้าง ${questionCount||3} ข้อสอบสำหรับ
วิชา/ทักษะ: ${domain}
ระดับปัจจุบัน: ${level||'กลาง'} (1=พื้นฐาน, 5=ผู้เชี่ยวชาญ)
${prevStr}
รูปแบบ: [{"q":"คำถาม","options":["ก","ข","ค","ง"],"answer":"ก","explanation":"เพราะ...","level":2}]`}]
      })
    });
    const d=await r.json();
    let questions=[];
    try{
      const txt=d.content?.[0]?.text||'[]';
      const m=txt.match(/\[[\s\S]*\]/);
      questions=m?JSON.parse(m[0]):[];
    }catch(_){}
    res.json({ok:true,questions,domain,level});
  }catch(e){res.status(500).json({ok:false,error:e.message});}
});

