app.post('/api/learn/ai-tutor', async (req,res)=>{
  learnCors(res);
  try {
    const {citizenId,message,mode,history,context}=req.body;
    const KEY=process.env.LEPHAYA_AI_KEY||process.env.ANTHROPIC_API_KEY||process.env.ANTHROPIC_KEY_1;
    const profile=_learnerProfiles[citizenId]||{};
    const logs=(_learningLogs[citizenId]||[]).slice(-5);
    const feedback=(_teacherFeedback[citizenId]||[]).slice(-3);

    const profileStr=[
      profile.name?`ชื่อ: ${profile.name}`:'',
      profile.ageGroup?`ช่วงวัย: ${profile.ageGroup}`:'',
      profile.occupation?`อาชีพ: ${profile.occupation}`:'',
      profile.interests?.length?`ความสนใจ: ${profile.interests.join(', ')}`:'',
      profile.skills?.length?`ทักษะ: ${profile.skills.map(s=>`${s.name}(${s.level}/5)`).join(', ')}`:'',
      profile.learningStyle?`สไตล์การเรียน: ${profile.learningStyle}`:'',
      logs.length?`เรียนล่าสุด: ${logs.map(l=>l.subject||l.activity).join(', ')}`:'',
      feedback.length?`ครูแนะนำว่า: ${feedback[feedback.length-1]?.observation||''}`:'',
    ].filter(Boolean).join('\n');

    const modePrompts={
      'tutor': `คุณคือ "ครู AI ตลอดชีวิต" ผู้เชี่ยวชาญด้านการสอนแบบ Adaptive
- สังเกตจากการตอบ ปรับการสอนให้เหมาะสมกับผู้เรียนแต่ละคน
- ถามกลับเพื่อกระตุ้นความคิด อย่าให้คำตอบตรงๆ แต่ชี้แนะทาง
- ชมเชยเมื่อทำได้ดี แก้ไขเมื่อเข้าใจผิดด้วยความอ่อนโยน
- ตอบภาษาไทย ไม่เกิน 250 ตัวอักษร`,
      'advisor': `คุณคือที่ปรึกษาการศึกษา ช่วยวางแผนการเรียนรู้ตลอดชีวิต
วิเคราะห์จากประวัติและแนะนำ: หลักสูตรที่เหมาะ, ทักษะที่ควรพัฒนา, เส้นทางอาชีพ
ตอบภาษาไทย กระชับ`,
      'practice': `คุณคือครูฝึก สร้างแบบฝึกหัดและแบบทดสอบ
ถ้าผู้เรียนตอบมา ให้ตรวจและให้ feedback ทันที พร้อมอธิบายเหตุผล
ปรับระดับยากง่ายตามความสามารถที่เห็น`,
    };

    const msgs=(history||[]).slice(-6).map(h=>({role:h.role,content:h.content}));
    msgs.push({role:'user',content:message});

    const r=await fetch('https://api.anthropic.com/v1/messages',{
      method:'POST',
      headers:{'x-api-key':KEY,'anthropic-version':'2023-06-01','Content-Type':'application/json'},
      body:JSON.stringify({
        model:'claude-sonnet-4-6',max_tokens:600,
        system:`${modePrompts[mode]||modePrompts['tutor']}

ข้อมูลผู้เรียน:
${profileStr||'(ยังไม่มีข้อมูล)'}`,
        messages:msgs
      })
    });
    const d=await r.json();
    res.json({ok:true,reply:d.content?.[0]?.text||'ขออภัย ไม่สามารถตอบได้',mode});
  }catch(e){res.status(500).json({ok:false,error:e.message});}
});

// POST /api/learn/ai-curriculum — generate personalized curriculum
app.post('/api/learn/ai-curriculum', async (req,res)=>{
  learnCors(res);
  try{
    const {citizenId,goal,timeframe}=req.body;
    const KEY=process.env.LEPHAYA_AI_KEY||process.env.ANTHROPIC_API_KEY||process.env.ANTHROPIC_KEY_1;
    const profile=_learnerProfiles[citizenId]||{};
    const r=await fetch('https://api.anthropic.com/v1/messages',{
      method:'POST',
      headers:{'x-api-key':KEY,'anthropic-version':'2023-06-01','Content-Type':'application/json'},
      body:JSON.stringify({
        model:'claude-haiku-4-5',max_tokens:800,
        system:`สร้างแผนการเรียนรู้ส่วนบุคคลเป็น JSON
{"weeks":[{"week":1,"theme":"...","activities":["..."],"assessment":"...","resources":["..."]}],"totalHours":N,"difficulty":"..."}`,
        messages:[{role:'user',content:`ผู้เรียน: ${JSON.stringify(profile)}
เป้าหมาย: ${goal}
ระยะเวลา: ${timeframe||'3 เดือน'}
สร้างแผนการเรียนรู้รายสัปดาห์`}]
      })
    });
    const d=await r.json();
    let plan={};
    try{const m=(d.content?.[0]?.text||'{}').match(/\{[\s\S]*\}/);plan=m?JSON.parse(m[0]):{};}catch(_){}
    if(citizenId) _learningPlans[citizenId]=plan;
    res.json({ok:true,plan});
  }catch(e){res.status(500).json({ok:false,error:e.message});}
});

