// Sub-agency login
app.post('/api/subagency/:agencyId/login', (req, res) => {
  const { agencyId } = req.params;
  const { employeeId, name, position, department } = req.body || {};
  if (!employeeId || !name) {
    return res.status(400).json({ ok: false, error: 'กรุณากรอกรหัสพนักงานและชื่อ' });
  }
  const userId = `${agencyId}-${employeeId}`;
  // Record login in personalAiStore if exists
  if (personalAiStore && personalAiStore[userId]) {
    personalAiStore[userId].lastLogin = new Date().toISOString();
  }
  res.json({
    ok: true,
    userId,
    agencyId,
    profile: { employeeId, name, position, department },
    timestamp: new Date().toISOString(),
    message: `ยินดีต้อนรับ ${name} เข้าสู่ระบบ`
  });
});

app.get('/api/subagency/:agencyId/report-up', (req, res) => {
  const { agencyId } = req.params;
  const cfg = subAgencyConfigs[agencyId];
  const data = getSubAgencyData(agencyId);
  res.json({
    agencyId, agencyName: cfg?.name,
    reportTo: cfg?.reportTo,
    reportDate: new Date().toISOString(),
    summary: {
      totalPersonnel: data.personnel.length,
      activeProjects: data.projects.filter(p=>p.status==='active').length,
      budgetItems: data.budget.length
    }
  });
});
