// ==================== PERSONAL AI (LINE AI SLOT) SYSTEM ====================
const personalAiStore = {}; // userId → { profile, memory[], conversations[] }

app.post('/api/personal-ai/register', (req, res) => {
  const { agencyId, userId, name, role, department, goals, context, preferredStyle } = req.body;
  if (!userId || !name) return res.status(400).json({ error: 'userId and name required' });
  const cfg = subAgencyConfigs[agencyId] || {};
  personalAiStore[userId] = {
    userId, agencyId, name, role, department,
    goals: goals || '',
    context: context || '',
    preferredStyle: preferredStyle || 'concise',
    memory: [],
    conversations: [],
    registeredAt: new Date().toISOString(),
    lastActive: new Date().toISOString()
  };
  res.json({ success: true, userId, aiName: `AI ผู้ช่วยของ ${name}`, agencySlots: cfg.aiSlots || 10 });
});

app.get('/api/personal-ai/:userId/profile', (req, res) => {
  const p = personalAiStore[req.params.userId];
  if (!p) return res.status(404).json({ error: 'User not registered', hint: 'Please register first' });
  res.json(p);
});

app.post('/api/personal-ai/:userId/memory', (req, res) => {
  const { userId } = req.params;
  if (!personalAiStore[userId]) return res.status(404).json({ error: 'User not found' });
  const m = { key: req.body.key, value: req.body.value, savedAt: new Date().toISOString() };
  personalAiStore[userId].memory.push(m);
  if (personalAiStore[userId].memory.length > 100) personalAiStore[userId].memory.shift();
  res.json({ success: true, memory: m });
});

app.get('/api/personal-ai/:userId/memory', (req, res) => {
  const p = personalAiStore[req.params.userId];
  if (!p) return res.status(404).json({ error: 'User not found' });
  res.json({ memory: p.memory });
});

app.post('/api/personal-ai/:userId/chat', async (req, res) => {
  const { userId } = req.params;
  const { message, history = [] } = req.body;
  const profile = personalAiStore[userId];
  if (!profile) return res.status(404).json({ error: 'User not registered. Please register first.' });

  const memoryContext = profile.memory.slice(-10).map(m => `- ${m.key}: ${m.value}`).join('\n');
  const systemPrompt = `คุณคือ AI ผู้ช่วยส่วนตัวของ ${profile.name} (${profile.role || 'เจ้าหน้าที่'}) สังกัด ${profile.department || profile.agencyId}

**ข้อมูลของผู้ใช้:**
- ชื่อ: ${profile.name}
- ตำแหน่ง: ${profile.role || '-'}
- แผนก/สังกัด: ${profile.department || '-'}
- เป้าหมาย: ${profile.goals || '-'}
- บริบท: ${profile.context || '-'}
- รูปแบบที่ชอบ: ${profile.preferredStyle}

**สิ่งที่จำได้:**
${memoryContext || 'ยังไม่มีข้อมูลที่บันทึกไว้'}

คุณเป็น AI ส่วนตัวที่รู้จักผู้ใช้นี้ดี ตอบเป็นภาษาไทย กระชับ และเป็นประโยชน์ตามบริบทราชการไทย`;

  try {
    const apiKey = process.env.ANTHROPIC_API_KEY || process.env.ANTHROPIC_KEY_1;
    if (!apiKey) return res.status(500).json({ error: 'Anthropic API key not configured' });
    const msgs = [...history.slice(-6), { role: 'user', content: message }];
    const r = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: { 'x-api-key': apiKey, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
      body: JSON.stringify({
        model: 'claude-haiku-4-5-20251001',
        max_tokens: 800,
        system: systemPrompt,
        messages: msgs
      })
    });
    const data = await r.json();
    if (data.error) throw new Error(`${data.error.type}: ${data.error.message}`);
    const reply = (data.content || []).map(c => c.text).join('\n');
    profile.lastActive = new Date().toISOString();
    profile.conversations.push({ role:'user', content:message, ts: new Date().toISOString() });
    profile.conversations.push({ role:'assistant', content:reply, ts: new Date().toISOString() });
    if (profile.conversations.length > 40) profile.conversations = profile.conversations.slice(-40);
    res.json({ reply, userId, assistantName: `AI ผู้ช่วยของ ${profile.name}` });
  } catch(e) {
    res.status(500).json({ error: e.message });
  }
});

app.get('/api/personal-ai/slots/:agencyId', (req, res) => {
  const { agencyId } = req.params;
  const cfg = subAgencyConfigs[agencyId] || { aiSlots: 10 };
  const used = Object.values(personalAiStore).filter(p => p.agencyId === agencyId).length;
  const users = Object.values(personalAiStore).filter(p => p.agencyId === agencyId)
    .map(p => ({ userId: p.userId, name: p.name, role: p.role, lastActive: p.lastActive }));
  res.json({ agencyId, total: cfg.aiSlots, used, available: cfg.aiSlots - used, users });
});
