// ==================== PLATFORM AUTH CODE SYSTEM ====================
const platformCodes = {}; // code → { agencyId, issuedBy, expiresAt, used }

app.post('/api/admin/platform-code/gen', (req, res) => {
  const { agencyId, issuedBy, adminPassword } = req.body;
  // Simple admin auth — in production use proper auth
  if (adminPassword !== (process.env.ADMIN_PASSWORD || 'g2gadmin2026')) {
    return res.status(403).json({ error: 'Invalid admin password' });
  }
  const code = `${(agencyId||'GOV').toUpperCase().slice(0,4)}-${Math.random().toString(36).slice(2,6).toUpperCase()}-${Math.floor(Math.random()*9000+1000)}`;
  const expiresAt = new Date(Date.now() + 30*24*60*60*1000).toISOString(); // 30 days
  platformCodes[code] = { code, agencyId, issuedBy: issuedBy || 'admin', expiresAt, used: false, createdAt: new Date().toISOString() };
  res.json({ success: true, code, expiresAt, message: `รหัสสำหรับ ${agencyId}: ${code} (หมดอายุ ${new Date(expiresAt).toLocaleDateString('th-TH')})` });
});

app.post('/api/admin/platform-code/verify', (req, res) => {
  const { code } = req.body;
  const entry = platformCodes[code];
  if (!entry) return res.json({ valid: false, reason: 'รหัสไม่ถูกต้อง' });
  if (new Date(entry.expiresAt) < new Date()) return res.json({ valid: false, reason: 'รหัสหมดอายุแล้ว' });
  res.json({ valid: true, agencyId: entry.agencyId, issuedBy: entry.issuedBy, expiresAt: entry.expiresAt });
});

app.post('/api/admin/platform-code/customize', async (req, res) => {
  const { code, agencyId, prompt, currentConfig } = req.body;
  const entry = platformCodes[code];
  if (!entry || new Date(entry.expiresAt) < new Date()) {
    return res.status(403).json({ error: 'Invalid or expired code' });
  }
  try {
    const apiKey = process.env.ANTHROPIC_API_KEY || process.env.ANTHROPIC_KEY_1;
    if (!apiKey) return res.status(500).json({ error: 'Anthropic API key not configured' });
    const r = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: { 'x-api-key': apiKey, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
      body: JSON.stringify({
        model: 'claude-haiku-4-5-20251001',
        max_tokens: 1000,
        system: `คุณเป็น AI ที่ช่วยปรับแต่ง UI ของแพลตฟอร์มราชการ ${agencyId} ตามคำขอ
คุณสามารถแนะนำการเปลี่ยน: สีธีม (cssVars), โมดูลที่แสดง (modules), ชื่อแพลตฟอร์ม (title), ข้อความต้อนรับ (welcomeMsg)
ตอบในรูปแบบ JSON: { "cssVars": {"--primary":"#..."}, "title": "...", "welcomeMsg": "...", "hideModules": [...], "explanation": "..." }
ถ้าไม่ต้องการเปลี่ยนส่วนไหน ไม่ต้องใส่ key นั้น`,
        messages: [{ role: 'user', content: `คำขอ: ${prompt}\nConfig ปัจจุบัน: ${JSON.stringify(currentConfig)}` }]
      })
    });
    const data = await r.json();
    if (data.error) throw new Error(`${data.error.type}: ${data.error.message}`);
    const text = (data.content || []).map(c => c.text).join('\n');
    let changes = {};
    try { changes = JSON.parse(text); } catch { changes = { explanation: text }; }
    res.json({ success: true, changes, code });
  } catch(e) {
    res.status(500).json({ error: e.message });
  }
});

