// In-memory hub store (in production: Airtable/DB)
const hubReports = new Map(); // agencyId → report object
const hubAlerts = [];         // all alerts across system

// Ministry registry — maps ministryId to agency list
const ministryRegistry = {
  moac: { name: 'กระทรวงเกษตรและสหกรณ์', abbr: 'กษ.', color: '#2e7d32', agencies: ['moac-doae','moac-rid','moac-dld','moac-fisheries','moac-doa','moac-ldd','moac-rice','moac-coop','moac-audit','moac-alro','moac-baac','moac-gat'], url: '/management-moac.html' },
  mhesi: { name: 'กระทรวงการอุดมศึกษาฯ', abbr: 'อว.', color: '#6a1b9a', agencies: ['mhesi-ops','mhesi-nstda','mhesi-nrct','mhesi-nectec','mhesi-biotec','mhesi-nanotec','mhesi-nia'], url: '/management-mhesi.html' },
  moi: { name: 'กระทรวงมหาดไทย', abbr: 'มท.', color: '#1565c0', agencies: ['moi-ops','moi-dopa','moi-dpt','moi-dla','moi-disaster'], url: '/management-moi.html' },
  mdes: { name: 'กระทรวงดิจิทัลฯ', abbr: 'ดศ.', color: '#00838f', agencies: ['mdes-ops','mdes-etda','mdes-dga','mdes-onde','mdes-nectec'], url: '/management-mdes.html' },
  moph: { name: 'กระทรวงสาธารณสุข', abbr: 'สธ.', color: '#c62828', agencies: ['moph-ops','moph-ddc','moph-dms','moph-dmh','moph-fda'], url: '/management-moph.html' },
  moc: { name: 'กระทรวงพาณิชย์', abbr: 'พณ.', color: '#e65100', agencies: ['moc-ops','moc-dbd','moc-dit','moc-dft','moc-doic'], url: '/management-moc.html' }
};

// Provincial office registry — maps province to agencies
const provincialRegistry = {
  phrae: { name: 'แพร่', ministries: ['moac','moi','moph','mdes'], agencies: ['moac-rid-phrae','moi-phrae','moph-phrae','mdes-phrae'] },
  chiangrai: { name: 'เชียงราย', ministries: ['moac','moi','moph'], agencies: ['moac-rid-chiangrai','moi-chiangrai','moph-chiangrai'] },
  udonthani: { name: 'อุดรธานี', ministries: ['moac','moi','moph'], agencies: ['moac-rid-udon','moi-udon','moph-udon'] }
};

// POST /api/hub/report — any agency pushes its report up the chain
app.post('/api/hub/report', (req, res) => {
  const report = req.body;
  if (!report.agencyId || !report.ministryId) return res.status(400).json({error:'agencyId and ministryId required'});
  report.receivedAt = new Date().toISOString();
  report.timestamp = report.timestamp || report.receivedAt;
  hubReports.set(report.agencyId, report);
  // Extract alerts
  if (report.alerts && report.alerts.length > 0) {
    report.alerts.forEach(a => {
      hubAlerts.unshift({...a, agencyId: report.agencyId, agencyName: report.agencyName, ministryId: report.ministryId, at: report.timestamp});
    });
    if (hubAlerts.length > 200) hubAlerts.splice(200);
  }
  res.json({ok:true, message:'รายงานส่งขึ้นระบบสำเร็จ', receivedAt: report.receivedAt});
});

// GET /api/hub/agency/:agencyId — get latest report for one agency
app.get('/api/hub/agency/:agencyId', (req, res) => {
  const r = hubReports.get(req.params.agencyId);
  if (!r) return res.json({agencyId: req.params.agencyId, noData: true, message:'ยังไม่มีรายงาน'});
  res.json(r);
});

// GET /api/hub/ministry/:ministryId — aggregated ministry view
app.get('/api/hub/ministry/:ministryId', (req, res) => {
  const min = ministryRegistry[req.params.ministryId];
  if (!min) return res.status(404).json({error:'Ministry not found'});
  const reports = [];
  let totalBudget=0, totalSpent=0, totalPersonnel=0, totalProjects=0, totalDelayed=0;
  hubReports.forEach((r,id) => {
    if (r.ministryId === req.params.ministryId) {
      reports.push(r);
      if (r.budget) { totalBudget += (r.budget.total||0); totalSpent += (r.budget.spent||0); }
      if (r.personnel) totalPersonnel += (r.personnel.total||0);
      if (r.projects) { totalProjects += (r.projects.total||0); totalDelayed += (r.projects.delayed||0); }
    }
  });
  const alerts = hubAlerts.filter(a => a.ministryId === req.params.ministryId).slice(0,20);
  res.json({
    ministryId: req.params.ministryId, ...min,
    reportCount: reports.length,
    agencies: reports,
    summary: { totalBudget, totalSpent, spentPct: totalBudget>0?Math.round(totalSpent/totalBudget*100):0, totalPersonnel, totalProjects, totalDelayed },
    alerts,
    generatedAt: new Date().toISOString()
  });
});

// POST /line/test-chat — ทดสอบ Bot โดยตรงจาก Admin Panel (ไม่ผ่าน LINE)
app.post('/line/test-chat', express.json(), async (req, res) => {
  try {
    const { channelIdExt, message, userName } = req.body;
    if (!channelIdExt || !message) return res.status(400).json({ ok: false, error: 'ต้องระบุ channelIdExt และ message' });

    const sysPrompt = CHANNEL_SYSTEM_PROMPTS[channelIdExt] || SYSTEM_PROMPT_G2G_THAI;
    const userMsg = userName ? `[ผู้ทดสอบ: ${userName}] ${message}` : message;

    const aiRes = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: {
        'x-api-key': process.env.ANTHROPIC_API_KEY,
        'anthropic-version': '2023-06-01',
        'content-type': 'application/json'
      },
      body: JSON.stringify({
        model: ['MHESI01', 'MHESI02'].includes(channelIdExt) ? 'claude-opus-4-6' : 'claude-sonnet-4-6',
        max_tokens: 1024,
        system: sysPrompt,
        messages: [{ role: 'user', content: userMsg }]
      })
    });
    const data = await aiRes.json();
    const reply = data?.content?.[0]?.text || 'ไม่มีการตอบกลับ';
    res.json({ ok: true, reply, model: data.model, channelIdExt });
  } catch (e) {
    console.error('[test-chat]', e.message);
    res.status(500).json({ ok: false, error: e.message });
  }
});

