// GET /api/hub/minister — ALL ministries aggregated (minister view)
app.get('/api/hub/minister', (req, res) => {
  const ministries = [];
  let grandBudget=0, grandSpent=0, grandPersonnel=0, grandProjects=0;
  Object.entries(ministryRegistry).forEach(([id, info]) => {
    let mBudget=0, mSpent=0, mPersonnel=0, mProjects=0, mDelayed=0, agencyCount=0;
    hubReports.forEach((r) => {
      if (r.ministryId === id) {
        agencyCount++;
        if (r.budget) { mBudget+=(r.budget.total||0); mSpent+=(r.budget.spent||0); }
        if (r.personnel) mPersonnel+=(r.personnel.total||0);
        if (r.projects) { mProjects+=(r.projects.total||0); mDelayed+=(r.projects.delayed||0); }
      }
    });
    grandBudget+=mBudget; grandSpent+=mSpent; grandPersonnel+=mPersonnel; grandProjects+=mProjects;
    ministries.push({
      ministryId:id, ...info,
      agencyReports: agencyCount,
      budget: {total:mBudget, spent:mSpent, pct:mBudget>0?Math.round(mSpent/mBudget*100):0},
      personnel: mPersonnel, projects: mProjects, delayed: mDelayed,
      alerts: hubAlerts.filter(a=>a.ministryId===id).length
    });
  });
  res.json({
    view:'minister', ministries,
    grandSummary: { totalBudget:grandBudget, totalSpent:grandSpent, spentPct:grandBudget>0?Math.round(grandSpent/grandBudget*100):0, totalPersonnel:grandPersonnel, totalProjects:grandProjects },
    recentAlerts: hubAlerts.slice(0,30),
    totalReports: hubReports.size,
    generatedAt: new Date().toISOString()
  });
});

// GET /api/hub/province/:provinceId — provincial view
app.get('/api/hub/province/:provinceId', (req, res) => {
  const prov = provincialRegistry[req.params.provinceId];
  if (!prov) return res.status(404).json({error:'Province not found'});
  const reports = prov.agencies.map(id => hubReports.get(id) || {agencyId:id, noData:true});
  res.json({ provinceId: req.params.provinceId, ...prov, agencies: reports, generatedAt: new Date().toISOString() });
});

// GET /api/hub/alerts — all system alerts
app.get('/api/hub/alerts', (req, res) => {
  const level = req.query.level;
  const ministry = req.query.ministry;
  let alerts = [...hubAlerts];
  if (level) alerts = alerts.filter(a => a.level === level);
  if (ministry) alerts = alerts.filter(a => a.ministryId === ministry);
  res.json({ alerts: alerts.slice(0, 50), total: alerts.length });
});

// GET /api/hub/registry — full registry of all platforms
app.get('/api/hub/registry', (req, res) => {
  res.json({ ministries: ministryRegistry, provinces: provincialRegistry, totalReports: hubReports.size });
});

