// ═══════════════════════════════════════════════════════
// MHESI PLATFORM — Task Delegation + Bottom-up Reporting
// ═══════════════════════════════════════════════════════
const mhesiTasks = [];   // {id,from,fromName,to,toName,title,detail,priority,status,created}
const mhesiReports = []; // {id,from,fromName,fromLevel,toLevel,title,summary,data,created}

// POST /api/mhesi/assign — ผู้บริหารมอบหมายงานลงไปยังลูกน้อง
app.post('/api/mhesi/assign', (req, res) => {
  try {
    const { from, fromName, to, toName, title, detail, priority='normal' } = req.body;
    if (!from || !to || !title) return res.status(400).json({ ok:false, error:'from/to/title required' });
    const task = { id:`T${Date.now()}`, from, fromName, to, toName, title, detail, priority, status:'pending', created: new Date().toISOString() };
    mhesiTasks.push(task);
    console.log(`[MHESI] Task assigned: ${fromName} → ${toName}: ${title}`);
    res.json({ ok:true, taskId: task.id, task });
  } catch(e) { res.status(500).json({ ok:false, error:e.message }); }
});

// GET /api/mhesi/tasks?assignee=ps — ดึงงานที่ถูกมอบหมายให้ตน
app.get('/api/mhesi/tasks', (req, res) => {
  const { assignee, assigner } = req.query;
  let tasks = mhesiTasks;
  if (assignee) tasks = tasks.filter(t => t.to === assignee);
  if (assigner) tasks = tasks.filter(t => t.from === assigner);
  res.json({ ok:true, count: tasks.length, tasks: tasks.slice(-50).reverse() });
});

// PATCH /api/mhesi/tasks/:id — อัพเดทสถานะงาน
app.patch('/api/mhesi/tasks/:id', (req, res) => {
  const t = mhesiTasks.find(t => t.id === req.params.id);
  if (!t) return res.status(404).json({ ok:false, error:'Task not found' });
  const { status, note } = req.body;
  if (status) t.status = status;
  if (note) t.note = note;
  t.updatedAt = new Date().toISOString();
  res.json({ ok:true, task: t });
});

