const moacTasks = [];   // {id,from,fromName,to,toName,title,detail,priority,status,created}
const moacReports = []; // {id,from,fromName,fromLevel,toLevel,title,summary,data,created}
const moacDirectives = []; // {id,code,title,body,category,issuedBy,issuedByName,issuedAt,targetLevel,dueDate,priority,kpis,relatedPolicyId,attachments,status,acknowledgements[],cascades[],cancelledAt?,cancelledBy?,cancelReason?}

