// ═══════════════════════════════════════════════════════
// MOAC Platform — extended routes for moac-app.js (Deliverable 2)
//   tasks-by-role · workflow · notifications · comments · dashboard · health
//   file persistence (/tmp/moac-data.json, 30s flush)
//   NOTE: /api/moac/sheets-sync is registered separately below in the
//   "MOAC SHEETS SYNC" block — we only log a placeholder if env not set.
// ═══════════════════════════════════════════════════════
const MOAC_DATA_FILE = '/tmp/moac-data.json';

// Load any persisted state on boot. moacTasks/moacReports are already
// declared above; this rehydrates them in-place if a file exists.
(function loadMoacData() {
  try {
    if (existsSync(MOAC_DATA_FILE)) {
      const raw = JSON.parse(readFileSync(MOAC_DATA_FILE, 'utf8'));
      if (Array.isArray(raw.tasks))   raw.tasks.forEach(t => moacTasks.push(t));
      if (Array.isArray(raw.reports)) raw.reports.forEach(r => moacReports.push(r));
      if (Array.isArray(raw.directives)) raw.directives.forEach(d => moacDirectives.push(d));
      console.log(`[MOAC] Rehydrated ${moacTasks.length} tasks + ${moacReports.length} reports + ${moacDirectives.length} directives from ${MOAC_DATA_FILE}`);
    }
  } catch (e) { console.warn('[MOAC] persistence load failed:', e.message); }
})();

// Persist every 30s
setInterval(() => {
  try {
    writeFileSync(MOAC_DATA_FILE, JSON.stringify({ tasks: moacTasks, reports: moacReports, directives: moacDirectives, savedAt: new Date().toISOString() }, null, 0));
  } catch (e) { console.warn('[MOAC] persistence write failed:', e.message); }
}, 30000);

// Per-role "read" flags for notifications (in-memory).
const moacReadFlags = new Map(); // roleId → Set<eventId>

function buildEventsForRole(roleId) {
  const read = moacReadFlags.get(roleId) || new Set();
  const events = [];
  for (const t of moacTasks) {
    if (t.to === roleId) {
      const id = 'evt-task-' + t.id;
      events.push({
        id, type: 'task_assigned', toRoleId: roleId,
        title: t.title, summary: 'จาก ' + (t.fromName || t.from) + (t.priority ? ' · ' + t.priority : ''),
        ts: t.created, read: read.has(id), ref: { kind: 'task', id: t.id, status: t.status }
      });
    }
    if (t.from === roleId && t.updatedAt) {
      const id = 'evt-status-' + t.id;
      events.push({
        id, type: 'task_status', toRoleId: roleId,
        title: t.title, summary: (t.toName || t.to) + ' → ' + (t.status || '?'),
        ts: t.updatedAt, read: read.has(id), ref: { kind: 'task', id: t.id, status: t.status }
      });
    }
  }
  for (const r of moacReports) {
    if (r.toLevel === roleId) {
      const id = 'evt-report-' + r.id;
      events.push({
        id, type: 'report_received', toRoleId: roleId,
        title: r.title, summary: 'รายงานจาก ' + (r.fromName || r.from),
        ts: r.created, read: read.has(id), ref: { kind: 'report', id: r.id }
      });
    }
  }
  // Directive events: notify roleIds that have an acknowledgement entry pending
  for (const dir of moacDirectives) {
    if (dir.status === 'cancelled') continue;
    const ack = (dir.acknowledgements || []).find(a => a.roleId === roleId);
    if (ack && !ack.acknowledgedAt) {
      const id = 'evt-directive-' + dir.id;
      events.push({
        id, type: 'directive_received', toRoleId: roleId,
        title: '📜 ' + (dir.code || dir.id) + ' · ' + dir.title,
        summary: 'คำสั่งจาก ' + (dir.issuedByName || dir.issuedBy) +
                 (dir.priority ? ' · ' + dir.priority : '') +
                 (dir.dueDate ? ' · กำหนด ' + dir.dueDate : ''),
        ts: dir.issuedAt, read: read.has(id),
        ref: { kind: 'directive', id: dir.id, code: dir.code, priority: dir.priority }
      });
    }
  }
  events.sort((a, b) => (b.ts || '').localeCompare(a.ts || ''));
  return events;
}

// 1) GET /api/moac/tasks/by-role/:roleId
app.get('/api/moac/tasks/by-role/:roleId', moacCors, (req, res) => {
  const rid = req.params.roleId;
  const tasks = moacTasks.filter(t => t.to === rid).slice().sort((a, b) => (b.created || '').localeCompare(a.created || ''));
  const counts = { pending: 0, in_progress: 0, done: 0 };
  tasks.forEach(t => { const s = t.status || 'pending'; counts[s] = (counts[s] || 0) + 1; });
  res.json({ ok: true, roleId: rid, total: tasks.length, counts, tasks });
});

// 2) GET /api/moac/workflow/:taskId
app.get('/api/moac/workflow/:taskId', moacCors, (req, res) => {
  const tid = req.params.taskId;
  const task = moacTasks.find(t => t.id === tid);
  if (!task) return res.status(404).json({ ok: false, error: 'task not found' });
  const events = [];
  events.push({
    type: 'assigned',
    label: 'มอบหมาย: ' + task.title,
    summary: (task.fromName || task.from) + ' → ' + (task.toName || task.to),
    ts: task.created
  });
  if (task.updatedAt) {
    events.push({
      type: 'status',
      label: 'อัปเดตสถานะ → ' + (task.status || '?'),
      summary: task.note || '',
      ts: task.updatedAt
    });
  }
  (task.comments || []).forEach(c => events.push({
    type: 'comment',
    label: 'ความเห็น',
    summary: (c.byName || c.by) + ': ' + c.text,
    ts: c.created
  }));
  moacReports.filter(r => r.data && r.data.taskId === tid).forEach(r => events.push({
    type: 'report',
    label: '📨 รายงาน: ' + r.title,
    summary: (r.fromName || r.from) + ' → ' + (r.toLevel || '?'),
    ts: r.created
  }));
  events.sort((a, b) => (a.ts || '').localeCompare(b.ts || ''));
  res.json({ ok: true, task, events });
});

// 3) GET /api/moac/notifications/:roleId
app.get('/api/moac/notifications/:roleId', moacCors, (req, res) => {
  const rid = req.params.roleId;
  const all = buildEventsForRole(rid);
  const unread = all.filter(e => !e.read).length;
  res.json({ ok: true, roleId: rid, unread, total: all.length, events: all.slice(0, 10) });
});

// 3b) POST /api/moac/notifications/:roleId/read — mark read
app.post('/api/moac/notifications/:roleId/read', moacCors, (req, res) => {
  const rid = req.params.roleId;
  const ids = Array.isArray(req.body && req.body.ids) ? req.body.ids : null;
  if (!moacReadFlags.has(rid)) moacReadFlags.set(rid, new Set());
  const set = moacReadFlags.get(rid);
  if (ids) {
    ids.forEach(i => set.add(i));
  } else {
    buildEventsForRole(rid).forEach(e => set.add(e.id));
  }
  res.json({ ok: true, roleId: rid, markedCount: set.size });
});

// 4) POST /api/moac/tasks/:id/comment — add a comment to a task
app.post('/api/moac/tasks/:id/comment', moacCors, (req, res) => {
  const t = moacTasks.find(x => x.id === req.params.id);
  if (!t) return res.status(404).json({ ok: false, error: 'task not found' });
  const { by, byName, text } = req.body || {};
  if (!text) return res.status(400).json({ ok: false, error: 'text required' });
  if (!Array.isArray(t.comments)) t.comments = [];
  const c = {
    id: 'C' + Date.now(),
    by: by || '?',
    byName: byName || by || '?',
    text: String(text),
    created: new Date().toISOString()
  };
  t.comments.push(c);
  res.json({ ok: true, comment: c, task: t });
});

// 5) GET /api/moac/dashboard/:roleId
app.get('/api/moac/dashboard/:roleId', moacCors, (req, res) => {
  const rid = req.params.roleId;
  const myAssigned = moacTasks.filter(t => t.from === rid);
  const myInbox    = moacTasks.filter(t => t.to === rid);
  const open       = myInbox.filter(t => (t.status || 'pending') !== 'done');
  const inReports  = moacReports.filter(r => r.toLevel === rid);
  const recent = []
    .concat(myInbox.map(t => ({ kind: 'task_in', title: t.title, ts: t.created })))
    .concat(myAssigned.map(t => ({ kind: 'task_out', title: t.title, ts: t.created })))
    .concat(inReports.map(r => ({ kind: 'report_in', title: r.title, ts: r.created })))
    .sort((a, b) => (b.ts || '').localeCompare(a.ts || ''))
    .slice(0, 10);
  res.json({
    ok: true,
    roleId: rid,
    openTaskCount: open.length,
    inboxCount: myInbox.length,
    assignedOutCount: myAssigned.length,
    reportsCount: inReports.length,
    statusBreakdown: {
      pending:     myInbox.filter(t => t.status === 'pending').length,
      in_progress: myInbox.filter(t => t.status === 'in_progress').length,
      done:        myInbox.filter(t => t.status === 'done').length
    },
    recent,
    fetchedAt: new Date().toISOString()
  });
});

// 7) GET /api/moac/health
app.get('/api/moac/health', moacCors, (req, res) => {
  const all = moacTasks.concat(moacReports)
    .map(x => x.updatedAt || x.created || '')
    .filter(Boolean)
    .sort();
  res.json({
    ok: true,
    tasksCount: moacTasks.length,
    reportsCount: moacReports.length,
    lastActivity: all.length ? all[all.length - 1] : null,
    persistFile: MOAC_DATA_FILE,
    persistExists: existsSync(MOAC_DATA_FILE),
    uptime_s: Math.round(process.uptime())
  });
});

