// ═══════════════════════════════════════════════════════
// MOAC DIRECTIVE (คำสั่ง/นโยบาย) CASCADE SYSTEM
//   Top-down command-and-control flowing Minister → PS → Dept Heads → Provinces → Staff
//   Each directive has acknowledgement chain + cascade tree + compliance tracking
//   9 routes — POST /directives, GET /directives, /:id, /acknowledge, /cascade,
//   /compliance, /compliance-summary, GET /active-for/:roleId, POST /cancel
//   Persisted to /tmp/moac-data.json (key: directives)
// ═══════════════════════════════════════════════════════

// API key guard for write routes (matches existing moacCors-protected POSTs)
function moacDirectiveAuth(req, res, next) {
  if (req.method === 'OPTIONS' || req.method === 'GET') return next();
  const k = req.header('x-api-key');
  if (!['phrae2026', 'moac2026', 'mhesi2026'].includes(k)) {
    return res.status(401).json({ ok: false, error: 'x-api-key required (phrae2026 / moac2026)' });
  }
  next();
}

// Buddhist-year helper (พ.ศ. = ค.ศ. + 543)
function thaiBuddhistYear() {
  return new Date().getFullYear() + 543;
}

// Auto-generate sequential directive code per Thai year: MOAC-DIR-2569-0001
function generateDirectiveCode() {
  const by = thaiBuddhistYear();
  const prefix = `MOAC-DIR-${by}-`;
  const existing = moacDirectives
    .map(d => d.code || '')
    .filter(c => c.startsWith(prefix))
    .map(c => parseInt(c.slice(prefix.length), 10) || 0);
  const next = (existing.length ? Math.max(...existing) : 0) + 1;
  return prefix + String(next).padStart(4, '0');
}

// Role-id → display name (best-effort, mirrors moac-app.js role map)
const MOAC_ROLE_NAMES = {
  'moac-minister': 'รัฐมนตรีว่าการกระทรวงเกษตรและสหกรณ์',
  'moac-dep-minister': 'รัฐมนตรีช่วยว่าการกระทรวงเกษตรและสหกรณ์',
  'moac-minister-sec': 'เลขานุการรัฐมนตรีว่าการ',
  'moac-dep-minister-sec': 'เลขานุการรัฐมนตรีช่วยว่าการ',
  'moac-ps': 'ปลัดกระทรวงเกษตรและสหกรณ์',
  'moac-deputy-ps': 'รองปลัดกระทรวงเกษตรและสหกรณ์',
  'moac-ps-sec': 'เลขานุการปลัดกระทรวง',
  'moac-ps-advisor': 'ที่ปรึกษาปลัดกระทรวง',
  'moac-deputy-ps-sec': 'เลขานุการรองปลัดกระทรวง'
};
function moacRoleName(roleId) {
  if (!roleId) return '';
  if (MOAC_ROLE_NAMES[roleId]) return MOAC_ROLE_NAMES[roleId];
  // Dept head / deputy / staff fallback
  const m = roleId.match(/^(?:moac-)?([a-z]+)(?:-(deputy|staff))?$/i);
  if (m) {
    const code = m[1].toUpperCase();
    if (m[2] === 'deputy') return `รองอธิบดี (${code})`;
    if (m[2] === 'staff') return `นักวิชาการ (${code})`;
    return `อธิบดี (${code})`;
  }
  return roleId;
}

// Derive an "overdue" flag from dueDate (48h grace after due)
function isDirectiveOverdue(dir) {
  if (!dir.dueDate || dir.status === 'completed' || dir.status === 'cancelled') return false;
  const due = new Date(dir.dueDate).getTime();
  if (!due) return false;
  return Date.now() > (due + 48 * 3600 * 1000);
}

// Compute compliance summary for a directive
function computeComplianceSummary(dir) {
  const acks = dir.acknowledgements || [];
  const total = acks.length;
  const counts = { pending: 0, in_progress: 0, achieved: 0, failed: 0 };
  let pctSum = 0, pctN = 0;
  const byLevel = {};
  const stragglers = [];
  for (const a of acks) {
    const c = a.compliance || 'pending';
    counts[c] = (counts[c] || 0) + 1;
    if (typeof a.compliancePct === 'number') { pctSum += a.compliancePct; pctN++; }
    const lvl = a.level || 'unknown';
    if (!byLevel[lvl]) byLevel[lvl] = { total: 0, pending: 0, in_progress: 0, achieved: 0, failed: 0, avgPct: 0, _sum: 0, _n: 0 };
    byLevel[lvl].total++;
    byLevel[lvl][c] = (byLevel[lvl][c] || 0) + 1;
    if (typeof a.compliancePct === 'number') { byLevel[lvl]._sum += a.compliancePct; byLevel[lvl]._n++; }
    if (!a.acknowledgedAt) stragglers.push({ roleId: a.roleId, roleName: a.roleName, level: a.level, reason: 'ยังไม่รับทราบ' });
    else if (c === 'pending' || c === 'in_progress') stragglers.push({ roleId: a.roleId, roleName: a.roleName, level: a.level, reason: 'ยังไม่บรรลุผล', compliancePct: a.compliancePct || 0 });
  }
  Object.keys(byLevel).forEach(lvl => {
    const b = byLevel[lvl];
    b.avgPct = b._n ? Math.round(b._sum / b._n) : 0;
    delete b._sum; delete b._n;
  });
  const overallPct = pctN ? Math.round(pctSum / pctN) : 0;
  return {
    overallCompliancePct: overallPct,
    totalEntries: total,
    counts,
    byLevel,
    stragglerCount: stragglers.length,
    stragglers: stragglers.slice(0, 50),
    overdue: isDirectiveOverdue(dir)
  };
}

// ─── AI Advisory Generator (Claude + Perplexity) ──────────────────────────
// Produces structured policy advisory broken down by role level for any
// directive. Auto-triggered on POST /directives and also reachable via the
// /refresh-advisory · /advisory · /role-advisory endpoints below.
//   ENV: CLAUDE_API_KEY (preferred) or ANTHROPIC_API_KEY · PPLX_API_KEY
// Returns { ai_model, generated_at, research:{text,sources[]}, analysis:{…}, tokens_used }
async function generateDirectiveAdvisory(directive) {
  const CLAUDE_KEY = process.env.CLAUDE_API_KEY || process.env.ANTHROPIC_API_KEY || process.env.ANTHROPIC_KEY_1;
  const PPLX_KEY   = process.env.PPLX_API_KEY   || process.env.PERPLEXITY_API_KEY;
  if (!CLAUDE_KEY) {
    return {
      ai_model: 'stub',
      generated_at: new Date().toISOString(),
      research: { text: '', sources: [] },
      analysis: {
        context_summary: 'ระบบ AI Advisory ยังไม่ได้ตั้งค่า (CLAUDE_API_KEY ไม่พบ) — กรุณาตั้งค่า environment variable เพื่อเปิดใช้งานคำแนะนำอัตโนมัติ',
        key_data_points: [],
        action_plans: {
          ps: { summary: 'ยังไม่มีคำแนะนำ — โปรดเปิดใช้ AI Advisory', steps: [], deadline_hint: '' },
          'deputy-ps': { summary: 'ยังไม่มีคำแนะนำ', steps: [] },
          'dept-head': { summary: 'ยังไม่มีคำแนะนำ', steps: [] },
          'dept-deputy': { summary: 'ยังไม่มีคำแนะนำ', steps: [] },
          'dept-staff': { summary: 'ยังไม่มีคำแนะนำ', steps: [] },
          provincial: { summary: 'ยังไม่มีคำแนะนำ', steps: [] }
        },
        risks: [], best_practices: [], milestones: [], success_metrics: [],
        model_notes: 'Advisory disabled: missing CLAUDE_API_KEY env'
      },
      tokens_used: 0,
      error: 'missing_claude_api_key'
    };
  }

  const kpiTxt = (directive.kpis || []).map((k, i) =>
    `${i + 1}. ${k.name || ''} = ${k.target || ''} ${k.unit || ''}`).join('\n') || '— ไม่ระบุ —';

  // ── Step 1: Perplexity research (best-effort) ──────────────────────────
  let researchText = '';
  let researchSources = [];
  if (PPLX_KEY) {
    try {
      const ppQ = `${directive.title}\n\nบริบท: ${directive.body || ''}\n\nให้ค้นข้อมูลล่าสุดในประเทศไทย: สถานะปัจจุบัน, ตัวเลขสำคัญ, นโยบายของรัฐที่ผ่านมา, ตัวอย่างกรณีศึกษาที่สำเร็จ, ความท้าทาย หรือความเสี่ยงที่อาจเกิด.`;
      const ppRaw = await fetch('https://api.perplexity.ai/chat/completions', {
        method: 'POST',
        headers: { Authorization: `Bearer ${PPLX_KEY}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({
          model: 'sonar-pro',
          messages: [
            { role: 'system', content: 'คุณคือนักวิจัยนโยบายภาครัฐไทย ตอบกระชับ มีตัวเลขและหลักฐาน อ้างอิงแหล่งที่มาเสมอ' },
            { role: 'user', content: ppQ }
          ],
          max_tokens: 1200
        })
      });
      const ppData = await ppRaw.json();
      if (ppData.error) throw new Error(ppData.error.message || JSON.stringify(ppData.error));
      researchText = ppData.choices?.[0]?.message?.content || '';
      // Perplexity returns citations either as top-level `citations` or `search_results`
      researchSources = (ppData.citations || ppData.search_results || [])
        .map((c, i) => typeof c === 'string'
          ? { idx: i + 1, url: c, title: '' }
          : { idx: i + 1, url: c.url || c.link || '', title: c.title || '' })
        .filter(s => s.url);
    } catch (e) {
      console.warn('[directive-advisory] Perplexity step failed (continuing without):', e.message);
      researchText = '';
      researchSources = [];
    }
  }

  // ── Step 2: Claude policy analysis ────────────────────────────────────
  const sysPrompt = 'คุณคือที่ปรึกษานโยบายรัฐบาลไทย ผู้เชี่ยวชาญด้านเกษตร เศรษฐกิจ และการบริหารราชการ ภารกิจคือวิเคราะห์คำสั่ง/นโยบายที่ออกโดยรัฐมนตรี และเสนอแนวทางปฏิบัติที่ลึก ละเอียด เป็นรูปธรรม แยกตามระดับผู้รับผิดชอบ (ปลัด, รองปลัด, อธิบดี, รองอธิบดี, นักวิชาการ, จังหวัด) เน้นภาษาราชการที่กระชับ ตรงประเด็น ปฏิบัติได้จริง คำตอบเป็น JSON เท่านั้น';

  const userMsg = [
    `คำสั่ง/นโยบายของรัฐมนตรีกระทรวงเกษตรและสหกรณ์:`,
    `• ชื่อคำสั่ง: ${directive.title || '-'}`,
    `• หมวด: ${directive.category || '-'}`,
    `• ระดับความสำคัญ: ${directive.priority || 'normal'}`,
    `• กำหนดผลภายใน: ${directive.dueDate || 'ไม่ระบุ'}`,
    `• ออกโดย: ${directive.issuedByName || directive.issuedBy || '-'}`,
    `• ระดับเป้าหมาย: ${(directive.targetLevel || []).join(', ') || '-'}`,
    ``,
    `เนื้อหาคำสั่ง:`,
    directive.body || '(ไม่มีรายละเอียดเพิ่มเติม)',
    ``,
    `KPI/ตัวชี้วัด ที่กำหนดไว้:`,
    kpiTxt,
    ``,
    researchText ? `ข้อมูลวิจัยจาก Perplexity (อ้างอิงตัวเลขและกรณีศึกษา ใช้ประกอบการให้คำแนะนำ):\n${researchText}\n` : '',
    `งานของคุณ: วิเคราะห์และเสนอแนวทางปฏิบัติแบบ JSON เท่านั้น (ไม่ต้องมี markdown fence ไม่ต้องมีคำอธิบายภายนอก JSON) ตามโครงสร้างนี้:`,
    `{`,
    `  "context_summary": "string — สรุปบริบทและความสำคัญ 2-3 ประโยค",`,
    `  "key_data_points": ["...", "..."],`,
    `  "action_plans": {`,
    `    "ps":          { "summary": "บทบาทของปลัด", "steps": ["...","..."], "deadline_hint": "string" },`,
    `    "deputy-ps":   { "summary": "...", "steps": [...], "deadline_hint": "string" },`,
    `    "dept-head":   { "summary": "...", "steps": [...], "deadline_hint": "string" },`,
    `    "dept-deputy": { "summary": "...", "steps": [...], "deadline_hint": "string" },`,
    `    "dept-staff":  { "summary": "...", "steps": [...], "deadline_hint": "string" },`,
    `    "provincial":  { "summary": "...", "steps": [...], "deadline_hint": "string" }`,
    `  },`,
    `  "risks": [{ "risk": "string", "mitigation": "string", "severity": "low|medium|high" }],`,
    `  "best_practices": ["...", "..."],`,
    `  "milestones": [{ "week": 1, "title": "string", "owner_level": "string" }],`,
    `  "success_metrics": [{ "metric": "string", "target": "string", "tied_to_kpi": "string" }],`,
    `  "model_notes": "string — note about limitations of analysis"`,
    `}`,
    ``,
    `ข้อกำหนดเพิ่มเติม:`,
    `- ภายใต้ action_plans แต่ละระดับ ให้มีอย่างน้อย 3-5 steps ที่ปฏิบัติได้จริง เริ่มด้วยกริยา ("จัดทำ...", "ประสานงาน...", "ตรวจสอบ...")`,
    `- risks ให้อย่างน้อย 3 ข้อ พร้อม severity ที่เหมาะสม`,
    `- milestones ให้ไล่เป็นรายสัปดาห์ตั้งแต่สัปดาห์ที่ 1 ถึง 8-12`,
    `- success_metrics ผูกกับ KPI ที่ตั้งไว้ ถ้ามี`,
    `- ภาษาราชการไทยที่เป็นทางการ กระชับ`
  ].filter(Boolean).join('\n');

  const claudeModel = 'claude-sonnet-4-5'; // smarter than haiku for policy analysis; sonnet-4-5 is the current sonnet family
  let analysis = null;
  let tokensUsed = 0;
  let modelUsed = claudeModel;
  try {
    const aiRaw = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: {
        'x-api-key': CLAUDE_KEY,
        'anthropic-version': '2023-06-01',
        'content-type': 'application/json'
      },
      body: JSON.stringify({
        model: claudeModel,
        max_tokens: 8000,
        system: sysPrompt,
        // Use Anthropic Tool Use → enforces schema at runtime, no JSON.parse fragility
        tools: [{
          name: 'save_directive_advisory',
          description: 'บันทึกผลการวิเคราะห์คำสั่งราชการพร้อมแนวทางปฏิบัติแยกตามระดับ',
          input_schema: {
            type: 'object',
            properties: {
              context_summary:   { type: 'string', description: 'สรุปบริบทและความสำคัญ 2-3 ประโยค' },
              key_data_points:   { type: 'array',  items: { type: 'string' }, description: 'ข้อมูลสำคัญ 3-6 ข้อ' },
              action_plans: {
                type: 'object',
                properties: {
                  'ps':          { type:'object', properties:{ summary:{type:'string'}, steps:{type:'array', items:{type:'string'}}, deadline_hint:{type:'string'} }, required:['summary','steps'] },
                  'deputy-ps':   { type:'object', properties:{ summary:{type:'string'}, steps:{type:'array', items:{type:'string'}}, deadline_hint:{type:'string'} }, required:['summary','steps'] },
                  'dept-head':   { type:'object', properties:{ summary:{type:'string'}, steps:{type:'array', items:{type:'string'}}, deadline_hint:{type:'string'} }, required:['summary','steps'] },
                  'dept-deputy': { type:'object', properties:{ summary:{type:'string'}, steps:{type:'array', items:{type:'string'}}, deadline_hint:{type:'string'} }, required:['summary','steps'] },
                  'dept-staff':  { type:'object', properties:{ summary:{type:'string'}, steps:{type:'array', items:{type:'string'}}, deadline_hint:{type:'string'} }, required:['summary','steps'] },
                  'provincial':  { type:'object', properties:{ summary:{type:'string'}, steps:{type:'array', items:{type:'string'}}, deadline_hint:{type:'string'} }, required:['summary','steps'] }
                },
                required: ['ps','dept-head','dept-staff']
              },
              risks:           { type:'array', items: { type:'object', properties:{ risk:{type:'string'}, mitigation:{type:'string'}, severity:{type:'string', enum:['low','medium','high']} }, required:['risk','mitigation','severity'] }, description:'ความเสี่ยง 3 ข้อขึ้นไป' },
              best_practices:  { type:'array', items: { type:'string' }, description:'แนวปฏิบัติที่ดี 3-6 ข้อ' },
              milestones:      { type:'array', items: { type:'object', properties:{ week:{type:'integer'}, title:{type:'string'}, owner_level:{type:'string'} }, required:['week','title','owner_level'] }, description:'milestone รายสัปดาห์' },
              success_metrics: { type:'array', items: { type:'object', properties:{ metric:{type:'string'}, target:{type:'string'}, tied_to_kpi:{type:'string'} }, required:['metric','target'] } },
              model_notes:     { type:'string' }
            },
            required: ['context_summary','key_data_points','action_plans','risks','best_practices','milestones','success_metrics']
          }
        }],
        tool_choice: { type: 'tool', name: 'save_directive_advisory' },
        messages: [{ role: 'user', content: userMsg }]
      })
    });
    const aiData = await aiRaw.json();
    if (aiData.error) throw new Error(aiData.error.message || aiData.error.type || 'anthropic_error');
    tokensUsed = (aiData.usage?.input_tokens || 0) + (aiData.usage?.output_tokens || 0);
    modelUsed = aiData.model || claudeModel;

    // Extract tool_use block — Anthropic returns parsed object in .input (no JSON.parse needed)
    const toolBlock = (aiData.content || []).find(c => c.type === 'tool_use' && c.name === 'save_directive_advisory');
    if (toolBlock && toolBlock.input && typeof toolBlock.input === 'object') {
      analysis = toolBlock.input;
    } else {
      // Fallback: legacy text response
      const text = (aiData.content || []).map(c => c.text || '').join('\n').trim();
      let jsonStr = text;
      const fence = text.match(/```(?:json)?\s*([\s\S]*?)```/);
      if (fence) jsonStr = fence[1].trim();
      const first = jsonStr.indexOf('{');
      const last = jsonStr.lastIndexOf('}');
      if (first >= 0 && last > first) jsonStr = jsonStr.slice(first, last + 1);
      analysis = JSON.parse(jsonStr);
    }
  } catch (e) {
    console.warn('[directive-advisory] Claude step failed:', e.message);
    analysis = {
      context_summary: 'ไม่สามารถวิเคราะห์ได้ในขณะนี้ (Claude error: ' + e.message + ')',
      key_data_points: [],
      action_plans: {
        ps: { summary: '—', steps: [] }, 'deputy-ps': { summary: '—', steps: [] },
        'dept-head': { summary: '—', steps: [] }, 'dept-deputy': { summary: '—', steps: [] },
        'dept-staff': { summary: '—', steps: [] }, provincial: { summary: '—', steps: [] }
      },
      risks: [], best_practices: [], milestones: [], success_metrics: [],
      model_notes: 'analysis_failed: ' + e.message
    };
  }

  return {
    ai_model: `${modelUsed}${PPLX_KEY ? ' + perplexity/sonar-pro' : ''}`,
    generated_at: new Date().toISOString(),
    research: { text: researchText, sources: researchSources },
    analysis,
    tokens_used: tokensUsed
  };
}

// Compute which role-level a roleId belongs to. Mirrors moac-app.js ROLE_MAP
// but lives server-side so /role-advisory can pre-filter.
function levelOfRoleId(roleId) {
  if (!roleId) return null;
  if (roleId === 'moac-ps') return 'ps';
  if (roleId === 'moac-deputy-ps') return 'deputy-ps';
  if (/^level:(.+)$/.test(roleId)) return roleId.replace(/^level:/, '');
  // dept-head pattern: moac-<code>
  const head = roleId.match(/^moac-([a-z]+)$/i);
  if (head) {
    // exclude ministerial roles
    if (['minister','dep-minister','dep-minister-2','minister-sec','dep-minister-sec','dep-minister-2-sec','ps','deputy-ps','ps-sec','ps-advisor','deputy-ps-sec'].includes(head[1])) {
      return null;
    }
    return 'dept-head';
  }
  if (/-deputy$/.test(roleId)) return 'dept-deputy';
  if (/-staff$/.test(roleId))  return 'dept-staff';
  if (/^prov(ince|incial)?-/.test(roleId)) return 'provincial';
  return null;
}

// Persist moac data immediately (sync) — used by the async advisory writer so
// the advisory survives a restart before the 30s flush would have happened.
function persistMoacData() {
  try {
    writeFileSync(MOAC_DATA_FILE, JSON.stringify({
      tasks: moacTasks, reports: moacReports, directives: moacDirectives,
      savedAt: new Date().toISOString()
    }, null, 0));
  } catch (e) { console.warn('[MOAC] persistMoacData failed:', e.message); }
}

// 1) POST /api/moac/directives — ออกคำสั่ง/นโยบายใหม่
app.post('/api/moac/directives', moacCors, moacDirectiveAuth, (req, res) => {
  try {
    const b = req.body || {};
    if (!b.issuedBy || !b.title) return res.status(400).json({ ok: false, error: 'issuedBy/title required' });
    if (!Array.isArray(b.targetLevel) || !b.targetLevel.length) return res.status(400).json({ ok: false, error: 'targetLevel[] required (at least one of ps/deputy-ps/dept-head/dept-deputy/dept-staff/provincial)' });
    const id = 'MD' + Date.now();
    const code = generateDirectiveCode();
    const now = new Date().toISOString();
    // Build initial acknowledgement entries from targetLevel.
    // If body provides explicit targetRoleIds[], use those; otherwise infer from level (level only).
    const acknowledgements = [];
    if (Array.isArray(b.targetRoleIds) && b.targetRoleIds.length) {
      for (const rid of b.targetRoleIds) {
        acknowledgements.push({
          roleId: rid, roleName: moacRoleName(rid), level: null,
          acknowledgedAt: null, acknowledgmentNote: null,
          compliance: 'pending', compliancePct: 0, evidence: [], reportedAt: null
        });
      }
    } else {
      // Level-only entries — UI/cascade flow will resolve concrete roleIds
      for (const lvl of b.targetLevel) {
        acknowledgements.push({
          roleId: 'level:' + lvl, roleName: 'ทุกตำแหน่งระดับ ' + lvl, level: lvl,
          acknowledgedAt: null, acknowledgmentNote: null,
          compliance: 'pending', compliancePct: 0, evidence: [], reportedAt: null
        });
      }
    }
    const dir = {
      id, code,
      title: String(b.title).trim(),
      body: String(b.body || '').trim(),
      category: b.category || 'policy', // policy / regulation / urgent_order / cabinet_resolution
      issuedBy: b.issuedBy,
      issuedByName: b.issuedByName || moacRoleName(b.issuedBy),
      issuedAt: now,
      targetLevel: b.targetLevel,
      dueDate: b.dueDate || null,
      priority: b.priority || 'normal', // normal / high / urgent
      kpis: Array.isArray(b.kpis) ? b.kpis : [],
      relatedPolicyId: b.relatedPolicyId || null,
      attachments: Array.isArray(b.attachments) ? b.attachments : [],
      status: 'issued',
      acknowledgements,
      cascades: [
        { fromRoleId: b.issuedBy, fromRoleName: b.issuedByName || moacRoleName(b.issuedBy),
          toRoleIds: acknowledgements.map(a => a.roleId), toRoleNames: acknowledgements.map(a => a.roleName),
          note: 'ออกคำสั่งครั้งแรก', ts: now }
      ]
    };
    moacDirectives.push(dir);
    console.log(`[MOAC-DIR] Issued ${code}: ${dir.title} by ${dir.issuedByName} → ${acknowledgements.length} targets`);
    // Best-effort mirror to Google Sheets (no-op if not configured)
    try {
      syncToSheetsAsync('append', 'audit_log', {
        ts: now, action: 'directive_issue', actor: dir.issuedBy, target: dir.targetLevel.join(','),
        payload: JSON.stringify({ directiveId: id, code, title: dir.title, priority: dir.priority })
      });
    } catch (_) {}
    // Fire-and-forget AI advisory generation. Doesn't block the response —
    // the advisory will appear in the directive object on the next GET.
    dir.aiAdvisoryStatus = 'pending';
    generateDirectiveAdvisory(dir).then(advisory => {
      dir.aiAdvisory = advisory;
      dir.aiAdvisoryAt = new Date().toISOString();
      dir.aiAdvisoryStatus = advisory.error ? 'error' : 'ready';
      persistMoacData();
      console.log(`[MOAC-DIR] AI advisory ready for ${code} (${advisory.tokens_used || 0} tokens, status=${dir.aiAdvisoryStatus})`);
    }).catch(err => {
      dir.aiAdvisoryStatus = 'error';
      dir.aiAdvisoryError = err.message;
      console.warn('[directive-advisory]', err.message);
    });
    res.json({ ok: true, directiveId: id, code, directive: dir });
  } catch (e) {
    console.error('[MOAC-DIR] issue error', e);
    res.status(500).json({ ok: false, error: e.message });
  }
});

// 2) GET /api/moac/directives — list with filters
app.get('/api/moac/directives', moacCors, (req, res) => {
  const { status, issuedBy, priority, category, targetLevel } = req.query;
  const limit  = Math.min(parseInt(req.query.limit  || '50', 10), 500);
  const offset = Math.max(parseInt(req.query.offset || '0',  10), 0);
  let list = moacDirectives.slice();
  if (status)      list = list.filter(d => d.status === status);
  if (issuedBy)    list = list.filter(d => d.issuedBy === issuedBy);
  if (priority)    list = list.filter(d => d.priority === priority);
  if (category)    list = list.filter(d => d.category === category);
  if (targetLevel) list = list.filter(d => Array.isArray(d.targetLevel) && d.targetLevel.includes(targetLevel));
  list.sort((a, b) => (b.issuedAt || '').localeCompare(a.issuedAt || ''));
  const total = list.length;
  const slice = list.slice(offset, offset + limit).map(d => ({
    id: d.id, code: d.code, title: d.title, category: d.category,
    issuedBy: d.issuedBy, issuedByName: d.issuedByName, issuedAt: d.issuedAt,
    targetLevel: d.targetLevel, dueDate: d.dueDate, priority: d.priority,
    status: d.status, relatedPolicyId: d.relatedPolicyId,
    overdue: isDirectiveOverdue(d),
    ackCount: (d.acknowledgements || []).filter(a => a.acknowledgedAt).length,
    targetCount: (d.acknowledgements || []).length
  }));
  res.json({ ok: true, total, limit, offset, directives: slice });
});

// 3) GET /api/moac/directives/:id — single directive (full)
app.get('/api/moac/directives/:id', moacCors, (req, res) => {
  const d = moacDirectives.find(x => x.id === req.params.id || x.code === req.params.id);
  if (!d) return res.status(404).json({ ok: false, error: 'directive not found' });
  res.json({
    ok: true,
    directive: Object.assign({}, d, { overdue: isDirectiveOverdue(d) }),
    summary: computeComplianceSummary(d)
  });
});

// 4) POST /api/moac/directives/:id/acknowledge — บันทึกการรับทราบคำสั่ง
app.post('/api/moac/directives/:id/acknowledge', moacCors, moacDirectiveAuth, (req, res) => {
  const d = moacDirectives.find(x => x.id === req.params.id || x.code === req.params.id);
  if (!d) return res.status(404).json({ ok: false, error: 'directive not found' });
  const { roleId, roleName, note } = req.body || {};
  if (!roleId) return res.status(400).json({ ok: false, error: 'roleId required' });
  let entry = (d.acknowledgements || []).find(a => a.roleId === roleId);
  if (!entry) {
    // allow ad-hoc ack from someone in cascade chain who wasn't in initial target
    entry = { roleId, roleName: roleName || moacRoleName(roleId), level: null,
      acknowledgedAt: null, acknowledgmentNote: null, compliance: 'pending',
      compliancePct: 0, evidence: [], reportedAt: null };
    d.acknowledgements.push(entry);
  }
  entry.acknowledgedAt = new Date().toISOString();
  entry.acknowledgmentNote = note || null;
  if (roleName) entry.roleName = roleName;
  if (d.status === 'issued') d.status = 'in_progress';
  console.log(`[MOAC-DIR] ${d.code} acknowledged by ${entry.roleName}`);
  res.json({ ok: true, directive: d, ackEntry: entry });
});

// 5) POST /api/moac/directives/:id/cascade — กระจายคำสั่งลงไปยังลูกน้อง
app.post('/api/moac/directives/:id/cascade', moacCors, moacDirectiveAuth, (req, res) => {
  const d = moacDirectives.find(x => x.id === req.params.id || x.code === req.params.id);
  if (!d) return res.status(404).json({ ok: false, error: 'directive not found' });
  const { fromRoleId, fromRoleName, toRoleIds, toRoleNames, note } = req.body || {};
  if (!fromRoleId || !Array.isArray(toRoleIds) || !toRoleIds.length) {
    return res.status(400).json({ ok: false, error: 'fromRoleId + toRoleIds[] required' });
  }
  const now = new Date().toISOString();
  const namesArr = Array.isArray(toRoleNames) ? toRoleNames : toRoleIds.map(moacRoleName);
  // Append acknowledgement entries for new targets
  for (let i = 0; i < toRoleIds.length; i++) {
    const rid = toRoleIds[i];
    if (!(d.acknowledgements || []).some(a => a.roleId === rid)) {
      d.acknowledgements.push({
        roleId: rid, roleName: namesArr[i] || moacRoleName(rid), level: null,
        acknowledgedAt: null, acknowledgmentNote: null,
        compliance: 'pending', compliancePct: 0, evidence: [], reportedAt: null
      });
    }
  }
  d.cascades = d.cascades || [];
  d.cascades.push({
    fromRoleId, fromRoleName: fromRoleName || moacRoleName(fromRoleId),
    toRoleIds, toRoleNames: namesArr,
    note: note || '', ts: now
  });
  console.log(`[MOAC-DIR] ${d.code} cascaded by ${fromRoleName || fromRoleId} → ${toRoleIds.length} role(s)`);
  res.json({ ok: true, directive: d, newCascade: d.cascades[d.cascades.length - 1] });
});

// 6) POST /api/moac/directives/:id/compliance — รายงานความก้าวหน้า/ผลการปฏิบัติ
app.post('/api/moac/directives/:id/compliance', moacCors, moacDirectiveAuth, (req, res) => {
  const d = moacDirectives.find(x => x.id === req.params.id || x.code === req.params.id);
  if (!d) return res.status(404).json({ ok: false, error: 'directive not found' });
  const { roleId, compliance, compliancePct, evidence } = req.body || {};
  if (!roleId) return res.status(400).json({ ok: false, error: 'roleId required' });
  let entry = (d.acknowledgements || []).find(a => a.roleId === roleId);
  if (!entry) return res.status(404).json({ ok: false, error: 'roleId not in this directive — acknowledge first' });
  if (compliance && !['pending','in_progress','achieved','failed'].includes(compliance)) {
    return res.status(400).json({ ok: false, error: 'compliance must be pending/in_progress/achieved/failed' });
  }
  if (compliance) entry.compliance = compliance;
  if (typeof compliancePct === 'number') entry.compliancePct = Math.max(0, Math.min(100, compliancePct));
  if (Array.isArray(evidence)) {
    entry.evidence = (entry.evidence || []).concat(evidence.map(e => ({
      type: e.type || 'note', url: e.url || null, note: e.note || '', ts: new Date().toISOString()
    })));
  }
  entry.reportedAt = new Date().toISOString();
  // Auto-flag directive as completed if every entry has achieved compliance
  const acks = d.acknowledgements || [];
  if (acks.length && acks.every(a => a.compliance === 'achieved')) d.status = 'completed';
  console.log(`[MOAC-DIR] ${d.code} compliance update from ${entry.roleName}: ${entry.compliance} ${entry.compliancePct}%`);
  res.json({ ok: true, directive: d, entry });
});

// 7) GET /api/moac/directives/:id/compliance-summary
app.get('/api/moac/directives/:id/compliance-summary', moacCors, (req, res) => {
  const d = moacDirectives.find(x => x.id === req.params.id || x.code === req.params.id);
  if (!d) return res.status(404).json({ ok: false, error: 'directive not found' });
  res.json({
    ok: true, directiveId: d.id, code: d.code, title: d.title,
    status: d.status, priority: d.priority, dueDate: d.dueDate,
    summary: computeComplianceSummary(d)
  });
});

// 8) GET /api/moac/directives/active-for/:roleId — คำสั่งที่ค้างต้องปฏิบัติของบุคคลนั้น
app.get('/api/moac/directives/active-for/:roleId', moacCors, (req, res) => {
  const rid = req.params.roleId;
  const need_ack = [];
  const need_cascade = [];
  const need_report = [];
  for (const d of moacDirectives) {
    if (d.status === 'cancelled' || d.status === 'completed') continue;
    const ack = (d.acknowledgements || []).find(a => a.roleId === rid);
    if (!ack) continue;
    const overdue = isDirectiveOverdue(d);
    const item = {
      id: d.id, code: d.code, title: d.title, category: d.category,
      issuedByName: d.issuedByName, issuedAt: d.issuedAt,
      priority: d.priority, dueDate: d.dueDate, overdue,
      acknowledgedAt: ack.acknowledgedAt, compliance: ack.compliance,
      compliancePct: ack.compliancePct
    };
    if (!ack.acknowledgedAt) {
      need_ack.push(item);
    } else if (ack.compliance === 'achieved' || ack.compliance === 'failed') {
      // already reported final outcome → not active
    } else {
      need_report.push(item);
      // Anyone who acknowledged but is not a leaf (staff) may also need to cascade.
      // We surface this generically — the UI shows the "cascade" button only when
      // there are subordinate roles to cascade to.
      need_cascade.push(item);
    }
  }
  res.json({
    ok: true, roleId: rid,
    need_ack_count: need_ack.length,
    need_cascade_count: need_cascade.length,
    need_report_count: need_report.length,
    need_ack, need_cascade, need_report
  });
});

// 9) POST /api/moac/directives/:id/cancel — ยกเลิกคำสั่ง (ผู้ออกหรือเหนือกว่าเท่านั้น)
app.post('/api/moac/directives/:id/cancel', moacCors, moacDirectiveAuth, (req, res) => {
  const d = moacDirectives.find(x => x.id === req.params.id || x.code === req.params.id);
  if (!d) return res.status(404).json({ ok: false, error: 'directive not found' });
  const { roleId, reason } = req.body || {};
  if (!roleId) return res.status(400).json({ ok: false, error: 'roleId required' });
  // Authority check: issuer, or minister, or PS (top-of-chain)
  const ALLOWED_OVERRIDES = new Set(['moac-minister', 'moac-ps']);
  if (roleId !== d.issuedBy && !ALLOWED_OVERRIDES.has(roleId)) {
    return res.status(403).json({ ok: false, error: 'เฉพาะผู้ออกคำสั่งหรือผู้บังคับบัญชาสูงสุด (รมว./ปลัด) เท่านั้นที่ยกเลิกได้' });
  }
  d.status = 'cancelled';
  d.cancelledAt = new Date().toISOString();
  d.cancelledBy = roleId;
  d.cancelReason = reason || '';
  console.log(`[MOAC-DIR] ${d.code} CANCELLED by ${roleId}: ${reason || ''}`);
  res.json({ ok: true, directive: d });
});

// 10) GET /api/moac/directives/:id/advisory — return just the AI advisory blob
app.get('/api/moac/directives/:id/advisory', moacCors, (req, res) => {
  const d = moacDirectives.find(x => x.id === req.params.id || x.code === req.params.id);
  if (!d) return res.status(404).json({ ok: false, error: 'directive not found' });
  if (!d.aiAdvisory) {
    return res.json({
      ok: true,
      status: d.aiAdvisoryStatus || 'pending',
      directiveId: d.id, code: d.code,
      advisory: null,
      hint: 'AI กำลังวิเคราะห์… โปรดรอประมาณ 30 วินาทีแล้วลองใหม่ หรือกดปุ่ม "ขอ AI วิเคราะห์ใหม่"'
    });
  }
  res.json({
    ok: true,
    status: d.aiAdvisoryStatus || 'ready',
    directiveId: d.id, code: d.code,
    aiAdvisoryAt: d.aiAdvisoryAt,
    advisory: d.aiAdvisory
  });
});

// 11) POST /api/moac/directives/:id/refresh-advisory — regenerate AI advisory
app.post('/api/moac/directives/:id/refresh-advisory', moacCors, moacDirectiveAuth, async (req, res) => {
  const d = moacDirectives.find(x => x.id === req.params.id || x.code === req.params.id);
  if (!d) return res.status(404).json({ ok: false, error: 'directive not found' });
  d.aiAdvisoryStatus = 'pending';
  try {
    const advisory = await generateDirectiveAdvisory(d);
    d.aiAdvisory = advisory;
    d.aiAdvisoryAt = new Date().toISOString();
    d.aiAdvisoryStatus = advisory.error ? 'error' : 'ready';
    persistMoacData();
    console.log(`[MOAC-DIR] AI advisory refreshed for ${d.code} (${advisory.tokens_used || 0} tokens)`);
    res.json({ ok: true, directiveId: d.id, code: d.code, advisory });
  } catch (e) {
    d.aiAdvisoryStatus = 'error';
    console.warn('[directive-advisory] refresh failed:', e.message);
    res.status(500).json({ ok: false, error: e.message });
  }
});

// 12) POST /api/moac/directives/:id/role-advisory — role-filtered advisory slice
//     body: { roleId }. Returns only the action_plan + relevant risks/milestones
//     for the role's level. Useful when UI does not need the whole tree.
app.post('/api/moac/directives/:id/role-advisory', moacCors, (req, res) => {
  const d = moacDirectives.find(x => x.id === req.params.id || x.code === req.params.id);
  if (!d) return res.status(404).json({ ok: false, error: 'directive not found' });
  const { roleId } = req.body || {};
  if (!roleId) return res.status(400).json({ ok: false, error: 'roleId required' });
  const lvl = levelOfRoleId(roleId);
  if (!d.aiAdvisory || !d.aiAdvisory.analysis) {
    return res.json({
      ok: true, status: d.aiAdvisoryStatus || 'pending', roleId, level: lvl,
      advisory: null,
      hint: 'ยังไม่มี AI วิเคราะห์ — โปรดรอ หรือกดปุ่ม "ขอ AI วิเคราะห์ใหม่"'
    });
  }
  const a = d.aiAdvisory.analysis;
  const myPlan = (a.action_plans && (a.action_plans[lvl] || a.action_plans[lvl?.replace('moac-', '')])) || null;
  const relevantMilestones = (a.milestones || []).filter(m =>
    !m.owner_level || m.owner_level === lvl || m.owner_level === 'all'
  );
  res.json({
    ok: true,
    status: d.aiAdvisoryStatus || 'ready',
    directiveId: d.id, code: d.code,
    roleId, level: lvl,
    advisory: {
      context_summary: a.context_summary,
      my_action_plan: myPlan,
      risks: a.risks || [],
      best_practices: a.best_practices || [],
      milestones: relevantMilestones,
      success_metrics: a.success_metrics || [],
      sources: d.aiAdvisory.research?.sources || []
    }
  });
});

