// GET /api/farmer/buyers — list buyers (supports ?tier=broker|retailer|exporter|processor)
app.get('/api/farmer/buyers', (req, res) => {
  const { region, grade, crop, tier } = req.query;
  let b = farmerBuyers;
  if (tier)   b = b.filter(x => x.tier === tier);
  if (region) b = b.filter(x => x.regions.includes('*') || x.regions.includes(region));
  if (grade)  b = b.filter(x => x.grades.includes(grade));
  if (crop)   b = b.filter(x => x.crops.includes('*') || x.crops.includes(crop));
  res.json({
    ok: true,
    count: b.length,
    breakdown: {
      broker:    b.filter(x => x.tier === 'broker').length,
      retailer:  b.filter(x => x.tier === 'retailer').length,
      exporter:  b.filter(x => x.tier === 'exporter').length,
      processor: b.filter(x => x.tier === 'processor').length
    },
    buyers: b
  });
});

// Score one buyer against a plot (only brokers should be matched directly)
function scoreBuyer(plot, buyer){
  let s = 0;
  // region match (40 pts) — '*' means national buyer
  if (buyer.regions.includes('*') || (plot.province && buyer.regions.includes(plot.province))) s += 40;
  // grade match (30 pts)
  if (plot.grade && buyer.grades.includes(plot.grade)) s += 30;
  // capacity (30 pts) — buyer can absorb the estimated volume
  const est = Number(plot.estimateKg) || 0;
  if (est > 0 && est <= buyer.capacityKgPerWeek) s += 30;
  // crop bonus (10 pts) — buyer specializes in this crop
  if (plot.crop && (buyer.crops.includes('*') || buyer.crops.includes(plot.crop))) s += 10;
  return s;
}

// POST /api/farmer/matching — รับ plot info, คืน brokers 3 อันดับแรก + downstream chain
// IMPORTANT: matches ONLY tier='broker' (ล้ง/สหกรณ์/รัฐวิสาหกิจ) — เกษตรกรไม่ขายตรงให้ห้าง
app.post('/api/farmer/matching', (req, res) => {
  try {
    const plot = req.body || {};
    if (!plot.plotId && !plot.province && !plot.crop) {
      return res.status(400).json({ ok:false, error:'plot info required (plotId/province/crop/grade/estimateKg)' });
    }
    const brokersOnly = farmerBuyers.filter(b => b.tier === 'broker');
    const ranked = brokersOnly
      .map(b => ({
        buyer: b,
        score: scoreBuyer(plot, b),
        downstream: _expandSellsTo(b).map(d => ({ id:d.id, tier:d.tier, subtype:d.subtype, name:d.name, paymentTerms:d.paymentTerms }))
      }))
      .sort((a,b) => b.score - a.score)
      .slice(0, 3);
    // log the match attempt
    if (plot.plotId) {
      ranked.forEach(r => {
        farmerMatches.push({ id:`M${Date.now()}-${r.buyer.id}`, plotId:plot.plotId, buyerId:r.buyer.id, score:r.score, status:'suggested', created:new Date().toISOString() });
      });
    }
    res.json({
      ok: true,
      plot,
      note: 'matching จำกัดเฉพาะ tier=broker (ล้ง/สหกรณ์) · downstream แสดงห้าง/ผู้ส่งออกที่ล้งขายต่อ',
      top3: ranked
    });
  } catch(e) { res.status(500).json({ ok:false, error:e.message }); }
});

// GET /api/farmer/market-chain/:crop — full 3-tier chain for a crop
// Reads brokers handling this crop, traces sellsTo[] to retailers/exporters/processors,
// pulls farmgate/wholesale/retail price points + typical_margin from the crop JSON's market_chain block
app.get('/api/farmer/market-chain/:crop', (req, res) => {
  try {
    const crop = String(req.params.crop).replace(/[^a-z0-9_-]/gi, '').toLowerCase();
    const file = join(__dirname, 'public', 'crop-data', `${crop}.json`);
    if (!existsSync(file)) return res.status(404).json({ ok:false, error:`crop ${crop} not found` });
    const data = JSON.parse(readFileSync(file, 'utf8'));
    const mc = data.market_chain || {};

    // brokers handling this crop
    const brokers = farmerBuyers.filter(b => b.tier === 'broker' && (b.crops.includes('*') || b.crops.includes(crop)));
    // downstream tier-2 set (retailer + exporter + processor) — unique by id
    const downstreamIds = new Set();
    brokers.forEach(br => (br.sellsTo || []).forEach(id => downstreamIds.add(id)));
    const downstream = Array.from(downstreamIds).map(_findBuyer).filter(Boolean);

    // Try to extract a representative weekly market_signal for current quarter
    const weeks = Array.isArray(data.weeks) ? data.weeks : [];
    const peakSignal = weeks.find(w => (data.harvest_peak_weeks||[]).includes(w.week) && w.market_signal && w.market_signal !== '-');
    const sampleSignal = peakSignal ? peakSignal.market_signal : (weeks.find(w => w.market_signal && w.market_signal !== '-') || {}).market_signal || null;

    res.json({
      ok: true,
      crop,
      crop_th: data.crop_th,
      icon: data.icon,
      margin: mc.typical_margin || { broker_pct: 25, retailer_pct: 20, note: '-' },
      tiers_meta: mc.tiers || [],
      price_reference_url: mc.price_reference_url || null,
      sample_market_signal: sampleSignal,
      chain: [
        {
          tier: 'farmer', label: 'เกษตรกร', icon: '👨‍🌾',
          count: null, // wired to /api/farmer/plots count in admin dashboard if needed
          members: [],
          note: 'ขายให้ล้ง/สหกรณ์ (Tier 1) เท่านั้น'
        },
        {
          tier: 'broker', label: 'ล้ง / สหกรณ์ / รัฐวิสาหกิจ', icon: '🏬',
          count: brokers.length,
          members: brokers.map(b => ({
            id: b.id, subtype: b.subtype, name: b.name, regions: b.regions,
            capacityKgPerWeek: b.capacityKgPerWeek, paymentTerms: b.paymentTerms,
            sellsTo: (b.sellsTo||[]).map(id => {
              const d = _findBuyer(id); return d ? { id:d.id, tier:d.tier, name:d.name } : { id };
            })
          })),
          note: 'รับซื้อตรงจากเกษตรกร (จุดที่ matching API ส่งกลับ)'
        },
        {
          tier: 'downstream', label: 'ห้าง / ผู้ส่งออก / โรงงานแปรรูป', icon: '🏪',
          count: downstream.length,
          members: downstream.map(d => ({
            id: d.id, tier: d.tier, subtype: d.subtype, name: d.name,
            regions: d.regions, paymentTerms: d.paymentTerms,
            buysFrom: (d.buysFrom||[]).filter(id => brokers.some(b => b.id === id))
          })),
          note: 'ซื้อจากล้งเท่านั้น — ไม่ซื้อตรงจากเกษตรกร (informational)'
        },
        {
          tier: 'consumer', label: 'ผู้บริโภค', icon: '🛒',
          count: null, members: [],
          note: 'ซื้อจากห้าง/ตลาดสด/ออนไลน์'
        }
      ]
    });
  } catch(e) { res.status(500).json({ ok:false, error:e.message }); }
});

