// LINE WEBHOOK — Farmer Tracker Bot
// ═══════════════════════════════════════════════════════

// Simple Thai keyword → activity type parser (regex fallback)
function parseFarmerActivityFallback(text){
  const t = String(text||'');
  let type = 'other';
  if (/ใส่ปุ๋ย|ปุ๋ย/.test(t))                          type = 'fertilize';
  else if (/พ่นยา|ฉีดยา|พ่นสาร|ฉีดสาร/.test(t))       type = 'spray';
  else if (/เก็บเกี่ยว|เก็บผล|เก็บ ?\d/.test(t))      type = 'harvest';
  else if (/รดน้ำ|ให้น้ำ|น้ำเข้าแปลง/.test(t))         type = 'water';
  else if (/ตัดแต่ง|ตัดกิ่ง|ตัดยอด/.test(t))           type = 'prune';
  else if (/กำจัดวัชพืช|ถางหญ้า|พรวนดิน/.test(t))     type = 'weed';
  else if (/ตรวจ|สำรวจ|ดูแปลง/.test(t))                type = 'inspect';
  else if (/ปลูก|หว่าน|ย้ายกล้า/.test(t))              type = 'plant';

  // crop detection
  let crop = null;
  if (/ลำไย/.test(t))         crop = 'lamyai';
  else if (/ลิ้นจี่/.test(t)) crop = 'lychee';
  else if (/มะม่วง/.test(t))  crop = 'mango';
  else if (/สับปะรด/.test(t)) crop = 'pineapple';
  else if (/ส้ม/.test(t))     crop = 'orange';
  else if (/กาแฟ/.test(t))    crop = 'coffee';
  else if (/ชา/.test(t))      crop = 'tea';
  else if (/ทุเรียน/.test(t)) crop = 'durian';
  else if (/ข้าวเหนียว/.test(t)) crop = 'rice-sticky';
  else if (/หอมมะลิ|ข้าวหอม|ข้าว/.test(t)) crop = 'rice-jasmine';
  else if (/อ้อย/.test(t))    crop = 'sugarcane';
  else if (/มันสำปะหลัง|มันสำ/.test(t)) crop = 'cassava';
  else if (/ยางพารา|ยาง/.test(t)) crop = 'rubber';

  // plotId extraction e.g. "แปลง P001" or "แปลง#42"
  let plotId = null;
  const pm = t.match(/แปลง[\s#]?([A-Z]?\d{1,6})/i);
  if (pm) plotId = pm[1].toUpperCase();

  return { type, crop, plotId, note: t };
}

// Optional Claude Haiku parser — uses ANTHROPIC_API_KEY if present, else falls back
async function parseFarmerActivity(text, userId){
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) return { farmerId:userId||null, ...parseFarmerActivityFallback(text) };
  try {
    const sys = 'คุณคือ parser ที่แปลงข้อความเกษตรกรเป็น JSON. ตอบ JSON เท่านั้น keys: type (fertilize|spray|harvest|water|prune|weed|inspect|plant|other), crop (lamyai|lychee|mango|pineapple|orange|coffee|tea|durian|rice-jasmine|rice-sticky|sugarcane|cassava|rubber|null), plotId (string|null), note (string).';
    const r = await fetch('https://api.anthropic.com/v1/messages', {
      method:'POST',
      headers:{'x-api-key':apiKey,'anthropic-version':'2023-06-01','content-type':'application/json'},
      body: JSON.stringify({ model:'claude-haiku-4-5', max_tokens:200, system: sys, messages:[{role:'user', content:text}] })
    });
    if (!r.ok) throw new Error('claude '+r.status);
    const j = await r.json();
    const raw = j.content?.[0]?.text || '{}';
    const m = raw.match(/\{[\s\S]*\}/);
    if (!m) throw new Error('no json');
    const parsed = JSON.parse(m[0]);
    return { farmerId:userId||null, type:parsed.type||'other', crop:parsed.crop||null, plotId:parsed.plotId||null, note:parsed.note||text };
  } catch(e) {
    console.warn('[farmer-webhook] Claude parse failed, using regex:', e.message);
    return { farmerId:userId||null, ...parseFarmerActivityFallback(text) };
  }
}

// POST /api/line-webhook/farmer — รับ event จาก LINE OA Farmer Tracker
app.post('/api/line-webhook/farmer', async (req, res) => {
  try {
    const secret = process.env.LINE_CHANNEL_SECRET_FARMER || process.env.LINE_CHANNEL_SECRET;
    const sig = req.header('x-line-signature');
    const raw = req.rawBody || JSON.stringify(req.body || {});
    if (secret && sig && !verifyLineSignature(raw, sig, secret)) {
      console.warn('[farmer-webhook] signature mismatch');
      return res.status(401).json({ ok:false, error:'signature mismatch' });
    }
    const events = (req.body && req.body.events) || [];
    const lineToken = process.env.LINE_CHANNEL_ACCESS_TOKEN_FARMER || process.env.LINE_CHANNEL_ACCESS_TOKEN;

    for (const ev of events) {
      if (ev.type === 'message' && ev.message && ev.message.type === 'text') {
        const text = ev.message.text;
        const userId = ev.source && ev.source.userId;
        const parsed = await parseFarmerActivity(text, userId);
        const a = {
          id:`A${Date.now()}`,
          farmerId: parsed.farmerId || userId || 'unknown',
          plotId: parsed.plotId || null,
          crop: parsed.crop || null,
          type: parsed.type || 'other',
          week: null,
          note: parsed.note || text,
          raw: text,
          source: 'line',
          created: new Date().toISOString()
        };
        farmerActivities.push(a);
        console.log(`[farmer-webhook] saved: ${a.farmerId} ${a.type} ${a.crop||''} ${a.plotId||''}`);

        if (lineToken && ev.replyToken) {
          const cropLabel = a.crop ? ` (${a.crop})` : '';
          const plotLabel = a.plotId ? ` แปลง ${a.plotId}` : '';
          await lineReply(ev.replyToken, `✅ บันทึกแล้ว: ${a.type}${cropLabel}${plotLabel}\nขอบคุณค่ะ`, lineToken);
        }
      } else if (ev.type === 'follow') {
        if (lineToken && ev.replyToken) {
          await lineReply(ev.replyToken, 'สวัสดีค่ะ ยินดีต้อนรับสู่บอทบันทึกกิจกรรมเกษตรกร G2G AgriTech 🌱\nพิมพ์ข้อความเล่ากิจกรรมที่ทำ เช่น "วันนี้ใส่ปุ๋ยลำไยแปลง P001" แล้วบอทจะบันทึกให้อัตโนมัติ', lineToken);
        }
      }
    }
    res.json({ ok:true });
  } catch(e) {
    console.error('[farmer-webhook]', e);
    res.status(500).json({ ok:false, error:e.message });
  }
});

