/* ── In-memory stores (backed by Airtable async) ── */
const STAFF_CODES   = new Map(); // code -> { code, staffName, agencySlug, adminCode, createdAt, expiresAt, active }
const PENDING_CHANGES = new Map(); // changeId -> { changeId, agencySlug, staffCode, staffName, description, oldValue, newValue, endpoint, method, body, submittedAt, expiresAt, status }

/* ── Admin code per agency: env DELEGATION_ADMIN_CODE or fallback ── */
function getAdminCode(agencySlug) {
  return process.env[`DELEG_ADMIN_${agencySlug.toUpperCase()}`]
    || process.env.DELEGATION_ADMIN_CODE
    || 'g2g2026';
}

/* ── Random code generator ── */
function genCode(len = 6) {
  const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  let code = '';
  for (let i = 0; i < len; i++) code += chars[Math.floor(Math.random() * chars.length)];
  return code;
}

/* ── LINE notify to agency bot ── */
async function delegNotifyLine(agencySlug, text) {
  try {
    // Try to find agency LINE token from CHANNEL_SYSTEM_PROMPTS slug mapping
    const slugMap = {
      moac: 'MHESI10', mhesi: 'MHESI02', moi: 'MHESI03',
      mdes: 'MHESI04', moph: 'MHESI05', moc: 'MHESI06',
    };
    const mhesiSlug = slugMap[agencySlug.toLowerCase()];
    if (!mhesiSlug) return;
    const token = process.env[`LINE_TOKEN_${mhesiSlug}`];
    if (!token) return;
    await fetch('https://api.line.me/v2/bot/message/broadcast', {
      method: 'POST',
      headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ messages: [{ type: 'text', text }] }),
    });
  } catch (e) {
    console.warn('[delegation] LINE notify failed:', e.message);
  }
}

/* ── Load from Airtable on startup ── */
async function loadDelegationFromAirtable() {
  try {
    const [codesR, changesR] = await Promise.all([
      airtableGet('StaffCodes', { maxRecords: 500 }).catch(() => null),
      airtableGet('PendingChanges', { maxRecords: 500 }).catch(() => null),
    ]);
    if (codesR) {
      for (const rec of (codesR.records || [])) {
        const f = rec.fields;
        if (f.code && f.active) STAFF_CODES.set(f.code, { ...f, _airtableId: rec.id });
      }
      console.log(`[delegation] loaded ${STAFF_CODES.size} staff codes from Airtable`);
    }
    if (changesR) {
      for (const rec of (changesR.records || [])) {
        const f = rec.fields;
        if (f.changeId && f.status === 'pending') PENDING_CHANGES.set(f.changeId, { ...f, _airtableId: rec.id });
      }
      console.log(`[delegation] loaded ${PENDING_CHANGES.size} pending changes from Airtable`);
    }
  } catch (e) {
    console.warn('[delegation] Airtable load skipped (tables may not exist yet):', e.message);
  }
}

/* ── Save to Airtable (best-effort) ── */
async function saveStaffCodeToAirtable(c) {
  try { await airtablePost('StaffCodes', c); } catch (e) {}
}
async function saveChangeToAirtable(c) {
  try { await airtablePost('PendingChanges', c); } catch (e) {}
}
async function updateChangeInAirtable(c) {
  try {
    if (c._airtableId) await airtablePatch('PendingChanges', c._airtableId, { status: c.status });
  } catch (e) {}
}

/* ── 7-day cron: auto-revert pending changes ── */
setInterval(() => {
  const now = Date.now();
  for (const [id, ch] of PENDING_CHANGES) {
    if (ch.status === 'pending' && new Date(ch.expiresAt).getTime() < now) {
      ch.status = 'auto-reverted';
      PENDING_CHANGES.delete(id);
      console.log(`[delegation] auto-reverted: ${id} (${ch.agencySlug})`);
      updateChangeInAirtable(ch).catch(() => {});
      delegNotifyLine(ch.agencySlug, `⏰ ระบบยกเลิกการแก้ไขของ ${ch.staffName} อัตโนมัติ (ครบ 7 วัน)\n📝 ${ch.description}`);
    }
  }
}, 60 * 60 * 1000); // every hour

/* ── MIDDLEWARE: intercept staff API writes ── */
app.use('/api/', (req, res, next) => {
  const staffCode = req.headers['x-staff-code'];
  const agencySlug = req.headers['x-agency-slug'];
  if (!staffCode || !agencySlug) return next();

  const isWrite = ['POST', 'PUT', 'PATCH', 'DELETE'].includes(req.method);
  const isDelegRoute = req.path.startsWith('/delegation/');
  if (!isWrite || isDelegRoute) return next();

  // Verify code
  const info = STAFF_CODES.get(staffCode);
  if (!info || !info.active || info.agencySlug !== agencySlug || new Date(info.expiresAt) < new Date()) {
    return next(); // invalid code — pass through normally
  }

  // Capture and store as pending
  const changeId = `chg_${Date.now()}_${Math.random().toString(36).slice(2,8)}`;
  const now = new Date();
  const expires = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000);

  let body = {};
  try { body = req.body || {}; } catch (e) {}

  const change = {
    changeId,
    agencySlug,
    staffCode,
    staffName: info.staffName,
    description: `${req.method} ${req.path}`,
    oldValue: '',
    newValue: JSON.stringify(body).slice(0, 500),
    endpoint: req.path,
    method: req.method,
    body,
    submittedAt: now.toISOString(),
    expiresAt: expires.toISOString(),
    status: 'pending',
  };

  PENDING_CHANGES.set(changeId, change);
  saveChangeToAirtable(change).catch(() => {});

  // Notify agency head via LINE
  delegNotifyLine(agencySlug, `📋 มีคำขอแก้ไขใหม่จาก ${info.staffName}\n📝 ${req.method} ${req.path}\nรอการอนุมัติภายใน 7 วัน\n🔗 https://g2g-ai-pool.fly.dev/management-${agencySlug}.html`);

  // Return success but don't apply
  return res.json({ ok: true, pending: true, changeId, message: `บันทึกคำขอแก้ไขแล้ว รอหัวหน้าอนุมัติภายใน 7 วัน (ID: ${changeId.slice(-8)})` });
});

