/* HEAD LOGIN */
app.post('/api/delegation/head/login', (req, res) => {
  const { adminCode, agencySlug } = req.body || {};
  if (!adminCode || !agencySlug) return res.json({ ok: false, error: 'ต้องการ adminCode และ agencySlug' });
  if (adminCode !== getAdminCode(agencySlug)) return res.json({ ok: false, error: 'Admin Code ไม่ถูกต้อง' });
  res.json({ ok: true, agencySlug, message: 'เข้าสู่ระบบสำเร็จ' });
});

/* CREATE STAFF CODE */
app.post('/api/delegation/codes/create', async (req, res) => {
  const { adminCode, agencySlug, staffName } = req.body || {};
  if (adminCode !== getAdminCode(agencySlug)) return res.json({ ok: false, error: 'ไม่ได้รับอนุญาต' });
  if (!staffName) return res.json({ ok: false, error: 'ต้องการชื่อ' });

  // max 10 codes per agency
  const existing = [...STAFF_CODES.values()].filter(c => c.agencySlug === agencySlug && c.active);
  if (existing.length >= 10) return res.json({ ok: false, error: 'ถึงขีดสูงสุด 10 คน' });

  const code = genCode(6);
  const now = new Date();
  const expires = new Date(now.getTime() + 30 * 24 * 60 * 60 * 1000); // 30 days

  const staffObj = { code, staffName, agencySlug, adminCode, createdAt: now.toISOString(), expiresAt: expires.toISOString(), active: true };
  STAFF_CODES.set(code, staffObj);
  saveStaffCodeToAirtable(staffObj).catch(() => {});

  res.json({ ok: true, code, staffName, expiresAt: expires.toISOString() });
});

/* LIST STAFF CODES */
app.get('/api/delegation/codes/:agencySlug', (req, res) => {
  const { agencySlug } = req.params;
  const { adminCode } = req.query;
  if (adminCode !== getAdminCode(agencySlug)) return res.json({ ok: false, error: 'ไม่ได้รับอนุญาต' });

  const codes = [...STAFF_CODES.values()].filter(c => c.agencySlug === agencySlug && c.active);
  res.json({ ok: true, codes: codes.map(c => ({ code: c.code, staffName: c.staffName, expiresAt: c.expiresAt })) });
});

/* REVOKE STAFF CODE */
app.post('/api/delegation/codes/revoke', (req, res) => {
  const { adminCode, agencySlug, staffCode } = req.body || {};
  if (adminCode !== getAdminCode(agencySlug)) return res.json({ ok: false, error: 'ไม่ได้รับอนุญาต' });

  const info = STAFF_CODES.get(staffCode);
  if (!info || info.agencySlug !== agencySlug) return res.json({ ok: false, error: 'ไม่พบ Code' });
  info.active = false;
  res.json({ ok: true });
});

/* VERIFY STAFF CODE */
app.post('/api/delegation/staff/verify', (req, res) => {
  const { staffCode, agencySlug } = req.body || {};
  const info = STAFF_CODES.get((staffCode || '').toUpperCase());
  if (!info) return res.json({ ok: false, error: 'Code ไม่ถูกต้อง' });
  if (!info.active) return res.json({ ok: false, error: 'Code ถูกยกเลิกแล้ว' });
  if (info.agencySlug !== agencySlug) return res.json({ ok: false, error: 'Code ไม่ตรงกับหน่วยงาน' });
  if (new Date(info.expiresAt) < new Date()) return res.json({ ok: false, error: 'Code หมดอายุแล้ว' });
  res.json({ ok: true, staffName: info.staffName, agencySlug });
});

/* SUBMIT CHANGE (manual — used when staff explicitly submits a change description) */
app.post('/api/delegation/changes/submit', (req, res) => {
  const { staffCode, agencySlug, description, oldValue, newValue, endpoint, method, body } = req.body || {};
  const info = STAFF_CODES.get((staffCode || '').toUpperCase());
  if (!info || !info.active || info.agencySlug !== agencySlug) return res.json({ ok: false, error: 'Code ไม่ถูกต้อง' });

  const changeId = `chg_${Date.now()}_${Math.random().toString(36).slice(2,8)}`;
  const now = new Date();
  const expires = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000);

  const change = {
    changeId, agencySlug, staffCode, staffName: info.staffName,
    description: description || 'คำขอแก้ไข',
    oldValue: String(oldValue || '').slice(0, 1000),
    newValue: String(newValue || '').slice(0, 1000),
    endpoint: endpoint || '', method: method || 'POST', body: body || {},
    submittedAt: now.toISOString(), expiresAt: expires.toISOString(), status: 'pending',
  };

  PENDING_CHANGES.set(changeId, change);
  saveChangeToAirtable(change).catch(() => {});
  delegNotifyLine(agencySlug, `📋 คำขอแก้ไขใหม่จาก ${info.staffName}\n📝 ${description}\nรอหัวหน้าอนุมัติภายใน 7 วัน`);

  res.json({ ok: true, changeId, message: 'บันทึกคำขอแล้ว' });
});

/* COUNT PENDING */
app.get('/api/delegation/changes/:agencySlug/count', (req, res) => {
  const { agencySlug } = req.params;
  const count = [...PENDING_CHANGES.values()].filter(c => c.agencySlug === agencySlug && c.status === 'pending').length;
  res.json({ ok: true, count });
});

/* LIST PENDING CHANGES */
app.get('/api/delegation/changes/:agencySlug', (req, res) => {
  const { agencySlug } = req.params;
  const { adminCode, staffCode } = req.query;

  const isAdmin = adminCode && adminCode === getAdminCode(agencySlug);
  const isStaff = staffCode && STAFF_CODES.has(staffCode.toUpperCase()) && STAFF_CODES.get(staffCode.toUpperCase())?.agencySlug === agencySlug;

  if (!isAdmin && !isStaff) return res.json({ ok: false, error: 'ไม่ได้รับอนุญาต', changes: [] });

  let changes = [...PENDING_CHANGES.values()].filter(c => c.agencySlug === agencySlug && c.status === 'pending');
  if (isStaff && !isAdmin) changes = changes.filter(c => c.staffCode === staffCode.toUpperCase());

  changes.sort((a, b) => new Date(b.submittedAt) - new Date(a.submittedAt));
  res.json({ ok: true, changes });
});

/* APPROVE CHANGE */
app.post('/api/delegation/changes/approve', async (req, res) => {
  const { changeId, adminCode, agencySlug } = req.body || {};
  if (adminCode !== getAdminCode(agencySlug)) return res.json({ ok: false, error: 'ไม่ได้รับอนุญาต' });

  const change = PENDING_CHANGES.get(changeId);
  if (!change) return res.json({ ok: false, error: 'ไม่พบรายการ' });
  if (change.agencySlug !== agencySlug) return res.json({ ok: false, error: 'ไม่ตรงกัน' });

  // RE-EXECUTE the original API call
  let applyResult = null;
  let applyNote = '';
  if (change.endpoint && change.method) {
    try {
      // Make internal call to apply the change
      const baseUrl = `http://localhost:${process.env.PORT || 8080}`;
      const applyRes = await fetch(`${baseUrl}/api${change.endpoint}`, {
        method: change.method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(change.body || {}),
      });
      applyResult = await applyRes.json();
      applyNote = applyResult?.ok ? 'บันทึกข้อมูลสำเร็จ' : `บันทึกไม่สำเร็จ: ${applyResult?.error || 'unknown'}`;
    } catch (e) {
      applyNote = 'ไม่สามารถ replay คำขอได้ (กรุณาแก้ไขด้วยตนเอง)';
    }
  }

  change.status = 'approved';
  change.reviewedAt = new Date().toISOString();
  PENDING_CHANGES.delete(changeId);
  updateChangeInAirtable(change).catch(() => {});

  // Notify via LINE
  delegNotifyLine(agencySlug, `✅ หัวหน้าอนุมัติการแก้ไขของ ${change.staffName}\n📝 ${change.description}\n${applyNote}`);

  res.json({ ok: true, note: applyNote });
});

/* REJECT CHANGE */
app.post('/api/delegation/changes/reject', async (req, res) => {
  const { changeId, adminCode, agencySlug, reason } = req.body || {};
  if (adminCode !== getAdminCode(agencySlug)) return res.json({ ok: false, error: 'ไม่ได้รับอนุญาต' });

  const change = PENDING_CHANGES.get(changeId);
  if (!change) return res.json({ ok: false, error: 'ไม่พบรายการ' });

  change.status = 'rejected';
  change.reviewedAt = new Date().toISOString();
  change.rejectReason = reason || '';
  PENDING_CHANGES.delete(changeId);
  updateChangeInAirtable(change).catch(() => {});

  delegNotifyLine(agencySlug, `❌ หัวหน้าปฏิเสธการแก้ไขของ ${change.staffName}\n📝 ${change.description}\n${reason ? 'เหตุผล: ' + reason : ''}`);

  res.json({ ok: true });
});

/* LINE Quick Reply approval — handled inside main LINE webhook */
/* Pattern: message = "อนุมัติ chg_xxx" or "ปฏิเสธ chg_xxx [เหตุผล]" */
function checkDelegationLineCommand(text, agencySlug, adminCode) {
  const approveM = text.match(/^อนุมัติ\s+(chg_\S+)/i);
  const rejectM  = text.match(/^ปฏิเสธ\s+(chg_\S+)(?:\s+(.+))?/i);
  if (!approveM && !rejectM) return null;

  const changeId = (approveM || rejectM)[1];
  const change = PENDING_CHANGES.get(changeId);
  if (!change || change.agencySlug !== agencySlug) return '⚠️ ไม่พบรายการนี้';
  if (adminCode !== getAdminCode(agencySlug)) return '⚠️ ไม่ได้รับอนุญาต';

  if (approveM) {
    change.status = 'approved';
    PENDING_CHANGES.delete(changeId);
    updateChangeInAirtable(change).catch(() => {});
    return `✅ อนุมัติการแก้ไขของ ${change.staffName} แล้ว\n📝 ${change.description}`;
  } else {
    const reason = rejectM[2] || '';
    change.status = 'rejected';
    change.rejectReason = reason;
    PENDING_CHANGES.delete(changeId);
    updateChangeInAirtable(change).catch(() => {});
    return `❌ ปฏิเสธการแก้ไขของ ${change.staffName} แล้ว\n${reason ? 'เหตุผล: ' + reason : ''}`;
  }
}

/* Export for use in LINE webhook handler */
global.checkDelegationLineCommand = checkDelegationLineCommand;
global.getAgencyAdminCode = getAdminCode;

// ===== G2G CAREER PLATFORM API =====
const OCCUPATION_DB_PATH = path.join(__dirname, 'public', 'occupation-knowledge.json');

// GET /api/career/occupations — ดึงฐานข้อมูลอาชีพทั้งหมด
app.get('/api/career/occupations', (req, res) => {
  try {
    const db = JSON.parse(fs.readFileSync(OCCUPATION_DB_PATH, 'utf8'));
    const { sector, search } = req.query;
    let data = db.sectors;
    if (sector) data = data.filter(s => s.id === sector);
    if (search) {
      const q = search.toLowerCase();
      data = data.map(s => ({
        ...s,
        occupations: s.occupations.filter(o =>
          o.name.toLowerCase().includes(q) ||
          (o.knowledge_gaps || []).some(g => g.toLowerCase().includes(q))
        )
      })).filter(s => s.occupations.length > 0);
    }
    res.json({ ok: true, sectors: data, meta: db.meta });
  } catch (e) {
    res.status(500).json({ ok: false, error: e.message });
  }
});

// GET /api/career/occupation/:id — ดึงข้อมูลอาชีพเดี่ยว
app.get('/api/career/occupation/:id', (req, res) => {
  try {
    const db = JSON.parse(fs.readFileSync(OCCUPATION_DB_PATH, 'utf8'));
    for (const s of db.sectors) {
      const occ = s.occupations.find(o => o.id === req.params.id);
      if (occ) return res.json({ ok: true, sector: s.name, sector_icon: s.icon, occupation: occ });
    }
    res.status(404).json({ ok: false, error: 'not_found' });
  } catch (e) {
    res.status(500).json({ ok: false, error: e.message });
  }
});

// POST /api/career/ai-advice — AI ให้คำแนะนำอาชีพเฉพาะบุคคล
app.post('/api/career/ai-advice', async (req, res) => {
  const { question, occupation_id, user_context } = req.body;
  if (!question) return res.status(400).json({ ok: false, error: 'question_required' });

  let occupationContext = '';
  try {
    const db = JSON.parse(fs.readFileSync(OCCUPATION_DB_PATH, 'utf8'));
    if (occupation_id) {
      for (const s of db.sectors) {
        const occ = s.occupations.find(o => o.id === occupation_id);
        if (occ) {
          occupationContext = `\nอาชีพ: ${occ.name}\nช่องว่างความรู้หลัก: ${occ.knowledge_gaps.join(', ')}\nเทคนิคที่ต้องเรียน: ${occ.techniques.join(', ')}\nเทคโนโลยีที่ช่วยได้: ${occ.technology.join(', ')}`;
          break;
        }
      }
    }
  } catch (e) {}

  const apiKey = process.env.ANTHROPIC_API_KEY || process.env.ANTHROPIC_KEY_1;
  if (!apiKey) return res.json({ ok: true, reply: 'ขออภัย ระบบ AI ไม่พร้อมในขณะนี้' });

  try {
    const systemPrompt = `คุณคือ AI ที่ปรึกษาอาชีพระดับชาติของ G2G Career Platform ประเทศไทย
ภารกิจ: ช่วยคนไทยทุกคนพัฒนาอาชีพ เพิ่มรายได้ และใช้เทคโนโลยี
ตอบภาษาไทย กระชับ ใช้งานได้จริง เน้น Action Steps ที่ทำได้ทันที${occupationContext}
${user_context ? 'บริบทผู้ใช้: ' + user_context : ''}`;

    const r = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: { 'x-api-key': apiKey, 'anthropic-version': '2023-06-01', 'Content-Type': 'application/json' },
      body: JSON.stringify({ model: 'claude-haiku-4-5-20251001', max_tokens: 600, system: systemPrompt, messages: [{ role: 'user', content: question }] })
    });
    const d = await r.json();
    if (d.error) throw new Error(d.error.message);
    res.json({ ok: true, reply: d.content?.[0]?.text || 'ขออภัย ไม่สามารถตอบได้' });
  } catch (e) {
    res.json({ ok: false, reply: 'ขออภัย ระบบ AI ขัดข้อง กรุณาลองใหม่', error: e.message });
  }
});

